INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸引", "is_correct": true, "explanation": "正确答案。“吸引着”表示磁铁正把铁钉拉过来，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：磁铁不能“咬”铁钉，“咬”的主语需要有口或牙齿。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复损坏之物，与磁铁对铁钉的作用无关。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人，磁铁不能“欢迎”铁钉。"}], "explanations": {"吸引": "正确答案。“吸引着”表示磁铁正把铁钉拉过来，符合句意。", "咬": "搭配：磁铁不能“咬”铁钉，“咬”的主语需要有口或牙齿。", "修理": "语义：“修理”指修复损坏之物，与磁铁对铁钉的作用无关。", "欢迎": "搭配：“欢迎”的对象是人，磁铁不能“欢迎”铁钉。"}, "sentence_index": 6, "correct_answer": "吸引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人吸引了地板。", "explanation": "这里应该用〈冲洗〉。“吸引”表示让人或东西靠近，不表示清洗地板。"}, {"text": "他深深地吸引了一口空气。", "explanation": "这里应该用〈吸入〉。“吸引”指把人或东西引过来，不表示把空气吸进肺里。"}, {"text": "这块毛巾吸引了我的汗水。", "explanation": "这里应该用〈吸干〉。毛巾把汗水吸进去说「吸干」，「吸引」指把人或东西引到自己这边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "灯光吸引着了很多飞虫。", "corrected_sentence": "灯光吸引了很多飞虫。", "error_description": "体标错误：「着」表示持续，「了」表示完成，不能在「吸引」后叠用。这里表示已经发生，应删去「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜂蜜吸引了过很多苍蝇。", "corrected_sentence": "蜂蜜吸引了很多苍蝇。", "error_description": "错误的形式是“吸引了过”，正确的形式是“吸引了”。“了”和“过”不能同时用在“吸引”后面，这里只用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确答案。“展示”与“隐藏”在“拿出来给人看”这一义项上构成反义。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“展示”的义项没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污物，与“展示”的义项没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏之物，与“展示”的义项没有反义关系。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确答案。“展示”与“隐藏”在“拿出来给人看”这一义项上构成反义。", "搬运": "“搬运”指把东西从一处移到另一处，与“展示”的义项没有反义关系。", "清洗": "“清洗”指用水去除污物，与“展示”的义项没有反义关系。", "修理": "“修理”指修复损坏之物，与“展示”的义项没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确答案。“展示”与“隐藏”在“拿出来给人看”这一义项上构成反义。"}, {"text": "砍伐", "is_correct": false, "explanation": "“砍伐”指砍倒树木，与“展示”的义项没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "“翻译”指把一种语言转换成另一种语言，与“展示”的义项没有反义关系。"}, {"text": "批改", "is_correct": false, "explanation": "“批改”指评阅作业或文章，与“展示”的义项没有反义关系。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确答案。“展示”与“隐藏”在“拿出来给人看”这一义项上构成反义。", "砍伐": "“砍伐”指砍倒树木，与“展示”的义项没有反义关系。", "翻译": "“翻译”指把一种语言转换成另一种语言，与“展示”的义项没有反义关系。", "批改": "“批改”指评阅作业或文章，与“展示”的义项没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出来给人看。", "primary_collocate": null, "pronunciation": "zhǎn shì", "ipa": "ʈʂan˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "她把新书展示给大家。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明展示了他的玩具车。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你展示一下你的作业。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柜子里展示着很多茶杯。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向客人展示了新房子。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王展示过他的旧照片。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子向妈妈展示新鞋。", "target_word": "展示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商店门口展示着一辆车。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的票展示给老师看。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想向你展示我的画。", "target_word": "展示", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "展示了", "label": "体标"}, {"form": "展示着", "label": "体标"}, {"form": "展示过", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿出来给人看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。zhǎn shì，意思是拿出来给人看。"}, {"text": "战士", "is_correct": false, "explanation": "zhàn shì 与 zhǎn shì 第一音节声调不同，意思是士兵。"}, {"text": "战事", "is_correct": false, "explanation": "zhàn shì 与 zhǎn shì 第一音节声调不同（第四声与第三声），意思是战争。"}, {"text": "战史", "is_correct": false, "explanation": "zhàn shǐ 与 zhǎn shì 声调不同，史是第三声，意思是战争的历史。"}, {"text": "长势", "is_correct": false, "explanation": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是生长的态势。"}], "explanations": {"展示": "正确答案。zhǎn shì，意思是拿出来给人看。", "战士": "zhàn shì 与 zhǎn shì 第一音节声调不同，意思是士兵。", "战事": "zhàn shì 与 zhǎn shì 第一音节声调不同（第四声与第三声），意思是战争。", "战史": "zhàn shǐ 与 zhǎn shì 声调不同，史是第三声，意思是战争的历史。", "长势": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是生长的态势。"}, "sentence_index": null, "correct_answer": "展示"}, "level_3": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。“展示”表示把新书拿给大家看，符合句意。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”表示不让人看见，与“给大家”的语境相反。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”用于衣物、器具，不能用来描述把书给大家看。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”指私下珍藏，不能用“把新书收藏给大家”表示面向众人的行为。"}], "explanations": {"展示": "正确答案。“展示”表示把新书拿给大家看，符合句意。", "隐藏": "语义：“隐藏”表示不让人看见，与“给大家”的语境相反。", "清洗": "搭配：“清洗”用于衣物、器具，不能用来描述把书给大家看。", "收藏": "搭配：“收藏”指私下珍藏，不能用“把新书收藏给大家”表示面向众人的行为。"}, "sentence_index": 0, "correct_answer": "展示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上展示一壶热水。", "explanation": "这里应该用〈烧〉。烧热水是把水加热，“展示”是把东西拿出来给人看，用在这里不通。"}, {"text": "我们展示了整整一个下午的时间。", "explanation": "这里应该用〈度过〉。时间不是可以拿出来给人看的东西，“展示”不能用于它。"}, {"text": "这个孩子把糖展示进了肚子里。", "explanation": "这里应该用〈吞进〉。“展示”是把东西拿给人看，糖吞进肚子后就看不见了，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。zhǎn shì，意思是拿出来给人看。"}, {"text": "战时", "is_correct": false, "explanation": "zhàn shí 与 zhǎn shì 两个音节的声调都不同，意思是战争时期。"}, {"text": "战事", "is_correct": false, "explanation": "zhàn shì 与 zhǎn shì 第一音节声调不同（第四声与第三声），意思是战争。"}, {"text": "掌事", "is_correct": false, "explanation": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是主管事务。"}], "explanations": {"展示": "正确答案。zhǎn shì，意思是拿出来给人看。", "战时": "zhàn shí 与 zhǎn shì 两个音节的声调都不同，意思是战争时期。", "战事": "zhàn shì 与 zhǎn shì 第一音节声调不同（第四声与第三声），意思是战争。", "掌事": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是主管事务。"}, "sentence_index": null, "correct_answer": "展示"}, "level_3": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。“展示”表示把新鞋拿给妈妈看，符合句意。"}, {"text": "修补", "is_correct": false, "explanation": "语义：新鞋不需要修补，“修补”与“新”的语境矛盾。"}, {"text": "偷", "is_correct": false, "explanation": "配价：“偷”要用“从”引出对象，不能说“向妈妈偷新鞋”。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”的对象是土地或物体，不能用来修饰“新鞋”。"}], "explanations": {"展示": "正确答案。“展示”表示把新鞋拿给妈妈看，符合句意。", "修补": "语义：新鞋不需要修补，“修补”与“新”的语境矛盾。", "偷": "配价：“偷”要用“从”引出对象，不能说“向妈妈偷新鞋”。", "挖": "搭配：“挖”的对象是土地或物体，不能用来修饰“新鞋”。"}, "sentence_index": 6, "correct_answer": "展示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这道题的答案展示进了笔记本。", "explanation": "这里应该用〈记录〉。“展示”表示给人看，写进笔记本不是让人看到的意思。"}, {"text": "妈妈在厨房里展示了一锅汤的温度。", "explanation": "这里应该用〈测量〉。温度不是可以拿出来给人看的东西，“展示”不能用于它。"}, {"text": "胃展示了食物。", "explanation": "这里应该用〈消化〉。食物是在胃里被消化的，不能拿出来给人看，“展示”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店主把新款手表展示顾客看。", "corrected_sentence": "店主把新款手表展示给顾客看。", "error_description": "错误的形式是“展示顾客看”，正确的形式是“展示给顾客看”。“展示”后面要用“给”引出看的对象，省略“给”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把展示了学生的画。", "corrected_sentence": "老师展示了学生的画。", "error_description": "错误的形式是“把展示了”，正确的形式是“展示了”。“把”字句要求把要处置的对象放在“把”后面，这里没有对象，不能加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
