INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25054, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到突然发生的事情时要马上想办法解决。", "primary_collocate": null, "pronunciation": "yìng jí", "ipa": "iŋ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "手机没电了，我用朋友的充电宝应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子突然发烧，妈妈先用冷毛巾应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁坏了，他临时用椅子顶住门应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们用塑料袋当伞应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔没水了，她先用铅笔应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房没有盐了，我拿酱油应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说遇到危险要冷静，先想办法应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车在路上没油了，只好找人借油应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋带断了，他用一根绳子应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停水了，邻居们先用桶里的水应急。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应急预案", "label": "复合"}, {"form": "應急", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到突发情况时马上想办法临时解决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急 yìngjí：遇到突发情况时临时想办法解决，即正确答案。"}, {"text": "影集", "is_correct": false, "explanation": "影集 yǐngjí 与应急 yìngjí 第一个音节声调不同（第三声与第四声），意思是相册。"}, {"text": "应激", "is_correct": false, "explanation": "应激 yìngjī 与应急 yìngjí 第二个音节声调不同（第一声与第二声），意思是应激反应，是心理学术语。"}, {"text": "营级", "is_correct": false, "explanation": "营级 yíngjí 与应急 yìngjí 第一个音节声调不同（第二声与第四声），意思是军队中营这一级。"}], "explanations": {"应急": "应急 yìngjí：遇到突发情况时临时想办法解决，即正确答案。", "影集": "影集 yǐngjí 与应急 yìngjí 第一个音节声调不同（第三声与第四声），意思是相册。", "应激": "应激 yìngjī 与应急 yìngjí 第二个音节声调不同（第一声与第二声），意思是应激反应，是心理学术语。", "营级": "营级 yíngjí 与应急 yìngjí 第一个音节声调不同（第二声与第四声），意思是军队中营这一级。"}, "sentence_index": null, "correct_answer": "应急"}, "level_3": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急：遇到没电的情况，临时借用充电宝来解决，符合句意。"}, {"text": "观赏", "is_correct": false, "explanation": "语义：“观赏”是欣赏的意思，与手机没电时的临时解决不符。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：充电宝是用来充电的，说用它“装饰”与句意矛盾。"}, {"text": "收藏", "is_correct": false, "explanation": "配价：“收藏”需要带收藏的对象，句末缺宾语，不能说“用充电宝收藏”。"}], "explanations": {"应急": "应急：遇到没电的情况，临时借用充电宝来解决，符合句意。", "观赏": "语义：“观赏”是欣赏的意思，与手机没电时的临时解决不符。", "装饰": "语义：充电宝是用来充电的，说用它“装饰”与句意矛盾。", "收藏": "配价：“收藏”需要带收藏的对象，句末缺宾语，不能说“用充电宝收藏”。"}, "sentence_index": 0, "correct_answer": "应急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这块玉应急了三十年，从不拿出来。", "explanation": "这里应该用〈珍藏〉。应急指遇事临时想办法，不指长期保存。"}, {"text": "我们把会议应急了一个星期，大家都很不满。", "explanation": "这里应该用〈推迟〉。应急是遇到突发事情时马上想办法解决，不能用来表示会议延期。"}, {"text": "他每天应急着午后的阳光，非常惬意。", "explanation": "这里应该用〈享受〉。应急是临时应对，不用于形容享受美好的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25054, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急 yìngjí：遇到突发情况时临时想办法解决，即正确答案。"}, {"text": "性急", "is_correct": false, "explanation": "性急 xìngjí 与应急 yìngjí 声母不同（x 与 y），意思是急躁。"}, {"text": "应季", "is_correct": false, "explanation": "应季 yìngjì 与应急 yìngjí 第二个音节声调不同（第四声与第二声），意思是合乎季节。"}, {"text": "英籍", "is_correct": false, "explanation": "英籍 yīngjí 与应急 yìngjí 第一个音节声调不同（第一声与第四声），意思是英国国籍。"}], "explanations": {"应急": "应急 yìngjí：遇到突发情况时临时想办法解决，即正确答案。", "性急": "性急 xìngjí 与应急 yìngjí 声母不同（x 与 y），意思是急躁。", "应季": "应季 yìngjì 与应急 yìngjí 第二个音节声调不同（第四声与第二声），意思是合乎季节。", "英籍": "英籍 yīngjí 与应急 yìngjí 第一个音节声调不同（第一声与第四声），意思是英国国籍。"}, "sentence_index": null, "correct_answer": "应急"}, "level_3": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急：遇到危险时临时想办法应对，与“要冷静”的劝告一致。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是品味美好事物，与遇到危险时想办法应对不符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：遇到危险时去旅游，与句中“要冷静、想办法”的劝告矛盾。"}, {"text": "摆烂", "is_correct": false, "explanation": "语域：“摆烂”是网络口语，与老师这句正式的劝告语气不合。"}], "explanations": {"应急": "应急：遇到危险时临时想办法应对，与“要冷静”的劝告一致。", "欣赏": "语义：“欣赏”是品味美好事物，与遇到危险时想办法应对不符。", "旅游": "语义：遇到危险时去旅游，与句中“要冷静、想办法”的劝告矛盾。", "摆烂": "语域：“摆烂”是网络口语，与老师这句正式的劝告语气不合。"}, "sentence_index": 6, "correct_answer": "应急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都应急早睡的习惯，已经坚持了十年。", "explanation": "这里应该用〈养成〉。应急只指遇事临时应对，不能用于养成习惯。"}, {"text": "老师让我们提前应急课文，明天要考试。", "explanation": "这里应该用〈预习〉。应急是事情发生后临时应对，不能说提前去应急课文。"}, {"text": "这幅画很值得应急，大家都来看看。", "explanation": "这里应该用〈欣赏〉。应急用于突发情况，不能用来评价画作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车灯坏了，我先用布了应急一下。", "corrected_sentence": "车灯坏了，我先用布应急一下。", "error_description": "“了”不能放在动词“应急”前面，应放在动词之后；应说“用布应急一下”，不说“用布了应急一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "停电了，邻居们先把蜡烛应急一下。", "corrected_sentence": "停电了，邻居们先用蜡烛应急一下。", "error_description": "“应急”是不及物动词，不能带处置对象，所以不能用“把蜡烛应急”。应该说“用蜡烛应急一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
