INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25056, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由多种不同的东西组合而成的整体。", "primary_collocate": null, "pronunciation": "zōng hé tǐ", "ipa": "tsʊŋ˥ xɤ˧˥ tʰi˨˩", "syllable_count": 3, "sentences": [{"text": "这首歌是几种音乐的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人的性格是多种因素的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店是书店和咖啡馆的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个建筑是办公室和商店的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼是住宅和商场的综合体。", "target_word": "综合体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗是叙事和抒情的综合体。", "target_word": "综合体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目是三个小计划的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服是新旧风格的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学校是小学和幼儿园的综合体。", "target_word": "综合体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园是花园和运动场的综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "商业综合体", "label": "复合"}], "register": "中性", "sense_fingerprint": "不同东西合在一起形成的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "综合体", "is_correct": true, "explanation": "正确：「几种音乐的综合体」指把几种音乐合成的一个整体。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料是画画的材料，不能组成音乐。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是音乐的组成部分。"}, {"text": "酒", "is_correct": false, "explanation": "搭配：「几种音乐的」后不能接「酒」，搭配不通。"}], "explanations": {"综合体": "正确：「几种音乐的综合体」指把几种音乐合成的一个整体。", "颜料": "语义：颜料是画画的材料，不能组成音乐。", "桌子": "语义：桌子是家具，不是音乐的组成部分。", "酒": "搭配：「几种音乐的」后不能接「酒」，搭配不通。"}, "sentence_index": 0, "correct_answer": "综合体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶纯净水是一个综合体。", "explanation": "这里应该用〈纯净物〉。综合体指多种东西组合成的整体，纯净水只含一种物质，属于纯净物。"}, {"text": "这颗小石子是一个综合体。", "explanation": "这里应该用〈整体〉。一颗小石子只是一个东西，不是多种东西组合而成的，不说综合体。"}, {"text": "这是一个女子综合体。", "explanation": "这里应该用〈组合〉。组合可以指一组人，综合体指多种东西合成的整体，不说女子综合体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "综合体", "is_correct": true, "explanation": "正确：「三个小计划的综合体」指把三个小计划合成的一个整体。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能是计划的组成部分。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能组成一个计划。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：「夜晚」是时间，不能作为计划的组成部分，搭配不通。"}], "explanations": {"综合体": "正确：「三个小计划的综合体」指把三个小计划合成的一个整体。", "汽车": "语义：汽车是交通工具，不能是计划的组成部分。", "水果": "语义：水果是食物，不能组成一个计划。", "夜晚": "搭配：「夜晚」是时间，不能作为计划的组成部分，搭配不通。"}, "sentence_index": 6, "correct_answer": "综合体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这滴水是一个综合体。", "explanation": "这里应该用〈水滴〉。一滴水不是多种不同东西的组合，不说综合体。"}, {"text": "这个想法很单纯，是一个综合体。", "explanation": "这里应该用〈简单概念〉。综合体指多种因素组合，单纯的想法只有一个要素，不说综合体。"}, {"text": "这张纸是一个综合体。", "explanation": "这里应该用〈单页〉。综合体是多种东西的组合，一张纸不说综合体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种风格是多种元素的一把综合体。", "corrected_sentence": "这种风格是多种元素的一个综合体。", "error_description": "错误：「综合体」前应用量词「个」，「把」用于有柄的物件，不能用于综合体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校是传统与现代的综合体们。", "corrected_sentence": "这所学校是传统与现代的综合体。", "error_description": "错误：「综合体」是非人的抽象名词，不能加复数词尾「们」，应去掉「们」，直接说「……的综合体」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
