INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一块地上，所有房子占的总面积和这块地的面积的比。", "primary_collocate": null, "pronunciation": "róng jī lǜ", "ipa": "ɻʊŋ˧˥ tɕi˥ ly˥˩", "syllable_count": 3, "sentences": [{"text": "容积率是房子总面积和地的面积的比。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的容积率很低，房子不多。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容积率高，说明房子多，人也多。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是容积率。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的容积率只有一点五。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容积率越小，小区里的空地越大。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的楼很高，容积率一定不低。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牌子上写着，这里的容积率是二。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要建新楼，先要看这块地的容积率。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容积率太大，住在里面不舒服。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容積率", "label": "繁体"}], "register": "中性", "sense_fingerprint": "容积率：房子总面积和地的面积的比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容积率", "is_correct": true, "explanation": "正确。句子定义的是“容积率”，即房子总面积与地的面积之比。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品或房屋的售价，不是房子总面积与地面积的比。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，与面积之比无关。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”计算的是人的数量，不能与“……的面积的比”组成定义。"}], "explanations": {"容积率": "正确。句子定义的是“容积率”，即房子总面积与地的面积之比。", "价格": "语义：价格是商品或房屋的售价，不是房子总面积与地面积的比。", "颜色": "语义：颜色是视觉属性，与面积之比无关。", "人数": "搭配：“人数”计算的是人的数量，不能与“……的面积的比”组成定义。"}, "sentence_index": 0, "correct_answer": "容积率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的容积率有三千平方米。", "explanation": "这里应该用〈建筑面积〉。容积率是比值，没有平方米这个单位，说房子的总面积要用建筑面积。"}, {"text": "这个小区的容积率只有百分之四十。", "explanation": "这里应该用〈绿化率〉。绿化率用百分数表示绿地的占比；容积率是比值，不用百分数。"}, {"text": "这块地的容积率是五千平方米。", "explanation": "这里应该用〈用地面积〉。容积率是比值，不能用“平方米”计量，说地的大小要用用地面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容积率", "is_correct": true, "explanation": "正确。“楼很高”说明容积率一定不低，“不低”修饰的是容积率。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用“低”或“不低”来形容，与楼的高低无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是食物或气味的属性，不能用来形容楼的指标。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”用于人，不与“楼很高”所描述的建筑搭配。"}], "explanations": {"容积率": "正确。“楼很高”说明容积率一定不低，“不低”修饰的是容积率。", "颜色": "语义：颜色不能用“低”或“不低”来形容，与楼的高低无关。", "味道": "语义：味道是食物或气味的属性，不能用来形容楼的指标。", "性格": "搭配：“性格”用于人，不与“楼很高”所描述的建筑搭配。"}, "sentence_index": 6, "correct_answer": "容积率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小区的容积率太大，一共住了三千人。", "explanation": "这里应该用〈人口〉。容积率是面积的比值，不表示住了多少人。"}, {"text": "这瓶水的容积率是五百毫升。", "explanation": "这里应该用〈容量〉。容积率是建筑面积和用地面积的比，不指瓶子能装多少。"}, {"text": "这个小区的容积率很好，到处是树和草。", "explanation": "这里应该用〈绿化〉。容积率说的是房子面积和地的比，不指树和草的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的容积率比二点五。", "corrected_sentence": "这块地的容积率是二点五。", "error_description": "“比”用错：“比”需要接比较结果（如“比二点五高”），句中只有“比”，不成句；表示“是二点五”应直接用“是”。正确的是“这块地的容积率是二点五。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "规划部门把这块地的容积率低调了。", "corrected_sentence": "规划部门把这块地的容积率调低了。", "error_description": "“低调”与“调低”颠倒：“调低”表示调整使降低，“低调”指不张扬，“把……低调了”不成句。正确的是“规划部门把这块地的容积率调低了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
