INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25060, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "品牌就是被人知道和喜欢的东西的名字。", "primary_collocate": null, "pronunciation": "pǐn pái", "ipa": "pʰin˨˩˦ pʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个品牌的手机很受欢迎。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只买有名的品牌。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妈妈喜欢这个品牌的衣服。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想做一个中国品牌。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好品牌的东西通常比较贵。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个运动品牌的鞋我穿过。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对品牌不太在意，只看价格。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有很多国外品牌的牛奶。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌已经有一百年的历史了。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了很多钱宣传新品牌。", "target_word": "品牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大品牌", "label": "复合"}, {"form": "品牌效应", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品被大家熟悉的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是手机的名称或类别，“这个房子的手机”句意不通。"}, {"text": "品牌", "is_correct": true, "explanation": "正确：品牌是商品被大家熟悉的名称，“这个品牌的手机”指这一名称下的手机。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：修饰“手机”的应是品牌、型号等，“饮料”不能用来修饰手机。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能用来指称手机的类别，句意不通。"}], "explanations": {"房子": "语义：“房子”不是手机的名称或类别，“这个房子的手机”句意不通。", "品牌": "正确：品牌是商品被大家熟悉的名称，“这个品牌的手机”指这一名称下的手机。", "饮料": "搭配：修饰“手机”的应是品牌、型号等，“饮料”不能用来修饰手机。", "天气": "语义：“天气”不能用来指称手机的类别，句意不通。"}, "sentence_index": 0, "correct_answer": "品牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的英语品牌很高。", "explanation": "这里应该用〈水平〉。品牌指商品的名称，不能用来评价能力的高低。"}, {"text": "这棵树的品牌很大了。", "explanation": "这里应该用〈年龄〉。品牌是名称，不能用来表示树龄。"}, {"text": "这箱苹果的品牌很重。", "explanation": "这里应该用〈重量〉。品牌指商品的名称，不能用来说分量，说轻重要用“重量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是可以在意的对象，“她对桌子不太在意”与后半句的意思不连贯。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是消费选择的对象，“只看价格”与之无法衔接，句意不通。"}, {"text": "品牌", "is_correct": true, "explanation": "正确：“她对品牌不太在意，只看价格”指她不看重品牌，只看价格。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是一项运动，和“只看价格”的购物选择无关，“她对游泳不太在意，只看价格”句意不通。"}], "explanations": {"桌子": "语义：桌子不是可以在意的对象，“她对桌子不太在意”与后半句的意思不连贯。", "天空": "语义：天空不是消费选择的对象，“只看价格”与之无法衔接，句意不通。", "品牌": "正确：“她对品牌不太在意，只看价格”指她不看重品牌，只看价格。", "游泳": "语义：“游泳”是一项运动，和“只看价格”的购物选择无关，“她对游泳不太在意，只看价格”句意不通。"}, "sentence_index": 6, "correct_answer": "品牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的品牌很快，跑步很厉害。", "explanation": "这里应该用〈速度〉。品牌指商品的名称，不能用来说人跑得快慢，要用“速度”。"}, {"text": "这只小狗的品牌很纯。", "explanation": "这里应该用〈品种〉。品牌是商品的名称，说动物的种类要用品种。"}, {"text": "这块地的品牌很强，庄稼长得特别好。", "explanation": "这里应该用〈肥力〉。品牌指商品名称，不能用来说土地的肥沃程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们推出了一只新品牌。", "corrected_sentence": "他们推出了一个新品牌。", "error_description": "量词错误：“品牌”的量词应为“个”，“只”用于动物，不能用来数品牌。正确说法是“一个新品牌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司有一个很有名品牌。", "corrected_sentence": "这家公司有一个很有名的品牌。", "error_description": "定语漏“的”：“很有名”修饰“品牌”时中间要加“的”，应说“很有名的品牌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府向人们收的钱，用来修路、建学校。", "primary_collocate": null, "pronunciation": "shuì shōu", "ipa": "ʂweɪ˥˩ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "税收就是政府向人们收的钱。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新路是用税收修的。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的钱，有一部分来自税收。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们交的税，都变成了国家的税收。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税收可以用来建医院和学校。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城的税收不多，路也不太好。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有税收，政府就没有钱做事。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，税收和每个人都有关系。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司给国家的税收比小店多。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的税收比去年多了一点。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稅收", "label": "繁体"}], "register": "中性", "sense_fingerprint": "税收：政府收的钱，用来修路建学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "税收", "is_correct": true, "explanation": "税收指政府向人们收取的钱，句中的定义与之完全吻合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是付给劳动者的报酬，不是政府向人们收取的钱。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是发给员工的钱，与「向人们收的钱」方向相反。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」不能被「收」，与「钱」也不搭配。"}], "explanations": {"税收": "税收指政府向人们收取的钱，句中的定义与之完全吻合。", "工资": "语义：工资是付给劳动者的报酬，不是政府向人们收取的钱。", "奖金": "语义：奖金是发给员工的钱，与「向人们收的钱」方向相反。", "体重": "搭配：「体重」不能被「收」，与「钱」也不搭配。"}, "sentence_index": 0, "correct_answer": "税收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小区的税收每天都来打扫楼道。", "explanation": "这里应该用〈物业〉。税收是政府征收的钱，不会去打扫楼道；负责楼道卫生的是物业。"}, {"text": "他的税收全部用来买书。", "explanation": "这里应该用〈收入〉。个人的钱是收入，税收是国家的财政收入，不说个人的「税收」用来买书。"}, {"text": "他因为超速，交了一笔税收。", "explanation": "这里应该用〈罚款〉。因违章被处的钱是罚款，税收是国家依法征收的财政收入，不指违章罚款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "税收", "is_correct": true, "explanation": "没有税收，政府就没有钱做事，「税收」是政府的主要收入来源，符合句意。"}, {"text": "感情", "is_correct": false, "explanation": "语义：「感情」不是钱，政府没有感情不会导致没钱做事，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：「空气」与政府的财政无关，句意荒谬。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：「没有墨水」与「没有钱做事」之间没有因果搭配，句中需要的是钱。"}], "explanations": {"税收": "没有税收，政府就没有钱做事，「税收」是政府的主要收入来源，符合句意。", "感情": "语义：「感情」不是钱，政府没有感情不会导致没钱做事，句意不通。", "空气": "语义：「空气」与政府的财政无关，句意荒谬。", "墨水": "搭配：「没有墨水」与「没有钱做事」之间没有因果搭配，句中需要的是钱。"}, "sentence_index": 6, "correct_answer": "税收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府今年给农民的税收提高了不少。", "explanation": "这里应该用〈补助〉。政府发给农民的钱是补助，税收是政府向人们征收的钱，不能说「给农民的税收」。"}, {"text": "政府今年发行的税收又增加了。", "explanation": "这里应该用〈国债〉。政府借来的钱叫国债，税收是征收的钱，不能说「发行税收」。"}, {"text": "政府每月给公务员发的税收都很准时。", "explanation": "这里应该用〈工资〉。政府发给公务员的是工资，税收是政府向人们收取的钱，不能说「发税收」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆税收用于建一所学校。", "corrected_sentence": "这笔税收用于建一所学校。", "error_description": "量词错误：「税收」计量一笔款项时，前面应用量词「笔」，说「这笔税收」；用「辆」是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张税收用来修了新路。", "corrected_sentence": "这笔税收用来修了新路。", "error_description": "量词错误：「税收」计量一笔款项时应用量词「笔」，说「这笔税收」；「张」用于纸张等平面物，是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
