INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们为了盖房子、修路等，做的一件大事情。", "primary_collocate": null, "pronunciation": "jiàn shè xiàng mù", "ipa": "tɕjɛn˥˩ ʂɤ˥˩ ɕjɑŋ˥˩ mu˥˩", "syllable_count": 4, "sentences": [{"text": "我们城市有很多新的建设项目。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个建设项目是一座大桥。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路是一个很大的建设项目。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建设项目开始了，工人们很忙。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个建设项目里当工程师。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个建设项目要花很多钱。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有一个新建设项目。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建设项目完成了，大家都很高兴。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个建设项目让村子有了新路。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府今年做了十个建设项目。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}], "register": "通用", "sense_fingerprint": "盖房子、修路等需要很多人去做的一件大事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建设项目", "is_correct": true, "explanation": "符合句意：城市里新增的是按计划建造的工程项目。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“很多新的”修饰的应是可以建造或新增的事物，天气不能这样计数。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日属于个人，不能说一座城市有很多新的生日。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气是不可数的物质，不能与“很多新的”搭配。"}], "explanations": {"建设项目": "符合句意：城市里新增的是按计划建造的工程项目。", "天气": "语义：“很多新的”修饰的应是可以建造或新增的事物，天气不能这样计数。", "生日": "语义：生日属于个人，不能说一座城市有很多新的生日。", "空气": "搭配：空气是不可数的物质，不能与“很多新的”搭配。"}, "sentence_index": 0, "correct_answer": "建设项目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的建设项目是去公园散步。", "explanation": "这里应该用〈计划〉。建设项目指盖房子、修路等大工程，不能指出游的安排。"}, {"text": "老师给我们布置的建设项目是写一篇作文。", "explanation": "这里应该用〈作业〉。建设项目指盖房子、修路等大工程，老师布置的写作文是作业。"}, {"text": "周末的建设项目是大家一起唱歌跳舞。", "explanation": "这里应该用〈活动〉。建设项目指盖房子、修路等大工程，不是唱歌跳舞这类活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建设项目", "is_correct": true, "explanation": "符合句意：学校旁边新建的是一个工程项目。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是可以设在学校旁边的事物，与句意不符。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“学校旁边”要求可以在那里存在的实体，作业不能位于那里。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是可以新建并设在学校旁边的东西。"}], "explanations": {"建设项目": "符合句意：学校旁边新建的是一个工程项目。", "歌曲": "语义：歌曲不是可以设在学校旁边的事物，与句意不符。", "作业": "配价：“学校旁边”要求可以在那里存在的实体，作业不能位于那里。", "感冒": "语义：感冒是疾病，不是可以新建并设在学校旁边的东西。"}, "sentence_index": 6, "correct_answer": "建设项目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这档建设项目每周播出一次。", "explanation": "这里应该用〈节目〉。建设项目指盖房子、修路等工程，不能在电视上每周播出。"}, {"text": "他每天早上练的建设项目是太极拳。", "explanation": "这里应该用〈运动〉。建设项目指盖房子、修路等大事，不是锻炼身体的运动。"}, {"text": "这部建设项目讲的是一个侦探。", "explanation": "这里应该用〈电影〉。建设项目指工程，不是讲述故事的影片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府今年启动了一本建设项目。", "corrected_sentence": "政府今年启动了一个建设项目。", "error_description": "量词错误：建设项目应用“个”或“项”，“本”用于书籍，不能用来数建设项目。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆建设项目已经完工了。", "corrected_sentence": "这个建设项目已经完工了。", "error_description": "量词错误：建设项目应用“个”或“项”，“辆”用于车，不能用来数建设项目。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
