INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "租房子住的人。", "primary_collocate": null, "pronunciation": "zū hù", "ipa": "tsu˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "他是新来的租户。", "target_word": "租户", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "租户每月交房租。", "target_word": "租户", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这间房子有两个租户。", "target_word": "租户", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房东说楼上的租户很安静。", "target_word": "租户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房东给租户打了电话。", "target_word": "租户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个租户昨天搬走了。", "target_word": "租户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "租户想换一间大一点的房子。", "target_word": "租户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "租户一家人在这套小房子里住着。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个租户在这里住过三年，从来没有吵过架。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子太旧了，几个租户都想搬到新的小区去。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "租户们", "label": "复数"}], "register": "中性", "sense_fingerprint": "租户：向房东租房子居住的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "租户", "is_correct": true, "explanation": "正确：「租户」指租房子住的人，与「新来的」的语境相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：人不能是房子，「新来的」修饰人时不指房屋，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开门的工具，不能是新来的人。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「新来的」修饰人，不说「新来的空气」。"}], "explanations": {"租户": "正确：「租户」指租房子住的人，与「新来的」的语境相符。", "房子": "语义：人不能是房子，「新来的」修饰人时不指房屋，句意不通。", "钥匙": "语义：钥匙是开门的工具，不能是新来的人。", "空气": "搭配：「新来的」修饰人，不说「新来的空气」。"}, "sentence_index": 0, "correct_answer": "租户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "租户每个月都来收房租。", "explanation": "这里应该用〈房东〉。收房租的是房东，租户是交房租的人，两者角色相反。"}, {"text": "租户每月按时给工人发工资。", "explanation": "这里应该用〈雇主〉。发工资的是雇主，租户只是租房子住的人。"}, {"text": "租户负责安排小区的保安和保洁。", "explanation": "这里应该用〈物业〉。安排保安和保洁的是物业公司；租户只是租房子住的人，不管理小区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "租户", "is_correct": true, "explanation": "正确：「租户」是想换房子的人，与句意相符。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不会想换房子，句意不通。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头是设施，不能想换房子。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：「想换房子」的主语须是有意愿的人，「房价」不能有此意愿。"}], "explanations": {"租户": "正确：「租户」是想换房子的人，与句意相符。", "墙": "语义：墙不会想换房子，句意不通。", "水龙头": "语义：水龙头是设施，不能想换房子。", "房价": "搭配：「想换房子」的主语须是有意愿的人，「房价」不能有此意愿。"}, "sentence_index": 6, "correct_answer": "租户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "租户负责按时完成整栋楼的装修。", "explanation": "这里应该用〈承包商〉。装修工程由承包商负责，租户只是承租人，不负责施工。"}, {"text": "租户有权决定小区的改建方案。", "explanation": "这里应该用〈业主〉。改建方案由房屋所有者决定，租户无权决定。"}, {"text": "租户每成交一套房子都能拿到佣金。", "explanation": "这里应该用〈中介〉。佣金是促成交易的人拿的，租户不会有这种收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "房东把房子租户给了学生。", "corrected_sentence": "房东把房子租给了学生。", "error_description": "词性错误：「租户」是名词，不能作动词表示“出租”。应改为「租」，即「房东把房子租给了学生」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位租户们都想搬去新的小区。", "corrected_sentence": "几位租户都想搬去新的小区。", "error_description": "复数错误：「几位」已表示数量，「租户们」的「们」不能再与数词同用，应去掉「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
