INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家用来做大家需要的事情的钱。", "primary_collocate": null, "pronunciation": "gōng gòng cái zhèng", "ipa": "kʊŋ˥ kʊŋ˥˩ tsʰaɪ˧˥ ʈʂɤŋ˥˩", "syllable_count": 4, "sentences": [{"text": "公共财政是国家为大家花的钱。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家用公共财政修路、建学校。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政来自大家交的税。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政不够的时候，政府要少花钱。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院和学校都要用公共财政。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道公共财政是怎么花的。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政花在了哪里，大家都想知道。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱来自公共财政，用来帮助老人。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的公共财政能让生活更方便。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政用在大家需要的事情上。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "国家用来办大家需要的事的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共财政", "is_correct": true, "explanation": "符合句意：公共财政是国家为公众花的钱，正是句中所说的意思。"}, {"text": "私人财产", "is_correct": false, "explanation": "语义：私人财产属于个人，不是国家为大家花的钱。"}, {"text": "个人存款", "is_correct": false, "explanation": "语义：个人存款是个人储蓄，与国家为大家支出的钱无关。"}, {"text": "零花钱", "is_correct": false, "explanation": "语域：“零花钱”是口语化的个人小额用钱，不能指国家的公共支出。"}], "explanations": {"公共财政": "符合句意：公共财政是国家为公众花的钱，正是句中所说的意思。", "私人财产": "语义：私人财产属于个人，不是国家为大家花的钱。", "个人存款": "语义：个人存款是个人储蓄，与国家为大家支出的钱无关。", "零花钱": "语域：“零花钱”是口语化的个人小额用钱，不能指国家的公共支出。"}, "sentence_index": 0, "correct_answer": "公共财政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈的公共财政一个月只有三千块。", "explanation": "这里应该用〈工资〉。公共财政指国家用来办公共事业的钱，个人每月的收入要说工资。"}, {"text": "这个社团的公共财政还没有到账。", "explanation": "这里应该用〈经费〉。公共财政是国家的钱，社团的活动资金要说经费。"}, {"text": "他把自己的公共财政存进了银行。", "explanation": "这里应该用〈存款〉。公共财政是国家为大家花的钱，个人存进银行的钱要说存款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共财政", "is_correct": true, "explanation": "符合句意：这里问的是国家用于公共事务的钱花在了哪里。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是可以被花费的东西，“歌曲花在哪里”说不通。"}, {"text": "信件", "is_correct": false, "explanation": "搭配：“花”的对象应是钱或时间，信件不能被花。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：秘密不能被花费，与句中的钱款去向无关。"}], "explanations": {"公共财政": "符合句意：这里问的是国家用于公共事务的钱花在了哪里。", "歌曲": "语义：歌曲不是可以被花费的东西，“歌曲花在哪里”说不通。", "信件": "搭配：“花”的对象应是钱或时间，信件不能被花。", "秘密": "语义：秘密不能被花费，与句中的钱款去向无关。"}, "sentence_index": 6, "correct_answer": "公共财政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家慈善机构的公共财政帮助了很多穷人。", "explanation": "这里应该用〈捐款〉。公共财政指国家用于公共事务的钱，慈善机构募集的捐款不属于它。"}, {"text": "我的公共财政都用来买书了。", "explanation": "这里应该用〈积蓄〉。公共财政是国家用于公共事业的钱，个人的积蓄不能这样称呼。"}, {"text": "这家工厂的公共财政去年赚了很多。", "explanation": "这里应该用〈利润〉。公共财政指国家的收支体系，企业赚的钱要说利润。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国家吃公共财政修路。", "corrected_sentence": "国家用公共财政修路。", "error_description": "动词搭配错误：使用公共财政做事要说「用公共财政」，不能说「吃公共财政」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都想知道这笔公共财政是怎么吃的。", "corrected_sentence": "大家都想知道这笔公共财政是怎么花的。", "error_description": "动词搭配错误：公共财政是钱，只能说「花」，不能说「吃」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺乏", "is_correct": true, "explanation": "反义：“具备”表示拥有能力或条件，“缺乏”表示没有，二者意思相反"}, {"text": "进行", "is_correct": false, "explanation": "与“具备”没有反义或近义关系，“进行”表示开展某件事"}, {"text": "离开", "is_correct": false, "explanation": "与“具备”无关，“离开”表示离去"}, {"text": "使用", "is_correct": false, "explanation": "与“具备”无关，“使用”表示用某物做事"}], "correct_answer": "缺乏", "explanations": {"缺乏": "反义：“具备”表示拥有能力或条件，“缺乏”表示没有，二者意思相反", "进行": "与“具备”没有反义或近义关系，“进行”表示开展某件事", "离开": "与“具备”无关，“离开”表示离去", "使用": "与“具备”无关，“使用”表示用某物做事"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": false, "explanation": "与“具备”无关，“开始”表示起始"}, {"text": "缺乏", "is_correct": true, "explanation": "反义：“具备”表示拥有能力或条件，“缺乏”表示没有，二者意思相反"}, {"text": "收到", "is_correct": false, "explanation": "与“具备”无关，“收到”表示接受或得到"}, {"text": "搬迁", "is_correct": false, "explanation": "与“具备”无关，“搬迁”表示迁移居所"}], "correct_answer": "缺乏", "explanations": {"开始": "与“具备”无关，“开始”表示起始", "缺乏": "反义：“具备”表示拥有能力或条件，“缺乏”表示没有，二者意思相反", "收到": "与“具备”无关，“收到”表示接受或得到", "搬迁": "与“具备”无关，“搬迁”表示迁移居所"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "拥有某种能力或条件。", "primary_collocate": null, "pronunciation": "jù bèi", "ipa": "tɕy˥˩ peɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他具备做这件事的能力。", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师要具备耐心。", "target_word": "具备", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子具备很好的音乐天分。", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你具备这个工作需要的条件吗？", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司已经具备了生产汽车的条件。", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当医生必须具备爱心和责任感。", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不具备参加比赛的资格，因为年纪太小。", "target_word": "具备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要学好汉语，首先要具备一定的词汇量。", "target_word": "具备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市具备发展旅游的好条件。", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还没有具备自己开店的经验。", "target_word": "具备", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "具备了", "label": "完成体"}, {"form": "不具备", "label": "否定形式"}, {"form": "具备条件", "label": "常见搭配"}], "register": "书面", "sense_fingerprint": "拥有所需的能力、条件或素质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲述", "is_correct": false, "explanation": "语义：讲述指叙述故事或经历，能力不能被讲述"}, {"text": "具备", "is_correct": true, "explanation": "正确答案：具备指拥有某种能力，“他具备做这件事的能力”符合句意"}, {"text": "举办", "is_correct": false, "explanation": "搭配：举办只搭配活动、比赛，不能说举办能力"}, {"text": "宣布", "is_correct": false, "explanation": "语义：宣布指公开说出决定或消息，不用于能力"}], "explanations": {"讲述": "语义：讲述指叙述故事或经历，能力不能被讲述", "具备": "正确答案：具备指拥有某种能力，“他具备做这件事的能力”符合句意", "举办": "搭配：举办只搭配活动、比赛，不能说举办能力", "宣布": "语义：宣布指公开说出决定或消息，不用于能力"}, "sentence_index": 0, "correct_answer": "具备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的方案具备大家的期望。", "explanation": "这里应该用〈符合〉。具备用于能力、条件、素质，方案合乎期望要用符合"}, {"text": "他具备很多朋友。", "explanation": "这里应该用〈拥有〉。具备多用于能力、条件和素质，朋友等具体事物要用拥有"}, {"text": "这份套餐具备早餐。", "explanation": "这里应该用〈包括〉。具备指拥有某种能力或条件，套餐里含有的项目要用包括"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：放弃指不再坚持，与“因为年纪太小”的理由相矛盾"}, {"text": "具备", "is_correct": true, "explanation": "正确答案：具备指拥有某种资格或条件，“不具备……因为年纪太小”句意通顺"}, {"text": "取消", "is_correct": false, "explanation": "语义：取消指撤销已有的资格，与“年纪太小”的理由相矛盾"}, {"text": "停止", "is_correct": false, "explanation": "搭配：停止不能与“资格”搭配，资格不能被停止"}], "explanations": {"放弃": "语义：放弃指不再坚持，与“因为年纪太小”的理由相矛盾", "具备": "正确答案：具备指拥有某种资格或条件，“不具备……因为年纪太小”句意通顺", "取消": "语义：取消指撤销已有的资格，与“年纪太小”的理由相矛盾", "停止": "搭配：停止不能与“资格”搭配，资格不能被停止"}, "sentence_index": 6, "correct_answer": "具备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于具备了成功。", "explanation": "这里应该用〈获得〉。获得可以跟成功、胜利搭配，具备指拥有能力或条件，不能说具备成功"}, {"text": "这个周末我们好好具备了假期。", "explanation": "这里应该用〈享受〉。享受指愉快地享用，具备不能用于假期"}, {"text": "我们必须具备一张地图。", "explanation": "这里应该用〈带〉。具备指拥有能力或条件，随身携带的物品要用带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子很具备很强的学习能力。", "corrected_sentence": "这个孩子具备很强的学习能力。", "error_description": "错误：“很具备”；正确：“具备”。“具备”是动词，不能受程度副词“很”修饰", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校被具备良好的教学条件。", "corrected_sentence": "这所学校具备良好的教学条件。", "error_description": "错误：“被具备”；正确：“具备”。“具备”表示拥有，属于“有”类的状态动词，一般不用于“被”字句，应直接说“具备良好的教学条件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
