INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管理或处理事情，让大家遵守规则。", "primary_collocate": null, "pronunciation": "zhì lǐ", "ipa": "tʂɻ̩˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "市长想办法治理这个城市的交通。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府正在治理街上乱停车的问题。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府治理了这条河，现在河水干净多了。", "target_word": "治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要治理好一个国家，需要好的规则。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校用新办法治理校园里乱扔垃圾的现象。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都守规则，这个城市才好治理。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们治理这个村子已经十年了。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "治理一个大城市比治理一个小村难得多。", "target_word": "治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府用法律治理网上的乱象，让大家守规则。", "target_word": "治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街以前很乱，经过治理，现在很干净。", "target_word": "治理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "治理好", "label": "结果补语"}, {"form": "治理了", "label": "体标"}, {"form": "治理过", "label": "体标"}, {"form": "综合治理", "label": "复合"}], "register": "书面语", "sense_fingerprint": "治理：管理并处理事务，使人们守规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治理", "is_correct": true, "explanation": "正确：治理是管理并处理事务，“想办法治理交通”符合这一意思。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能说“种植交通”。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去某处看或学习，不表示管理交通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”表示毁坏，与“想办法”改善交通的意图相反。"}], "explanations": {"治理": "正确：治理是管理并处理事务，“想办法治理交通”符合这一意思。", "种植": "搭配：“种植”的对象是植物，不能说“种植交通”。", "参观": "语义：“参观”指去某处看或学习，不表示管理交通。", "烧毁": "语义：“烧毁”表示毁坏，与“想办法”改善交通的意图相反。"}, "sentence_index": 0, "correct_answer": "治理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位经理很会治理自己的汽车。", "explanation": "这里应该用〈保养〉。“治理”用于社会、环境等大范围的问题，爱车的日常维护要说“保养”。"}, {"text": "医生很快治理好了他的感冒。", "explanation": "这里应该用〈治疗〉。“治理”用于社会、环境等大范围的问题，治病要说“治疗”。"}, {"text": "他很快治理了那封邮件。", "explanation": "这里应该用〈处理〉。“治理”针对较大范围的社会或环境问题，处理一封邮件要说“处理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治理", "is_correct": true, "explanation": "正确：“治理这个村子已经十年了”符合管理村子这一意思。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能用于村子。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能说“洗这个村子”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”要求歌曲、戏曲等对象，与村子不符。"}], "explanations": {"治理": "正确：“治理这个村子已经十年了”符合管理村子这一意思。", "吃": "语义：“吃”的对象是食物，不能用于村子。", "洗": "搭配：“洗”的对象是物品或身体，不能说“洗这个村子”。", "唱": "语义：“唱”要求歌曲、戏曲等对象，与村子不符。"}, "sentence_index": 6, "correct_answer": "治理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人治理了坏掉的电脑。", "explanation": "这里应该用〈修理〉。“治理”不用于物品的维修，坏掉的电脑要说“修理”。"}, {"text": "农民治理了很多鸡。", "explanation": "这里应该用〈饲养〉。“治理”不用于动物，养鸡要说“饲养”。"}, {"text": "老师治理了今天的作业。", "explanation": "这里应该用〈布置〉。“治理”指管理大范围的社会事务，布置作业要说“布置”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府治理了过这条河。", "corrected_sentence": "市政府治理过这条河。", "error_description": "体标重复：“治理”后只能用一个体标，应说“治理过这条河”，不能同时用“了”和“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子治理的很好。", "corrected_sentence": "这个村子治理得很好。", "error_description": "程度补语：“治理”和“很好”之间应用“得”，不能用“的”，应说“治理得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
