INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25076, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带着别人走或教别人怎么做。", "primary_collocate": null, "pronunciation": "yǐn dǎo", "ipa": "in˨˩ tɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "老师引导学生自己找答案。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员引导我们走进会议室。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈引导孩子说出自己的想法。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游引导大家排队上车。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会引导学生多想问题。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直引导朋友去做正确的事。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生引导病人慢慢放松下来。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸引导我养成读书的习惯。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员把客人引导到座位上。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用问题引导大家一起讨论。", "target_word": "引导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引导了", "label": "完成体"}, {"form": "引导着", "label": "持续体"}, {"form": "引导过", "label": "经历体"}, {"form": "引导者", "label": "复合词"}], "register": "通用", "sense_fingerprint": "带人走或教人怎么做；老师、导游等引领他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引导", "is_correct": true, "explanation": "正确。“引导”指带领或启发，让学生自己动脑找答案。"}, {"text": "代替", "is_correct": false, "explanation": "语义：“代替”是替别人去做，与“学生自己找答案”相矛盾。"}, {"text": "包办", "is_correct": false, "explanation": "语义：“包办”是替别人全部做完，与“自己找”的意思相反。"}, {"text": "执行", "is_correct": false, "explanation": "搭配：“执行”的宾语多是任务、命令，不能说“执行学生”。"}], "explanations": {"引导": "正确。“引导”指带领或启发，让学生自己动脑找答案。", "代替": "语义：“代替”是替别人去做，与“学生自己找答案”相矛盾。", "包办": "语义：“包办”是替别人全部做完，与“自己找”的意思相反。", "执行": "搭配：“执行”的宾语多是任务、命令，不能说“执行学生”。"}, "sentence_index": 0, "correct_answer": "引导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师引导完了这些作业。", "explanation": "这里应该用〈批改〉。“引导”的对象是人或思路，不能用于作业，批改作业才用“批改”。"}, {"text": "我们想引导一箱书去图书馆。", "explanation": "这里不这么用。“引导”的对象是人或思路，不能用于搬运成箱的物品，应说“搬”。"}, {"text": "我用力引导了一下那扇门。", "explanation": "这里应该用〈推〉。“引导”的对象是人或思路，不能用于门，推门才用“推”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引导", "is_correct": true, "explanation": "正确。“引导”指带领或启发，让病人慢慢放松下来。"}, {"text": "逼迫", "is_correct": false, "explanation": "语义：“逼迫”是强迫，与“慢慢放松”的意思相矛盾。"}, {"text": "惊吓", "is_correct": false, "explanation": "语义：“惊吓”会让人紧张，与“放松”的结果相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：“驱赶”多用于动物或人群，不说“驱赶病人”。"}], "explanations": {"引导": "正确。“引导”指带领或启发，让病人慢慢放松下来。", "逼迫": "语义：“逼迫”是强迫，与“慢慢放松”的意思相矛盾。", "惊吓": "语义：“惊吓”会让人紧张，与“放松”的结果相反。", "驱赶": "搭配：“驱赶”多用于动物或人群，不说“驱赶病人”。"}, "sentence_index": 6, "correct_answer": "引导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天引导完了那本小说。", "explanation": "这里应该用〈读〉。“引导”的对象是人或思路，不能用于阅读书籍，读书才用“读”。"}, {"text": "他引导了一台电脑去修理。", "explanation": "这里应该用〈送〉。“引导”的对象是人，不能以机器为宾语，送去修理才用“送”。"}, {"text": "风把树叶引导到了地上。", "explanation": "这里应该用〈吹〉。“引导”需要有意识的施事者，风把树叶刮到地上应说“吹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师很引导学生思考。", "corrected_sentence": "老师引导学生思考。", "error_description": "副词误用：“很”是程度副词，一般不修饰“引导”这类动作动词，这里不能说“很引导”。正确说法是「老师引导学生思考。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务员把客人引导门口。", "corrected_sentence": "服务员把客人引导到门口。", "error_description": "“引导”后面需要表示去向的“到”，漏掉“到”句子不通。正确说法是「服务员把客人引导到门口。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
