INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一个东西抓住另一个东西，不容易分开。", "primary_collocate": null, "pronunciation": "nián xìng", "ipa": "njɛn˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "糖浆的粘性很大。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "胶水有很强的粘性。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种纸条没有粘性。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "饭粒粘在锅壁上，粘性很大，很难刮下来。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年糕的粘性比米饭大很多。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "泥巴的粘性让鞋子很难拔出来。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种便利贴的粘性刚好，贴着不掉。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后路上的泥土粘性很大，车轮转得很慢。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把胶带贴在墙上，粘性太小，一会儿就掉了。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕时，面粉加水后会有粘性，手上要涂一点油。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黏性", "label": "异形词"}], "register": "中性", "sense_fingerprint": "粘性：东西能粘住别的东西、不易分开的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粘性", "is_correct": true, "explanation": "正确：「粘性」指物体粘住别的东西的特性，糖浆的粘性可以很大。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：糖浆没有年龄，「很大」的说法也不合。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：糖浆是液体，不说硬度很大。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色通常说深或浅，不说「颜色很大」。"}], "explanations": {"粘性": "正确：「粘性」指物体粘住别的东西的特性，糖浆的粘性可以很大。", "年龄": "语义：糖浆没有年龄，「很大」的说法也不合。", "硬度": "语义：糖浆是液体，不说硬度很大。", "颜色": "搭配：颜色通常说深或浅，不说「颜色很大」。"}, "sentence_index": 0, "correct_answer": "粘性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰块放进冰箱，它的粘性会变大。", "explanation": "这里应该用〈硬度〉。冰块变硬说的是硬度，粘性指粘住别的东西的特性。"}, {"text": "气球充气以后，粘性会变小。", "explanation": "这里应该用〈弹性〉。充气后的变化说的是弹性，粘性指粘住的程度。"}, {"text": "这扇窗的粘性很好，能看清楚外面的景色。", "explanation": "这里应该用〈透明度〉。能看清外面的景色靠的是透明度，粘性指粘住别的东西的特性，与能否看清无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粘性", "is_correct": true, "explanation": "正确：「粘性」是便利贴贴着不掉的特性，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与便利贴“贴着不掉”无关，句意不通。"}, {"text": "保质期", "is_correct": false, "explanation": "语义：保质期与贴着不掉无关，句意不通。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味与贴着不掉无关，句意不通。"}], "explanations": {"粘性": "正确：「粘性」是便利贴贴着不掉的特性，与句意相符。", "颜色": "语义：颜色与便利贴“贴着不掉”无关，句意不通。", "保质期": "语义：保质期与贴着不掉无关，句意不通。", "香味": "语义：香味与贴着不掉无关，句意不通。"}, "sentence_index": 6, "correct_answer": "粘性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种金属的粘性很高，要很高的温度才能熔化。", "explanation": "这里应该用〈熔点〉。要很高的温度才能熔化说明的是熔点，粘性不是熔化温度。"}, {"text": "这根绳子的粘性很好，不容易断。", "explanation": "这里应该用〈韧性〉。不容易断说明韧性好，粘性指粘住别的东西的特性。"}, {"text": "这块布的粘性很好，穿很久也不容易磨破。", "explanation": "这里应该用〈耐磨性〉。穿很久不磨破说的是耐磨性，粘性指粘住别的东西的特性，与布料磨损无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种标签的粘性得很好，不会掉下来。", "corrected_sentence": "这种标签的粘性很好，不会掉下来。", "error_description": "助词错误：「粘性」后不能加「得」，修饰形容词应直接用「很」，应说「粘性很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种胶带的粘性的差，容易脱落。", "corrected_sentence": "这种胶带的粘性很差，容易脱落。", "error_description": "错误的形式是「粘性的差」，正确的形式是「粘性很差」。「的」不能用在形容词作谓语之前，修饰形容词应用「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
