INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做得好或取得好成绩时，别人给你的表扬或好东西。", "primary_collocate": null, "pronunciation": "jiǎng lì", "ipa": "tɕjɑŋ˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "这是老师给我的奖励。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到了一份很特别的奖励。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，我的奖励是一个大蛋糕。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做完作业，妈妈给了他一个奖励。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小狗来说，好吃的东西就是最好的奖励。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底，公司发给大家一笔奖励。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "努力了一年，这是对我的奖励。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是为了奖励才去帮助别人的。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试进步很大，你想要什么奖励？", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一名的奖励是一张电影票。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "獎勵", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奖励：做得好时得到的表扬或礼物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奖励", "is_correct": true, "explanation": "正确。奖励 jiǎng lì，指做得好时别人给的表扬或好东西。"}, {"text": "讲理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，讲理指说道理，意思不同。"}, {"text": "简历", "is_correct": false, "explanation": "jiǎn 与 jiǎng 的韵尾不同（n 与 ng），简历指个人履历材料，意思不同。"}, {"text": "脚力", "is_correct": false, "explanation": "jiǎo 与 jiǎng 的韵母不同（ao 与 iang），脚力指步行或跑动的力量，意思不同。"}], "explanations": {"奖励": "正确。奖励 jiǎng lì，指做得好时别人给的表扬或好东西。", "讲理": "lǐ（第三声）与 lì（第四声）声调不同，讲理指说道理，意思不同。", "简历": "jiǎn 与 jiǎng 的韵尾不同（n 与 ng），简历指个人履历材料，意思不同。", "脚力": "jiǎo 与 jiǎng 的韵母不同（ao 与 iang），脚力指步行或跑动的力量，意思不同。"}, "sentence_index": null, "correct_answer": "奖励"}, "level_3": {"options": [{"text": "奖励", "is_correct": true, "explanation": "正确。“这是老师给我的奖励”中，“奖励”指老师给的奖品或表扬。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或物的重量，不是老师能给我的东西。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“老师给我的脾气”说不通，“给”不与“脾气”搭配。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是医院的病情记录，与老师给我的东西无关。"}], "explanations": {"奖励": "正确。“这是老师给我的奖励”中，“奖励”指老师给的奖品或表扬。", "体重": "语义：体重是人或物的重量，不是老师能给我的东西。", "脾气": "搭配：“老师给我的脾气”说不通，“给”不与“脾气”搭配。", "病历": "语义：病历是医院的病情记录，与老师给我的东西无关。"}, "sentence_index": 0, "correct_answer": "奖励"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我生日那天，朋友送给我一份奖励。", "explanation": "这里应该用〈礼物〉。奖励是因做得好而给的，生日的赠品用“礼物”。"}, {"text": "学校每学期都向我收取奖励。", "explanation": "这里应该用〈学费〉。“奖励”是别人给的表扬或好东西，学校向学生收取的钱要用“学费”。"}, {"text": "他因为犯规，得到了一份奖励。", "explanation": "这里应该用〈处罚〉。奖励是因做得好而给的好处，因犯规受到的处理要说「处罚」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奖励", "is_correct": true, "explanation": "正确。“努力了一年”之后，“这是对我的奖励”指对努力的回报。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”是对过错的处理，与“努力了一年”的语境相反。"}, {"text": "处分", "is_correct": false, "explanation": "语义：“处分”是对违纪行为的处理，与努力的语境冲突。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“这是对我的批评”指对错误的指责，与“努力了一年”不搭。"}], "explanations": {"奖励": "正确。“努力了一年”之后，“这是对我的奖励”指对努力的回报。", "惩罚": "语义：“惩罚”是对过错的处理，与“努力了一年”的语境相反。", "处分": "语义：“处分”是对违纪行为的处理，与努力的语境冲突。", "批评": "搭配：“这是对我的批评”指对错误的指责，与“努力了一年”不搭。"}, "sentence_index": 6, "correct_answer": "奖励"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月的奖励是五千块，用来交房租。", "explanation": "这里应该用〈工资〉。奖励是因做得好而额外得到的，每个月固定拿的劳动报酬是工资。"}, {"text": "他上课说话，得到了老师的奖励。", "explanation": "这里应该用〈批评〉。奖励是因做得好而给的，上课说话受到的是批评。"}, {"text": "第一名得到了一头奖励，是一张电影票。", "explanation": "这里数量词应用〈份〉。“头”用于牲畜，不用于奖励，奖励用“份”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是老师给我的一只奖励。", "corrected_sentence": "这是老师给我的一份奖励。", "error_description": "“奖励”的量词应为“份”，“只”用于动物或成对的东西，不能用于奖励。正确的是“一份奖励”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她拿到了一张奖励。", "corrected_sentence": "她拿到了一份奖励。", "error_description": "量词错误：“奖励”的量词应为“份”，“张”用于纸张、票据等平面物，不用于奖励。正确的是“她拿到了一份奖励”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
