INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把脏水变干净。", "primary_collocate": null, "pronunciation": "wū shuǐ chǔ lǐ", "ipa": "u˥ ʂueɪ˨˩˦ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "污水处理就是把脏水变干净。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的脏水也需要污水处理。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有污水处理，河水会越来越脏。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污水处理让河水又变清了。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市每天都要做污水处理。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了污水处理是怎么回事。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的污水处理能让脏水变得很干净。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的污水处理做得不太好。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用过的水要经过污水处理再放回河里。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是研究污水处理的新办法。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "污水处理厂", "label": "复合"}, {"form": "污水处理系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "污水处理：把脏水变干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下水道", "is_correct": false, "explanation": "配价：“下水道”是设施，不能作“就是把脏水变干净”这一动作的主语。"}, {"text": "污水处理", "is_correct": true, "explanation": "污水处理就是把脏水变干净，主语与后半句的意思一致。"}, {"text": "交通管理", "is_correct": false, "explanation": "语义：交通管理与把脏水变干净毫无关系，这样说不通。"}, {"text": "园林绿化", "is_correct": false, "explanation": "语义：园林绿化是美化环境，不是把脏水变干净的过程。"}], "explanations": {"下水道": "配价：“下水道”是设施，不能作“就是把脏水变干净”这一动作的主语。", "污水处理": "污水处理就是把脏水变干净，主语与后半句的意思一致。", "交通管理": "语义：交通管理与把脏水变干净毫无关系，这样说不通。", "园林绿化": "语义：园林绿化是美化环境，不是把脏水变干净的过程。"}, "sentence_index": 0, "correct_answer": "污水处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一只污水处理。", "explanation": "这里应该用〈净水器〉。污水处理是把脏水变干净的过程，不是可以买回家的东西，“只”也不能用来计量它。"}, {"text": "他是一位污水处理，负责整理档案。", "explanation": "这里指人，应该用〈污水处理员〉。污水处理指净化脏水的过程，不指人。"}, {"text": "他每天用污水处理洗碗。", "explanation": "这里应该用〈清水〉。清水可以洗碗，污水处理是把脏水变干净的过程，不是洗碗用的水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音响", "is_correct": false, "explanation": "语义：音响是播放声音的设备，不能让脏水变得干净。"}, {"text": "污水处理", "is_correct": true, "explanation": "好的污水处理能让脏水变干净，主语与后半句的意思一致。"}, {"text": "发型", "is_correct": false, "explanation": "语义：“发型”描述外表，不能让脏水变得干净。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水会把水弄脏，不能让脏水变干净，句子的意思正好相反。"}], "explanations": {"音响": "语义：音响是播放声音的设备，不能让脏水变得干净。", "污水处理": "好的污水处理能让脏水变干净，主语与后半句的意思一致。", "发型": "语义：“发型”描述外表，不能让脏水变得干净。", "墨水": "语义：墨水会把水弄脏，不能让脏水变干净，句子的意思正好相反。"}, "sentence_index": 6, "correct_answer": "污水处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子每天都喝污水处理。", "explanation": "这里应该用〈净水〉。净水可以饮用，污水处理是废水的净化过程，不能喝。"}, {"text": "那家饭店的汤里加了污水处理。", "explanation": "这里应该用〈调料〉之类的食材。污水处理指废水的净化过程，不能加进食物里。"}, {"text": "老板让我们把污水处理拿去开会。", "explanation": "这里应该用〈会议材料〉。污水处理是净化废水的过程，不是可以拿去开会的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个厂每天做一只污水处理。", "corrected_sentence": "这个厂每天做一次污水处理。", "error_description": "错误在于量词。污水处理是一种过程，计算做了几回用“次”；“只”用于动物，不能用来计量它。应说“每天做一次污水处理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工厂认真污水处理。", "corrected_sentence": "这个工厂认真做污水处理。", "error_description": "错误在于缺少动词“做”。“认真”后面要带动词，应说“认真做污水处理”，直接说“认真污水处理”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
