INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个事情或问题的其中一部分。", "primary_collocate": null, "pronunciation": "fāng miàn", "ipa": "faŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这件事要从几个方面来看。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先谈钱的方面，再谈时间。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在经济方面遇到了困难。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题的一个方面已经解决了。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在哪方面需要帮助？", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在教育方面工作了十年。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，数学方面我最担心。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个方面都很重要。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在交通方面，这个城市很方便。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面天气不好，另一方面路也很远。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各方面", "label": "复合"}, {"form": "方方面面", "label": "重叠"}], "register": "中性", "sense_fingerprint": "一件事或一个问题的其中一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方面", "is_correct": true, "explanation": "fāng miàn（方面）指一件事或一个问题的其中一部分，此处正合句意。"}, {"text": "当面", "is_correct": false, "explanation": "dāng（第一声）与 fāng 声母不同，意思是“当面”，指面对面。"}, {"text": "方便", "is_correct": false, "explanation": "biàn（第四声）与 miàn 声母不同，意思是“方便”，指便利、不麻烦。"}, {"text": "汤面", "is_correct": false, "explanation": "tāng（第一声）与 fāng 声母不同，意思是“汤面”，指带汤的面条。"}], "explanations": {"方面": "fāng miàn（方面）指一件事或一个问题的其中一部分，此处正合句意。", "当面": "dāng（第一声）与 fāng 声母不同，意思是“当面”，指面对面。", "方便": "biàn（第四声）与 miàn 声母不同，意思是“方便”，指便利、不麻烦。", "汤面": "tāng（第一声）与 fāng 声母不同，意思是“汤面”，指带汤的面条。"}, "sentence_index": null, "correct_answer": "方面"}, "level_3": {"options": [{"text": "方面", "is_correct": true, "explanation": "“从几个方面来看”指从几个侧面看问题，此处正合句意。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：“盒子”不是可以用来看问题的视角，句子读不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“从……来看”要接视角或侧面，“饭菜”不能作视角。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是具体物体，不能指看问题的角度，句意不通。"}], "explanations": {"方面": "“从几个方面来看”指从几个侧面看问题，此处正合句意。", "盒子": "语义：“盒子”不是可以用来看问题的视角，句子读不通。", "饭菜": "搭配：“从……来看”要接视角或侧面，“饭菜”不能作视角。", "石头": "语义：“石头”是具体物体，不能指看问题的角度，句意不通。"}, "sentence_index": 0, "correct_answer": "方面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的一个方面来了三位客人。", "explanation": "这里应该用〈朋友〉。方面指事物或问题的侧面，不指人。"}, {"text": "他买了三张方面。", "explanation": "这里应该用〈纸〉。“张”用于纸等平面的东西，“方面”是抽象名词，不能当作可计量的物品。"}, {"text": "这家饭店的方面很好吃。", "explanation": "这里应该用〈菜〉。方面指侧面，不指可以吃的菜肴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "方面", "is_correct": true, "explanation": "fāng miàn（方面）指一件事或一个问题的其中一部分，此处正合句意。"}, {"text": "方片", "is_correct": false, "explanation": "piàn（第四声）与 miàn 声母不同，意思是“方片”，指扑克牌中的方块花色。"}, {"text": "翻面", "is_correct": false, "explanation": "fān（第一声）与 fāng 韵母不同，意思是“翻面”，指把东西翻过来。"}, {"text": "锋面", "is_correct": false, "explanation": "fēng（第一声）与 fāng 韵母不同，意思是“锋面”，指气象中冷暖气团的交界面。"}], "explanations": {"方面": "fāng miàn（方面）指一件事或一个问题的其中一部分，此处正合句意。", "方片": "piàn（第四声）与 miàn 声母不同，意思是“方片”，指扑克牌中的方块花色。", "翻面": "fān（第一声）与 fāng 韵母不同，意思是“翻面”，指把东西翻过来。", "锋面": "fēng（第一声）与 fāng 韵母不同，意思是“锋面”，指气象中冷暖气团的交界面。"}, "sentence_index": null, "correct_answer": "方面"}, "level_3": {"options": [{"text": "方面", "is_correct": true, "explanation": "“数学方面”指数学这一方面，此处是担心的对象，正合句意。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：“数学杯子”不成立，杯子不是考试中让人担心的部分。"}, {"text": "门口", "is_correct": false, "explanation": "搭配：“数学门口”不成立，门口是地点，不是考试的一部分。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：“数学香蕉”说不通，香蕉是水果，不是考试的一部分。"}], "explanations": {"方面": "“数学方面”指数学这一方面，此处是担心的对象，正合句意。", "杯子": "语义：“数学杯子”不成立，杯子不是考试中让人担心的部分。", "门口": "搭配：“数学门口”不成立，门口是地点，不是考试的一部分。", "香蕉": "语义：“数学香蕉”说不通，香蕉是水果，不是考试的一部分。"}, "sentence_index": 6, "correct_answer": "方面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他约我在下午的方面见面。", "explanation": "这里应该用〈时间〉。方面指事物或问题的侧面，不能指时间。"}, {"text": "这棵树的方面很高大。", "explanation": "这里应该用〈树干〉。方面指侧面问题，不能指具体的物体部分。"}, {"text": "他把方面放进了书包。", "explanation": "这里应该用〈课本〉。方面指事情或问题的一部分，是抽象的，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们先谈价格的一张方面，再谈交货时间。", "corrected_sentence": "我们先谈价格的一个方面，再谈交货时间。", "error_description": "“方面”要用“个”计量，不能用“张”；“张”多用于纸、桌子等平面的东西，应说“一个方面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项计划的两只方面都很重要。", "corrected_sentence": "这项计划的两个方面都很重要。", "error_description": "“方面”要用“个”计量，不能用“只”；“只”多用于动物或成对的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
