INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25086, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "融资就是找钱来用。", "primary_collocate": null, "pronunciation": "róng zī", "ipa": "ʐʊŋ˧˥ tsɹ̩˥", "syllable_count": 2, "sentences": [{"text": "这家小公司需要融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想向银行融资一百万元。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司去年成功融资了两千万元。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公司第一年最难的是融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了开店，到处找人融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "融资以后，公司请了很多新员工。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目已经融资过三次。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想融资，但是没有人愿意投钱。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司融资成功了，大家都很高兴。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正忙着跟投资人谈融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "融资了", "label": "体标"}, {"form": "融资过", "label": "体标"}, {"form": "融资额", "label": "复合"}, {"form": "融资渠道", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司或个人为了做事而筹集资金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融资", "is_correct": true, "explanation": "正确：“需要融资”表示公司需要筹集资金，与“小公司”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：公司不能睡觉，“这家小公司需要睡觉”的意思不通。"}, {"text": "生育", "is_correct": false, "explanation": "搭配：“生育”的对象是人或动物，不能用于公司。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣是人的情绪表现，公司不会哭泣，句子不通。"}], "explanations": {"融资": "正确：“需要融资”表示公司需要筹集资金，与“小公司”的语境相符。", "睡觉": "语义：公司不能睡觉，“这家小公司需要睡觉”的意思不通。", "生育": "搭配：“生育”的对象是人或动物，不能用于公司。", "哭泣": "语义：哭泣是人的情绪表现，公司不会哭泣，句子不通。"}, "sentence_index": 0, "correct_answer": "融资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子融资了一个苹果。", "explanation": "这里应该用〈吃〉。融资是筹集资金，不能用于苹果；吃苹果要说吃。"}, {"text": "我们要融资用水。", "explanation": "这里应该用〈节约〉。融资指筹集资金，不能用于用水；节约用水要说节约。"}, {"text": "他去超市融资。", "explanation": "这里应该用〈付款〉。融资是筹集资金，不是支付货款；在超市买东西要说付款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融资", "is_correct": true, "explanation": "正确：“已经融资过三次”表示做过的动作，与“这个项目”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”需要饮品做宾语，“这个项目已经喝过三次”的意思不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是人的动作，项目不会散步，“这个项目已经散步过三次”说不通。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是人的病症，项目不会感冒，句子不通。"}], "explanations": {"融资": "正确：“已经融资过三次”表示做过的动作，与“这个项目”的语境相符。", "喝": "语义：“喝”需要饮品做宾语，“这个项目已经喝过三次”的意思不通。", "散步": "语义：散步是人的动作，项目不会散步，“这个项目已经散步过三次”说不通。", "感冒": "语义：感冒是人的病症，项目不会感冒，句子不通。"}, "sentence_index": 6, "correct_answer": "融资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生在融资病人。", "explanation": "这里应该用〈治疗〉。融资指筹集资金，不能用于病人；医生给病人看病要说治疗。"}, {"text": "他前天融资了一场比赛。", "explanation": "这里应该用〈赢〉。融资是找钱，不能用于比赛；比赛取胜要说赢。"}, {"text": "他每天融资上班。", "explanation": "这里应该用〈开车〉。融资是筹集资金，不是交通方式；每天开车上班要说开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅正在向朋友融资过。", "corrected_sentence": "这家餐厅正在向朋友融资。", "error_description": "“正在”表示动作正在进行，与表示曾经经历的“过”不能同用，应为“正在向朋友融资”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经向朋友融资了过。", "corrected_sentence": "他们已经向朋友融资过。", "error_description": "“融资了过”错误，应为“融资过”。“过”表示曾经做过的经历，已经带有完成的意味，后面不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减量", "is_correct": true, "explanation": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。"}, {"text": "总额", "is_correct": false, "explanation": "总额指全部数量之和，与“增量”的增加部分不构成反义。"}, {"text": "面积", "is_correct": false, "explanation": "面积指平面或表面的大小，与“增加的数量”无关，不构成反义。"}, {"text": "比例", "is_correct": false, "explanation": "比例指两个量之间的比，与“增加的数量”不是反义关系。"}], "correct_answer": "减量", "explanations": {"减量": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。", "总额": "总额指全部数量之和，与“增量”的增加部分不构成反义。", "面积": "面积指平面或表面的大小，与“增加的数量”无关，不构成反义。", "比例": "比例指两个量之间的比，与“增加的数量”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减量", "is_correct": true, "explanation": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。"}, {"text": "速度", "is_correct": false, "explanation": "速度指物体运动的快慢，与“增加的数量”无关，不构成反义。"}, {"text": "体积", "is_correct": false, "explanation": "体积指物体所占空间的大小，与“增加的数量”不是反义关系。"}, {"text": "质地", "is_correct": false, "explanation": "质地指物质的结构或质量特征，与“增加的数量”不构成反义。"}], "correct_answer": "减量", "explanations": {"减量": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。", "速度": "速度指物体运动的快慢，与“增加的数量”无关，不构成反义。", "体积": "体积指物体所占空间的大小，与“增加的数量”不是反义关系。", "质地": "质地指物质的结构或质量特征，与“增加的数量”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "增加的数量，比如从3个变成5个。", "primary_collocate": null, "pronunciation": "zēng liàng", "ipa": "tsəŋ˥ liaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "从三个变成五个，增量是两个。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的增量只有十个。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书从十本到十五本，增量是五本。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算出了苹果的增量。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年班里的增量是三个学生。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "增量就是多出来的那部分。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次加水，水杯里的水增量是一百毫升。", "target_word": "增量", "complexity_tier": "T3", "furigana": "zhè cì jiāshuǐ, shuǐbēi lǐ de shuǐ zēngliàng shì yìbǎi háoshēng", "sentence_source": "generated"}, {"text": "去年的增量比今年大。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每天客人的增量不多。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的零花钱每月有五十元的增量。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "净增量", "label": "复合"}], "register": "通用", "sense_fingerprint": "增加出来的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增量", "is_correct": true, "explanation": "正确。“从三个变成五个，增量是两个”中，增量指增加出来的数量。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是数量的增加部分，与“从三个变成五个”的情境冲突。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是数量，与“三个变成五个”的情境冲突。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“是两个”的数量表达不能与“名字”搭配。"}], "explanations": {"增量": "正确。“从三个变成五个，增量是两个”中，增量指增加出来的数量。", "价格": "语义：价格不是数量的增加部分，与“从三个变成五个”的情境冲突。", "颜色": "语义：颜色不是数量，与“三个变成五个”的情境冲突。", "名字": "搭配：“是两个”的数量表达不能与“名字”搭配。"}, "sentence_index": 0, "correct_answer": "增量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他算出苹果的增量是百分之二十。", "explanation": "这里应该用〈增长率〉。增长率用百分比表示增长快慢；增量是增加的数量，不能用百分比表示。"}, {"text": "这箱苹果的增量是一百个，这就是箱里的全部。", "explanation": "这里应该用〈总数〉。增量是增加的部分，不是全部数量；“箱里的全部”要用总数。"}, {"text": "他算出了一只增量。", "explanation": "这里应该用量词〈个〉或〈部分〉。增量不用“只”，“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增量", "is_correct": true, "explanation": "正确。“水杯里的水增量是一百毫升”表示加水后增加的体积，与句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是可以用毫升计量的增加量，与“加水”的情境冲突。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用毫升计量，与“加水”的情境冲突。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“毫升”是体积单位，不能用来计量“重量”，二者不搭配。"}], "explanations": {"增量": "正确。“水杯里的水增量是一百毫升”表示加水后增加的体积，与句意相符。", "味道": "语义：味道不是可以用毫升计量的增加量，与“加水”的情境冲突。", "颜色": "语义：颜色不能用毫升计量，与“加水”的情境冲突。", "重量": "搭配：“毫升”是体积单位，不能用来计量“重量”，二者不搭配。"}, "sentence_index": 6, "correct_answer": "增量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明的成绩增量很快。", "explanation": "这里应该用〈增速〉。增速指增长的快慢，可以说“很快”；增量是增加的数量，不说快慢。"}, {"text": "小明的零花钱每月增量是百分之十。", "explanation": "这里应该用〈增幅〉。增幅用百分比表示增长比例；增量是绝对数量，不能用百分比表示。"}, {"text": "小明每月有一只五十元的增量。", "explanation": "这里应该用量词〈笔〉或〈部分〉。增量不用“只”，“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的一只增量是五个。", "corrected_sentence": "这次的增量是五个。", "error_description": "量词错误：“增量”是抽象数量，不用“一只”计量，“只”用于动物等。应说“这次的增量是五个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的零花钱增量们是五十元。", "corrected_sentence": "这个月的零花钱增量是五十元。", "error_description": "后缀错误：「们」只用于指人的名词，“增量”是抽象名词，不能加「们」表示复数。应说“这个月的零花钱增量是五十元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
