INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "债券就像一个借条，你借钱给别人，别人给你一张纸，以后会还你钱。", "primary_collocate": null, "pronunciation": "zhài quàn", "ipa": "ʈʂai˥˩ tɕʰyɛn˥˩", "syllable_count": 2, "sentences": [{"text": "债券就像一张借条。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你买债券，就是借钱给别人。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张债券上写着还钱的日期。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李把债券放在抽屉里。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷留着一张旧债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了债券，别人以后要还钱。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "债券到期时，我会拿回钱。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我讲了什么是债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存下来的钱买了债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张债券是向政府借钱的凭证。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "公司债券", "label": "复合"}], "register": "通用", "sense_fingerprint": "像借条一样的借钱凭证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25090, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确答案：债券 zhàiquàn，指像借条一样的借钱凭证，与听到的读音一致。"}, {"text": "债权", "is_correct": false, "explanation": "债权 zhàiquán 与 债券 zhàiquàn 只有第二个字声调不同（quán 第二声，quàn 第四声），意思是债权人享有的请求权。"}, {"text": "彩券", "is_correct": false, "explanation": "彩券 cǎiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh）且声调不同，意思是彩票。"}, {"text": "财权", "is_correct": false, "explanation": "财权 cáiquán 与 债券 zhàiquàn 第一个字声母与声调不同（c 与 zh，第二声与第四声），第二个字声调也不同，意思是支配财务的权力。"}, {"text": "菜券", "is_correct": false, "explanation": "菜券 càiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh），声调相同（第四声），意思是买菜用的购物券。"}], "explanations": {"债券": "正确答案：债券 zhàiquàn，指像借条一样的借钱凭证，与听到的读音一致。", "债权": "债权 zhàiquán 与 债券 zhàiquàn 只有第二个字声调不同（quán 第二声，quàn 第四声），意思是债权人享有的请求权。", "彩券": "彩券 cǎiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh）且声调不同，意思是彩票。", "财权": "财权 cáiquán 与 债券 zhàiquàn 第一个字声母与声调不同（c 与 zh，第二声与第四声），第二个字声调也不同，意思是支配财务的权力。", "菜券": "菜券 càiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh），声调相同（第四声），意思是买菜用的购物券。"}, "sentence_index": null, "correct_answer": "债券"}, "level_3": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确。“债券就像一张借条”中，债券是一种借钱凭证，与借条的比喻相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是借钱凭证，与“借条”的比喻冲突。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能像借条一样记录还钱。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是借钱凭证，不能像借条一样记录还钱，与“借条”的比喻冲突。"}], "explanations": {"债券": "正确。“债券就像一张借条”中，债券是一种借钱凭证，与借条的比喻相符。", "天气": "语义：天气不是借钱凭证，与“借条”的比喻冲突。", "花瓶": "语义：花瓶是器物，不能像借条一样记录还钱。", "饼干": "语义：饼干不是借钱凭证，不能像借条一样记录还钱，与“借条”的比喻冲突。"}, "sentence_index": 0, "correct_answer": "债券"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸向银行申请了一笔债券。", "explanation": "这里应该用〈贷款〉。申请的是贷款；这里的债券是借条，是借钱给别人后写下的还款凭证，不能向银行申请。"}, {"text": "这家公司的债券每年都会分红。", "explanation": "这里应该用〈股票〉。分红是股票的收益方式；这里的债券是借条，只表示借出的钱会还，不涉及分红。"}, {"text": "小明买了一本债券。", "explanation": "这里应该用量词〈张〉。债券的量词是“张”，“本”用于书册，不能用于债券。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确。“到期”用于借钱凭证，“债券到期时，我会拿回钱”成立。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不是借钱凭证，不会“到期”并让人拿回钱。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日期节点，不能“到期”，也不能拿回钱。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“到期”不与“考试”搭配，考试是举行而非到期。"}], "explanations": {"债券": "正确。“到期”用于借钱凭证，“债券到期时，我会拿回钱”成立。", "西瓜": "语义：西瓜不是借钱凭证，不会“到期”并让人拿回钱。", "生日": "语义：生日是日期节点，不能“到期”，也不能拿回钱。", "考试": "搭配：“到期”不与“考试”搭配，考试是举行而非到期。"}, "sentence_index": 6, "correct_answer": "债券"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给全家人买了人寿债券。", "explanation": "这里应该用〈保险〉。“人寿”修饰的是保险，人寿保险是保险合同，不是债券。"}, {"text": "他向朋友借债券度过了难关。", "explanation": "这里应该用〈借款〉。借的是钱款；这里的债券是借条，是借钱后写下的凭证，不是可以拿来借用的钱款。"}, {"text": "他每月都去银行给债券存钱，攒下了不少钱。", "explanation": "这里应该用〈存款〉。钱不能存进债券，存钱要存入银行的存款账户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一本债券。", "corrected_sentence": "我有一张债券。", "error_description": "量词错误：债券的量词应为“张”，“本”用于书册。应说“我有一张债券”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了两张债券们。", "corrected_sentence": "他买了两张债券。", "error_description": "后缀错误：「们」只用于指人的名词，债券是非人名词，不能加「们」表示复数。应说“他买了两张债券”，用量词“张”计量即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
