INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情得到的好处。", "primary_collocate": null, "pronunciation": "xiào yì", "ipa": "ɕiɑʊ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "学外语的效益很大。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法的效益不高。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了很多钱，却没有得到效益。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种树的效益要过几年才能看到。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的效益越来越好。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板只看眼前的效益。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会太多，公司的效益反而下降了。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这件事，我们要先想想效益。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法省时间，效益很明显。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花一年时间换来很大的效益。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济效益", "label": "复合"}, {"form": "社会效益", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事情得到的好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25094, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效益", "is_correct": true, "explanation": "正确答案。效益指做事得到的好处，读作第四声 xiào yì。"}, {"text": "校医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，校医指学校里的医生。"}, {"text": "教义", "is_correct": false, "explanation": "jiào 与 xiào 声母不同，教义指宗教的基本道理。"}, {"text": "效力", "is_correct": false, "explanation": "lì 与 yì 声母不同，效力指作用或效果。"}, {"text": "教益", "is_correct": false, "explanation": "jiào 与 xiào 声母不同，教益指从教导中得到的益处。"}], "explanations": {"效益": "正确答案。效益指做事得到的好处，读作第四声 xiào yì。", "校医": "yī（第一声）与 yì（第四声）声调不同，校医指学校里的医生。", "教义": "jiào 与 xiào 声母不同，教义指宗教的基本道理。", "效力": "lì 与 yì 声母不同，效力指作用或效果。", "教益": "jiào 与 xiào 声母不同，教益指从教导中得到的益处。"}, "sentence_index": null, "correct_answer": "效益"}, "level_3": {"options": [{"text": "效益", "is_correct": true, "explanation": "正确。“学外语的效益很大”指学习外语带来的好处。"}, {"text": "体温", "is_correct": false, "explanation": "语义：学外语不会改变体温，体温与学习无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很大”不能用来修饰颜色，学外语也不会产生颜色。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：学外语不会让鞋码变大，鞋码与学习无关。"}], "explanations": {"效益": "正确。“学外语的效益很大”指学习外语带来的好处。", "体温": "语义：学外语不会改变体温，体温与学习无关。", "颜色": "搭配：“很大”不能用来修饰颜色，学外语也不会产生颜色。", "鞋码": "语义：学外语不会让鞋码变大，鞋码与学习无关。"}, "sentence_index": 0, "correct_answer": "效益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的效益写得很快，一分钟写了十行。", "explanation": "这里应该用〈速度〉。效益指做事得到的好处，写字的快慢要用速度。"}, {"text": "他这次考试的效益进步很大。", "explanation": "这里应该用〈成绩〉。效益指利益，考试的结果要用成绩。"}, {"text": "这批衣服的效益很差，穿几天就坏了。", "explanation": "这里应该用〈质量〉。效益指投入产出的利益，衣服本身的好坏要用质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "效益", "is_correct": true, "explanation": "正确。“公司的效益下降了”指公司做事得到的好处变少了。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：工作不能说年龄下降，年龄只会增长。"}, {"text": "身高", "is_correct": false, "explanation": "语义：公司没有身高，“身高”只用来描述人的高矮。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：工作没有颜色，“颜色下降”说不通。"}], "explanations": {"效益": "正确。“公司的效益下降了”指公司做事得到的好处变少了。", "年龄": "语义：工作不能说年龄下降，年龄只会增长。", "身高": "语义：公司没有身高，“身高”只用来描述人的高矮。", "颜色": "语义：工作没有颜色，“颜色下降”说不通。"}, "sentence_index": 6, "correct_answer": "效益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的效益很好，很少生病。", "explanation": "这里应该用〈身体〉。效益指做事得到的好处，说人健康不健康要用身体。"}, {"text": "他们的汉语效益提高得很快。", "explanation": "这里应该用〈水平〉。效益指投入产出的利益，语言能力要用水平。"}, {"text": "这个人的效益很温和，从来不发脾气。", "explanation": "这里应该用〈性格〉。效益指做事得到的好处，人的温和与否要用性格来说，不能用效益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课有一场很大的效益。", "corrected_sentence": "这门课有很大的效益。", "error_description": "量词误用：“场”多用于比赛、雨等，不能修饰抽象的“效益”；应去掉“一场”，说“有很大的效益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种方法有很明显效益。", "corrected_sentence": "这种方法有很明显的效益。", "error_description": "“很明显”修饰名词“效益”时要加“的”，应说“很明显的效益”，不能说“很明显效益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
