INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在没有路的地方开出一条路，让人可以通过。", "primary_collocate": null, "pronunciation": "kāi pì", "ipa": "kʰaɪ˥ pʰi˥˩", "syllable_count": 2, "sentences": [{"text": "工人们在山里开辟了一条小路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪过后，战士们开辟出一条路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民在树林里开辟了一条路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里没有路，我们要先开辟一条路，才能过去。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着刀在草地里开辟小路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山太高，人们用了很久才开辟出这条路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的草太多，我们先开辟一条小路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在雪地里开辟道路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里没有路，他们自己开辟了一条。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起把这条路开辟出来了。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开辟了", "label": "体标"}, {"form": "开辟过", "label": "体标"}, {"form": "开辟着", "label": "体标"}], "register": "中性", "sense_fingerprint": "在没有路的地方打开一条路让人通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”与修路无关，“唱了一条小路”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“小路”搭配，“吃了一条小路”不成立。"}, {"text": "开辟", "is_correct": true, "explanation": "“开辟”指在没有路的地方打开一条路，与“在山里”“一条小路”相符，句意通顺。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能用于路，“煮了一条小路”不成立。"}], "explanations": {"唱": "语义：“唱”与修路无关，“唱了一条小路”说不通。", "吃": "搭配：“吃”不能与“小路”搭配，“吃了一条小路”不成立。", "开辟": "“开辟”指在没有路的地方打开一条路，与“在山里”“一条小路”相符，句意通顺。", "煮": "搭配：“煮”不能用于路，“煮了一条小路”不成立。"}, "sentence_index": 0, "correct_answer": "开辟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在泥路上开辟了一层砖。", "explanation": "这里应该用〈铺〉。开辟指打开原来没有的路，铺是把材料平放；铺砖要用“铺”，不能用“开辟”。"}, {"text": "工人们在山上开辟了一座桥。", "explanation": "这里应该用〈修建〉。开辟指在没有路的地方开出一条路，不用于建造桥梁；建桥要用“修建”。"}, {"text": "他开辟了一封信，看了起来。", "explanation": "这里应该用〈拆〉。开辟指在没有路的地方开出路来，不能用于打开信件；拆信要用“拆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“小路”搭配，“洗一条小路”不成立。"}, {"text": "开辟", "is_correct": true, "explanation": "“开辟”指在草丛中打开一条路，“草太多，我们先开辟一条小路”因果相符，句意通顺。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”只用于衣物等，“缝一条小路”不成立。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，不能用来表示在草丛里开路。"}], "explanations": {"洗": "搭配：“洗”不能与“小路”搭配，“洗一条小路”不成立。", "开辟": "“开辟”指在草丛中打开一条路，“草太多，我们先开辟一条小路”因果相符，句意通顺。", "缝": "搭配：“缝”只用于衣物等，“缝一条小路”不成立。", "咬": "语义：“咬”指用牙齿夹住，不能用来表示在草丛里开路。"}, "sentence_index": 6, "correct_answer": "开辟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们开辟了一棵大树。", "explanation": "这里应该用〈砍〉。开辟指打开道路或开创领域，不能指砍掉树木；砍树要用“砍”。"}, {"text": "妈妈每天开辟窗户。", "explanation": "这里应该用〈擦〉。开辟不能用于擦拭窗户这类动作；擦窗户要用“擦”。"}, {"text": "他每个周末都开辟车。", "explanation": "这里应该用〈洗〉。开辟不能用于清洗车辆；洗车要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们正在山上开辟了一条路。", "corrected_sentence": "他们正在山上开辟一条路。", "error_description": "“了”误用：“正在”表示动作正在进行，“开辟”后不能加“了”表示完成，二者冲突；应去掉“了”，说“正在开辟一条路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们慢慢开辟来一条小路。", "corrected_sentence": "他们慢慢开辟出一条小路。", "error_description": "补语误用：表示“开出来”的结果补语应用“出”，不能用“来”；“开辟来”不成立，应说“开辟出一条小路”。错误只在“来”，不在“慢慢”或数量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25098, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
