INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做一件事，会让别人也受到影响，但那个人没有付钱或得到钱。", "primary_collocate": null, "pronunciation": "wài bù xìng", "ipa": "waɪ˥˩ pu˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "邻居大声唱歌，这是一种外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的尾气有很大的外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他种树，别人乘凉，这就是外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂不付钱，却让河水变脏，这就是外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部性是指做事会影响别人。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟有外部性，旁边的人也会生病。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，噪音就是一种外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部性有好的，也有不好的。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人为这种外部性付钱。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得堵车有没有外部性？", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正外部性", "label": "复合"}, {"form": "负外部性", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人做事影响别人，却没有付钱或得到钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重不是一种行为影响，“这是一种体重”不成立。"}, {"text": "外部性", "is_correct": true, "explanation": "“这是一种外部性”指邻居唱歌影响了别人，而且没有人为此付钱，与句意一致。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：鞋码与唱歌扰民无关，不能作为“一种”之后的类别名称。"}, {"text": "电压", "is_correct": false, "explanation": "搭配：“电压”与量词“种”搭配不通，不能指称一种行为后果。"}], "explanations": {"体重": "语义：体重不是一种行为影响，“这是一种体重”不成立。", "外部性": "“这是一种外部性”指邻居唱歌影响了别人，而且没有人为此付钱，与句意一致。", "鞋码": "语义：鞋码与唱歌扰民无关，不能作为“一种”之后的类别名称。", "电压": "搭配：“电压”与量词“种”搭配不通，不能指称一种行为后果。"}, "sentence_index": 0, "correct_answer": "外部性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的外部性很开朗，很喜欢交朋友。", "explanation": "这里应该用〈性格〉。外部性指做事影响别人却没有付钱或得到钱，不用来形容人；说人开朗要用性格。"}, {"text": "这个鸡蛋的外部性很硬，不容易打破。", "explanation": "这里应该用〈外壳〉。外部性指做事影响别人而无偿，不指物体的硬壳；鸡蛋的硬壳要说“外壳”。"}, {"text": "这辆车的外部性很干净，我们擦一擦吧。", "explanation": "这里应该用〈外部〉。外部性不指物体的表面；说车的外面要用“外部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：噪音是声音造成的影响，不是颜色，“噪音就是一种颜色”不成立。"}, {"text": "外部性", "is_correct": true, "explanation": "“噪音就是一种外部性”说明噪音是影响别人而无人付费的行为后果，与句意相符。"}, {"text": "利息", "is_correct": false, "explanation": "搭配：“利息”通常与存款、借贷搭配，不能用来界定噪音的性质。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温与噪音的性质无关，不能用来说明噪音属于哪一类。"}], "explanations": {"颜色": "语义：噪音是声音造成的影响，不是颜色，“噪音就是一种颜色”不成立。", "外部性": "“噪音就是一种外部性”说明噪音是影响别人而无人付费的行为后果，与句意相符。", "利息": "搭配：“利息”通常与存款、借贷搭配，不能用来界定噪音的性质。", "气温": "语义：气温与噪音的性质无关，不能用来说明噪音属于哪一类。"}, "sentence_index": 6, "correct_answer": "外部性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房子被外部性推倒了。", "explanation": "这里应该用〈外力〉。外部性指做事影响别人而无偿，不指物理上来自外面的力量；被外力推倒要说“外力”。"}, {"text": "我们在房子的外部性种了很多花。", "explanation": "这里应该用〈外面〉。外部性指做事对别人的影响，不指地方；房子外边要说“外面”。"}, {"text": "这家店的外部性很吸引人。", "explanation": "这里应该用〈外观〉。外部性指经济行为对别人的影响，不指店铺的样子；说样子要用“外观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂偷偷排放废水，这就是了一种外部性。", "corrected_sentence": "工厂偷偷排放废水，这就是一种外部性。", "error_description": "“了”误用：“是”后面不能直接插入“了”；应去掉“了”，说“这就是一种外部性”。错误在“是”之后的“了”，不在量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府可以用补贴来减少一只负外部性。", "corrected_sentence": "政府可以用补贴来减少一种负外部性。", "error_description": "量词误用：“外部性”应搭配量词“种”，不能用“只”；应说“减少一种负外部性”。错误在量词，不在“负”的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪恶", "is_correct": true, "explanation": "反义：“正义”指做对的事、善待他人，“邪恶”指做坏事、伤害他人，二者相反。"}, {"text": "书本", "is_correct": false, "explanation": "不是反义：“书本”是学习用品，与做人的品行无关。"}, {"text": "冬天", "is_correct": false, "explanation": "不是反义：“冬天”指季节，与做人的品行无关。"}, {"text": "蔬菜", "is_correct": false, "explanation": "不是反义：“蔬菜”是食物，与做人的品行无关。"}], "correct_answer": "邪恶", "explanations": {"邪恶": "反义：“正义”指做对的事、善待他人，“邪恶”指做坏事、伤害他人，二者相反。", "书本": "不是反义：“书本”是学习用品，与做人的品行无关。", "冬天": "不是反义：“冬天”指季节，与做人的品行无关。", "蔬菜": "不是反义：“蔬菜”是食物，与做人的品行无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪恶", "is_correct": true, "explanation": "反义：“正义”指做对的事、善待他人，“邪恶”指做坏事、伤害他人，二者相反。"}, {"text": "河流", "is_correct": false, "explanation": "不是反义：“河流”指地表的水流，与做人的品行无关。"}, {"text": "桌子", "is_correct": false, "explanation": "不是反义：“桌子”是家具，与做人的品行无关。"}, {"text": "季节", "is_correct": false, "explanation": "不是反义：“季节”指一年中气候的分段，与做人的品行无关。"}], "correct_answer": "邪恶", "explanations": {"邪恶": "反义：“正义”指做对的事、善待他人，“邪恶”指做坏事、伤害他人，二者相反。", "河流": "不是反义：“河流”指地表的水流，与做人的品行无关。", "桌子": "不是反义：“桌子”是家具，与做人的品行无关。", "季节": "不是反义：“季节”指一年中气候的分段，与做人的品行无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做对的事情，对别人好，不欺负别人。", "primary_collocate": null, "pronunciation": "zhèng yì", "ipa": "ʈʂɤŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "老师教我们要讲正义，不要欺负同学。", "target_word": "正义", "complexity_tier": "T3", "furigana": "lǎo shī jiāo wǒ men yào jiǎng zhèng yì, bú yào qī fu tóng xué", "sentence_source": "generated"}, {"text": "他心里有正义，从不欺负弱小的人。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要讲正义，不能只想着自己。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人哭，他没走开，这就是正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常说：做对的事，就是正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友吵架时，班长站在正义这一边。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事告诉我们，正义总会赢。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的钱帮助穷人，这是正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要做正义的事，对每一个人都好。", "target_word": "正义", "complexity_tier": "T3", "furigana": "wǒ men yào zuò zhèng yì de shì, duì měi yí gè rén dōu hǎo", "sentence_source": "generated"}, {"text": "警察保护好人，抓坏人，代表着正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正义感", "label": "复合词"}, {"form": "正義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做对的事、善待他人、不欺负人的品行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确答案：正义（zhèng yì），指做对的事、善待他人、不欺负人的品行。"}, {"text": "争议", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。"}, {"text": "正式", "is_correct": false, "explanation": "shì 与 yì 的声母不同，意思是正规、符合规定。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 yì 的声母不同，意思是政府管理国家的活动。"}], "explanations": {"正义": "正确答案：正义（zhèng yì），指做对的事、善待他人、不欺负人的品行。", "争议": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。", "正式": "shì 与 yì 的声母不同，意思是正规、符合规定。", "政治": "zhì 与 yì 的声母不同，意思是政府管理国家的活动。"}, "sentence_index": null, "correct_answer": "正义"}, "level_3": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确：“讲正义”指做人要做对的事、不欺负人，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讲”不能与“窗户”搭配，“讲窗户”没有意义。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“讲电线”不成立，与做人的品行无关。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”与“不要欺负同学”的道理无关。"}], "explanations": {"正义": "正确：“讲正义”指做人要做对的事、不欺负人，与句意相符。", "窗户": "搭配：“讲”不能与“窗户”搭配，“讲窗户”没有意义。", "电线": "搭配：“讲电线”不成立，与做人的品行无关。", "早饭": "语义：“早饭”与“不要欺负同学”的道理无关。"}, "sentence_index": 0, "correct_answer": "正义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈最大的正义是身体健康。", "explanation": "这里应该用〈愿望〉。正义指做对的事、善待他人的品行，不指个人的心愿；“最大的愿望”才能说“身体健康”。"}, {"text": "她对古典音乐有浓厚的正义。", "explanation": "这里应该用〈兴趣〉。“浓厚的兴趣”说的是爱好的程度；正义指做对的事、善待他人的品行，不能用来形容对音乐的喜爱。"}, {"text": "妈妈做的正义味道很好。", "explanation": "这里应该用〈菜〉。“妈妈做的菜味道很好”才通顺；正义指做对的事、善待他人的品行，不是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确答案：正义（zhèng yì），指做对的事、善待他人、不欺负人的品行。"}, {"text": "争议", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。"}, {"text": "正业", "is_correct": false, "explanation": "yè 与 yì 只差韵母，意思是正当的职业。"}, {"text": "政绩", "is_correct": false, "explanation": "jì 与 yì 声母不同，意思是做官的成绩。"}], "explanations": {"正义": "正确答案：正义（zhèng yì），指做对的事、善待他人、不欺负人的品行。", "争议": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。", "正业": "yè 与 yì 只差韵母，意思是正当的职业。", "政绩": "jì 与 yì 声母不同，意思是做官的成绩。"}, "sentence_index": null, "correct_answer": "正义"}, "level_3": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确：“正义总会赢”说的是做对的事终会获胜，与故事的寓意相符。"}, {"text": "利润", "is_correct": false, "explanation": "语义：“利润总会赢”说不通，与故事的寓意无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能是故事要告诉我们的赢家。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“赢”不能与“体温”搭配。"}], "explanations": {"正义": "正确：“正义总会赢”说的是做对的事终会获胜，与故事的寓意相符。", "利润": "语义：“利润总会赢”说不通，与故事的寓意无关。", "颜色": "语义：“颜色”不能是故事要告诉我们的赢家。", "体温": "搭配：“赢”不能与“体温”搭配。"}, "sentence_index": 6, "correct_answer": "正义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张试卷上的答案很正义。", "explanation": "这里应该用〈正确〉。正义指做对的事、善待他人的品行，不能用来评价答案的对错。"}, {"text": "他的正义很快，三分钟就做完了。", "explanation": "这里应该用〈速度〉。正义指做对的事、善待他人的品行，不指动作的快慢；“速度很快”才是常用说法。"}, {"text": "他的正义很大，搬起箱子毫不费力。", "explanation": "这里应该用〈力气〉。“他力气很大，搬起箱子毫不费力”才通顺；正义指品行，不指身体的力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的举动代表着一块正义。", "corrected_sentence": "她的举动代表着一种正义。", "error_description": "量词误用：正义是抽象概念，不能用“块”计量，应说“一种正义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们吵架时，他总是坐在正义这一边。", "corrected_sentence": "同学们吵架时，他总是站在正义这一边。", "error_description": "动词搭配错误：表示支持正义要说“站在正义这一边”，不能说“坐在正义这一边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25102, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收入", "is_correct": true, "explanation": "收入与支出相对，指收进来的钱，是支出的反义词。"}, {"text": "篮球", "is_correct": false, "explanation": "“篮球”是体育用品，与支出没有反义关系。"}, {"text": "玻璃", "is_correct": false, "explanation": "“玻璃”是材料，与支出没有反义关系。"}, {"text": "云朵", "is_correct": false, "explanation": "“云朵”是自然景象，与支出没有反义关系。"}], "correct_answer": "收入", "explanations": {"收入": "收入与支出相对，指收进来的钱，是支出的反义词。", "篮球": "“篮球”是体育用品，与支出没有反义关系。", "玻璃": "“玻璃”是材料，与支出没有反义关系。", "云朵": "“云朵”是自然景象，与支出没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
