INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "花掉的钱。", "primary_collocate": null, "pronunciation": "zhī chū", "ipa": "ʈʂɨ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这个月我的支出很多。", "target_word": "支出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每天的支出不多。", "target_word": "支出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家的支出比收入少。", "target_word": "支出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买菜是我家一天的支出。", "target_word": "支出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生的支出主要在吃饭上。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把每一笔支出都写在本子上。", "target_word": "支出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的支出已经超过一万元了。", "target_word": "支出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租是每个月最大的支出。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想少一点支出，多一点存钱。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看看你上个月的支出有多少。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔支出", "label": "量词"}, {"form": "财政支出", "label": "复合"}, {"form": "教育支出", "label": "复合"}], "register": "中性", "sense_fingerprint": "支出：花掉的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25102, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支出", "is_correct": true, "explanation": "支出：zhī chū，指花掉的钱。"}, {"text": "指出", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，指出意思是指明。"}, {"text": "制出", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，制出意思是制造出来。"}, {"text": "吃出", "is_correct": false, "explanation": "zh 与 ch 声母不同，吃出（chī chū）意思是吃到某种东西。"}], "explanations": {"支出": "支出：zhī chū，指花掉的钱。", "指出": "zhī（第一声）与 zhǐ（第三声）声调不同，指出意思是指明。", "制出": "zhī（第一声）与 zhì（第四声）声调不同，制出意思是制造出来。", "吃出": "zh 与 ch 声母不同，吃出（chī chū）意思是吃到某种东西。"}, "sentence_index": null, "correct_answer": "支出"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能用“很多”修饰，也与“这个月”指的花销无关。"}, {"text": "支出", "is_correct": true, "explanation": "这里指这个月花掉的钱，“支出很多”说的正是花掉的钱多。"}, {"text": "书架", "is_correct": false, "explanation": "语义：“书架”是家具，不是花掉的钱，“这个月的书架很多”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是钱，不能说“这个月的天气很多”。"}], "explanations": {"身高": "搭配：“身高”不能用“很多”修饰，也与“这个月”指的花销无关。", "支出": "这里指这个月花掉的钱，“支出很多”说的正是花掉的钱多。", "书架": "语义：“书架”是家具，不是花掉的钱，“这个月的书架很多”说不通。", "天气": "语义：“天气”不是钱，不能说“这个月的天气很多”。"}, "sentence_index": 0, "correct_answer": "支出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月公司给爸爸发了五千元支出。", "explanation": "这里应该用〈工资〉或〈收入〉。公司发给人的钱是收进来的钱，支出是花掉的钱。"}, {"text": "买菜是我家的一条支出。", "explanation": "这里的量词错了。“条”用于细长的东西，支出应该用〈笔〉，说“一笔支出”。"}, {"text": "我家的支出一直存在银行。", "explanation": "这里应该用〈存款〉。支出是已经花掉的钱，不能存进银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不是花掉的钱，不能“超过一万元”。"}, {"text": "支出", "is_correct": true, "explanation": "这里指这个月花掉的钱，超过一万元说的是花的钱超过了一万元。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”是温度，不能超过一万元，这样说毫无意义。"}, {"text": "车速", "is_correct": false, "explanation": "搭配：“车速”不能用“超过一万元”来计量，二者搭配不当。"}], "explanations": {"体重": "语义：“体重”是身体的重量，不是花掉的钱，不能“超过一万元”。", "支出": "这里指这个月花掉的钱，超过一万元说的是花的钱超过了一万元。", "气温": "语义：“气温”是温度，不能超过一万元，这样说毫无意义。", "车速": "搭配：“车速”不能用“超过一万元”来计量，二者搭配不当。"}, "sentence_index": 6, "correct_answer": "支出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把你上个月的支出放进了冰箱。", "explanation": "这里应该用〈账单〉或〈记录〉。支出是花掉的钱，不能放进冰箱。"}, {"text": "爸爸每个月都去银行领支出。", "explanation": "这里应该用〈工资〉。工资是收进来的钱，可以领取；支出是花出去的钱，不能领取。"}, {"text": "他每天都给上个月的支出浇水。", "explanation": "这里应该用〈花草〉之类的植物。支出是钱，不能浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月多了一块房租支出。", "corrected_sentence": "他这个月多了一笔房租支出。", "error_description": "错误在于量词。“块”用于块状的东西，支出应该用“笔”，应说“一笔房租支出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我每个月支出。", "corrected_sentence": "这是我每个月的支出。", "error_description": "错误在于缺少“的”。定语“每个月”和中心词“支出”之间要加“的”，应说“每个月的支出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出新的东西或想出新的办法。", "primary_collocate": null, "pronunciation": "chuàng xīn", "ipa": "tʂʰwɑŋ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这家公司每年都在创新。", "target_word": "创新", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师希望我们敢于创新。", "target_word": "创新", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做菜也要创新，不能总做一样的。", "target_word": "创新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不怕失败，一直在创新。", "target_word": "创新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂为了卖得更好，决定创新产品。", "target_word": "创新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想做得更好，就要不断创新。", "target_word": "创新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用新办法做实验，真会创新。", "target_word": "创新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友喜欢创新，做的东西总是不一样。", "target_word": "创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位设计师每年都创新，所以衣服很受欢迎。", "target_word": "创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只学别人的做法不行，我们要自己创新。", "target_word": "创新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "創新", "label": "繁体"}, {"form": "创新性", "label": "复合"}, {"form": "创新能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "创新：做出新东西、想出新办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主体是人，不能用于公司。"}, {"text": "创新", "is_correct": true, "explanation": "正确：“创新”指做出新东西或想出新办法，与公司每年的活动相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”的主体是人或动物，不能用来说公司每年都在生病。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”指人离开工作岗位，不能用于公司的年度活动。"}], "explanations": {"结婚": "语义：“结婚”的主体是人，不能用于公司。", "创新": "正确：“创新”指做出新东西或想出新办法，与公司每年的活动相符。", "生病": "语义：“生病”的主体是人或动物，不能用来说公司每年都在生病。", "退休": "搭配：“退休”指人离开工作岗位，不能用于公司的年度活动。"}, "sentence_index": 0, "correct_answer": "创新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥伦布很早就创新了美洲大陆。", "explanation": "这里应该用〈发现〉。创新指做出新东西或想出新办法，不用来表示找到已经存在的大陆。"}, {"text": "工人们创新了那座古桥，一点儿也没有改变它原来的样子。", "explanation": "这里应该用〈修复〉。创新是做出新东西，而“没有改变原样”的修补应说“修复”。"}, {"text": "他在旧书里创新了一个早就存在的秘密，谁也没有看到。", "explanation": "这里应该用〈发现〉。创新是做出新东西；找到早已存在的秘密应说“发现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模仿", "is_correct": false, "explanation": "语义：“模仿”是照着别人做，与“用新办法做实验”的语境矛盾。"}, {"text": "创新", "is_correct": true, "explanation": "正确：“真会创新”表示善于想出新办法，与“用新办法做实验”一致。"}, {"text": "抄袭", "is_correct": false, "explanation": "语义：“抄袭”是照搬别人的东西，与“用新办法做实验”相矛盾。"}, {"text": "守旧", "is_correct": false, "explanation": "语义：“守旧”指坚持老办法，与“用新办法做实验”正好相反。"}], "explanations": {"模仿": "语义：“模仿”是照着别人做，与“用新办法做实验”的语境矛盾。", "创新": "正确：“真会创新”表示善于想出新办法，与“用新办法做实验”一致。", "抄袭": "语义：“抄袭”是照搬别人的东西，与“用新办法做实验”相矛盾。", "守旧": "语义：“守旧”指坚持老办法，与“用新办法做实验”正好相反。"}, "sentence_index": 6, "correct_answer": "创新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们一笔一划地创新老师的字帖，写得一模一样。", "explanation": "这里应该用〈模仿〉。创新是做出新东西，与“写得一模一样”相矛盾；照着样子学写应说“模仿”。"}, {"text": "他把课文创新了一遍，一个字也没改。", "explanation": "这里应该用〈抄写〉。创新是做出新东西，与“一个字也没改”相矛盾；照原样写一遍应说“抄写”。"}, {"text": "他在森林里创新了好久，还是找不到出口。", "explanation": "这里应该用〈迷路〉。创新指做出新东西，不表示在森林里走不出去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的小组这几个月正在创新过。", "corrected_sentence": "我们的小组这几个月正在创新。", "error_description": "体标错误：“正在”表示动作正在进行，不能再加表示经历的“过”，应说“正在创新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的学校鼓励学生大胆得创新。", "corrected_sentence": "我们的学校鼓励学生大胆创新。", "error_description": "结构助词错误：“大胆”修饰动词作状语时，中间不用“得”，应说“大胆创新”；“得”不能放在状语和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
