INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25106, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西变成可以买卖的票券。", "primary_collocate": null, "pronunciation": "zhèng quàn huà", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛn˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "他想把一首歌的版税证券化。", "target_word": "证券化", "complexity_tier": "T3", "furigana": "tā xiǎng bǎ yī shǒu gē de bǎnshuì zhèngquànhuà", "sentence_source": "generated"}, {"text": "证券化就是把东西变成票券来卖。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把明年的分红证券化，先拿到了钱。", "target_word": "证券化", "complexity_tier": "T3", "furigana": "tā bǎ míngnián de fēnhóng zhèngquànhuà, xiān nádào le qián", "sentence_source": "generated"}, {"text": "老师说把房租证券化就可以在市场上卖。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店把未来一年的会员费证券化，很快筹到了资金。", "target_word": "证券化", "complexity_tier": "T3", "furigana": "zhè jiā diàn bǎ wèilái yì nián de huìyuánfèi zhèngquànhuà, hěn kuài chóu dào le zījīn", "sentence_source": "generated"}, {"text": "他们想把一批应收账款证券化。", "target_word": "证券化", "complexity_tier": "T3", "furigana": "tāmen xiǎng bǎ yī pī yīngshōu zhàngkuǎn zhèngquànhuà", "sentence_source": "generated"}, {"text": "把电影收入证券化以后大家都能买。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把电影票房收入证券化，卖给了很多投资者。", "target_word": "证券化", "complexity_tier": "T3", "furigana": "gōngsī bǎ diànyǐng piàofáng shōurù zhèngquànhuà, mài gěi le hěn duō tóuzīzhě", "sentence_source": "generated"}, {"text": "他们为什么不把这笔收费权证券化呢？", "target_word": "证券化", "complexity_tier": "T3", "furigana": "tāmen wèishénme bù bǎ zhè bǐ shōufèiquán zhèngquànhuà ne", "sentence_source": "generated"}, {"text": "哥哥在银行工作，每天研究怎么证券化房贷。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "证券化了", "label": "体标"}, {"form": "资产证券化", "label": "复合"}, {"form": "證券化", "label": "繁体"}], "register": "通用", "sense_fingerprint": "证券化：把东西变成能买卖的票券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "证券化", "is_correct": true, "explanation": "证券化：把版税变成可以买卖的证券，符合「想把版税」这一意图。"}, {"text": "录制", "is_correct": false, "explanation": "搭配：录制针对声音或影像，不能用于版税。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁会让版税消失，与「想把版税变成钱」的意图相悖。"}, {"text": "抄写", "is_correct": false, "explanation": "配价：抄写要求文字作宾语，版税不是可以抄写的文本。"}], "explanations": {"证券化": "证券化：把版税变成可以买卖的证券，符合「想把版税」这一意图。", "录制": "搭配：录制针对声音或影像，不能用于版税。", "烧毁": "语义：烧毁会让版税消失，与「想把版税变成钱」的意图相悖。", "抄写": "配价：抄写要求文字作宾语，版税不是可以抄写的文本。"}, "sentence_index": 0, "correct_answer": "证券化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把旧手机证券化给了同学。", "explanation": "这里应该用〈出售〉。证券化是把东西变成可以买卖的票券，不是把东西直接卖给某人，所以不能说「证券化给了同学」。"}, {"text": "他把人民币证券化成了美元。", "explanation": "这里应该用〈兑换〉。证券化是把东西变成可买卖的票券，货币之间的换算不叫证券化；人民币换成美元应说「兑换」。"}, {"text": "法院证券化了那批古董。", "explanation": "这里应该用〈拍卖〉。证券化是把东西变成票券来卖，不是公开出价卖掉；古董不能变成票券，法院也不这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证券化", "is_correct": true, "explanation": "证券化：把电影收入变成可以买卖的票券，与后半句「大家都能买」相符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：抛弃是丢掉收入，大家就买不到了，与句子的意思相反。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：印刷针对文字或图片，不搭配电影收入。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：翻译要求文字作宾语，电影收入不是可以翻译的文本。"}], "explanations": {"证券化": "证券化：把电影收入变成可以买卖的票券，与后半句「大家都能买」相符。", "抛弃": "语义：抛弃是丢掉收入，大家就买不到了，与句子的意思相反。", "印刷": "搭配：印刷针对文字或图片，不搭配电影收入。", "翻译": "配价：翻译要求文字作宾语，电影收入不是可以翻译的文本。"}, "sentence_index": 6, "correct_answer": "证券化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把那枚戒指证券化给了我。", "explanation": "这里应该用〈赠与〉。证券化是把东西变成可买卖的票券，不是把东西送给别人，所以不能说「证券化给了我」。"}, {"text": "专家把这幅画证券化装裱好了。", "explanation": "这里应该用〈装裱〉。证券化是把东西变成可买卖的票券，不是给画加工装裱，所以不能说「证券化装裱好了」。"}, {"text": "这只基金被证券化为低风险。", "explanation": "这里应该用〈评为〉。证券化指把东西变成可交易的票券，不用来描述风险等级，风险高低要用「评为」来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她没自己的版税证券化。", "corrected_sentence": "她没把自己的版税证券化。", "error_description": "「把」字句漏了「把」：「自己的版税」是宾语，应提到动词前，说「没把版税证券化」，不能省略「把」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把一笔房租收入证券化着。", "corrected_sentence": "他们把一笔房租收入证券化了。", "error_description": "体标用错了：「把」字句要求动词后有表示结果或完成的成分，「证券化」这个动作已经完成，应该用「了」，不能用表示持续状态的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
