INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分东西的方法。", "primary_collocate": null, "pronunciation": "fēn pèi mó shì", "ipa": "fən˥ pʰeɪ˥˩ mwɔ˧˥ ʂɨ˥˩", "syllable_count": 4, "sentences": [{"text": "我们想出了一个公平的分配模式。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家对这个分配模式都没有意见。", "target_word": "分配模式", "complexity_tier": "T3", "furigana": "dà jiā duì zhè ge fēn pèi mó shì dōu méi yǒu yì jiàn.", "sentence_source": "generated"}, {"text": "这个分配模式是先到的人先拿。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈定了新的分配模式，每人一块蛋糕。", "target_word": "分配模式", "complexity_tier": "T3", "furigana": "mā ma dìng le xīn de fēn pèi mó shì, měi rén yí kuài dàn gāo.", "sentence_source": "generated"}, {"text": "大家一起商量水果的分配模式。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种分配模式让每个人都很满意。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长改了分配模式，现在按人数分饭。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的分配模式很简单，大家平均分。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得哪种分配模式对孩子更好？", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不同意这个分配模式，因为太不公平了。", "target_word": "分配模式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种分配模式", "label": "量词"}], "register": "通用", "sense_fingerprint": "分配模式：日常分东西的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分配模式", "is_correct": true, "explanation": "正确。“想出了一个公平的分配模式”指想出了一套公平分东西的办法。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是分东西的办法，“公平的颜色”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是分东西的办法，“公平的体重”没有意义。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：鞋码是鞋子的尺寸，不能用来说“想出了一个公平的鞋码”。"}], "explanations": {"分配模式": "正确。“想出了一个公平的分配模式”指想出了一套公平分东西的办法。", "颜色": "语义：颜色不是分东西的办法，“公平的颜色”说不通。", "体重": "语义：体重不是分东西的办法，“公平的体重”没有意义。", "鞋码": "语义：鞋码是鞋子的尺寸，不能用来说“想出了一个公平的鞋码”。"}, "sentence_index": 0, "correct_answer": "分配模式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个分配模式很好吃，大家都抢着吃。", "explanation": "这里应该用〈蛋糕〉。分配模式是分东西的办法，本身不能吃，说好吃要用蛋糕。"}, {"text": "我每天早上都喝分配模式，喝完就去上学。", "explanation": "这里应该用〈牛奶〉。分配模式指分东西的办法，不能喝，早上喝的要用牛奶。"}, {"text": "这台电脑的分配模式有五公斤重。", "explanation": "这里应该用〈重量〉。分配模式指分东西的办法，没有重量；说电脑有多重要用「重量」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分配模式", "is_correct": true, "explanation": "正确。“班长改了分配模式，现在按人数分饭”指改变了分东西的办法。"}, {"text": "字体", "is_correct": false, "explanation": "语义：班长改的是字体，字体与按人数分饭无关。"}, {"text": "体型", "is_correct": false, "explanation": "语义：体型是人或物的外形，跟按人数分饭没有关系，“改了体型，现在按人数分饭”说不通。"}, {"text": "声调", "is_correct": false, "explanation": "语义：声调是语言的音高特征，改变声调无法决定按人数分饭。"}], "explanations": {"分配模式": "正确。“班长改了分配模式，现在按人数分饭”指改变了分东西的办法。", "字体": "语义：班长改的是字体，字体与按人数分饭无关。", "体型": "语义：体型是人或物的外形，跟按人数分饭没有关系，“改了体型，现在按人数分饭”说不通。", "声调": "语义：声调是语言的音高特征，改变声调无法决定按人数分饭。"}, "sentence_index": 6, "correct_answer": "分配模式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的分配模式很高，我够不着。", "explanation": "这里应该用〈高度〉。分配模式是分东西的办法，没有高低，说桌子高要用高度。"}, {"text": "这件衣服的分配模式很漂亮，穿起来很好看。", "explanation": "这里应该用〈款式〉。分配模式指分东西的办法，衣服好不好看要用款式。"}, {"text": "这间教室的分配模式很亮。", "explanation": "这里应该用〈亮度〉。分配模式没有亮暗，说教室亮要用亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们定了一场公平的分配模式。", "corrected_sentence": "我们定了一种公平的分配模式。", "error_description": "量词用错。“场”多用于比赛、雨等，分配模式是抽象的办法，应说“一种分配模式”，不能说“一场分配模式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈制定了一种更公平分配模式。", "corrected_sentence": "妈妈制定了一种更公平的分配模式。", "error_description": "“更公平”作定语修饰“分配模式”时，中间要加“的”，应说“更公平的分配模式”，不能省掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
