INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人给予自己的帮助或好处，给予相应的报答。", "primary_collocate": null, "pronunciation": "huí bào", "ipa": "xwei˧˥ pau˥˩", "syllable_count": 2, "sentences": [{"text": "别人帮了你，你要回报他。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈对我这么好，我想回报她。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友帮过我，我一定回报。", "target_word": "回报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想回报那位帮助过他的邻居。", "target_word": "回报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你的照顾，以后我会回报你。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用一顿饭回报他的帮忙。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教了我很多，我想回报老师。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她请大家吃饭，回报大家的关心。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居送来了水果，我们做了点心回报他们。", "target_word": "回报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说，别人对你好，你要回报。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回报了", "label": "体标"}, {"form": "回报过", "label": "体标"}], "register": "中性", "sense_fingerprint": "别人帮助或关心了自己，自己以行动或物品报答对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回报", "is_correct": true, "explanation": "回报 huí bào：别人帮了自己，自己也去帮别人作为报答，是本词。"}, {"text": "汇报", "is_correct": false, "explanation": "汇报 huì bào：第一音节声调不同（第四声与第二声），意思是向上级报告情况。"}, {"text": "回到", "is_correct": false, "explanation": "回到 huí dào：声母由 b 变为 d，意思是返回到某处。"}, {"text": "回本", "is_correct": false, "explanation": "回本 huí běn：韵母由 ao 变为 en，声调也不同，意思是收回成本。"}, {"text": "怀抱", "is_correct": false, "explanation": "怀抱 huái bào：第一音节韵母由 ui 变为 uai，意思是胸怀或拥抱。"}], "explanations": {"回报": "回报 huí bào：别人帮了自己，自己也去帮别人作为报答，是本词。", "汇报": "汇报 huì bào：第一音节声调不同（第四声与第二声），意思是向上级报告情况。", "回到": "回到 huí dào：声母由 b 变为 d，意思是返回到某处。", "回本": "回本 huí běn：韵母由 ao 变为 en，声调也不同，意思是收回成本。", "怀抱": "怀抱 huái bào：第一音节韵母由 ui 变为 uai，意思是胸怀或拥抱。"}, "sentence_index": null, "correct_answer": "回报"}, "level_3": {"options": [{"text": "回报", "is_correct": true, "explanation": "正确：报答别人的帮助，与“别人帮了你”相合。"}, {"text": "攻击", "is_correct": false, "explanation": "语义：别人帮了你之后再去“攻击”他，与前句的语境相反。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”的对象是车辆或船只，不能用于人。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：对帮助过自己的人“嘲笑”，与前句的感恩语境相悖。"}], "explanations": {"回报": "正确：报答别人的帮助，与“别人帮了你”相合。", "攻击": "语义：别人帮了你之后再去“攻击”他，与前句的语境相反。", "停靠": "搭配：“停靠”的对象是车辆或船只，不能用于人。", "嘲笑": "语义：对帮助过自己的人“嘲笑”，与前句的感恩语境相悖。"}, "sentence_index": 0, "correct_answer": "回报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些废纸应该回报再利用。", "explanation": "这里应该用〈回收〉。回报指报答别人的帮助，回收指把废品收集起来再利用。"}, {"text": "他总是回报这个问题。", "explanation": "这里应该用〈回避〉。回报指报答，回避指躲开问题。"}, {"text": "她常常回报童年的时光。", "explanation": "这里应该用〈回味〉。回报指报答，回味指回想并体会过去的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25110, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回报", "is_correct": true, "explanation": "回报 huí bào：别人帮了自己，自己也去帮别人作为报答，是本词。"}, {"text": "回拨", "is_correct": false, "explanation": "回拨 huí bō：韵母由 ao 变为 o，声调也不同，意思是回拨款项或拨回。"}, {"text": "回拜", "is_correct": false, "explanation": "回拜 huí bài：韵母由 ao 变为 ai，意思是回访。"}, {"text": "回补", "is_correct": false, "explanation": "回补 huí bǔ：韵母由 ao 变为 u，声调也不同，意思是补回、补足。"}], "explanations": {"回报": "回报 huí bào：别人帮了自己，自己也去帮别人作为报答，是本词。", "回拨": "回拨 huí bō：韵母由 ao 变为 o，声调也不同，意思是回拨款项或拨回。", "回拜": "回拜 huí bài：韵母由 ao 变为 ai，意思是回访。", "回补": "回补 huí bǔ：韵母由 ao 变为 u，声调也不同，意思是补回、补足。"}, "sentence_index": null, "correct_answer": "回报"}, "level_3": {"options": [{"text": "回报", "is_correct": true, "explanation": "正确：报答老师的教导，与“老师教了我很多”相合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是花果等，不能用于老师。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗老师”与“老师教了我很多”的感恩语境相反。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负老师”与感激的语境相反，不符合前句。"}], "explanations": {"回报": "正确：报答老师的教导，与“老师教了我很多”相合。", "摘": "搭配：“摘”的对象是花果等，不能用于老师。", "欺骗": "语义：“欺骗老师”与“老师教了我很多”的感恩语境相反。", "辜负": "语义：“辜负老师”与感激的语境相反，不符合前句。"}, "sentence_index": 6, "correct_answer": "回报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师寄来的信，我当天就回报了一封。", "explanation": "这里应该用〈回信〉。回报指报答别人的帮助，回复来信要用回信。"}, {"text": "他走出门口，又突然回报看了一眼。", "explanation": "这里应该用〈回头〉。回报指报答别人的帮助，转过头来看要用回头。"}, {"text": "学生举手，认真回报了老师的问题。", "explanation": "这里应该用〈回答〉。回报指报答别人的帮助，回答问题要用回答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "收到礼物后，我也要回报了朋友的心意。", "corrected_sentence": "收到礼物后，我也要回报朋友的心意。", "error_description": "“了”位置错误：“要”表示意愿或将来，后面的动词不能带“了”，应说“要回报朋友的心意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该常常过回报父母的养育之恩。", "corrected_sentence": "我们应该常常回报父母的养育之恩。", "error_description": "“过”用法错误：“过”是体标，只能放在动词后面表示经历，不能放在动词“回报”前面；这里说的是应该做的事，也不需要“过”，删去即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
