INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25112, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西变成数字来算。", "primary_collocate": null, "pronunciation": "liàng huà", "ipa": "ljaŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "老师说，学习进步可以量化。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把每天的运动时间量化。", "target_word": "量化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开心不开心，很难量化。", "target_word": "量化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用表格量化每月的花费。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种感觉没法量化。", "target_word": "量化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们先把问题量化，再讨论。", "target_word": "量化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用分数量化病人的疼痛。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把时间量化后，我发现浪费很多。", "target_word": "量化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢量化自己的生活。", "target_word": "量化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友的感情可以量化吗？", "target_word": "量化", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "量化了", "label": "体标"}, {"form": "量化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西变成数字来计算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "量化", "is_correct": true, "explanation": "量化：这里指把学习进步变成可以计算的数值，与语境相合。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指切开，学习进步不能被切开，与语境不合。"}, {"text": "抛光", "is_correct": false, "explanation": "语义：抛光指打磨表面使发亮，与学习进步的计算意思不合。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的对象是文字内容，不能说“学习进步可以背诵”。"}], "explanations": {"量化": "量化：这里指把学习进步变成可以计算的数值，与语境相合。", "切割": "语义：切割指切开，学习进步不能被切开，与语境不合。", "抛光": "语义：抛光指打磨表面使发亮，与学习进步的计算意思不合。", "背诵": "搭配：“背诵”的对象是文字内容，不能说“学习进步可以背诵”。"}, "sentence_index": 0, "correct_answer": "量化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向朋友量化了自己的心事。", "explanation": "这里应该用〈倾诉〉。量化指把东西变成数字来算；向朋友说心事要用倾诉。"}, {"text": "大家都要量化规则。", "explanation": "这里应该用〈遵守〉。量化指把东西变成数字来算，对规则的服从要用遵守。"}, {"text": "他每天晚上量化书包。", "explanation": "这里应该用〈整理〉。量化指把东西变成数字，整理书包要用整理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "量化", "is_correct": true, "explanation": "量化：这里指用分数把疼痛变成数值，与语境相合。"}, {"text": "涂抹", "is_correct": false, "explanation": "语义：涂抹指把东西抹在表面，不能用分数去涂抹疼痛。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：打扮指修饰外表，与用分数处理疼痛的意思不合。"}, {"text": "吸引", "is_correct": false, "explanation": "搭配：“吸引”的对象是人或注意力，不能说“吸引病人的疼痛”。"}], "explanations": {"量化": "量化：这里指用分数把疼痛变成数值，与语境相合。", "涂抹": "语义：涂抹指把东西抹在表面，不能用分数去涂抹疼痛。", "打扮": "语义：打扮指修饰外表，与用分数处理疼痛的意思不合。", "吸引": "搭配：“吸引”的对象是人或注意力，不能说“吸引病人的疼痛”。"}, "sentence_index": 6, "correct_answer": "量化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们量化了这首诗的美。", "explanation": "这里应该用〈欣赏〉。量化指把东西变成数字来算；体会诗的美要用欣赏。"}, {"text": "用彩灯量化房间。", "explanation": "这里应该用〈装饰〉。量化指变成数字来算，用彩灯美化房间要用装饰。"}, {"text": "她量化了一阵微风。", "explanation": "这里应该用〈感受〉。量化指把东西变成数字来算；体会微风的凉爽要用感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生把病人的疼痛量化的。", "corrected_sentence": "医生把病人的疼痛量化了。", "error_description": "“了”误用为“的”：动词“量化”后要用“了”表示完成，“的”不能接在动词后作谓语，应说“量化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把每天的步数量化了成数字。", "corrected_sentence": "我把每天的步数量化成数字。", "error_description": "“了”位置错误：“了”插在“量化”和补语“成”之间，补语结构中不能插入“了”，应说“量化成数字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
