INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某个人或事物有更强的能力去做事情。", "primary_collocate": null, "pronunciation": "fù néng", "ipa": "fu˥˩ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "好老师能赋能学生。", "target_word": "赋能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个软件赋能每一个小店主。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络课程赋能了很多农村孩子。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想用新设备赋能工人。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书赋能读者，让他们更会思考。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套训练方法赋能了我，让我敢去挑战。", "target_word": "赋能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科技正在赋能我们的生活。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多学一门语言，会赋能你的职业发展。", "target_word": "赋能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行赋能小公司，给它们更多机会。", "target_word": "赋能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好工具赋能团队，大家做事更快。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赋能了", "label": "体标（了）"}, {"form": "赋能过", "label": "体标（过）"}, {"form": "賦能", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "使人或事物获得更强的做事能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b763f8e4-c8e2-4fed-b4e1-513ee2e3c8b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赋能", "is_correct": true, "explanation": "赋能：给予能力，与“好老师”及“学生”的语境相符，表示老师帮助学生提升能力。"}, {"text": "误导", "is_correct": false, "explanation": "语义：“误导”是使人走错方向，与“好老师”的正面形象矛盾。"}, {"text": "折磨", "is_correct": false, "explanation": "语义：“折磨”是使人痛苦，与“好老师”的正面形象矛盾。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢下不管，与“好老师”的正面形象矛盾。"}], "explanations": {"赋能": "赋能：给予能力，与“好老师”及“学生”的语境相符，表示老师帮助学生提升能力。", "误导": "语义：“误导”是使人走错方向，与“好老师”的正面形象矛盾。", "折磨": "语义：“折磨”是使人痛苦，与“好老师”的正面形象矛盾。", "抛弃": "语义：“抛弃”是丢下不管，与“好老师”的正面形象矛盾。"}, "sentence_index": 0, "correct_answer": "赋能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项政策赋能了农民的收入。", "explanation": "这里应该用〈提升〉。赋能指给人或事物能力或条件，收入这类数量变化要用提升。"}, {"text": "图书馆赋能免费的座位。", "explanation": "这里应该用〈提供〉。赋能多指给人或组织能力，座位是物品，应用提供。"}, {"text": "社会赋能老师崇高的使命。", "explanation": "这里应该用〈赋予〉。赋能指提供能力或条件，使命这类抽象的任务要用赋予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赋能", "is_correct": true, "explanation": "赋能：给予能力，符合“科技正在……我们的生活”的积极语境。"}, {"text": "欺骗", "is_correct": false, "explanation": "配价：“欺骗”的对象须是人，不能以“生活”为宾语。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”指对人不热情，与“科技”的积极作用相反，“冷落生活”不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽，与“科技”带来改善的语境不符。"}], "explanations": {"赋能": "赋能：给予能力，符合“科技正在……我们的生活”的积极语境。", "欺骗": "配价：“欺骗”的对象须是人，不能以“生活”为宾语。", "冷落": "语义：“冷落”指对人不热情，与“科技”的积极作用相反，“冷落生活”不通。", "嘲笑": "语义：“嘲笑”是讥讽，与“科技”带来改善的语境不符。"}, "sentence_index": 6, "correct_answer": "赋能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员迅速赋能了大火。", "explanation": "这里应该用〈扑灭〉。赋能指给予能力，不能用于使火熄灭。"}, {"text": "工厂主要赋能家具。", "explanation": "这里应该用〈生产〉。赋能指给人或事物能力，不能用于制造货物。"}, {"text": "他努力赋能了污染。", "explanation": "这里应该用〈减少〉。赋能是正面的给予能力，不能用于降低污染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器赋能得每一位工人。", "corrected_sentence": "这台机器赋能了每一位工人。", "error_description": "错误：“得”不能直接接宾语，应改为“了”，说“赋能了每一位工人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统没赋能了很多车间。", "corrected_sentence": "这套系统没赋能很多车间。", "error_description": "错误：“没赋能了”，正确：“没赋能”。否定词“没”不能与“了”同用，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高收入", "is_correct": true, "explanation": "“高收入”与“低收入”构成反义关系，指收入多。"}, {"text": "公园", "is_correct": false, "explanation": "与“低收入”没有反义关系，只是普通名词。"}, {"text": "图书馆", "is_correct": false, "explanation": "与“低收入”没有反义关系，只是普通名词。"}, {"text": "地铁", "is_correct": false, "explanation": "与“低收入”没有反义关系，只是普通名词。"}], "correct_answer": "高收入", "explanations": {"高收入": "“高收入”与“低收入”构成反义关系，指收入多。", "公园": "与“低收入”没有反义关系，只是普通名词。", "图书馆": "与“低收入”没有反义关系，只是普通名词。", "地铁": "与“低收入”没有反义关系，只是普通名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高收入", "is_correct": true, "explanation": "“高收入”与“低收入”构成反义关系，指收入多。"}, {"text": "桌子", "is_correct": false, "explanation": "与“低收入”没有反义关系，只是普通名词。"}, {"text": "河流", "is_correct": false, "explanation": "与“低收入”没有反义关系，只是普通名词。"}, {"text": "草地", "is_correct": false, "explanation": "与“低收入”没有反义关系，只是普通名词。"}], "correct_answer": "高收入", "explanations": {"高收入": "“高收入”与“低收入”构成反义关系，指收入多。", "桌子": "与“低收入”没有反义关系，只是普通名词。", "河流": "与“低收入”没有反义关系，只是普通名词。", "草地": "与“低收入”没有反义关系，只是普通名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "赚的钱很少。", "primary_collocate": null, "pronunciation": "dī shōu rù", "ipa": "ti˥ ʂoʊ˥ ɻu˥˩", "syllable_count": 3, "sentences": [{"text": "他现在属于低收入群体，生活不容易。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "因为家里是低收入家庭，我们很少去饭店吃饭。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "低收入的家庭常常要算着花钱。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸工作很累，家里却仍是低收入家庭。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "她家是低收入家庭，所以买衣服很小心。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "低收入的人也想过好日子。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他属于低收入人群，很难买得起房子。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "这份工作主要由低收入人群来做，大家都不想做。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "我们家属于低收入人群，但是大家很开心。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}, {"text": "很多年轻人刚工作时都属于低收入人群。", "target_word": "低收入", "complexity_tier": "T3", "furigana": "dī shōu rù", "sentence_source": "generated"}], "morphological_forms": [{"form": "低收入者", "label": "复合词"}, {"form": "低收入群体", "label": "复合词"}], "register": "中性", "sense_fingerprint": "赚的钱很少，生活开销紧张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低收入", "is_correct": true, "explanation": "正确：“低收入群体”指收入少的人群，与“生活不容易”相符。"}, {"text": "高收入", "is_correct": false, "explanation": "语义：“高收入”与后半句“生活不容易”矛盾。"}, {"text": "富人", "is_correct": false, "explanation": "语义：“富人”的生活一般不会“不容易”，与后半句矛盾。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”多描述生活或地区，与“群体”组合不如“富人群体”自然，且与“生活不容易”矛盾。"}], "explanations": {"低收入": "正确：“低收入群体”指收入少的人群，与“生活不容易”相符。", "高收入": "语义：“高收入”与后半句“生活不容易”矛盾。", "富人": "语义：“富人”的生活一般不会“不容易”，与后半句矛盾。", "富裕": "搭配：“富裕”多描述生活或地区，与“群体”组合不如“富人群体”自然，且与“生活不容易”矛盾。"}, "sentence_index": 0, "correct_answer": "低收入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔投资的低收入很少，老板很失望。", "explanation": "这里应该用〈收益〉。低收入只说人或家庭的收入，投资的回报应说收益。"}, {"text": "这次考试我的成绩是低收入的，老师很担心。", "explanation": "这里应该用〈低〉或〈差〉。低收入只说人或家庭的收入，不能形容成绩。"}, {"text": "这块地的低收入很差，种不出庄稼。", "explanation": "这里应该用〈低产〉。低收入只说人或家庭，不说土地的产出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低收入", "is_correct": true, "explanation": "正确：“低收入人群”指收入少的群体，与“很难买得起房子”相符。"}, {"text": "富翁", "is_correct": false, "explanation": "语义：“富翁”家境富裕，与“很难买得起房子”矛盾。"}, {"text": "高薪", "is_correct": false, "explanation": "语义：“高薪”指收入高，与“很难买得起房子”矛盾。"}, {"text": "富有", "is_correct": false, "explanation": "搭配：“富有”多修饰人或事物，“富有人群”不是常用说法，且与“很难买得起房子”矛盾。"}], "explanations": {"低收入": "正确：“低收入人群”指收入少的群体，与“很难买得起房子”相符。", "富翁": "语义：“富翁”家境富裕，与“很难买得起房子”矛盾。", "高薪": "语义：“高薪”指收入高，与“很难买得起房子”矛盾。", "富有": "搭配：“富有”多修饰人或事物，“富有人群”不是常用说法，且与“很难买得起房子”矛盾。"}, "sentence_index": 6, "correct_answer": "低收入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学水平属于低收入，需要补课。", "explanation": "这里应该用〈偏低〉。低收入指人或家庭的收入少，不用来说水平高低。"}, {"text": "他在公司里的低收入，大家都不太听他的。", "explanation": "这里应该用〈地位〉。低收入只说收入少，不说在公司里的位置或威信。"}, {"text": "这家小店给员工的是低收入，所以员工经常换。", "explanation": "这里应该用〈低薪〉。低收入说的是人或家庭的收入，工资的多少应说低薪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他属于很低收入人群，生活很紧张。", "corrected_sentence": "他属于低收入人群，生活很紧张。", "error_description": "错误：“很低收入人群”。正确：“低收入人群”。“低收入”作定语修饰“人群”，前面不能加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些都是低收入们的家庭。", "corrected_sentence": "这些都是低收入家庭。", "error_description": "错误：“低收入们”。正确：“低收入家庭”。“低收入”不能加复数词尾“们”，应直接修饰“家庭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
