INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "粮食指稻、麦、玉米等可以作为主食的谷物。", "primary_collocate": null, "pronunciation": "liáng shi", "ipa": "ljɑŋ˧˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "农民种了很多粮食。", "target_word": "粮食", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能浪费粮食。", "target_word": "粮食", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年的粮食产量很高。", "target_word": "粮食", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋天是收粮食的季节。", "target_word": "粮食", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家里有一袋粮食，够吃一个月。", "target_word": "粮食", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家需要从国外买粮食。", "target_word": "粮食", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把粮食放在仓库里，不怕坏。", "target_word": "粮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，田里的粮食都坏了。", "target_word": "粮食", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷小时候家里很穷，常常没有粮食吃。", "target_word": "粮食", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的人用粮食换了一头牛。", "target_word": "粮食", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "量词"}, {"form": "吨", "label": "量词"}, {"form": "粮食作物", "label": "复合"}, {"form": "糧食", "label": "繁体"}], "register": "中性", "sense_fingerprint": "粮食|名词|人们吃的主食类食物，如米、面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粮食", "is_correct": true, "explanation": "粮食：指米、面等主食，“农民种了很多粮食”正确。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能种植，“种”的对象应是植物，“种了很多石头”不通。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不能种植，“种”不能搭配“钱”，句子不通。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能种植，“种了很多衣服”不通。"}], "explanations": {"粮食": "粮食：指米、面等主食，“农民种了很多粮食”正确。", "石头": "语义：石头不能种植，“种”的对象应是植物，“种了很多石头”不通。", "钱": "语义：钱不能种植，“种”不能搭配“钱”，句子不通。", "衣服": "语义：衣服不能种植，“种了很多衣服”不通。"}, "sentence_index": 0, "correct_answer": "粮食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的粮食很好吃。", "explanation": "这里应该用〈食物〉。“粮食”专指米、面等主食，饭店做的菜不叫粮食。"}, {"text": "这只小猫最喜欢的粮食是鱼。", "explanation": "这里应该用〈食物〉。“粮食”专指米、面等谷物主食，鱼不是粮食，应说“食物”。"}, {"text": "早上我喝了一杯粮食。", "explanation": "这里应该用〈牛奶〉。“粮食”是固体主食，不能用来喝，喝的应是牛奶等液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粮食", "is_correct": true, "explanation": "粮食：耐储存，适合放在仓库里，“不怕坏”与之相符，正确。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：鲜花容易枯萎变坏，与“不怕坏”矛盾，句子不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果容易腐烂，与“不怕坏”矛盾，前后不一致。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“不怕坏”通常用于耐储存的东西，蛋糕易变质，两者不搭。"}], "explanations": {"粮食": "粮食：耐储存，适合放在仓库里，“不怕坏”与之相符，正确。", "鲜花": "语义：鲜花容易枯萎变坏，与“不怕坏”矛盾，句子不通。", "水果": "语义：水果容易腐烂，与“不怕坏”矛盾，前后不一致。", "蛋糕": "搭配：“不怕坏”通常用于耐储存的东西，蛋糕易变质，两者不搭。"}, "sentence_index": 6, "correct_answer": "粮食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用粮食盖房子。", "explanation": "这里应该用〈木头〉。“粮食”是吃的东西，不能用来盖房子。"}, {"text": "学生用粮食写字。", "explanation": "这里应该用〈纸〉。“粮食”不能用来写字，写字要用纸等书写材料。"}, {"text": "妈妈用粮食做衣服。", "explanation": "这里应该用〈布〉。“粮食”不能用来做衣服，做衣服要用布料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民今年收了很多只粮食。", "corrected_sentence": "农民今年收了很多吨粮食。", "error_description": "“粮食”前的量词用错。正确的是“吨”“袋”等，“只”多用于动物等，不能用来修饰“粮食”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里存着吨粮食。", "corrected_sentence": "仓库里存着几吨粮食。", "error_description": "量词“吨”前缺少数词。数量词组需要数词，正确的是“几吨粮食”，去掉“几”后“吨粮食”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
