INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家自己管自己的权力。", "primary_collocate": null, "pronunciation": "zhǔ quán", "ipa": "ʈʂu˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "国家有主权，别国不能乱管。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家的主权很重要。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，主权就是国家自己管自己。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们国家的主权，别人不能拿走。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都爱护自己的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别的国家想拿走我们的主权，我们不同意。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说到了两个国家的主权问题。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家失去主权，就不能自己做决定。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国重视主权，也尊重别国的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地理课上，我们学到每个国家都有自己的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主权国家", "label": "复合"}, {"form": "国家主权", "label": "复合"}, {"form": "主權", "label": "繁体"}], "register": "正式", "sense_fingerprint": "主权：国家自己管理自己的权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主权", "is_correct": true, "explanation": "正确：主权指国家自己管理自己的权力，“有主权，别国不能乱管”语义连贯。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或动物身体的重量，国家没有体重，别国也无从“乱管”它。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不能用来说国家有没有身高。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，国家不能拥有天气，句子的意思不通。"}], "explanations": {"主权": "正确：主权指国家自己管理自己的权力，“有主权，别国不能乱管”语义连贯。", "体重": "语义：体重是人或动物身体的重量，国家没有体重，别国也无从“乱管”它。", "身高": "体貌：身高是人的外形特征，不能用来说国家有没有身高。", "天气": "语义：天气是自然现象，国家不能拥有天气，句子的意思不通。"}, "sentence_index": 0, "correct_answer": "主权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们国家的主权很大，别人不能拿走。", "explanation": "这里应该用〈领土〉。主权是国家的权力，不说大小；说土地的范围大小要用领土。"}, {"text": "他有中国主权，所以可以去那里工作。", "explanation": "这里应该用〈国籍〉。主权只属于国家，个人不能拥有主权；一个人属于哪个国家要用国籍。"}, {"text": "这块主权是我们国家的，别人不能拿走。", "explanation": "这里“块”用错了，应该用〈项〉。“块”用于有形的一块东西或一片土地，主权是抽象的权力，应说“这项主权”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主权", "is_correct": true, "explanation": "正确：“两个国家的主权问题”指国家自己管理自己权力的问题，与“新闻里说到”的语境相符。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”一般指人或动物的视觉能力，不说“两个国家的视力问题”。"}, {"text": "食量", "is_correct": false, "explanation": "语义：食量指吃东西的多少，与国家的权力无关，句子不通。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是人或动物的生理特征，国家没有血型，句子不通。"}], "explanations": {"主权": "正确：“两个国家的主权问题”指国家自己管理自己权力的问题，与“新闻里说到”的语境相符。", "视力": "搭配：“视力”一般指人或动物的视觉能力，不说“两个国家的视力问题”。", "食量": "语义：食量指吃东西的多少，与国家的权力无关，句子不通。", "血型": "语义：血型是人或动物的生理特征，国家没有血型，句子不通。"}, "sentence_index": 6, "correct_answer": "主权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他取得了参赛主权。", "explanation": "这里应该用〈资格〉。主权是国家的权力，不能用来指参加比赛的条件；获得参赛的条件要用资格。"}, {"text": "他的主权很有道理。", "explanation": "这里应该用〈主张〉。主权是国家的权力，不是看法；表示观点要用主张。"}, {"text": "这次比赛我们拿到了主权。", "explanation": "这里应该用〈冠军〉。主权是国家的权力，不能用来说比赛的名次；比赛获胜的名次要用冠军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "主权的国家应该尊重彼此的主权。", "corrected_sentence": "主权国家应该尊重彼此的主权。", "error_description": "“主权的国家”错误，应为“主权国家”。“主权”作定语修饰“国家”时不加“的”，“主权国家”是固定的复合词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个国家不能失去了主权。", "corrected_sentence": "一个国家不能失去主权。", "error_description": "“不能失去了主权”错误。“不能”表示禁止或可能性，后面的动作还没有发生，不能加完成体“了”，应说“不能失去主权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
