INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "意思是拥有或得到某种好处。", "primary_collocate": null, "pronunciation": "xiǎng yǒu", "ipa": "ɕiɑŋ˨˩ iou˨˩", "syllable_count": 2, "sentences": [{"text": "每个公民都享有选举的权利。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们享有受教育的权利。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在学校里享有很高的声誉。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店在本地享有盛名。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们享有每年休假的权利。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在这个国家享有很多福利。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员享有九折的优惠。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在法律面前享有平等的地位。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市以美食享有盛名。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这里的居民享有免费用水的待遇。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "享有着", "label": "体标"}, {"form": "享有过", "label": "体标"}], "register": "书面", "sense_fingerprint": "拥有或得到权利、声誉、待遇等好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "享有", "is_correct": true, "explanation": "正确：“享有”指拥有或得到权利，与“每个公民都……选举的权利”相符。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”的宾语是具体产品，不能说“制造选举的权利”。"}, {"text": "限制", "is_correct": false, "explanation": "语义：“限制”通常由他人施加，与“每个公民都”自己拥有权利的意思矛盾。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”后接责任、义务，不接“选举的权利”。"}], "explanations": {"享有": "正确：“享有”指拥有或得到权利，与“每个公民都……选举的权利”相符。", "制造": "搭配：“制造”的宾语是具体产品，不能说“制造选举的权利”。", "限制": "语义：“限制”通常由他人施加，与“每个公民都”自己拥有权利的意思矛盾。", "承担": "搭配：“承担”后接责任、义务，不接“选举的权利”。"}, "sentence_index": 0, "correct_answer": "享有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的房子享有很大的面积。", "explanation": "这里应该用〈有〉。面积是房子本身的属性，不是可以享受的好处，不能说享有。"}, {"text": "这种材料享有很强的韧性。", "explanation": "这里应该用〈具备〉。享有指得到好处，材料的性质应说具备。"}, {"text": "他享有很多麻烦。", "explanation": "这里应该用〈遇到〉。享有只用于权利、利益等好的方面，不能用于麻烦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "享有", "is_correct": true, "explanation": "正确：“享有”指得到权利或好处，与“会员……九折的优惠”相符。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：“支付”的宾语应是钱款，不能说“支付……优惠”。"}, {"text": "设计", "is_correct": false, "explanation": "语义：会员不会“设计”商家的优惠，与句意矛盾。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”表示取消，与“会员”得到优惠的意思矛盾。"}], "explanations": {"享有": "正确：“享有”指得到权利或好处，与“会员……九折的优惠”相符。", "支付": "搭配：“支付”的宾语应是钱款，不能说“支付……优惠”。", "设计": "语义：会员不会“设计”商家的优惠，与句意矛盾。", "收回": "语义：“收回”表示取消，与“会员”得到优惠的意思矛盾。"}, "sentence_index": 6, "correct_answer": "享有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市享有很多责任，压力很大。", "explanation": "这里应该用〈承担〉。享有指得到权利或利益，责任要用承担。"}, {"text": "他在比赛中享有好成绩，大家很高兴。", "explanation": "这里应该用〈取得〉。享有指得到权利、利益、声誉，成绩要用取得。"}, {"text": "他的孩子享有治疗，很快就好了。", "explanation": "这里应该用〈接受〉。享有指得到权利或利益，治疗是接受的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个学生都很享有免费的午餐。", "corrected_sentence": "每个学生都享有免费的午餐。", "error_description": "错误：“很享有”。正确：“享有”。“享有”是动词，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们享有给平等的受教育机会。", "corrected_sentence": "学生们享有平等的受教育机会。", "error_description": "错误：“享有给”。正确：“享有”。“给”在这里多余，“享有”的宾语前不能加“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
