INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25126, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特权就是只有少数人才能有的特别权利。", "primary_collocate": null, "pronunciation": "tè quán", "ipa": "tʰɤ˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "只有老板有这个特权。", "target_word": "特权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生没有迟到的特权。", "target_word": "特权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国王有很多普通人没有的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得自己是老大，有特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会员有先买票的特权。", "target_word": "特权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这个家里，爷爷有坐大椅子的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，谁也没有不写作业的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有钱人不应该有特权。", "target_word": "特权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小区的住户有免费停车的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长有第一个选座位的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "特權", "label": "繁体"}, {"form": "特权阶级", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "只有少数人才有的特别权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特权", "is_correct": true, "explanation": "正确：“这个特权”指只属于少数人的特别权利，与“只有老板有”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生的学习任务，与“只有老板有”不搭。"}, {"text": "考卷", "is_correct": false, "explanation": "搭配：“考卷”是学生用的，不能说“老板有这个考卷”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是学生的学习用品，与老板的身份不合。"}], "explanations": {"特权": "正确：“这个特权”指只属于少数人的特别权利，与“只有老板有”相符。", "作业": "语义：“作业”是学生的学习任务，与“只有老板有”不搭。", "考卷": "搭配：“考卷”是学生用的，不能说“老板有这个考卷”。", "课本": "语义：“课本”是学生的学习用品，与老板的身份不合。"}, "sentence_index": 0, "correct_answer": "特权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个人都有选择职业的特权。", "explanation": "这里应该用〈权利〉。人人都有的选择权要说“权利”，“特权”只指少数人才有的特别权利。"}, {"text": "他有很强的特权，做事总是很快。", "explanation": "这里应该用〈能力〉。“特权”指只属于少数人的权利，不能用来指能力强。"}, {"text": "他有照顾弟弟的特权，每天都要接送他上学。", "explanation": "这里应该用〈义务〉。接送弟弟是应尽的义务，“特权”指只属于少数人的特别权利，不能用来说分内的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特权", "is_correct": true, "explanation": "正确：“不写作业的特权”指少数人才有的特别权利，与“谁也没有”的语境相符。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：“荣誉”指值得夸耀的名声，与“不写作业”的语境不合。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：“冠军”指比赛第一名，与“不写作业”毫无关系。"}, {"text": "奖状", "is_correct": false, "explanation": "搭配：“奖状”是奖励凭证，不能与“不写作业”搭配。"}], "explanations": {"特权": "正确：“不写作业的特权”指少数人才有的特别权利，与“谁也没有”的语境相符。", "荣誉": "语义：“荣誉”指值得夸耀的名声，与“不写作业”的语境不合。", "冠军": "语义：“冠军”指比赛第一名，与“不写作业”毫无关系。", "奖状": "搭配：“奖状”是奖励凭证，不能与“不写作业”搭配。"}, "sentence_index": 6, "correct_answer": "特权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长的特权是维护课堂纪律。", "explanation": "这里应该用〈职责〉。维护纪律是班长的职责，“特权”指只属于少数人的待遇。"}, {"text": "这所学校的特权是音乐教育。", "explanation": "这里应该用〈特色〉。“特权”指只属于少数人的特别权利，学校的办学风格要说“特色”。"}, {"text": "我的特权是喜欢唱歌，每天都唱很久。", "explanation": "这里应该用〈爱好〉。“特权”指只属于少数人的权利，个人喜欢做的事要说“爱好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长有一只特权，可以先选座位。", "corrected_sentence": "班长有一项特权，可以先选座位。", "error_description": "“特权”的量词应用“项”或“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长享有一项的特权，可以先选座位。", "corrected_sentence": "班长享有一项特权，可以先选座位。", "error_description": "数量短语“一项”后不能直接加“的”修饰名词，应说“一项特权”，不说“一项的特权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
