INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25128, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个事物与另一个事物相反的样子。", "primary_collocate": null, "pronunciation": "duì lì miàn", "ipa": "twei˥˩ li˥˩ mjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "冷的对立面是热。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种想法正好是对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天的对立面是黑夜。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大和小是一对对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的性格是姐姐的对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安静的对立面是吵闹。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法正好站在我的对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上和下互为对立面。", "target_word": "对立面", "complexity_tier": "T3", "furigana": "shàng hé xià hù wéi duì lì miàn", "sentence_source": "generated"}, {"text": "诚实的对立面是说谎。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“高”这个词的对立面你知道吗？", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物性质或特点上互相相反的一面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对立面", "is_correct": true, "explanation": "正确：“对立面”指与另一事物相反的一面，“冷的对立面是热”通顺。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热的程度，本身不是“冷”的对立面，“冷的温度是热”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“冷”不修饰“名字”，“冷的名字”不成词组，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能与“热”构成相反的一面，“冷的味道是热”说不通。"}], "explanations": {"对立面": "正确：“对立面”指与另一事物相反的一面，“冷的对立面是热”通顺。", "温度": "语义：“温度”是冷热的程度，本身不是“冷”的对立面，“冷的温度是热”说不通。", "名字": "搭配：“冷”不修饰“名字”，“冷的名字”不成词组，句子说不通。", "味道": "语义：“味道”不能与“热”构成相反的一面，“冷的味道是热”说不通。"}, "sentence_index": 0, "correct_answer": "对立面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸的对立面写着字。", "explanation": "这里应该用〈反面〉。“对立面”指性质或观点相反的一面，指纸的背面要说“反面”。"}, {"text": "他和我分在同一队，是我的对立面。", "explanation": "这里应该用〈队友〉。“对立面”指性质相反的一方，同队的人要说“队友”。"}, {"text": "比赛开始后，对立面一直控制着球。", "explanation": "这里应该用〈对方〉。“对立面”指性质相反的一方，比赛中的对手要说“对方”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对立面", "is_correct": true, "explanation": "正确：“对立面”指与“我”的看法相反的一面，“站在我的对立面”通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“站在”不能带“年龄”作处所，“站在我的年龄”不成词组。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”不是可以站立的地方，“站在我的地图”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能作站立的场所，“站在我的手机”说不通。"}], "explanations": {"对立面": "正确：“对立面”指与“我”的看法相反的一面，“站在我的对立面”通顺。", "年龄": "搭配：“站在”不能带“年龄”作处所，“站在我的年龄”不成词组。", "地图": "语义：“地图”不是可以站立的地方，“站在我的地图”说不通。", "手机": "语义：“手机”不能作站立的场所，“站在我的手机”说不通。"}, "sentence_index": 6, "correct_answer": "对立面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "针对这个问题，公司制定了新的对立面。", "explanation": "这里应该用〈对策〉。“对立面”指性质相反的一面，不指应付问题的办法；制定办法要说“对策”。"}, {"text": "他是我最好的对立面。", "explanation": "这里应该用〈同伴〉。“对立面”指性质相反的一方，不指一起行动的伙伴；朋友、伙伴要说“同伴”。"}, {"text": "这把刀是我的对立面。", "explanation": "这里应该用〈工具〉。“对立面”指性质相反的事物，不指用来干活的器具；作为用具要说“工具”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种观点是一只对立面，很难同时成立。", "corrected_sentence": "这两种观点是一对对立面，很难同时成立。", "error_description": "错误在量词：“对立面”前应用“对”（一对对立面），不能用“只”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在这个问题上，他的看法成了我在对立面。", "corrected_sentence": "在这个问题上，他的看法成了我的对立面。", "error_description": "错误在定语标记：“我”修饰“对立面”要用“的”，说“我的对立面”，不能说“我在对立面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
