INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起做一件事。", "primary_collocate": null, "pronunciation": "xié tóng", "ipa": "ɕjɛ˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "两个部门协同完成这项工作。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们协同合作，才能成功。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和警察协同救了那个人。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要协同解决这个问题。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个学校协同办了这次活动。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人与工程师协同工作。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几家公司协同修了新路。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国协同帮助受灾的人。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长协同教育孩子。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们协同做好了这件事。", "target_word": "协同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协同作战", "label": "复合"}, {"form": "協同", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多方互相配合，一起完成一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对抗", "is_correct": false, "explanation": "语义：“对抗”是相互抗衡，与“共同完成工作”的意思相反。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“完成这项工作”搭配，句子不通。"}, {"text": "协同", "is_correct": true, "explanation": "正确：协同指多方一起做事，符合“两个部门”共同完成工作的语境。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”要求买卖的对象，不能带“完成这项工作”作宾语。"}], "explanations": {"对抗": "语义：“对抗”是相互抗衡，与“共同完成工作”的意思相反。", "唱": "搭配：“唱”不能与“完成这项工作”搭配，句子不通。", "协同": "正确：协同指多方一起做事，符合“两个部门”共同完成工作的语境。", "卖": "配价：“卖”要求买卖的对象，不能带“完成这项工作”作宾语。"}, "sentence_index": 0, "correct_answer": "协同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个孩子协同玩了一下午。", "explanation": "这里应该用〈一起〉。协同强调多方配合完成一件任务，玩耍不用协同，要说一起玩。"}, {"text": "我协同写完了作业。", "explanation": "这里应该用〈独立〉。协同要求多方一起做，一个人写作业不能说协同。"}, {"text": "两国在战场上互相开火，并且协同作战。", "explanation": "这里前后矛盾：“互相开火”是对抗，与“协同作战”（同一方共同行动）不能并存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“修了新路”（已经完成）相矛盾，不合语境。"}, {"text": "协同", "is_correct": true, "explanation": "正确：协同指多方一起做事，与“这几家公司”一起修路相合。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”与“修了新路”（已经完成）相矛盾，句子不合常理。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”与“修新路”的动作相反，句子不通。"}], "explanations": {"拒绝": "语义：“拒绝”与“修了新路”（已经完成）相矛盾，不合语境。", "协同": "正确：协同指多方一起做事，与“这几家公司”一起修路相合。", "禁止": "语义：“禁止”与“修了新路”（已经完成）相矛盾，句子不合常理。", "拆除": "语义：“拆除”与“修新路”的动作相反，句子不通。"}, "sentence_index": 6, "correct_answer": "协同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明协同洗好了碗。", "explanation": "这里应该用〈独自〉。协同要多方一起做，一个人洗碗不能说协同。"}, {"text": "他一个人协同搬完了所有的箱子。", "explanation": "这里应该用〈独自〉。协同要求多方一起配合做事，“一个人”搬箱子不能说协同。"}, {"text": "我们在公园里协同放风筝，各玩各的。", "explanation": "这里应该用〈各自〉。协同指大家配合做一件事，各玩各的就不是协同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们协同得解决了这个难题。", "corrected_sentence": "我们协同解决了这个难题。", "error_description": "“协同”作状语修饰“解决”，后面不能加“得”（“得”用于动词后的补语）；应说“我们协同解决了这个难题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位工程师协同得设计了新桥。", "corrected_sentence": "三位工程师协同设计了新桥。", "error_description": "“协同”作状语修饰“设计”，中间不能加“得”（“得”用于动词后的补语）；应说“协同设计了新桥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
