INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25132, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把别人的东西拿过来，变成自己的。", "primary_collocate": null, "pronunciation": "zhàn yǒu", "ipa": "ʈʂan˥˩ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想占有朋友的东西。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人占有了老人的房子。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人用假合同占有了别人的钱。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王占有了邻国的土地。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人不该占有别人的财产。", "target_word": "占有", "complexity_tier": "T3", "furigana": "nà ge rén bù gāi zhànyǒu biéren de cáichǎn.", "sentence_source": "generated"}, {"text": "哥哥偷偷占有了我的书。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能占有员工的工资。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人偷偷占有了别人的电脑。", "target_word": "占有", "complexity_tier": "T3", "furigana": "nà ge rén tōutōu zhànyǒu le biéren de diànnǎo.", "sentence_source": "generated"}, {"text": "他占有这笔钱，不肯还给我们。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有人占有公共的土地。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占有了", "label": "体标"}, {"form": "占有着", "label": "体标"}, {"form": "占有过", "label": "体标"}, {"form": "占有欲", "label": "复合"}], "register": "中性", "sense_fingerprint": "把别人的东西拿来据为己有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占有", "is_correct": true, "explanation": "占有：把朋友的东西据为己有，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”的对象是人，不能说“表扬朋友的东西”。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”的对象是人或情绪，不能用于东西。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”针对人或关系，说“冷落东西”句意不通。"}], "explanations": {"占有": "占有：把朋友的东西据为己有，符合句意。", "表扬": "语义：“表扬”的对象是人，不能说“表扬朋友的东西”。", "安慰": "语义：“安慰”的对象是人或情绪，不能用于东西。", "冷落": "语义：“冷落”针对人或关系，说“冷落东西”句意不通。"}, "sentence_index": 0, "correct_answer": "占有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我占有一辆自己买的车。", "explanation": "这里应该用〈拥有〉。占有含有把别人的东西拿来据为己有的意思，指自己买来的车要用拥有。"}, {"text": "这件事占有了我三个小时。", "explanation": "这里应该用〈占用〉。占用多用于时间、空间，占有多用于财物，不说占有时间。"}, {"text": "这种材料占有很强的弹性。", "explanation": "这里应该用〈具有〉。占有只用于人对财物的据有，材料的性质、特点要用具有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占有", "is_correct": true, "explanation": "占有：把员工的工资据为己有，符合句意。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示爱好，句中说的是公司对工资的处理，句意不通。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”的对象是人或物体表面，不能拍工资。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不说唱工资。"}], "explanations": {"占有": "占有：把员工的工资据为己有，符合句意。", "喜欢": "语义：“喜欢”表示爱好，句中说的是公司对工资的处理，句意不通。", "拍": "搭配：“拍”的对象是人或物体表面，不能拍工资。", "唱": "搭配：“唱”的对象是歌曲，不说唱工资。"}, "sentence_index": 6, "correct_answer": "占有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很好地占有了这门外语。", "explanation": "这里应该用〈掌握〉。占有用于财物，学会语言、技能要用掌握。"}, {"text": "这次行动占有了很大的成功。", "explanation": "这里应该用〈取得〉。占有只用于财物，成功、成绩要用取得。"}, {"text": "她占有了大家的尊重。", "explanation": "这里应该用〈赢得〉。占有强调把财物据为己有，尊重、信任要用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他非法占有成了一块农田。", "corrected_sentence": "他非法占有了一块农田。", "error_description": "动词用错：“占有”后面表示完成应接“了”，不能接动词“成”，“成”会让句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他非法占有了着那片林地。", "corrected_sentence": "他非法占有着那片林地。", "error_description": "助词用错：表示持续时已用“着”，后面不能再加“了”，应说“占有着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
