INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "福祉就是幸福和好运。", "primary_collocate": null, "pronunciation": "fú zhǐ", "ipa": "fu˧˥ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "祝您和家人永远享有福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱护孩子，就是为他们的福祉着想。", "target_word": "福祉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的邻居带给大家福祉。", "target_word": "福祉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家平安，就是最大的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的人民享受着和平的福祉。", "target_word": "福祉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生的精力都用在家乡人的福祉上。", "target_word": "福祉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人希望子孙后代享有福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康的身体是个人福祉的基础。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们的福祉取决于这片土地。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家的发展，最终要为百姓带来福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "幸福和好运", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "福祉", "is_correct": true, "explanation": "福祉 fú zhǐ：幸福和好运，是本词。"}, {"text": "服饰", "is_correct": false, "explanation": "服饰 fú shì：第二音节声母由 zh 变为 sh，声调也不同，意思是衣服和装饰品。"}, {"text": "复职", "is_correct": false, "explanation": "复职 fù zhí：声母韵母相同，两个音节声调都不同，意思是恢复原来的职务。"}, {"text": "扶志", "is_correct": false, "explanation": "扶志 fú zhì：第二音节由第三声变为第四声，意思是扶助意志。"}], "explanations": {"福祉": "福祉 fú zhǐ：幸福和好运，是本词。", "服饰": "服饰 fú shì：第二音节声母由 zh 变为 sh，声调也不同，意思是衣服和装饰品。", "复职": "复职 fù zhí：声母韵母相同，两个音节声调都不同，意思是恢复原来的职务。", "扶志": "扶志 fú zhì：第二音节由第三声变为第四声，意思是扶助意志。"}, "sentence_index": null, "correct_answer": "福祉"}, "level_3": {"options": [{"text": "福祉", "is_correct": true, "explanation": "正确：福祉指幸福和好运，与“永远享有”的祝福语境相合。"}, {"text": "困难", "is_correct": false, "explanation": "搭配：“享有”多用于好的事物，不能与“困难”搭配。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，与祝福的语境相悖。"}, {"text": "债务", "is_correct": false, "explanation": "语义：“债务”是负担，与“永远享有”的祝福语境不符。"}], "explanations": {"福祉": "正确：福祉指幸福和好运，与“永远享有”的祝福语境相合。", "困难": "搭配：“享有”多用于好的事物，不能与“困难”搭配。", "垃圾": "语义：“垃圾”是废弃物，与祝福的语境相悖。", "债务": "语义：“债务”是负担，与“永远享有”的祝福语境不符。"}, "sentence_index": 0, "correct_answer": "福祉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的福祉很好。", "explanation": "这里应该用〈运气〉。福祉指幸福和好运，多指整体的生活状况，不用来形容某次考试的运气好坏。"}, {"text": "这笔投资带来了不错的福祉。", "explanation": "这里应该用〈收益〉。收益指经济上的所得，福祉指幸福和好运，不用于投资的回报。"}, {"text": "他攒下了很多福祉。", "explanation": "这里应该用〈财富〉。财富指可以积攒的钱财或物资，福祉不能积攒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "福祉", "is_correct": true, "explanation": "福祉 fú zhǐ：幸福和好运，是本词。"}, {"text": "扶植", "is_correct": false, "explanation": "扶植 fú zhí：第二音节声调不同（第三声与第二声），意思是扶助、培植。"}, {"text": "扶持", "is_correct": false, "explanation": "扶持 fú chí：声母由 zh 变为 ch，声调也不同，意思是扶助支持。"}, {"text": "废纸", "is_correct": false, "explanation": "废纸 fèi zhǐ：韵母由 u 变为 ei，声调也不同，意思是没用的纸。"}, {"text": "肤质", "is_correct": false, "explanation": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}], "explanations": {"福祉": "福祉 fú zhǐ：幸福和好运，是本词。", "扶植": "扶植 fú zhí：第二音节声调不同（第三声与第二声），意思是扶助、培植。", "扶持": "扶持 fú chí：声母由 zh 变为 ch，声调也不同，意思是扶助支持。", "废纸": "废纸 fèi zhǐ：韵母由 u 变为 ei，声调也不同，意思是没用的纸。", "肤质": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}, "sentence_index": null, "correct_answer": "福祉"}, "level_3": {"options": [{"text": "福祉", "is_correct": true, "explanation": "正确：福祉指幸福和好运，与“希望子孙后代”的祝愿语境相合。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是令人烦恼的声音，与祝愿的语境相悖。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”的对象是车辆或船只，不能与“享有”搭配。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：“蚊子”是害虫，与“子孙后代享有”的祝愿语境不符。"}], "explanations": {"福祉": "正确：福祉指幸福和好运，与“希望子孙后代”的祝愿语境相合。", "噪音": "语义：“噪音”是令人烦恼的声音，与祝愿的语境相悖。", "停靠": "搭配：“停靠”的对象是车辆或船只，不能与“享有”搭配。", "蚊子": "语义：“蚊子”是害虫，与“子孙后代享有”的祝愿语境不符。"}, "sentence_index": 6, "correct_answer": "福祉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的福祉很好，穿着很舒服。", "explanation": "这里应该用〈质量〉。福祉指人的幸福和好运，不能用来说衣服好不好。"}, {"text": "他每个月的福祉有五千块。", "explanation": "这里应该用〈工资〉。工资是每月领的钱，福祉指幸福和好运，不是钱。"}, {"text": "今天的福祉很好，出太阳了。", "explanation": "这里应该用〈天气〉。说晴天雨天要用天气，福祉指幸福和好运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作曾经为家人带来着福祉。", "corrected_sentence": "这份工作曾经为家人带来过福祉。", "error_description": "体标误用：“曾经”表示经历过，应用“过”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一生家乡人谋福祉。", "corrected_sentence": "他一生为家乡人谋福祉。", "error_description": "介词缺失：“为家乡人”表示对象，不能省去“为”，应说“为家乡人谋福祉”，不能说“家乡人谋福祉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
