INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子下面的石头，让房子站得稳。", "primary_collocate": null, "pronunciation": "gēn jī", "ipa": "kən˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "房子的根基是用大石头做的。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座老房子的根基很稳。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人先在地下打好根基，再盖房子。", "target_word": "根基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根基不稳，房子就会倒。", "target_word": "根基", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大雨冲走了房子旁边的土，根基露出来了。", "target_word": "根基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些大石头是房子的根基。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老房子的根基一百年了还很结实。", "target_word": "根基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在地上看房子的根基有没有裂开。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塔很高，所以根基也要很深。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民把大石头搬到房子下面当根基。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "房子下面起支撑作用的石头基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根基", "is_correct": true, "explanation": "根基（gēn jī）是正确答案，指房子下面起支撑作用的石头基础。"}, {"text": "根据", "is_correct": false, "explanation": "根据 gēnjù：第二音节韵母由 i 变为 ü，声调也不同，意思是依据。"}, {"text": "感激", "is_correct": false, "explanation": "感激（gǎnjī）与根基的第一音节韵母不同（en 与 an）且声调改变，意思是感谢，不是同一个词。"}, {"text": "根系", "is_correct": false, "explanation": "根系（gēnxì）第二音节声母 x 与 j 不同，意思是植物根的整体，与根基声音相近。"}, {"text": "根治", "is_correct": false, "explanation": "根治（gēnzhì）第二音节声母 zh 与 j 不同，意思是彻底治好，与根基声音相近。"}], "explanations": {"根基": "根基（gēn jī）是正确答案，指房子下面起支撑作用的石头基础。", "根据": "根据 gēnjù：第二音节韵母由 i 变为 ü，声调也不同，意思是依据。", "感激": "感激（gǎnjī）与根基的第一音节韵母不同（en 与 an）且声调改变，意思是感谢，不是同一个词。", "根系": "根系（gēnxì）第二音节声母 x 与 j 不同，意思是植物根的整体，与根基声音相近。", "根治": "根治（gēnzhì）第二音节声母 zh 与 j 不同，意思是彻底治好，与根基声音相近。"}, "sentence_index": null, "correct_answer": "根基"}, "level_3": {"options": [{"text": "根基", "is_correct": true, "explanation": "根基：指房子下面起支撑作用的石头基础，与“用大石头做的”的语境相合。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是布料做的，不能用大石头做，与句子语境不合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是气味，不是有形的物体，无法用石头做成。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指外形，不能说房子的外貌是用大石头做的，与句意不合。"}], "explanations": {"根基": "根基：指房子下面起支撑作用的石头基础，与“用大石头做的”的语境相合。", "窗帘": "语义：窗帘是布料做的，不能用大石头做，与句子语境不合。", "味道": "语义：味道是气味，不是有形的物体，无法用石头做成。", "外貌": "体貌：外貌指外形，不能说房子的外貌是用大石头做的，与句意不合。"}, "sentence_index": 0, "correct_answer": "根基"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里的根基很平。", "explanation": "这里应该用〈地面〉。根基指房子下面起支撑的石头基础，说屋里平不平要用地面。"}, {"text": "我们在根基上铺了地毯。", "explanation": "这里应该用〈地板〉。根基是房子下面的石头，不能铺地毯；铺地毯要说地板。"}, {"text": "窗户上的根基被打碎了。", "explanation": "这里应该用〈玻璃〉。根基是房子下面的石头，不在窗户上，也不会被打碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根基", "is_correct": true, "explanation": "根基：房子下面的石头基础，这里说老房子的根基经久结实，语义相合。"}, {"text": "房租", "is_correct": false, "explanation": "语义：房租是付给房东的钱，不能用“结实”来形容。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味指气味，不能说“还很结实”，与句意不合。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的颜色，不能用来形容老房子是否结实。"}], "explanations": {"根基": "根基：房子下面的石头基础，这里说老房子的根基经久结实，语义相合。", "房租": "语义：房租是付给房东的钱，不能用“结实”来形容。", "香味": "语义：香味指气味，不能说“还很结实”，与句意不合。", "脸色": "体貌：脸色指面部的颜色，不能用来形容老房子是否结实。"}, "sentence_index": 6, "correct_answer": "根基"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用根基擦了擦桌子。", "explanation": "这里应该用〈抹布〉。根基是房子下面的石头，不能拿来擦桌子。"}, {"text": "他推开了根基，走进屋里。", "explanation": "这里应该用〈门〉。根基是房下的石头，不能推开；推门进屋要说门。"}, {"text": "屋顶盖着一层根基。", "explanation": "这里应该用〈瓦片〉。根基是房子下面起支撑的石头，不能盖在屋顶上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座房子的一只根基很结实。", "corrected_sentence": "这座房子的根基很结实。", "error_description": "量词错误：“根基”不用“只”（“只”用于动物等），应去掉“一只”，说“这座房子的根基”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把根基挖以后，发现老房子很结实。", "corrected_sentence": "工人把根基挖开以后，发现老房子很结实。", "error_description": "“把”字句缺少补语：动词“挖”后要加结果补语“开”，应说“把根基挖开”，不能只说“把根基挖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
