INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25138, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水就是使用水。", "primary_collocate": null, "pronunciation": "yòng shuǐ", "ipa": "jʊŋ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们每天都要节约用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手的时候请少用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天气热，大家用水比较多。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方很缺水，大家都很小心地用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民春天种地，需要用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭、洗衣服都要用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们，刷牙时不要一直用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家用水不多，水费很便宜。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的人用水很不容易。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校提醒学生注意用水。", "target_word": "用水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用水量", "label": "复合"}], "register": "中性", "sense_fingerprint": "使用水;日常生活或生产中用水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用水", "is_correct": true, "explanation": "正确：“节约用水”是固定搭配，表示减少使用水，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“节约散步”没有意义，句子说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“节约”后接资源或能源，不能接“唱歌”。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步不是需要节约的资源，句子说不通。"}], "explanations": {"用水": "正确：“节约用水”是固定搭配，表示减少使用水，符合句意。", "散步": "语义：“节约散步”没有意义，句子说不通。", "唱歌": "搭配：“节约”后接资源或能源，不能接“唱歌”。", "跑步": "语义：跑步不是需要节约的资源，句子说不通。"}, "sentence_index": 0, "correct_answer": "用水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他渴了，就去用水。", "explanation": "这里应该用〈喝水〉。“用水”指使用水，如洗涤、浇灌、生产；解渴要说〈喝水〉。"}, {"text": "他饿了，就用水吃饭。", "explanation": "这里不该用〈用水〉。“用水”指使用水，与吃饭无关；应说“他饿了，就去吃饭。”"}, {"text": "我昨晚十点就用水睡觉了。", "explanation": "这里应该用〈睡〉。“用水”指使用水，不能表示睡觉；应说“我昨晚十点就睡觉了。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用水", "is_correct": true, "explanation": "正确：“一直用水”指长时间让水流着，与“刷牙时不要浪费”的劝告相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“刷牙时睡觉”不合逻辑，句子说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“刷牙时吃饭”与刷牙的动作相冲突，句子说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“刷牙时游泳”不合常理，与刷牙的场景和动作相矛盾。"}], "explanations": {"用水": "正确：“一直用水”指长时间让水流着，与“刷牙时不要浪费”的劝告相符。", "睡觉": "语义：“刷牙时睡觉”不合逻辑，句子说不通。", "吃饭": "语义：“刷牙时吃饭”与刷牙的动作相冲突，句子说不通。", "游泳": "语义：“刷牙时游泳”不合常理，与刷牙的场景和动作相矛盾。"}, "sentence_index": 6, "correct_answer": "用水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐每天用水学习两个小时。", "explanation": "这里应该用〈读书〉。“用水”指使用水，不能表示学习；学习、看书要说〈读书〉。"}, {"text": "我每天七点用水去学校。", "explanation": "这里应该用〈上学〉。“用水”指使用水，不能表示去学校；这里应说“去上学”。"}, {"text": "他早上散步半小时，然后用水吃早饭。", "explanation": "这里不该用〈用水〉。“用水”指使用水，不能表示吃东西；应说“然后吃早饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家每天都要节约用水了。", "corrected_sentence": "我家每天都要节约用水。", "error_description": "时态错误：“了”表示已完成的动作或变化，与“每天都要”表示的习惯性、要求性语境矛盾，“用水”后不应加“了”，应说“我家每天都要节约用水。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家今年用水数很多。", "corrected_sentence": "他家今年用水量很大。", "error_description": "词语错误：表示用水的数量要用复合词“用水量”，“用水数”不成词，应说“用水量很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
