INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给国家或大家东西。", "primary_collocate": null, "pronunciation": "gòng xiàn", "ipa": "kʊŋ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他把自己的钱贡献给了学校。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们为国家贡献了很多力量。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想为社会贡献自己的一份力量。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一生都在为教育贡献力量。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都愿意为这个城市贡献时间。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生都贡献给了科学。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都可以为环境贡献一点力量。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生为人民贡献了三十年青春。", "target_word": "贡献", "complexity_tier": "T3", "furigana": "gòngxiàn", "sentence_source": "generated"}, {"text": "我们应该为班级贡献自己的想法。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把多年的书贡献给了图书馆。", "target_word": "贡献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贡献了", "label": "体标"}, {"form": "贡献过", "label": "体标"}, {"form": "貢獻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "贡献：把东西或力量献给国家或大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贡献", "is_correct": true, "explanation": "正确：贡献指把钱献给国家或大家，与“给了学校”搭配，符合句意。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：“卖”指交易买卖，不能用于把钱无偿交给学校。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”指强行夺取，与自愿把钱交给学校的意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是随手丢出去，不表示把钱献给学校的意思。"}], "explanations": {"贡献": "正确：贡献指把钱献给国家或大家，与“给了学校”搭配，符合句意。", "卖": "搭配：“卖”指交易买卖，不能用于把钱无偿交给学校。", "抢": "语义：“抢”指强行夺取，与自愿把钱交给学校的意思相反。", "扔": "语义：“扔”是随手丢出去，不表示把钱献给学校的意思。"}, "sentence_index": 0, "correct_answer": "贡献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司贡献了受伤工人一笔钱。", "explanation": "这里应该用〈赔偿〉。贡献是献给国家或大家的东西，对受伤个人的补偿要说赔偿。"}, {"text": "上级对他贡献了很大的信任。", "explanation": "这里应该用〈给予〉。贡献的对象是国家、社会或大家，对某个人的信任应说给予。"}, {"text": "他主动贡献了全部责任。", "explanation": "这里应该用〈承担〉。贡献是献出自己的东西，接受责任要说承担。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贡献", "is_correct": true, "explanation": "正确：贡献指把力量献给国家或大家，与“为环境”和“一点力量”搭配，符合句意。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：“消耗”指耗用，与为环境出力的积极意思相反。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白花费，与为环境出力的积极意思不符。"}, {"text": "破坏", "is_correct": false, "explanation": "搭配：“破坏”后不能接“一点力量”表示为环境出力，与“贡献力量”的说法不搭配。"}], "explanations": {"贡献": "正确：贡献指把力量献给国家或大家，与“为环境”和“一点力量”搭配，符合句意。", "消耗": "语义：“消耗”指耗用，与为环境出力的积极意思相反。", "浪费": "语义：“浪费”指白白花费，与为环境出力的积极意思不符。", "破坏": "搭配：“破坏”后不能接“一点力量”表示为环境出力，与“贡献力量”的说法不搭配。"}, "sentence_index": 6, "correct_answer": "贡献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的车贡献给了朋友。", "explanation": "这里应该用〈赠送〉。贡献是献给国家或大家，把车送给朋友应说赠送。"}, {"text": "老板把任务贡献给了每一个员工。", "explanation": "这里应该用〈分配〉。贡献的对象是国家或大家，给员工派工作应说分配。"}, {"text": "他把房子贡献给了银行。", "explanation": "这里应该用〈抵押〉。贡献是献给国家或大家，把房子作为借款担保要说抵押。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他社区贡献了很多时间。", "corrected_sentence": "他为社区贡献了很多时间。", "error_description": "介词缺失：“社区”作服务对象，要用介词“为”引出，应说“为社区贡献”，“他社区贡献”中须补上“为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅把积蓄贡献了给山区小学。", "corrected_sentence": "我舅舅把积蓄贡献给了山区小学。", "error_description": "语序错误：“贡献给”是固定结构，“了”应放在“给”之后，不能插在“贡献”和“给”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
