INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把身体或头转到另一个方向。", "primary_collocate": null, "pronunciation": "zhuǎn xiàng", "ipa": "ʈʂwan˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听到声音，他转向了窗户。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师转向黑板，开始写字。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她慢慢转向我，笑了一下。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把头转向右边，看了看路。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体转向门口，不想说话。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗听见铃声，马上转向门口。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起转向舞台，开始鼓掌。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你转向我这边，我给你拍照。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听到名字，就转向了老师。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈转向孩子，小声说了几句话。", "target_word": "转向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转向了", "label": "体标"}, {"form": "转向过", "label": "体标"}, {"form": "轉向", "label": "繁体"}], "register": "中性", "sense_fingerprint": "转向：把身体或头转到另一个方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转向", "is_correct": true, "explanation": "正确。转向：把身体或头转到另一个方向，此处指他把头转向窗户。"}, {"text": "认识", "is_correct": false, "explanation": "搭配：“认识”后接的是人或事，不说“认识窗户”。"}, {"text": "说服", "is_correct": false, "explanation": "配价：“说服”的对象必须是人，窗户不能被说服。"}, {"text": "请教", "is_correct": false, "explanation": "配价：“请教”的对象是人，窗户不能被请教。"}], "explanations": {"转向": "正确。转向：把身体或头转到另一个方向，此处指他把头转向窗户。", "认识": "搭配：“认识”后接的是人或事，不说“认识窗户”。", "说服": "配价：“说服”的对象必须是人，窗户不能被说服。", "请教": "配价：“请教”的对象是人，窗户不能被请教。"}, "sentence_index": 0, "correct_answer": "转向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在床上转向了两个小时，才睡着。", "explanation": "这里应该用〈翻身〉。“转向”指把身体或头转到某个方向，不能表示在床上翻动所花的时间。"}, {"text": "司机把车转向了一个小时，还是没找到路。", "explanation": "这里应该用〈绕〉。“转向”指改变方向，不能表示在路上兜圈子所花的时间，要用〈绕〉。"}, {"text": "他在原地转向了一圈，没有说话。", "explanation": "这里应该用〈转〉。“转向”要说明转到哪一个方向，不能表示绕着自己转圈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转向", "is_correct": true, "explanation": "正确。转向：把身体或头转到另一个方向，此处指大家一起把身体转向舞台。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的对象是人，舞台不能被感谢。"}, {"text": "怀疑", "is_correct": false, "explanation": "配价：“怀疑”后接的是人或说法，不能说“怀疑舞台”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”是拆掉，与“开始鼓掌”的场面不相符。"}], "explanations": {"转向": "正确。转向：把身体或头转到另一个方向，此处指大家一起把身体转向舞台。", "感谢": "配价：“感谢”的对象是人，舞台不能被感谢。", "怀疑": "配价：“怀疑”后接的是人或说法，不能说“怀疑舞台”。", "拆除": "语义：“拆除”是拆掉，与“开始鼓掌”的场面不相符。"}, "sentence_index": 6, "correct_answer": "转向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他转向了新的发型，看起来年轻了很多。", "explanation": "这里应该用〈换〉。“转向”指转到某个方向或改变方向，不能用来说换发型，应说〈换〉。"}, {"text": "他转向了三个小时的作业，终于写完了。", "explanation": "这里应该用〈做〉。“转向”表示转到某个方向，不能用来说做作业，做作业应说〈做〉。"}, {"text": "他把电视转向了大声，吵得邻居都睡不着。", "explanation": "这里应该用〈调〉。“转向”指转动到某个方向，不能用来说调节音量，应说〈调〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把转向了窗户。", "corrected_sentence": "他把头转向了窗户。", "error_description": "错误：“把转向了窗户”。“把”后面缺少被转动的部位“头”，应说“他把头转向了窗户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我头把转向了左边。", "corrected_sentence": "我把头转向了左边。", "error_description": "错误：“头把转向了左边”。“把”的位置不对，应放在“头”前面，说“我把头转向了左边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
