INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地上一条窄窄的小水道。", "primary_collocate": null, "pronunciation": "xiǎo gōu", "ipa": "ɕiɑʊ˨˩˦ kɤʊ˥", "syllable_count": 2, "sentences": [{"text": "院子里的小沟很窄，一步就能跨过去。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后路边的小沟里流着水。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后面有一条小沟，一直通到河边。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们蹲在小沟边看小蝌蚪。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小沟不深，水只到脚边。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在地上挖了一条小沟，让水流出去。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小沟里长着绿草，旁边是一条小路。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条小沟很窄，青蛙常常从这边跳到那边。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要往小沟里扔垃圾。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，小沟里的水干了，只剩下泥。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "小溝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地上窄窄的小水道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小沟", "is_correct": true, "explanation": "“院子里的小沟很窄，一步就能跨过去”指地上窄窄的水道，与句意相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海非常宽，不能“一步就能跨过去”。"}, {"text": "小鸡", "is_correct": false, "explanation": "语义：小鸡是动物，不说“很窄，一步就能跨过去”。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不用“很窄”形容，也不是跨过去的东西。"}], "explanations": {"小沟": "“院子里的小沟很窄，一步就能跨过去”指地上窄窄的水道，与句意相符。", "大海": "语义：大海非常宽，不能“一步就能跨过去”。", "小鸡": "语义：小鸡是动物，不说“很窄，一步就能跨过去”。", "大树": "语义：大树不用“很窄”形容，也不是跨过去的东西。"}, "sentence_index": 0, "correct_answer": "小沟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐小沟去上学。", "explanation": "这里应该用〈公共汽车〉。小沟是地上的水道，不能坐着去上学。"}, {"text": "他每天去小沟上班，下班后很累。", "explanation": "这里应该用〈工厂〉。小沟是窄窄的水道，不是工作的地方，上班要说去「工厂」。"}, {"text": "他把书放进了小沟里。", "explanation": "这里应该用〈书柜〉。「小沟」是地上的水道，书不能放进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小沟", "is_correct": true, "explanation": "“小沟里长着绿草，旁边是一条小路”指地上窄窄的水道，与句意相符。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不会“长着绿草”，句意不通。"}, {"text": "小床", "is_correct": false, "explanation": "搭配：“长着绿草”不用来描述床。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海里是海水，不说“长着绿草，旁边是一条小路”。"}], "explanations": {"小沟": "“小沟里长着绿草，旁边是一条小路”指地上窄窄的水道，与句意相符。", "小鸟": "语义：小鸟不会“长着绿草”，句意不通。", "小床": "搭配：“长着绿草”不用来描述床。", "大海": "语义：大海里是海水，不说“长着绿草，旁边是一条小路”。"}, "sentence_index": 6, "correct_answer": "小沟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用小沟烧水做饭。", "explanation": "这里应该用〈锅〉。小沟不是烧水的器具，不能用来烧水做饭。"}, {"text": "他推开小沟走进屋里。", "explanation": "这里应该用〈门〉。「推开」用于门、窗等，不能推开小沟。"}, {"text": "她把小沟放进了书包里。", "explanation": "这里应该用〈课本〉。「小沟」是地上的水道，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条小沟窄很，我一跳就过去了。", "corrected_sentence": "这条小沟很窄，我一跳就过去了。", "error_description": "“很”应放在“窄”前面，说「很窄」，「窄很」的语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条小沟水的很清。", "corrected_sentence": "这条小沟的水很清。", "error_description": "“的”放错了位置：应说「这条小沟的水很清」，不应说「小沟水的很清」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
