INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25146, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑掉的意思是离开，不在了。", "primary_collocate": null, "pronunciation": "pǎo diào", "ipa": "pʰaʊ˨˩˦ tiaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "鸡从笼子里跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到我，他转身就跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快关门，别让猫跑掉。", "target_word": "跑掉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "抓到一半，小鸡跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一听要考试，就跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩着玩着，突然跑掉了。", "target_word": "跑掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗看见大车，吓得跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把绳子松开，羊就跑掉了。", "target_word": "跑掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们见老师来了，都跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只兔子一眨眼就跑掉了。", "target_word": "跑掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑掉了", "label": "体标（了）"}, {"form": "跑不掉", "label": "可能补语（否定）"}, {"form": "跑得掉", "label": "可能补语（肯定）"}], "register": "口语", "sense_fingerprint": "人或动物跑开，离开原来的地方，不在那里了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b763f8e4-c8e2-4fed-b4e1-513ee2e3c8b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉（pǎo diào）：离开，不在原处了，是本题的正确词形。"}, {"text": "跑跳", "is_correct": false, "explanation": "跑跳（pǎo tiào）与跑掉的第二音节声母不同（t 与 d），声调相同，意思是边跑边跳。"}, {"text": "跑道", "is_correct": false, "explanation": "跑道（pǎo dào）与跑掉的第二音节韵母不同（dào 与 diào），声调相同，意思是运动场或机场的跑道。"}, {"text": "倒掉", "is_correct": false, "explanation": "倒掉（dǎo diào）与跑掉的第一音节声母不同（d 与 p），声调相同，意思是把液体倒出去。"}], "explanations": {"跑掉": "跑掉（pǎo diào）：离开，不在原处了，是本题的正确词形。", "跑跳": "跑跳（pǎo tiào）与跑掉的第二音节声母不同（t 与 d），声调相同，意思是边跑边跳。", "跑道": "跑道（pǎo dào）与跑掉的第二音节韵母不同（dào 与 diào），声调相同，意思是运动场或机场的跑道。", "倒掉": "倒掉（dǎo diào）与跑掉的第一音节声母不同（d 与 p），声调相同，意思是把液体倒出去。"}, "sentence_index": null, "correct_answer": "跑掉"}, "level_3": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉：离开，符合“鸡从笼子里……”的语境，表示鸡逃出了笼子。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”需要食物作对象，“鸡从笼子里煮了”句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，“鸡从笼子里咬了”句意不通。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，鸡不能从笼子里“讲”，句意不通。"}], "explanations": {"跑掉": "跑掉：离开，符合“鸡从笼子里……”的语境，表示鸡逃出了笼子。", "煮": "语义：“煮”需要食物作对象，“鸡从笼子里煮了”句意不通。", "咬": "语义：“咬”指用牙齿夹住，“鸡从笼子里咬了”句意不通。", "讲": "语义：“讲”指说话，鸡不能从笼子里“讲”，句意不通。"}, "sentence_index": 0, "correct_answer": "跑掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门突然跑掉了。", "explanation": "这句想表达“倒下”；门不能自行离开，跑掉指人或动物快速离开，此义应用〈倒下〉。"}, {"text": "他的脚踝突然跑掉了。", "explanation": "这句想表达“脱臼”；脚踝不能自行离开，跑掉的主语须是能自行移动的人或动物，此义应用〈脱臼〉。"}, {"text": "这块玻璃突然跑掉了。", "explanation": "这句想表达“碎裂”；玻璃不能自行离开，跑掉指人或动物快速离开，此义应用〈碎裂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25146, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉（pǎo diào）：快速离开，不在原处了，是本题的正确词形。"}, {"text": "抛掉", "is_correct": false, "explanation": "抛掉（pāo diào）与跑掉的第一音节声调不同（第一声与第三声），意思是扔掉。"}, {"text": "泡掉", "is_correct": false, "explanation": "泡掉（pào diào）与跑掉的第一音节声调不同（第四声），意思是用水浸掉。"}, {"text": "刨掉", "is_correct": false, "explanation": "刨掉（páo diào）与跑掉的第一音节声调不同（第二声），意思是挖去或削去。"}], "explanations": {"跑掉": "跑掉（pǎo diào）：快速离开，不在原处了，是本题的正确词形。", "抛掉": "抛掉（pāo diào）与跑掉的第一音节声调不同（第一声与第三声），意思是扔掉。", "泡掉": "泡掉（pào diào）与跑掉的第一音节声调不同（第四声），意思是用水浸掉。", "刨掉": "刨掉（páo diào）与跑掉的第一音节声调不同（第二声），意思是挖去或削去。"}, "sentence_index": null, "correct_answer": "跑掉"}, "level_3": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉：离开，符合“狗看见大车，吓得……”的语境，表示狗受惊逃走。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吓得吃了”与受惊的语境不合，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：狗受惊后不会“写”，“吓得写了”句意不通。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”需要带宾语，“吓得拿了”缺少宾语，句子不完整。"}], "explanations": {"跑掉": "跑掉：离开，符合“狗看见大车，吓得……”的语境，表示狗受惊逃走。", "吃": "语义：“吓得吃了”与受惊的语境不合，句意不通。", "写": "语义：狗受惊后不会“写”，“吓得写了”句意不通。", "拿": "配价：“拿”需要带宾语，“吓得拿了”缺少宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "跑掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视突然跑掉了。", "explanation": "这句想表达“关掉”；电视不能自行离开，跑掉指人或动物快速离开，此义应用〈关掉〉。"}, {"text": "他慢条斯理地跑掉了。", "explanation": "这句想表达“从容地离开”；跑掉指快速离开，与“慢条斯理”的从容义矛盾，此义应用〈走开〉。"}, {"text": "他一动不动地跑掉了。", "explanation": "这句想表达“静止不动”；跑掉指快速离开，与“一动不动”矛盾，此义不能用跑掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门关得很严，小猫没跑掉了。", "corrected_sentence": "门关得很严，小猫没跑掉。", "error_description": "错误在于“没”与“了”不能同用。“没跑掉”表示动作没有发生，应删去句末的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门没关好，猫就跑掉着了。", "corrected_sentence": "门没关好，猫就跑掉了。", "error_description": "错误在于“着”。“跑掉”表示动作已经完成，不能与持续体“着”同用，应删去“着”，说“门没关好，猫就跑掉了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
