INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种庄稼的地。", "primary_collocate": null, "pronunciation": "tián", "ipa": "tʰiɛn˧˥", "syllable_count": 1, "sentences": [{"text": "他有一块田，每年种两次菜。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们走过小路，到了村外的田里。", "target_word": "田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里的庄稼长得很好。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸正在田里给玉米浇水。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块田去年种过水稻，今年种麦子。", "target_word": "田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈去田里拔草。", "target_word": "田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下大雨，田里的水满了。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，那块田里全是绿色的菜。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民们在田里忙了一天。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把种子撒在田里。", "target_word": "田", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "种庄稼的地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25148, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "田", "is_correct": true, "explanation": "田指种庄稼的地，读 tián（阳平）。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān，阴平）与 tián（阳平）声调不同，意思是天空。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tián（第二声）声调不同，舔指用舌头碰。"}, {"text": "添", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，添指增加。"}], "explanations": {"田": "田指种庄稼的地，读 tián（阳平）。", "天": "天（tiān，阴平）与 tián（阳平）声调不同，意思是天空。", "舔": "tiǎn（第三声）与 tián（第二声）声调不同，舔指用舌头碰。", "添": "tiān（第一声）与 tián（第二声）声调不同，添指增加。"}, "sentence_index": null, "correct_answer": "田"}, "level_3": {"options": [{"text": "田", "is_correct": true, "explanation": "正确：田是种菜的地，一年能种两次，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能种菜，与“每年种两次菜”矛盾。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“种”的对象是植物，不能与蛋糕搭配。"}, {"text": "布", "is_correct": false, "explanation": "语义：布料不能种菜，句意不通。"}], "explanations": {"田": "正确：田是种菜的地，一年能种两次，句意通顺。", "石头": "语义：石头不能种菜，与“每年种两次菜”矛盾。", "蛋糕": "搭配：“种”的对象是植物，不能与蛋糕搭配。", "布": "语义：布料不能种菜，句意不通。"}, "sentence_index": 0, "correct_answer": "田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上我躺在田里睡觉。", "explanation": "这里应该用〈床〉。田指种庄稼的地，睡觉要在床上。"}, {"text": "同学们在田里写作业。", "explanation": "这里应该用〈书房〉。田指种庄稼的地，写作业应在书房或教室里，不在田里。"}, {"text": "妈妈在田里看电视。", "explanation": "这里应该用〈客厅〉。田指种庄稼的地，看电视要在室内，不能说在田里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25148, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "田", "is_correct": true, "explanation": "田指种庄稼的地，读 tián（阳平）。"}, {"text": "年", "is_correct": false, "explanation": "nián 与 tián 只差声母，年指年份。"}, {"text": "钱", "is_correct": false, "explanation": "qián 与 tián 只差声母，钱指货币。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tián 只差介音（i），谈指谈话。"}], "explanations": {"田": "田指种庄稼的地，读 tián（阳平）。", "年": "nián 与 tián 只差声母，年指年份。", "钱": "qián 与 tián 只差声母，钱指货币。", "谈": "tán 与 tián 只差介音（i），谈指谈话。"}, "sentence_index": null, "correct_answer": "田"}, "level_3": {"options": [{"text": "田", "is_correct": true, "explanation": "正确：“田里的水满了”指田地积水，句意通顺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不装水，“书包里的水满了”说不通。"}, {"text": "床", "is_correct": false, "explanation": "语义：床不会积水，与“下大雨，水满了”的语境不符。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：“水满了”只用于能盛水的地方，钱包不能这样说。"}], "explanations": {"田": "正确：“田里的水满了”指田地积水，句意通顺。", "书包": "语义：书包不装水，“书包里的水满了”说不通。", "床": "语义：床不会积水，与“下大雨，水满了”的语境不符。", "钱包": "搭配：“水满了”只用于能盛水的地方，钱包不能这样说。"}, "sentence_index": 6, "correct_answer": "田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把菜放进田里炒。", "explanation": "这里应该用〈锅〉。田是种庄稼的土地，不能放进去炒菜。"}, {"text": "我在田里买了一本书。", "explanation": "这里应该用〈书店〉。田指种庄稼的地，不是卖书的地方，买书要去书店。"}, {"text": "他每天早上在田里刷牙。", "explanation": "这里应该用〈卫生间〉。田指种庄稼的地，刷牙应在卫生间或水池边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷田里浇了一上午的水。", "corrected_sentence": "爷爷在田里浇了一上午的水。", "error_description": "“田里”前缺少介词“在”。表示动作发生的地点时应说“在田里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只田里的草已经拔干净了。", "corrected_sentence": "那块田里的草已经拔干净了。", "error_description": "“田”的量词应用〈块〉或〈片〉。“只”多用于动物，不用于田地，应说“那块田”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“新”与“老”在做事经验多少上相反（老手／新手）。"}, {"text": "深", "is_correct": false, "explanation": "“深”形容距离或程度，与“老”的经验义没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "“圆”形容形状，与“老”没有反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”形容宽度，与“老”的经验义没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“新”与“老”在做事经验多少上相反（老手／新手）。", "深": "“深”形容距离或程度，与“老”的经验义没有反义关系。", "圆": "“圆”形容形状，与“老”没有反义关系。", "窄": "“窄”形容宽度，与“老”的经验义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“新”与“老”在做事经验多少上相反（新手／老手）。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”形容重量，与“老”的经验义没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”形容光线，与“老”的经验义没有反义关系。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”形容宽度，与“老”的经验义没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“新”与“老”在做事经验多少上相反（新手／老手）。", "轻": "“轻”形容重量，与“老”的经验义没有反义关系。", "亮": "“亮”形容光线，与“老”的经验义没有反义关系。", "宽": "“宽”形容宽度，与“老”的经验义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容东西放的时间久或者做事情的经验多。", "primary_collocate": null, "pronunciation": "lǎo", "ipa": "lɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "柜子里有一张很老的照片。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教师教了三十年书，学生都很喜欢他。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视很老，是爸爸二十年前买的。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老渔民看一眼天，就知道明天有没有风。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家有一口很老的锅，用了几十年。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是店里资格最老的员工，客人的事他都知道。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很老，纸都黄了。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老护士打针又快又不疼。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有一把很老的椅子，是外公留下来的。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老警察一听声音，就知道是谁来了。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老了", "label": "体标"}], "register": "中性", "sense_fingerprint": "老：东西放的时间久，或人做事经验多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 院子 (Zipf 3.93), 外公 (Zipf 3.58), 留下来 (Zipf 3.97)']::text[], '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老", "is_correct": true, "explanation": "老 lǎo：东西放的时间久，或人做事的经验多。"}, {"text": "牢", "is_correct": false, "explanation": "láo（第二声）与 lǎo 声调不同，意思是监狱。"}, {"text": "涝", "is_correct": false, "explanation": "lào（第四声）与 lǎo 声调不同，意思是雨水过多造成的积水。"}, {"text": "捞", "is_correct": false, "explanation": "lāo（第一声）与 lǎo 声调不同，意思是打捞。"}], "explanations": {"老": "老 lǎo：东西放的时间久，或人做事的经验多。", "牢": "láo（第二声）与 lǎo 声调不同，意思是监狱。", "涝": "lào（第四声）与 lǎo 声调不同，意思是雨水过多造成的积水。", "捞": "lāo（第一声）与 lǎo 声调不同，意思是打捞。"}, "sentence_index": null, "correct_answer": "老"}, "level_3": {"options": [{"text": "老", "is_correct": true, "explanation": "“很老的照片”指放的时间久的照片，与句中的语境相符。"}, {"text": "矮", "is_correct": false, "explanation": "语义：照片不能用“矮”来形容。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”形容距离，不能用来形容照片。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”形容速度，不能用来形容照片。"}], "explanations": {"老": "“很老的照片”指放的时间久的照片，与句中的语境相符。", "矮": "语义：照片不能用“矮”来形容。", "远": "语义：“远”形容距离，不能用来形容照片。", "慢": "搭配：“慢”形容速度，不能用来形容照片。"}, "sentence_index": 0, "correct_answer": "老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这条路很老，闭着眼睛也能走。", "explanation": "这里应该用〈熟悉〉。「老」形容东西放的时间久或人做事的经验多，不能用来形容对一条路的熟悉程度。"}, {"text": "他刚学会游泳，游得很老。", "explanation": "这里应该用〈熟练〉。「老」形容东西放的时间久或做事的经验多，刚学的人不能说游得很老；做事的熟练程度要用「熟练」。"}, {"text": "今天的风很老，吹得窗户直响。", "explanation": "这里应该用〈大〉。「老」形容东西放的时间久或人做事的经验多，不能用来形容风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老", "is_correct": true, "explanation": "老 lǎo：东西放的时间久，或人做事的经验多。"}, {"text": "劳", "is_correct": false, "explanation": "láo（第二声）与 lǎo 声调不同，意思是劳动。"}, {"text": "烙", "is_correct": false, "explanation": "lào（第四声）与 lǎo 声调不同，意思是用火烤。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 lǎo 声母不同（n 与 l），意思是大脑。"}], "explanations": {"老": "老 lǎo：东西放的时间久，或人做事的经验多。", "劳": "láo（第二声）与 lǎo 声调不同，意思是劳动。", "烙": "lào（第四声）与 lǎo 声调不同，意思是用火烤。", "脑": "nǎo 与 lǎo 声母不同（n 与 l），意思是大脑。"}, "sentence_index": null, "correct_answer": "老"}, "level_3": {"options": [{"text": "老", "is_correct": true, "explanation": "“这本书很老”指放的时间久，与“纸都黄了”相符。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”与“纸都黄了”的状态矛盾。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”用于人，不能用来形容书。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说明不了纸已经发黄的状态。"}], "explanations": {"老": "“这本书很老”指放的时间久，与“纸都黄了”相符。", "新": "语义：“新”与“纸都黄了”的状态矛盾。", "年轻": "搭配：“年轻”用于人，不能用来形容书。", "亮": "语义：“亮”说明不了纸已经发黄的状态。"}, "sentence_index": 6, "correct_answer": "老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视是上个月刚买的，已经很老了。", "explanation": "这里应该用〈新〉。「老」指东西存在的时间长，上个月刚买的电视不能说很老。"}, {"text": "他是个很老的司机，上个星期才拿到驾照。", "explanation": "这里应该用〈新〉。「老」指做事经验多，上个星期才拿到驾照的人是新司机，不能说很老。"}, {"text": "这座桥很老，三个月前才通车。", "explanation": "这里应该用〈新〉。「老」指存在时间长，三个月前才通车的桥不能说老。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋老很，该换了。", "corrected_sentence": "这双鞋很老，该换了。", "error_description": "「老」是形容词，程度副词「很」要放在它前面，应说“很老”，不能说“老很”。错误：“老很”。正确：“这双鞋很老，该换了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子用了很多年，已经老过了。", "corrected_sentence": "这把椅子用了很多年，已经老了。", "error_description": "“老”后面不能用“过”表示经历，应去掉“过”，说「这把椅子用了很多年，已经老了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
