INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以前的人把东西留给了我们，就像爷爷奶奶把故事讲给我们听。", "primary_collocate": null, "pronunciation": "chuán xià lái", "ipa": "tʂʰwan˧˥ ɕja˥˩ lai˧˥", "syllable_count": 3, "sentences": [{"text": "这块玉是外婆传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是一代代人讲着传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子是爷爷的爷爷传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首老歌是村里的老人传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里传下来一个小木盒。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些老故事靠爷爷奶奶讲，才传下来。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那把旧椅子是我们家传下来的宝贝。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本家谱已经传下来五代了。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷讲的故事，我们要好好传下来。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧东西是以前的人传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传下来了", "label": "体标"}, {"form": "传下来的", "label": "结构助词"}], "register": "中性", "sense_fingerprint": "前人把物品或故事留给后人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传下来", "is_correct": true, "explanation": "正确：表示这块玉从外婆那一辈流传到我们手里。"}, {"text": "吃掉", "is_correct": false, "explanation": "配价：“吃掉”的宾语必须能吃，“玉”不能被吃掉。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”一般搭配“歌”之类，不说“唱玉”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：玉不能煮，“外婆煮的玉”说不通。"}], "explanations": {"传下来": "正确：表示这块玉从外婆那一辈流传到我们手里。", "吃掉": "配价：“吃掉”的宾语必须能吃，“玉”不能被吃掉。", "唱": "搭配：“唱”一般搭配“歌”之类，不说“唱玉”。", "煮": "语义：玉不能煮，“外婆煮的玉”说不通。"}, "sentence_index": 0, "correct_answer": "传下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在旧货市场传下来了这块玉。", "explanation": "这里应该用〈找到〉。传下来指东西世代流传到现在，不能用于在旧货市场里发现东西。"}, {"text": "考古队传下来了一块古玉。", "explanation": "这里应该用〈挖出〉。传下来指东西经代代流传保存，不指从地下发掘。"}, {"text": "我昨天刚传下来这块玉。", "explanation": "这里应该用〈买到〉。传下来指世代相传，不能说“昨天刚传下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传下来", "is_correct": true, "explanation": "正确：表示这把旧椅子从前辈一直流传到我们家，是宝贝。"}, {"text": "喝掉", "is_correct": false, "explanation": "语义：椅子不能喝，“宝贝”也不能被喝掉。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”不搭配“宝贝”，“踢的宝贝”说不通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁的宝贝”自相矛盾，与“宝贝”的语义冲突。"}], "explanations": {"传下来": "正确：表示这把旧椅子从前辈一直流传到我们家，是宝贝。", "喝掉": "语义：椅子不能喝，“宝贝”也不能被喝掉。", "踢": "搭配：“踢”不搭配“宝贝”，“踢的宝贝”说不通。", "烧毁": "语义：“烧毁的宝贝”自相矛盾，与“宝贝”的语义冲突。"}, "sentence_index": 6, "correct_answer": "传下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家传下来了一种新药。", "explanation": "这里应该用〈研制〉。传下来指东西从过去一代代留给现在，不能用于刚研发出来的新东西。"}, {"text": "我把旧书传下来给了二手书店。", "explanation": "这里应该用〈卖〉。传下来指旧东西一代代留给后人，不能说把书交给店家换钱。"}, {"text": "妈妈给我传下来了一双新鞋。", "explanation": "这里应该用〈买〉。传下来指旧东西一代代流传，不能用于新买的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶的银镯子是我们家传下来了。", "corrected_sentence": "奶奶的银镯子是我们家传下来的。", "error_description": "“是……的”句式中，“传下来”后应用“的”，不能用“了”。应为“传下来的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只旧木箱是我们家传下来得老物件。", "corrected_sentence": "那只旧木箱是我们家传下来的老物件。", "error_description": "“得”用错，应为结构助词“的”。“传下来的老物件”中，“的”连接修饰语和被修饰的名词，“得”不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
