INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让人想做好的方法或奖励。", "primary_collocate": null, "pronunciation": "jī lì jī zhì", "ipa": "tɕi˥ li˥˩ tɕi˥ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "妈妈给我们家定了一个激励机制。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师设立的小红花激励机制，同学们都很喜欢。", "target_word": "激励机制", "complexity_tier": "T3", "furigana": "lǎo shī shè lì de xiǎo hóng huā jī lì jī zhì, tóng xué men dōu hěn xǐ huan.", "sentence_source": "generated"}, {"text": "这个激励机制让孩子爱上了读书。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组也需要一个激励机制。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了一个好玩的激励机制，大家都想参加。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的激励机制对学生很有用。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有激励机制，我就不想早起跑步。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的激励机制是考好了就带我去玩。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队的激励机制让队员每场都很拼。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问你们有什么激励机制？", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个激励机制", "label": "量词"}], "register": "中性", "sense_fingerprint": "让人想把事做好的奖励办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激励机制", "is_correct": true, "explanation": "激励机制：指让人想把事做好的奖励办法，家里可以“定”下这样的办法，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被“定”下来，句意不通。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：哭声是声音，不是可以“定”下来的办法，句意不通。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是打扫用的工具，不是可以“定”下来的规定或安排，句意不通。"}], "explanations": {"激励机制": "激励机制：指让人想把事做好的奖励办法，家里可以“定”下这样的办法，句意通顺。", "天气": "语义：天气是自然现象，不能被“定”下来，句意不通。", "哭声": "语义：哭声是声音，不是可以“定”下来的办法，句意不通。", "扫帚": "语义：扫帚是打扫用的工具，不是可以“定”下来的规定或安排，句意不通。"}, "sentence_index": 0, "correct_answer": "激励机制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友住在一个很好的激励机制里。", "explanation": "这里应该用〈房子〉。激励机制是制度或奖励，不能用来居住，住的地方要说〈房子〉。"}, {"text": "我们小组也需要一只激励机制。", "explanation": "量词错误：机制是抽象的办法，应该用〈个〉或〈种〉，〈只〉多用于动物或成对器物中的一件。"}, {"text": "比赛的激励机制很好听，大家都爱听。", "explanation": "这里应该用〈音乐〉。激励机制指让人想做好的制度或奖励，不能用“好听”形容；比赛的背景音乐要说〈音乐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激励机制", "is_correct": true, "explanation": "激励机制：指让人想把事做好的奖励办法，它的存在正是“我想早起跑步”的原因。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：说明书只介绍用法，它的有无与“不想早起跑步”的动机无关，句意不通。"}, {"text": "决议", "is_correct": false, "explanation": "语义：“决议”是会议正式通过的决定，不是让人想把事做好的奖励办法，与“不想早起跑步”的动机无关，句意不通。"}, {"text": "教科书", "is_correct": false, "explanation": "语义：教科书是学习材料，不会决定人是否早起跑步，句子的逻辑断开了。"}], "explanations": {"激励机制": "激励机制：指让人想把事做好的奖励办法，它的存在正是“我想早起跑步”的原因。", "说明书": "语义：说明书只介绍用法，它的有无与“不想早起跑步”的动机无关，句意不通。", "决议": "语义：“决议”是会议正式通过的决定，不是让人想把事做好的奖励办法，与“不想早起跑步”的动机无关，句意不通。", "教科书": "语义：教科书是学习材料，不会决定人是否早起跑步，句子的逻辑断开了。"}, "sentence_index": 6, "correct_answer": "激励机制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请问你们有几朵激励机制？", "explanation": "量词错误：〈朵〉用于花、云等，机制是抽象的办法，应该用〈个〉或〈种〉。"}, {"text": "这首歌的激励机制很动人，大家都爱唱。", "explanation": "这里应该用〈旋律〉。激励机制指制度或奖励，不能用“动人”形容歌曲的曲调；歌曲的音调起伏要说〈旋律〉。"}, {"text": "妈妈在厨房里烧了激励机制。", "explanation": "这里应该用〈菜〉。激励机制指制度或奖励，不能被“烧”；厨房里做出来的食物要说〈菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校为了鼓励阅读，设立了一只激励机制。", "corrected_sentence": "学校为了鼓励阅读，设立了一个激励机制。", "error_description": "量词错误：“激励机制”是抽象的办法，应用“个”，“只”用于动物或成对器物中的一件，应改为“一个激励机制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司地激励机制很有效。", "corrected_sentence": "我们公司的激励机制很有效。", "error_description": "“的”误写为“地”。“地”用于修饰动词或形容词，修饰名词“激励机制”要用“的”，正确为“我们公司的激励机制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣质", "is_correct": true, "explanation": "正确：“劣质”指品质低劣，与“高质量”相对。"}, {"text": "轻便", "is_correct": false, "explanation": "“轻便”说分量轻，不是“高质量”的反义词。"}, {"text": "时尚", "is_correct": false, "explanation": "“时尚”说流行，与品质优劣不构成反义。"}, {"text": "雅致", "is_correct": false, "explanation": "“雅致”说样式精巧，不是“高质量”的反义词。"}], "correct_answer": "劣质", "explanations": {"劣质": "正确：“劣质”指品质低劣，与“高质量”相对。", "轻便": "“轻便”说分量轻，不是“高质量”的反义词。", "时尚": "“时尚”说流行，与品质优劣不构成反义。", "雅致": "“雅致”说样式精巧，不是“高质量”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣质", "is_correct": true, "explanation": "正确：“劣质”指品质低劣，与“高质量”相对。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价钱低，与品质高低不构成反义关系。"}, {"text": "笨重", "is_correct": false, "explanation": "“笨重”说分量大，与品质优劣不构成反义。"}, {"text": "华丽", "is_correct": false, "explanation": "“华丽”说装饰多，与品质优劣不构成反义。"}], "correct_answer": "劣质", "explanations": {"劣质": "正确：“劣质”指品质低劣，与“高质量”相对。", "便宜": "“便宜”说价钱低，与品质高低不构成反义关系。", "笨重": "“笨重”说分量大，与品质优劣不构成反义。", "华丽": "“华丽”说装饰多，与品质优劣不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西很好，很结实。", "primary_collocate": null, "pronunciation": "gāo zhì liàng", "ipa": "kaʊ˥ ʈʂʅ˥˩ ljaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这把椅子是高质量的，用了十年还很结实。", "target_word": "高质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋是高质量的，怎么穿都不坏。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一张高质量的桌子，很多年都不会坏。", "target_word": "高质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高质量的行李箱摔了几次也没有坏。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种高质量的雨伞，大风也吹不坏。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸做的木床是高质量的，睡了二十年没坏。", "target_word": "高质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个高质量的书包，能用很久。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条高质量的牛仔裤洗了很多次还没变形。", "target_word": "高质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些锅都是高质量的，摔在地上也不会坏。", "target_word": "高质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自行车是高质量的，骑了很多年还像新的。", "target_word": "高质量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高質量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西做得好、结实耐用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高质量", "is_correct": true, "explanation": "正确：“这把椅子是高质量的”与“用了十年还很结实”相符。"}, {"text": "劣质", "is_correct": false, "explanation": "语义：“劣质”指质量差，与“用了十年还很结实”矛盾。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：“易碎”与“很结实”相反，句子说不通。"}, {"text": "松软", "is_correct": false, "explanation": "体貌：“松软”描述质地柔软，与“很结实”的外观和质地矛盾。"}], "explanations": {"高质量": "正确：“这把椅子是高质量的”与“用了十年还很结实”相符。", "劣质": "语义：“劣质”指质量差，与“用了十年还很结实”矛盾。", "易碎": "语义：“易碎”与“很结实”相反，句子说不通。", "松软": "体貌：“松软”描述质地柔软，与“很结实”的外观和质地矛盾。"}, "sentence_index": 0, "correct_answer": "高质量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很高质量，大家都喜欢和他做朋友。", "explanation": "这里应该用〈温和〉。“高质量”只用于物品或服务，形容性格要用“温和”或“好”。"}, {"text": "这个包的价格很高质量，要花不少钱。", "explanation": "这里应该用〈贵〉。价格高要说“贵”，“高质量”只说物品或服务的品质。"}, {"text": "他的身高很高质量，比同学高出一个头。", "explanation": "这里应该用〈个子高〉。说人的身高要用“个子高”之类的说法，“高质量”只用于物品或服务的品质，不能形容人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高质量", "is_correct": true, "explanation": "正确：“高质量的书包”与“能用很久”相符。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易损坏，与“能用很久”矛盾。"}, {"text": "一次性", "is_correct": false, "explanation": "搭配：“一次性”用于用后即弃的物品，不能与“能用很久”搭配。"}, {"text": "破旧", "is_correct": false, "explanation": "体貌：“破旧”说外观磨损，与“能用很久”的耐用意思矛盾。"}], "explanations": {"高质量": "正确：“高质量的书包”与“能用很久”相符。", "脆弱": "语义：“脆弱”指容易损坏，与“能用很久”矛盾。", "一次性": "搭配：“一次性”用于用后即弃的物品，不能与“能用很久”搭配。", "破旧": "体貌：“破旧”说外观磨损，与“能用很久”的耐用意思矛盾。"}, "sentence_index": 6, "correct_answer": "高质量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的温度很高质量，开了空调也不凉快。", "explanation": "这里应该用〈热〉。说温度高要用“热”，“高质量”只用于物品或服务的品质，不能形容温度。"}, {"text": "他今天的心情很高质量，大家都觉得他很开心。", "explanation": "这里应该用〈高兴〉。心情好要说“高兴”，“高质量”只说物品或服务的品质。"}, {"text": "这辆车跑得很高质量，一下子就到了。", "explanation": "这里应该用〈快〉。速度要说“快”或“高速”，“高质量”只说品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张床是高质量得，睡了十年还没坏。", "corrected_sentence": "这张床是高质量的，睡了十年还没坏。", "error_description": "“是……的”句式要用结构助词“的”，说“是高质量的”。“得”用于动词后引出补语，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个高质量得书包，能用很久。", "corrected_sentence": "这是一个高质量的书包，能用很久。", "error_description": "“高质量”修饰名词“书包”要用结构助词“的”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
