INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水渠是人工挖的、用来让水流走的长长的沟。", "primary_collocate": null, "pronunciation": "shuǐ qú", "ipa": "ʂweɪ˨˩˦ tɕʰy˧˥", "syllable_count": 2, "sentences": [{"text": "村子里有一条长长的水渠。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水渠把雨水引到河里。", "target_word": "水渠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在路边挖了一条水渠。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水渠堵住了，水流不出去。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在清理水渠里的垃圾。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鱼游进了水渠。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水渠两边种着柳树。", "target_word": "水渠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要往水渠里扔东西。", "target_word": "水渠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天，水渠里的水流得很快。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家门前的水渠通到大河。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "输水渠", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人工挖成的、让水流走的长沟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b763f8e4-c8e2-4fed-b4e1-513ee2e3c8b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水渠", "is_correct": true, "explanation": "水渠（shuǐ qú）指人工挖成的让水流走的长沟，是正确答案。"}, {"text": "水球", "is_correct": false, "explanation": "qú（第二声）与 qiú（第二声）只差介音 i，意思是水球（一种球类运动）。"}, {"text": "水泉", "is_correct": false, "explanation": "qú 与 quán 韵母不同，意思是泉水的出口，不是人工挖成的长沟。"}, {"text": "睡去", "is_correct": false, "explanation": "shuì qù 与 shuǐ qú 声母韵母相同，只是声调不同，意思是入睡，与水沟无关。"}], "explanations": {"水渠": "水渠（shuǐ qú）指人工挖成的让水流走的长沟，是正确答案。", "水球": "qú（第二声）与 qiú（第二声）只差介音 i，意思是水球（一种球类运动）。", "水泉": "qú 与 quán 韵母不同，意思是泉水的出口，不是人工挖成的长沟。", "睡去": "shuì qù 与 shuǐ qú 声母韵母相同，只是声调不同，意思是入睡，与水沟无关。"}, "sentence_index": null, "correct_answer": "水渠"}, "level_3": {"options": [{"text": "水渠", "is_correct": true, "explanation": "“长长的”可以用来形容长条形的渠道，“水渠”可以填入。"}, {"text": "水井", "is_correct": false, "explanation": "体貌：水井是圆形的深坑，不能说“长长的”。"}, {"text": "水缸", "is_correct": false, "explanation": "体貌：水缸是圆形的容器，不是长条形的，不能说“长长的”。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶是盛水的器具，不是可以延伸成“长长的”的设施。"}], "explanations": {"水渠": "“长长的”可以用来形容长条形的渠道，“水渠”可以填入。", "水井": "体貌：水井是圆形的深坑，不能说“长长的”。", "水缸": "体貌：水缸是圆形的容器，不是长条形的，不能说“长长的”。", "水壶": "语义：水壶是盛水的器具，不是可以延伸成“长长的”的设施。"}, "sentence_index": 0, "correct_answer": "水渠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把水渠叠好，放进了衣柜。", "explanation": "这里应该用〈衣服〉。水渠是固定在地上的沟渠，不能叠好放进衣柜，叠放的是衣服。"}, {"text": "他把水渠开到了城里的超市。", "explanation": "这里应该用〈汽车〉。水渠是固定在地上的沟渠，不能开动，开的应是汽车。"}, {"text": "他把水渠倒满了，递给我。", "explanation": "这里应该用〈水杯〉。水渠是地面的渠道，不能倒满，也不能递给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水渠", "is_correct": true, "explanation": "“两边”可以指渠道的两侧，“水渠”可以填入。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是喝水用的器具，不能在它两边种柳树。"}, {"text": "水龙头", "is_correct": false, "explanation": "搭配：“两边种着柳树”要求带长度或地段的地物，水龙头是小型设备，不搭配。"}, {"text": "水桶", "is_correct": false, "explanation": "语义：水桶是盛东西的容器，不是能种柳树的地方。"}], "explanations": {"水渠": "“两边”可以指渠道的两侧，“水渠”可以填入。", "水杯": "语义：水杯是喝水用的器具，不能在它两边种柳树。", "水龙头": "搭配：“两边种着柳树”要求带长度或地段的地物，水龙头是小型设备，不搭配。", "水桶": "语义：水桶是盛东西的容器，不是能种柳树的地方。"}, "sentence_index": 6, "correct_answer": "水渠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门前的水渠今天考了第一名。", "explanation": "这里应该用〈学生〉。水渠是人工挖的沟渠，不能参加考试，考试的主体应是人。"}, {"text": "我家门前的水渠每天要吃三顿饭。", "explanation": "这里应该用〈狗〉。水渠不会吃饭，“吃饭”的主体应是人或动物。"}, {"text": "我家门前的水渠昨晚睡得很香。", "explanation": "这里应该用〈猫〉。水渠不会睡觉，“睡得很香”的主体应是人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们在河边修了一只新水渠。", "corrected_sentence": "工人们在河边修了一条新水渠。", "error_description": "“水渠”的量词应用“条”，不能用“只”。“只”多用于动物或成对的物品，长条形的水渠要用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里那条很长水渠是新修的。", "corrected_sentence": "村里那条很长的水渠是新修的。", "error_description": "修饰语“很长”与名词“水渠”之间漏了“的”。修饰语是词组时要用“的”连接，应说“很长的水渠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
