INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "例子是用来教别人明白一个道理的事情。", "primary_collocate": null, "pronunciation": "lì zi", "ipa": "li˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "老师给我们举了一个很好的例子。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道理太难了，你能给我一个例子吗？", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的故事做例子，我们一听就懂了。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的例子很简单，学生都能看懂。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再举一个例子，让大家明白。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个例子说明，努力会有好结果。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每天跑步，是爱运动的好例子。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，没有例子，学语法很难。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子可以当作例子，写在本子上。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的例子，我才明白什么是帮助别人。", "target_word": "例子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用具体的事来说明道理的事例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "例子", "is_correct": true, "explanation": "正确：例子是用来说明道理的具体事情。"}, {"text": "李子", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是李子，一种水果。"}, {"text": "梨子", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是梨子，一种水果。"}, {"text": "日子", "is_correct": false, "explanation": "rì 与 lì 声母不同（r 与 l），意思是日子、时光。"}, {"text": "弟子", "is_correct": false, "explanation": "dì 与 lì 声母不同（d 与 l），意思是弟子、学生。"}], "explanations": {"例子": "正确：例子是用来说明道理的具体事情。", "李子": "lǐ（第三声）与 lì（第四声）声调不同，意思是李子，一种水果。", "梨子": "lí（第二声）与 lì（第四声）声调不同，意思是梨子，一种水果。", "日子": "rì 与 lì 声母不同（r 与 l），意思是日子、时光。", "弟子": "dì 与 lì 声母不同（d 与 l），意思是弟子、学生。"}, "sentence_index": null, "correct_answer": "例子"}, "level_3": {"options": [{"text": "例子", "is_correct": true, "explanation": "正确：例子是用来说明道理的具体事情，与“举”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“举”后接的是例子、例证等具体事例，不能举桌子，句子不通。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不能用来说明道理，“很好的病人”句子不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“举”后接的是例子、例证等具体事例，不能举蛋糕，句子不通。"}], "explanations": {"例子": "正确：例子是用来说明道理的具体事情，与“举”搭配。", "桌子": "语义：“举”后接的是例子、例证等具体事例，不能举桌子，句子不通。", "病人": "语义：病人不能用来说明道理，“很好的病人”句子不通。", "蛋糕": "语义：“举”后接的是例子、例证等具体事例，不能举蛋糕，句子不通。"}, "sentence_index": 0, "correct_answer": "例子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是新产品的例子，请大家先试用。", "explanation": "这里应该用〈样品〉。例子是用来说明道理的事，不是可以试用的实物。"}, {"text": "这个月的例子还没发，我没钱吃饭了。", "explanation": "这里应该用〈工资〉。例子指用来说明道理的事，每月发给工人的钱要说工资。"}, {"text": "他的例子很充分，法官相信了他。", "explanation": "这里应该用〈证据〉。例子只能说明道理，不能用来证明案件的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25162, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "例子", "is_correct": true, "explanation": "正确：例子是用来说明道理的具体事情。"}, {"text": "里子", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是衣服的里层。"}, {"text": "梨子", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是梨子，一种水果。"}, {"text": "荔枝", "is_correct": false, "explanation": "第二个音节 zhī 与 zi 声母不同（zh 与 z），意思是荔枝，一种水果。"}], "explanations": {"例子": "正确：例子是用来说明道理的具体事情。", "里子": "lǐ（第三声）与 lì（第四声）声调不同，意思是衣服的里层。", "梨子": "lí（第二声）与 lì（第四声）声调不同，意思是梨子，一种水果。", "荔枝": "第二个音节 zhī 与 zi 声母不同（zh 与 z），意思是荔枝，一种水果。"}, "sentence_index": null, "correct_answer": "例子"}, "level_3": {"options": [{"text": "例子", "is_correct": true, "explanation": "正确：例子可以指值得学习的具体事例，与“好”搭配。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是书，不能是爱运动的人，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能是爱运动的人，句子不通。"}, {"text": "宾客", "is_correct": false, "explanation": "语域：“宾客”是正式场合的用语，指应邀来做客的人，用来形容平时的运动习惯不合语境。"}], "explanations": {"例子": "正确：例子可以指值得学习的具体事例，与“好”搭配。", "词典": "语义：词典是书，不能是爱运动的人，句子不通。", "冰箱": "语义：冰箱是家电，不能是爱运动的人，句子不通。", "宾客": "语域：“宾客”是正式场合的用语，指应邀来做客的人，用来形容平时的运动习惯不合语境。"}, "sentence_index": 6, "correct_answer": "例子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆里陈列着一件珍贵的例子。", "explanation": "这里应该用〈标本〉。例子指用来说明道理的事，陈列的实物要说标本。"}, {"text": "妈妈送给我一个生日例子。", "explanation": "这里应该用〈礼物〉。例子指用来说明道理的事，送人的物品要说礼物。"}, {"text": "他掏出例子，门卫看后才放他进去。", "explanation": "这里应该用〈证件〉。例子指用来说明道理的事，供人查验身份的东西要说证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师举了三个的例子。", "corrected_sentence": "老师举了三个例子。", "error_description": "错误：数量词“三个”和名词“例子”之间不能加“的”，应说“三个例子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们来看一本例子。", "corrected_sentence": "我们来看一个例子。", "error_description": "错误：“本”用于书籍、册子，不能用来数“例子”。应把“本”改为“个”，说“我们来看一个例子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
