INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把需要的东西管好用好。", "primary_collocate": null, "pronunciation": "zī yuán guǎn lǐ", "ipa": "tsɹ̩˥ ɥɛn˧˥ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "他的工作是资源管理。", "target_word": "资源管理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司请他负责资源管理。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的资源管理能让工作更快。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的资源管理做得很好。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做好资源管理，就不会浪费钱和时间。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学学习资源管理。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里的水和电也需要资源管理。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个项目失败，是因为资源管理出了问题。", "target_word": "资源管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开了一个关于资源管理的会。", "target_word": "资源管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好资源管理以后，她把时间安排得很清楚。", "target_word": "资源管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資源管理", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词，指对人、钱、时间、物品等资源的安排和使用方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资源管理", "is_correct": true, "explanation": "正确：“资源管理”是一项抽象的工作，作“工作”的内容，句意通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是具体的物件，不是工作，“他的工作是椅子”不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，不是工作，“他的工作是冰箱”不通。"}, {"text": "字典", "is_correct": false, "explanation": "语义：“字典”是工具书，不是工作，“他的工作是字典”不通。"}], "explanations": {"资源管理": "正确：“资源管理”是一项抽象的工作，作“工作”的内容，句意通顺。", "椅子": "语义：“椅子”是具体的物件，不是工作，“他的工作是椅子”不通。", "冰箱": "语义：“冰箱”是电器，不是工作，“他的工作是冰箱”不通。", "字典": "语义：“字典”是工具书，不是工作，“他的工作是字典”不通。"}, "sentence_index": 0, "correct_answer": "资源管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的资源管理很冷，要多穿衣服。", "explanation": "这里应该用〈天气〉。“资源管理”指安排和使用资源的工作，不能说冷热。"}, {"text": "他做事很有资源管理。", "explanation": "这里应该用〈条理〉。“资源管理”指对资源的安排和使用，是工作内容，不是做事的品质；形容做事有秩序应说“他做事很有条理”。"}, {"text": "他对家人的资源管理很深。", "explanation": "这里应该用〈感情〉。“资源管理”指对资源的安排和使用，不能用“很深”来形容，感情的深浅要说“感情很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资源管理", "is_correct": true, "explanation": "正确：水和电需要被管好用好，“资源管理”符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "语义：水和电不需要吃饭，“需要饭”与句子的主语不符。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：水和电不会睡觉，“睡眠”不能用于它们。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“需要感情”一般指人，水和电不能有感情，这里不搭。"}], "explanations": {"资源管理": "正确：水和电需要被管好用好，“资源管理”符合句意。", "饭": "语义：水和电不需要吃饭，“需要饭”与句子的主语不符。", "睡眠": "语义：水和电不会睡觉，“睡眠”不能用于它们。", "感情": "搭配：“需要感情”一般指人，水和电不能有感情，这里不搭。"}, "sentence_index": 6, "correct_answer": "资源管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是一个很好的资源管理。", "explanation": "这里应该用〈管理者〉。“资源管理”指做的工作，不指人；指人要说“资源管理者”。"}, {"text": "这场比赛的资源管理很激烈。", "explanation": "这里应该用〈竞争〉。“激烈”形容竞争、战斗等场面，“资源管理”是安排和使用资源的工作，不能用“激烈”形容，应说“这场比赛的竞争很激烈”。"}, {"text": "学校的资源管理很负责。", "explanation": "这里应该用〈管理员〉。“资源管理”指工作内容，不指人，“负责”是形容人的品质，应说“学校的管理员很负责”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟资源管理很感兴趣。", "corrected_sentence": "他对资源管理很感兴趣。", "error_description": "介词错误：“感兴趣”的对象要用介词“对”引出，不能用“跟”，应说“他对资源管理很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个项目的资源管理做很好。", "corrected_sentence": "这个项目的资源管理做得很好。", "error_description": "补语错误：“做很好”缺少结构助词“得”，程度补语前要加“得”，应说“做得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
