INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或很多人住在同一个房子里。", "primary_collocate": null, "pronunciation": "zhù zài yì qǐ", "ipa": "ʈ͡ʂu˥˩ t͡sai˥˩ i˥˩ t͡ɕʰi˨˩˦", "syllable_count": 4, "sentences": [{"text": "我们公司有宿舍，同事都住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们三个人住在一起，房租很便宜。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学时，我和他住在一起。", "target_word": "住在一起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人想和孩子住在一起。", "target_word": "住在一起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这套房子很大，四个人可以住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们住在一起三年了，像一家人。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为工作太忙，爸爸不能和我们住在一起。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边的小房子里，五个学生住在一起。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有了孩子，还住在一起吗？", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "室友们住在一起，每天一起做饭。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "住在一起了", "label": "完成体"}, {"form": "住在一起过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "多个人同住在一座房子里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬走", "is_correct": false, "explanation": "语义：“搬走”指迁离，与“公司有宿舍，同事都住在一起”的情境相悖。"}, {"text": "住在一起", "is_correct": true, "explanation": "正确：“公司有宿舍，同事都住在一起”说的是多人同住一处，与句意相符。"}, {"text": "分居", "is_correct": false, "explanation": "搭配：“分居”多指夫妻或伴侣分开住，不能用于同事。"}, {"text": "独居", "is_correct": false, "explanation": "语义：“独居”指独自一人住，与“同事都”和“宿舍”的说法矛盾。"}], "explanations": {"搬走": "语义：“搬走”指迁离，与“公司有宿舍，同事都住在一起”的情境相悖。", "住在一起": "正确：“公司有宿舍，同事都住在一起”说的是多人同住一处，与句意相符。", "分居": "搭配：“分居”多指夫妻或伴侣分开住，不能用于同事。", "独居": "语义：“独居”指独自一人住，与“同事都”和“宿舍”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "住在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人住在一起，很自由。", "explanation": "这里不这么用。住在一起指两人或多人共同住，只有一个人时不能用。"}, {"text": "这把椅子和那张桌子住在一起。", "explanation": "这里应该用〈摆在一起〉。住在一起指人或动物共同居住，家具不能“住”，只能说摆在一起。"}, {"text": "大家在照相机前住在一起。", "explanation": "这里应该用〈站在一起〉。住在一起指共同居住，不能用于拍照时的站位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陪伴", "is_correct": false, "explanation": "配价：“陪伴”需要直接带宾语，不能说“和我们陪伴”。"}, {"text": "住在一起", "is_correct": true, "explanation": "正确：“因为工作太忙，爸爸不能和我们住在一起”说明爸爸无法与家人同住，与句意相符。"}, {"text": "出走", "is_correct": false, "explanation": "语义：“出走”指离家出走，与“因为工作太忙”这一原因不相符。"}, {"text": "辞行", "is_correct": false, "explanation": "配价：“辞行”要用“向”引出告别的对象，不能直接说“和我们辞行”。"}], "explanations": {"陪伴": "配价：“陪伴”需要直接带宾语，不能说“和我们陪伴”。", "住在一起": "正确：“因为工作太忙，爸爸不能和我们住在一起”说明爸爸无法与家人同住，与句意相符。", "出走": "语义：“出走”指离家出走，与“因为工作太忙”这一原因不相符。", "辞行": "配价：“辞行”要用“向”引出告别的对象，不能直接说“和我们辞行”。"}, "sentence_index": 6, "correct_answer": "住在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们在公园住在一起。", "explanation": "这里应该用〈见面〉。住在一起指共同住在一处，不能表示在公园碰面。"}, {"text": "电影院里，大家住在一起看电影。", "explanation": "这里应该用〈坐在一起〉。住在一起指共同住在一个房子里，不能指在影院里同坐看电影。"}, {"text": "运动会上，同学们住在一起加油。", "explanation": "这里应该用〈聚在一起〉。住在一起指共同居住，不能指在赛场上聚集助威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来的同事都把住在一起，互相照顾。", "corrected_sentence": "新来的同事都住在一起，互相照顾。", "error_description": "“把”错误：“住在一起”前不能加“把”，应去掉“把”，说“都住在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月老家来的亲戚都很住在一起，热闹极了。", "corrected_sentence": "这个月老家来的亲戚都住在一起，热闹极了。", "error_description": "错误：“很”不能直接修饰动作“住在一起”，应去掉“很”，说“都住在一起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25168, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
