INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25168, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从很小的时候开始。", "primary_collocate": null, "pronunciation": "cóng xiǎo", "ipa": "tsʰʊŋ˧˥ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他从小就很聪明，大家都喜欢他。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从小怕黑，晚上不关灯睡不着。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶从小教我写字，现在我写得很好。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两家是邻居，两个孩子从小一起玩。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小跟爸爸学做饭，菜做得很香。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟从小不爱吃青菜，只爱吃肉。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小爱唱歌，长大后成了歌手。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只猫从小在我家长大，很怕生人。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，好习惯要从小养成。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们从小就在这条河里洗澡。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "从小到大", "label": "固定搭配"}, {"form": "从小就", "label": "常见搭配"}], "register": "中性", "sense_fingerprint": "从小：从很小的时候开始做某事或有某特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上，不能和“就很聪明”这种长期特点搭配。"}, {"text": "从小", "is_correct": true, "explanation": "正确：“从小”表示从很小的时候开始就有某种特点，与“就很聪明”相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，说“偶尔就很聪明”与“聪明”这一稳定特点相矛盾。"}, {"text": "方才", "is_correct": false, "explanation": "语域：“方才”是书面语，与口语化的“就很聪明，大家都喜欢他”不协调。"}], "explanations": {"立刻": "搭配：“立刻”表示马上，不能和“就很聪明”这种长期特点搭配。", "从小": "正确：“从小”表示从很小的时候开始就有某种特点，与“就很聪明”相符。", "偶尔": "语义：“偶尔”表示不经常，说“偶尔就很聪明”与“聪明”这一稳定特点相矛盾。", "方才": "语域：“方才”是书面语，与口语化的“就很聪明，大家都喜欢他”不协调。"}, "sentence_index": 0, "correct_answer": "从小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小在这里教过书，后来调走了。", "explanation": "这里应该用〈年轻时〉。“从小”指幼年时期起的情况，教书是成年后的事，说成年后的经历要用“年轻时”。"}, {"text": "这片山坡从小是一片果园。", "explanation": "这里应该用〈从前〉。“从小”指生物从幼年起的经历，山坡没有幼年，说地方过去的样子要用“从前”。"}, {"text": "我从小结了婚，现在有两个孩子。", "explanation": "这里应该用〈毕业后〉。“从小”指幼年时期起的情况，结婚是成年后的事，不能用“从小”，应改用“毕业后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽而", "is_correct": false, "explanation": "语义：“忽而”表示时有时无、忽然，与“爱唱歌”的稳定爱好不符。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与口语化的“爱唱歌，长大后成了歌手”不协调。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”表示突然发生，不能修饰“爱唱歌”这种长期爱好。"}, {"text": "从小", "is_correct": true, "explanation": "正确：“从小”表示从幼年时期起，与“爱唱歌，长大后成了歌手”的经历相符。"}], "explanations": {"忽而": "语义：“忽而”表示时有时无、忽然，与“爱唱歌”的稳定爱好不符。", "业已": "语域：“业已”是书面语，与口语化的“爱唱歌，长大后成了歌手”不协调。", "一下子": "搭配：“一下子”表示突然发生，不能修饰“爱唱歌”这种长期爱好。", "从小": "正确：“从小”表示从幼年时期起，与“爱唱歌，长大后成了歌手”的经历相符。"}, "sentence_index": 6, "correct_answer": "从小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小去了城里工作。", "explanation": "这里应该用〈后来〉。“从小”指从幼年起，不能用来说长大后才发生的事。"}, {"text": "这里从小只有几户人家。", "explanation": "这里应该用〈当初〉。“从小”指生物从幼年起的情况，地方没有幼年，说地方的早先情况要用“当初”。"}, {"text": "他接到通知，从小出发了。", "explanation": "这里应该用〈立即〉。“从小”指从幼年起的持续状况，不能表示马上发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟从小的不爱说话。", "corrected_sentence": "我弟弟从小不爱说话。", "error_description": "错误：“从小”是副词，后面不能加“的”，“从小的”不能用在“不爱说话”前作状语。正确应为“我弟弟从小不爱说话。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从小了就爱唱歌。", "corrected_sentence": "他从小就爱唱歌。", "error_description": "错误：“从小”后面直接加了“了”。“从小”是时间状语，不能带“了”。正确应为“他从小就爱唱歌。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
