INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25170, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "田地里种植、用来收获的农作物，如麦子、稻子。", "primary_collocate": null, "pronunciation": "zhuāng jia", "ipa": "ʈʂwaŋ˥ tɕja", "syllable_count": 2, "sentences": [{"text": "地里的庄稼长得很好。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，农民去看庄稼。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在村里种庄稼。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个月没下雨，庄稼都枯了。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大风吹倒了不少庄稼。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子和稻子都是庄稼。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民忙着给庄稼浇水。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虫子吃了庄稼，农民很着急。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天庄稼熟了，田里一片金黄。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里的庄稼需要阳光和水。", "target_word": "庄稼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片庄稼", "label": "量词"}, {"form": "莊稼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "田地里种植、用来收获的农作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "庄稼", "is_correct": true, "explanation": "“庄稼”指地里种的粮食作物，句中“地里的庄稼长得很好”符合句意。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不会生长，不能说“地里的机器长得很好”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“长得很好”只用于植物或人，不用来形容房子。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会生长，“地里的石头长得很好”说不通。"}], "explanations": {"庄稼": "“庄稼”指地里种的粮食作物，句中“地里的庄稼长得很好”符合句意。", "机器": "语义：机器不会生长，不能说“地里的机器长得很好”。", "房子": "搭配：“长得很好”只用于植物或人，不用来形容房子。", "石头": "语义：石头不会生长，“地里的石头长得很好”说不通。"}, "sentence_index": 0, "correct_answer": "庄稼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里开满了各色庄稼。", "explanation": "这里应该用〈鲜花〉。庄稼是种来收获的农作物，花园里供观赏的花不说庄稼。"}, {"text": "公园的草地上长着很多庄稼。", "explanation": "这里应该用〈野草〉。庄稼是人种来收获的作物，草地上没人种的野草不说庄稼。"}, {"text": "苗圃里种着很多庄稼。", "explanation": "这里应该用〈树苗〉。苗圃里种的是树苗，不是用来收获的作物，不说庄稼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庄稼", "is_correct": true, "explanation": "“庄稼”是需要浇水的植物，句中农民给它浇水，符合句意。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不需要浇水，不能说给玩具浇水。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不需要浇水，“给电脑浇水”说不通。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“浇水”的对象是植物，不说给学生浇水。"}], "explanations": {"庄稼": "“庄稼”是需要浇水的植物，句中农民给它浇水，符合句意。", "玩具": "语义：玩具不需要浇水，不能说给玩具浇水。", "电脑": "语义：电脑不需要浇水，“给电脑浇水”说不通。", "学生": "搭配：“浇水”的对象是植物，不说给学生浇水。"}, "sentence_index": 6, "correct_answer": "庄稼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田里长着一朵庄稼，需要阳光和水。", "explanation": "这里应该用〈一片〉。朵用于花朵，庄稼是成片种的，不能说“一朵庄稼”。"}, {"text": "田里有一颗庄稼，需要阳光和水。", "explanation": "这里应该用〈一片〉。颗用于颗粒或圆形的小东西，如一颗麦粒，不用于整片庄稼。"}, {"text": "田里有一座庄稼，需要阳光和水。", "explanation": "这里应该用〈一片〉。座用于山、房屋这类大型固定物，不能用来量庄稼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子后面有一片庄稼们。", "corrected_sentence": "村子后面有一片庄稼。", "error_description": "词缀错误：“们”只用于指人的复数，“庄稼”是植物，不能加“们”，应说“一片庄稼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民在田里种了一只庄稼。", "corrected_sentence": "农民在田里种了一片庄稼。", "error_description": "量词错误：“只”多用于动物等，不能用于庄稼。庄稼是成片种的，应用“片”，说“一片庄稼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
