INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25172, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一个接一个做事情。", "primary_collocate": null, "pronunciation": "lún liú", "ipa": "lwən˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "每个人都说一句，大家轮流说。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们四个人轮流看家。", "target_word": "轮流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个星期，哥哥和我轮流倒垃圾。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生轮流读课文。", "target_word": "轮流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们轮流玩这个新玩具。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈上班时，邻居们轮流帮她看孩子。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛时，两个队员轮流上场。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里，护士们轮流上夜班。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们轮流把行李搬上了楼。", "target_word": "轮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们轮流请客，这次轮到我了。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多人依次一个接一个做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抢着", "is_correct": false, "explanation": "语义：“抢着”指争先恐后，与“每个人都说一句”的依次进行矛盾。"}, {"text": "轮流", "is_correct": true, "explanation": "正确：“每个人都说一句，大家轮流说”指一个接一个依次进行，与句意相符。"}, {"text": "齐声", "is_correct": false, "explanation": "语义：“齐声”指同时发声，与“每个人都说一句”的先后顺序矛盾。"}, {"text": "静默", "is_correct": false, "explanation": "搭配：“静默”与“说”搭配不当，不能说“静默说”。"}], "explanations": {"抢着": "语义：“抢着”指争先恐后，与“每个人都说一句”的依次进行矛盾。", "轮流": "正确：“每个人都说一句，大家轮流说”指一个接一个依次进行，与句意相符。", "齐声": "语义：“齐声”指同时发声，与“每个人都说一句”的先后顺序矛盾。", "静默": "搭配：“静默”与“说”搭配不当，不能说“静默说”。"}, "sentence_index": 0, "correct_answer": "轮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我一个人轮流读课文。", "explanation": "这里不这么用。轮流需要多人依次进行，只有一个人时不能用〈轮流〉。"}, {"text": "老师让学生轮流齐读课文。", "explanation": "这里不这么用。“轮流”指依次进行，与“齐读”矛盾。"}, {"text": "老师让学生一起轮流读课文。", "explanation": "这里不这么用。“轮流”指一个接一个进行，不能和表示同时的“一起”连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包办", "is_correct": false, "explanation": "搭配：“包办”不能搭配“上场”，且与两人轮换的情境不符。"}, {"text": "轮流", "is_correct": true, "explanation": "正确：“比赛时，两个队员轮流上场”指两人依次替换上场，与句意相符。"}, {"text": "独占", "is_correct": false, "explanation": "语义：“独占”指单独占有，与两个队员依次上场的情况矛盾。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人，与“两个队员”矛盾。"}], "explanations": {"包办": "搭配：“包办”不能搭配“上场”，且与两人轮换的情境不符。", "轮流": "正确：“比赛时，两个队员轮流上场”指两人依次替换上场，与句意相符。", "独占": "语义：“独占”指单独占有，与两个队员依次上场的情况矛盾。", "独自": "语义：“独自”指一个人，与“两个队员”矛盾。"}, "sentence_index": 6, "correct_answer": "轮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人轮流请客，每次都是他付钱。", "explanation": "这里不这么用。“轮流”需要多人一个接一个做，只有一个人时不能用。"}, {"text": "朋友们轮流同时唱歌，声音很大。", "explanation": "这里不这么用。“轮流”指一个接一个进行，与“同时”矛盾。"}, {"text": "这条河轮流流过我们的城市。", "explanation": "这里应该用〈慢慢〉。“轮流”指多人依次做事，不能用来说河水流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们把轮流回答问题，每人一次。", "corrected_sentence": "同学们轮流回答问题，每人一次。", "error_description": "“把”误用：“轮流”作状语后直接接动词，“把”不能插在“轮流”前，应去掉，说“同学们轮流回答问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们轮流了去饭馆吃饭，这次轮到我了。", "corrected_sentence": "朋友们轮流去饭馆吃饭，这次轮到我了。", "error_description": "“轮流了”错误。“了”不能紧跟状语“轮流”，应去掉，只保留“轮流去饭馆吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大意", "is_correct": true, "explanation": "“大意”指不注意、疏忽，与“小心”构成反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "坚硬", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "清晰", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}], "correct_answer": "大意", "explanations": {"大意": "“大意”指不注意、疏忽，与“小心”构成反义关系。", "宽广": "与“小心”没有反义关系，语义无关。", "坚硬": "与“小心”没有反义关系，语义无关。", "清晰": "与“小心”没有反义关系，语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗心", "is_correct": true, "explanation": "“粗心”指不细心、不留神，与“小心”构成反义关系。"}, {"text": "圆满", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "热闹", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}], "correct_answer": "粗心", "explanations": {"粗心": "“粗心”指不细心、不留神，与“小心”构成反义关系。", "圆满": "与“小心”没有反义关系，语义无关。", "潮湿": "与“小心”没有反义关系，语义无关。", "热闹": "与“小心”没有反义关系，语义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注意安全，不要让自己受伤。", "primary_collocate": null, "pronunciation": "xiǎo xīn", "ipa": "ɕjɑʊ˨˩˦ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "山路很滑，你走路要小心。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，别摔倒，地上有冰。", "target_word": "小心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "刀很快，切菜时小心别切到手。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在河边玩，妈妈叫他小心点。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山的时候要小心，别从石头上掉下去。", "target_word": "小心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里的油很热，你小心别烫到自己。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑车很快，我对他说：“小心点！”", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨路滑，请大家小心走路。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小心地走过那座窄桥。", "target_word": "小心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上一个人回家，要多小心。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小心点儿", "label": "儿化"}, {"form": "小心翼翼", "label": "复合"}, {"form": "小心地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "小心：注意人身安全，避免自己受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小心", "is_correct": true, "explanation": "“小心”指注意安全、避免受伤，与“山路很滑”的警示语境相合。"}, {"text": "跑", "is_correct": false, "explanation": "语义：山路很滑，走路时跑会摔倒，与句中的警示相悖。"}, {"text": "唱", "is_correct": false, "explanation": "语义：走路时唱歌与“山路很滑”的提醒语境不相合。"}, {"text": "带", "is_correct": false, "explanation": "配价：“带”需要带宾语，“走路要带”里没有宾语。"}], "explanations": {"小心": "“小心”指注意安全、避免受伤，与“山路很滑”的警示语境相合。", "跑": "语义：山路很滑，走路时跑会摔倒，与句中的警示相悖。", "唱": "语义：走路时唱歌与“山路很滑”的提醒语境不相合。", "带": "配价：“带”需要带宾语，“走路要带”里没有宾语。"}, "sentence_index": 0, "correct_answer": "小心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶很小心打雷。", "explanation": "这里应该用〈害怕〉。“小心”表示留神避免危险，不表示惧怕。"}, {"text": "妈妈小心生病的孩子。", "explanation": "这里应该用〈照顾〉。“小心”指注意避免危险，不用于照料人。"}, {"text": "我昨天在商店小心了一本书。", "explanation": "这里应该用〈买〉。“小心”表示注意安全，不能表示购买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小心", "is_correct": true, "explanation": "“小心点！”是劝对方注意安全，与“他骑车很快”的语境相合。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑点”不能用来劝骑车快的人，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写点”与“骑车很快”的劝告语境不相合。"}, {"text": "思索", "is_correct": false, "explanation": "语域：“思索”是书面语，口语的劝告“……点！”不这样说。"}], "explanations": {"小心": "“小心点！”是劝对方注意安全，与“他骑车很快”的语境相合。", "笑": "语义：“笑点”不能用来劝骑车快的人，句意不通。", "写": "语义：“写点”与“骑车很快”的劝告语境不相合。", "思索": "语域：“思索”是书面语，口语的劝告“……点！”不这样说。"}, "sentence_index": 6, "correct_answer": "小心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她小心地哭了，眼泪流个不停。", "explanation": "这里应该用〈伤心〉。“小心”表示留神避免危险，不能用来修饰哭泣这类情绪行为。"}, {"text": "老师很小心学生，每天都问他们的身体。", "explanation": "这里应该用〈关心〉。“小心”表示注意安全，不表示关怀。"}, {"text": "孩子在院子里小心球。", "explanation": "这里应该用〈玩〉。“小心”表示注意避免危险，不能带“球”作宾语表示玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下雨以后，路很滑，大家要小心地。", "corrected_sentence": "下雨以后，路很滑，大家要小心。", "error_description": "“小心”作谓语时不加“地”，应说“要小心”；“小心地”只用于修饰后面的动词，如“小心地走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上回家的路很暗，你要小心了点儿。", "corrected_sentence": "晚上回家的路很暗，你要小心点儿。", "error_description": "“小心点儿”是动词加补语，中间不能插“了”；“小心了点儿”不成立，应说“小心点儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
