INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一直用的方法。", "primary_collocate": null, "pronunciation": "lǎo bàn fǎ", "ipa": "lɑʊ˨˩ pan˥˩ fa˨˩", "syllable_count": 3, "sentences": [{"text": "妈妈治感冒还是用老办法，喝热水。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店做面还是几十年前的老办法。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一直用老办法记账。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗这件衣服，我用的是外婆的老办法。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老办法不一定不好，关键是有用。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人用老办法做豆腐，味道很好。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的老办法是早睡早起。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热，我们用老办法，在院子里洒水。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老办法他用了很多年，从来没有变过。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学外语的老办法就是多听多说。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老辦法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "老办法：一直沿用下来的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老办法", "is_correct": true, "explanation": "老办法：此处是名词，指一直沿用的治感冒方法，与“喝热水”相合。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”不是家里常用的治感冒方法，与“喝热水”不协调，句意不通。"}, {"text": "注射器", "is_correct": false, "explanation": "语义：“注射器”与“喝热水”的治法不一致，句意不合。"}, {"text": "电锯", "is_correct": false, "explanation": "搭配：“用电锯”不能用来治感冒，与“喝热水”的说法不相配。"}], "explanations": {"老办法": "老办法：此处是名词，指一直沿用的治感冒方法，与“喝热水”相合。", "手术": "语义：“手术”不是家里常用的治感冒方法，与“喝热水”不协调，句意不通。", "注射器": "语义：“注射器”与“喝热水”的治法不一致，句意不合。", "电锯": "搭配：“用电锯”不能用来治感冒，与“喝热水”的说法不相配。"}, "sentence_index": 0, "correct_answer": "老办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们俩是几十年的老办法。", "explanation": "这里应该用〈老伙计〉。老办法指方法，不指人，不能用来形容两个人的交情。"}, {"text": "他的老办法又犯了，一到冬天就咳嗽。", "explanation": "这里应该用〈老病根〉。“犯”后面接的是病根这类缺点，老办法指方法，不指病根。"}, {"text": "他们是老办法，二十年没见了。", "explanation": "这里应该用〈老同学〉。老办法指方法，不指人，不能说“他们是老办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老办法", "is_correct": true, "explanation": "老办法：此处是名词，指家里一直沿用的生活方式，与“早睡早起”相合。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”不是生活方式，“是早睡早起”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能充当“早睡早起”的内容，句意不合。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“是早睡早起”说的是生活习惯，电脑不能与之搭配。"}], "explanations": {"老办法": "老办法：此处是名词，指家里一直沿用的生活方式，与“早睡早起”相合。", "电视": "语义：“电视”不是生活方式，“是早睡早起”说不通。", "冰箱": "语义：“冰箱”是家电，不能充当“早睡早起”的内容，句意不合。", "电脑": "搭配：“是早睡早起”说的是生活习惯，电脑不能与之搭配。"}, "sentence_index": 6, "correct_answer": "老办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座老办法有一百年了。", "explanation": "这里应该用〈老房子〉。老办法指方法，不指房屋，不能用来形容建筑。"}, {"text": "这幅老办法很珍贵。", "explanation": "这里应该用〈老画〉。老办法指方法，不指画作，不能用来形容画。"}, {"text": "这家百年老店是老办法。", "explanation": "这里应该用〈老字号〉。老办法指方法，不指店铺，不能用来指老店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他们家传下来老办法。", "corrected_sentence": "这是他们家传下来的老办法。", "error_description": "“传下来”修饰“老办法”，中间需要“的”。错误：漏掉“的”，写成“传下来老办法”。正确：“这是他们家传下来的老办法。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一台老办法，我们用了几代人。", "corrected_sentence": "这是一个老办法，我们用了几代人。", "error_description": "“台”多用于机器、电器等，不能用来计量“办法”。“老办法”的量词应为“个”。错误：“一台老办法”。正确：“这是一个老办法，我们用了几代人。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
