INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久不下雨，土地很干，没有水。", "primary_collocate": null, "pronunciation": "gān hàn", "ipa": "kan˥˥ xan˥˩", "syllable_count": 2, "sentences": [{"text": "今年夏天很长时间没下雨，出现了严重的干旱。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱让农民的庄稼都枯死了。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区每年春天都有干旱。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为干旱，河里的水越来越少。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在帮助受干旱影响的农民。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方这几个月的干旱让大家很担心。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们挖了很深的井来对付干旱。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场干旱已经持续了三个月。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱的时候，田里的土会裂开。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，明年可能还会有干旱。", "target_word": "干旱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乾旱", "label": "繁体"}, {"form": "干旱地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "长期无雨、土地缺水的自然灾害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干旱", "is_correct": true, "explanation": "“严重的干旱”与“很长时间没下雨”相符。"}, {"text": "暴雨", "is_correct": false, "explanation": "语义：暴雨需要大量降雨，与“很长时间没下雨”矛盾。"}, {"text": "洪水", "is_correct": false, "explanation": "语义：洪水要有大量雨水，与“没下雨”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“严重的”不修饰颜色，句子不通。"}], "explanations": {"干旱": "“严重的干旱”与“很长时间没下雨”相符。", "暴雨": "语义：暴雨需要大量降雨，与“很长时间没下雨”矛盾。", "洪水": "语义：洪水要有大量雨水，与“没下雨”矛盾。", "颜色": "搭配：“严重的”不修饰颜色，句子不通。"}, "sentence_index": 0, "correct_answer": "干旱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次大雨造成了严重的干旱。", "explanation": "这里应该用〈洪涝〉。干旱指长期缺雨，大雨造成的灾害要用〈洪涝〉。"}, {"text": "我们村去年取得了一场干旱。", "explanation": "这里应该用〈胜利〉。干旱是灾害，不能说“取得”，取得的是〈胜利〉这类成果。"}, {"text": "干旱让城市的排水系统都满了。", "explanation": "这里应该用〈暴雨〉。排水系统满是因为雨多，干旱不会造成这种结果，要用〈暴雨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干旱", "is_correct": true, "explanation": "挖深井是为了应对缺水，与“对付干旱”相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：挖井不能对付感冒，句子不成立。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：挖井与对付蚊子无关，句子不通。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：“对付”用于敌人、困难或灾害，不说“对付朋友”。"}], "explanations": {"干旱": "挖深井是为了应对缺水，与“对付干旱”相符。", "感冒": "语义：挖井不能对付感冒，句子不成立。", "蚊子": "语义：挖井与对付蚊子无关，句子不通。", "朋友": "搭配：“对付”用于敌人、困难或灾害，不说“对付朋友”。"}, "sentence_index": 6, "correct_answer": "干旱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干旱让很多房子倒塌了。", "explanation": "这里应该用〈地震〉。干旱不会直接导致房屋倒塌，倒塌要用〈地震〉。"}, {"text": "妈妈在厨房里用干旱炒了一盘菜。", "explanation": "这里应该用〈油〉。干旱不能用来炒菜，炒菜要用〈油〉。"}, {"text": "干旱把屋顶都掀翻了。", "explanation": "这里应该用〈龙卷风〉。干旱不会掀翻屋顶，把屋顶掀翻的是〈龙卷风〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年夏天发生了一朵干旱。", "corrected_sentence": "今年夏天发生了一场干旱。", "error_description": "错误：“一朵干旱”。正确：“一场干旱”。“朵”用于花、云等，不用于灾害或事件；“场”用于灾害和事件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带的干旱们很严重。", "corrected_sentence": "这一带的干旱很严重。", "error_description": "错误：“干旱们”。正确：“干旱”。“干旱”是抽象名词，不加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费水", "is_correct": true, "explanation": "反义：“浪费水”指不珍惜、多用水，与“节约用水”正好相对。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指出外游览，与节约用水不相对。"}, {"text": "写作", "is_correct": false, "explanation": "无反义关系：“写作”指写文章，与用水无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发声演唱，与节约用水不相对。"}], "correct_answer": "浪费水", "explanations": {"浪费水": "反义：“浪费水”指不珍惜、多用水，与“节约用水”正好相对。", "旅行": "无反义关系：“旅行”指出外游览，与节约用水不相对。", "写作": "无反义关系：“写作”指写文章，与用水无关。", "唱歌": "无反义关系：“唱歌”指发声演唱，与节约用水不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费水", "is_correct": true, "explanation": "反义：“浪费水”指不珍惜、多用水，与“节约用水”正好相对。"}, {"text": "游览", "is_correct": false, "explanation": "无反义关系：“游览”指参观风景，与节约用水不相对。"}, {"text": "烹饪", "is_correct": false, "explanation": "无反义关系：“烹饪”指做饭做菜，与节约用水不相对。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”指舞蹈动作，与用水无关。"}], "correct_answer": "浪费水", "explanations": {"浪费水": "反义：“浪费水”指不珍惜、多用水，与“节约用水”正好相对。", "游览": "无反义关系：“游览”指参观风景，与节约用水不相对。", "烹饪": "无反义关系：“烹饪”指做饭做菜，与节约用水不相对。", "跳舞": "无反义关系：“跳舞”指舞蹈动作，与用水无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是不浪费水，比如洗手时关小水龙头。", "primary_collocate": null, "pronunciation": "jié yuē yòng shuǐ", "ipa": "tɕje˧˥ ɥe˥ jʊŋ˥˩ ʂweɪ˨˩˦", "syllable_count": 4, "sentences": [{"text": "洗手的时候关小水龙头，就是节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家很缺水，所以大家都要节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天气干旱，老师请同学们节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙的时候关上水龙头，也是节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，洗菜的水可以浇花，这样能节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的墙上写着“请节约用水”。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该从小养成节约用水的习惯。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市水不多，市民都在节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用洗衣服的水冲厕所，是节约用水的好办法。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了节约用水，妈妈把洗米水留下来浇花。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不浪费水、节省用水的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡与“关小水龙头”这种节水做法无关，句子说不通。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：“玩耍”与“关小水龙头”的节水做法不符，句意矛盾。"}, {"text": "浪费水", "is_correct": false, "explanation": "搭配：“浪费水”指多用水，不能用来解释“关小水龙头”这种做法。"}, {"text": "节约用水", "is_correct": true, "explanation": "正确：关小水龙头正是“节约用水”的具体做法，与“就是”的解释相符。"}], "explanations": {"洗澡": "语义：洗澡与“关小水龙头”这种节水做法无关，句子说不通。", "玩耍": "语义：“玩耍”与“关小水龙头”的节水做法不符，句意矛盾。", "浪费水": "搭配：“浪费水”指多用水，不能用来解释“关小水龙头”这种做法。", "节约用水": "正确：关小水龙头正是“节约用水”的具体做法，与“就是”的解释相符。"}, "sentence_index": 0, "correct_answer": "节约用水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑每天都节约用水。", "explanation": "这里应该用〈省电〉。电脑不用水，“节约用水”只能指减少用水；说减少用电要用“省电”。"}, {"text": "这盏台灯每天都节约用水。", "explanation": "这里应该用〈省电〉。台灯不用水，“节约用水”不能用于不用水的物品；说减少用电要用“省电”。"}, {"text": "这台电视机每天都节约用水。", "explanation": "这里应该用〈省电〉。电视机不用水，“节约用水”不能用于它；说减少用电要用“省电”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费水", "is_correct": false, "explanation": "搭配：“养成……的习惯”常接好习惯，“浪费水”是坏习惯，与“应该”的要求不搭。"}, {"text": "打架", "is_correct": false, "explanation": "语义：养成“打架”的习惯与“应该”的要求相反，句意不成立。"}, {"text": "乱扔垃圾", "is_correct": false, "explanation": "语义：养成“乱扔垃圾”的习惯与“应该从小”的要求相反，句意矛盾。"}, {"text": "节约用水", "is_correct": true, "explanation": "正确：“从小养成节约用水的习惯”是好习惯，与“应该”的要求相符。"}], "explanations": {"浪费水": "搭配：“养成……的习惯”常接好习惯，“浪费水”是坏习惯，与“应该”的要求不搭。", "打架": "语义：养成“打架”的习惯与“应该”的要求相反，句意不成立。", "乱扔垃圾": "语义：养成“乱扔垃圾”的习惯与“应该从小”的要求相反，句意矛盾。", "节约用水": "正确：“从小养成节约用水的习惯”是好习惯，与“应该”的要求相符。"}, "sentence_index": 6, "correct_answer": "节约用水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块手表每天都节约用水。", "explanation": "这里应该用〈走〉。手表不用水，“节约用水”不能用于手表；说手表的运行要用“走”。"}, {"text": "这台空调每天都节约用水。", "explanation": "这里应该用〈省电〉。空调不用水，“节约用水”不能用于空调；说减少用电要用“省电”。"}, {"text": "这个煤气灶每天都节约用水。", "explanation": "这里应该用〈省气〉。煤气灶用的是煤气，不是水；说减少用气要用“省气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区水费很高，物业要求住户节约用水电。", "corrected_sentence": "这个小区水费很高，物业要求住户节约用水。", "error_description": "错误：“节约用水电”；正确：“节约用水”。“节约用水”已经是完整的动宾短语，后面不能再加“电”。如果要同时说水和电，应说“节约水电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的学生从小就被节约用水。", "corrected_sentence": "这所学校的学生从小就节约用水。", "error_description": "错误：“被节约用水”；正确：“节约用水”。“节约用水”是学生自己主动的行为，学生是施事，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
