INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25184, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一件事物从一个人传给另一个人，再传给下一个人，一直传下去。", "primary_collocate": null, "pronunciation": "dài dài xiāng chuán", "ipa": "taɪ˥˩ taɪ˥˩ ɕjaŋ˥ ʈʂʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "这块玉是我们家的宝贝，要代代相传下去。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个戒指从奶奶传给妈妈，再传给我，代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老菜谱在我们家代代相传，谁也不告诉别人。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的旧椅子在我们家代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个秘方不能给别人，只能在家里代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子是祖先盖的，我们要让它代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老人说，这块手表是代代相传的东西。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本旧书从爷爷传到爸爸，再传给我，就是代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片在我们家代代相传，已经很旧了。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把妈妈的银镯子留给女儿，希望能代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一件事物从一个人传给下一个人，一直传下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代代相传", "is_correct": true, "explanation": "正确：强调东西一代代往下传，与“要……下去”和家传宝贝的语境相符。"}, {"text": "失传", "is_correct": false, "explanation": "语义：“失传”指不再流传、丢失，与“要……下去”的意愿相反。"}, {"text": "变卖", "is_correct": false, "explanation": "语义：“变卖”指把东西卖掉，与“宝贝”以及家中一直保存的语境冲突。"}, {"text": "消化", "is_correct": false, "explanation": "搭配：“消化”的对象是食物或知识，不能用于玉这类宝贝。"}], "explanations": {"代代相传": "正确：强调东西一代代往下传，与“要……下去”和家传宝贝的语境相符。", "失传": "语义：“失传”指不再流传、丢失，与“要……下去”的意愿相反。", "变卖": "语义：“变卖”指把东西卖掉，与“宝贝”以及家中一直保存的语境冲突。", "消化": "搭配：“消化”的对象是食物或知识，不能用于玉这类宝贝。"}, "sentence_index": 0, "correct_answer": "代代相传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师一节课就把这门技术代代相传给学生。", "explanation": "这里应该用〈传授〉。代代相传指经过世代往下传，一节课内教完要用〈传授〉。"}, {"text": "这条新闻很快就在网上代代相传。", "explanation": "这里应该用〈传播〉。代代相传强调经过世代往下传，消息在网上迅速扩散要用〈传播〉。"}, {"text": "我把这份材料代代相传给领导。", "explanation": "这里应该用〈递交〉。代代相传用于世代相承的东西，把材料交给领导要用〈递交〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代代相传", "is_correct": true, "explanation": "正确：表示这块手表经过多代传下来，与“东西”搭配自然。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”的对象是燃料、资源等会被用完的东西，手表不会被消耗。"}, {"text": "食用", "is_correct": false, "explanation": "搭配：“食用”只用于能吃的东西，手表不能食用。"}, {"text": "流动", "is_correct": false, "explanation": "语义：“流动”描述液体、人群等移动的状态，与手表这件物品不符。"}], "explanations": {"代代相传": "正确：表示这块手表经过多代传下来，与“东西”搭配自然。", "消耗": "搭配：“消耗”的对象是燃料、资源等会被用完的东西，手表不会被消耗。", "食用": "搭配：“食用”只用于能吃的东西，手表不能食用。", "流动": "语义：“流动”描述液体、人群等移动的状态，与手表这件物品不符。"}, "sentence_index": 6, "correct_answer": "代代相传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这家小店代代相传给了朋友。", "explanation": "这里应该用〈转让〉。代代相传指经过多代往下传，一次性把店卖给朋友要用〈转让〉。"}, {"text": "父亲去世后，他一个人代代相传了全部财产。", "explanation": "这里应该用〈继承〉。代代相传指经过多代传承，某个人一次接收全部财产要用〈继承〉。"}, {"text": "奶奶每晚都给我代代相传睡前故事。", "explanation": "这里应该用〈讲述〉。代代相传用于世代传下来的东西，每晚讲故事要用〈讲述〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份手艺已经代代代相传了好几百年。", "corrected_sentence": "这份手艺已经代代相传了好几百年。", "error_description": "“代代相传”是固定的四字词，前面不能多加一个“代”。写成“代代代相传”不成词，正确形式是“代代相传”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些古书是家族里代代相传宝物。", "corrected_sentence": "这些古书是家族里代代相传的宝物。", "error_description": "“代代相传”修饰名词时要加“的”，应说“代代相传的宝物”。漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
