INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把种子放在土里，会长出新的植物。", "primary_collocate": null, "pronunciation": "zhòng", "ipa": "ʈʂʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我想在院子里种一些西瓜。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在花盆里种了向日葵。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门前种了两排杨树。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在后院种黄瓜和西红柿。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在学校的花园里种花。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地很好，种什么都能长。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天天气凉，适合种白菜。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用小铲子在土里种了几棵小树。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家没有地，只能在箱子里种菜。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山边种了一片竹子。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种了", "label": "体标"}, {"form": "种过", "label": "体标"}, {"form": "种着", "label": "体标"}], "register": "中性", "sense_fingerprint": "种（zhòng）：把种子放进土里，让新的植物长出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 小明 (Zipf 3.37), 花盆 (Zipf 3.02), 向日葵 (Zipf 3.36)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 后院 (Zipf 3.73), 黄瓜 (Zipf 3.64), 西红柿 (Zipf 3.59)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 铲 (Zipf 3.76), 棵 (Zipf 3.72), 小树 (Zipf 3.2)']::text[], '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25186, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种", "is_correct": true, "explanation": "zhòng 指把种子放进土里，让植物长出来，是本词的读音和意思。"}, {"text": "中", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，中指中间，与栽种无关。"}, {"text": "证", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是证明、证件。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhòng 韵母不同（ang 与 ong），意思是账目。"}, {"text": "政", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是政治、政府。"}], "explanations": {"种": "zhòng 指把种子放进土里，让植物长出来，是本词的读音和意思。", "中": "zhōng（第一声）与 zhòng（第四声）声调不同，中指中间，与栽种无关。", "证": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是证明、证件。", "账": "zhàng 与 zhòng 韵母不同（ang 与 ong），意思是账目。", "政": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是政治、政府。"}, "sentence_index": null, "correct_answer": "种"}, "level_3": {"options": [{"text": "种", "is_correct": true, "explanation": "种：此处是动词，“种一垄西瓜”指在院子里栽种西瓜。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的宾语是房屋、道路等，不能说修西瓜。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”的对象是建筑或物件，与“西瓜”不相干，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是液体，西瓜不能喝，句子不成立。"}], "explanations": {"种": "种：此处是动词，“种一垄西瓜”指在院子里栽种西瓜。", "修": "搭配：“修”的宾语是房屋、道路等，不能说修西瓜。", "拆": "语义：“拆”的对象是建筑或物件，与“西瓜”不相干，句意不通。", "喝": "搭配：“喝”的宾语是液体，西瓜不能喝，句子不成立。"}, "sentence_index": 0, "correct_answer": "种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶在后院种了两只鸡。", "explanation": "这里应该用〈养〉。种用于栽植植物，养用于鸡等动物。"}, {"text": "他们在后院种了一间小屋。", "explanation": "这里应该用〈建〉。种指栽植，建造房屋要说“建”或“盖”。"}, {"text": "妈妈在厨房种了一锅粥。", "explanation": "这里应该用〈煮〉。种指栽植，煮粥要说“煮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25186, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "种", "is_correct": true, "explanation": "zhòng 指把种子放进土里，让植物长出来，是本词的读音和意思。"}, {"text": "钟", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，钟指时钟。"}, {"text": "正", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同，意思是正确、正在。"}, {"text": "肿", "is_correct": false, "explanation": "zhǒng 与 zhòng 仅声调不同（第三声与第四声）；肿指浮肿，与栽种无关。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhòng 仅元音不同（a 与 o）；账指账目。"}], "explanations": {"种": "zhòng 指把种子放进土里，让植物长出来，是本词的读音和意思。", "钟": "zhōng（第一声）与 zhòng（第四声）声调不同，钟指时钟。", "正": "zhèng 与 zhòng 韵母不同，意思是正确、正在。", "肿": "zhǒng 与 zhòng 仅声调不同（第三声与第四声）；肿指浮肿，与栽种无关。", "账": "zhàng 与 zhòng 仅元音不同（a 与 o）；账指账目。"}, "sentence_index": null, "correct_answer": "种"}, "level_3": {"options": [{"text": "种", "is_correct": true, "explanation": "种：此处是动词，“适合种白菜”指适合栽种白菜，与秋天的气候相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣服、鞋帽，白菜不能穿。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的宾语是车、马等，不能说骑白菜。"}, {"text": "戴", "is_correct": false, "explanation": "语义：“戴”指戴在头、脸、手等处，与“白菜”不相干，句意不通。"}], "explanations": {"种": "种：此处是动词，“适合种白菜”指适合栽种白菜，与秋天的气候相合。", "穿": "搭配：“穿”的宾语是衣服、鞋帽，白菜不能穿。", "骑": "搭配：“骑”的宾语是车、马等，不能说骑白菜。", "戴": "语义：“戴”指戴在头、脸、手等处，与“白菜”不相干，句意不通。"}, "sentence_index": 6, "correct_answer": "种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在山边种了一座桥。", "explanation": "这里应该用〈架〉。种用于栽植植物，架桥要说“架”。"}, {"text": "他们在山边种了一条路。", "explanation": "这里应该用〈修〉。种指栽植，修路要说“修”。"}, {"text": "他们在山边种了一条沟。", "explanation": "这里应该用〈挖〉。种指栽植，挖沟要说“挖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在门前种了下两排杨树。", "corrected_sentence": "他在门前种下了两排杨树。", "error_description": "补语“下”必须紧接动词，应说“种下了”，不能说“种了下”。错误：“种了下”。正确：“种下了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山边种得一片竹子。", "corrected_sentence": "他们在山边种着一片竹子。", "error_description": "“种”后面接“得”引出补语，但这里没有补语，应该用“着”表示动作持续的状态。错误：“种得一片竹子”。正确：“他们在山边种着一片竹子。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
