INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情的方法。", "primary_collocate": null, "pronunciation": "zuò fǎ", "ipa": "tswo˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这道菜的做法很简单。", "target_word": "做法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的做法不对，应该先问老师。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不同意他的做法。", "target_word": "做法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "解决这个问题还有别的做法吗？", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的做法会浪费很多时间。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法让大家都很生气。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你告诉我这道汤的做法。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这种做法不太安全。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人的做法都不一样。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把问题放到一边，这种做法不好。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "做事或做菜时所用的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd295e12-7231-4a6a-a8ef-075f24fccda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做法", "is_correct": true, "explanation": "“做法”指做这道菜的方法，句中“很简单”描述的正是做菜的步骤，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“简单”可以形容做法或步骤，但不能用来形容价格。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”只能说高低，不能说“很简单”。"}, {"text": "分量", "is_correct": false, "explanation": "语义：“分量”指食物的多少，与句中“很简单”所描述的内容无关。"}], "explanations": {"做法": "“做法”指做这道菜的方法，句中“很简单”描述的正是做菜的步骤，符合语境。", "价格": "搭配：“简单”可以形容做法或步骤，但不能用来形容价格。", "温度": "搭配：“温度”只能说高低，不能说“很简单”。", "分量": "语义：“分量”指食物的多少，与句中“很简单”所描述的内容无关。"}, "sentence_index": 0, "correct_answer": "做法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的做法很开朗，每天都笑呵呵的。", "explanation": "这里应该用〈性格〉。做法指做事的方式，不能用来形容人的性格或情绪。"}, {"text": "我有个做法，我们周末去爬山吧。", "explanation": "这里应该用〈主意〉。做法指做事的方式，提出建议时要说〈主意〉。"}, {"text": "这把椅子的做法很高，我坐不上去。", "explanation": "这里应该用〈高度〉。做法指做事的方式，不能用来说椅子的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做法", "is_correct": true, "explanation": "“做法”指做汤的方法，询问“这道汤的做法”符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物存在的时间，汤没有年龄。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”用于人的性情，不能说一道汤的性格。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或动物的高矮，汤没有身高。"}], "explanations": {"做法": "“做法”指做汤的方法，询问“这道汤的做法”符合句意。", "年龄": "语义：“年龄”指人或生物存在的时间，汤没有年龄。", "性格": "搭配：“性格”用于人的性情，不能说一道汤的性格。", "身高": "语义：“身高”指人或动物的高矮，汤没有身高。"}, "sentence_index": 6, "correct_answer": "做法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在话剧里演了一个做法。", "explanation": "这里应该用〈角色〉。做法指做事的方式，不能指人物。"}, {"text": "我的做法叫小红。", "explanation": "这里应该用〈名字〉。做法是抽象的方式，不能用“叫”来称呼。"}, {"text": "他做法很大，常常发脾气。", "explanation": "这里应该用〈脾气〉。做法指方式，不能用来形容人的性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他换了一只新做法。", "corrected_sentence": "他换了一种新做法。", "error_description": "错误：“做法”前的量词用了“只”。正确：应用“种”或“个”，因为“只”不用于做法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他采用了几种新做法们。", "corrected_sentence": "他采用了几种新做法。", "error_description": "错误：“做法”后加了复数词尾“们”。正确：“做法”指事物，不能加“们”，应说“几种新做法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
