INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪大、有经验的一代人，比如爷爷奶奶那一辈。", "primary_collocate": null, "pronunciation": "lǎo yí bèi", "ipa": "lɑʊ˨˩˦ i˧˥ peɪ˥˩", "syllable_count": 3, "sentences": [{"text": "我们家的老一辈都住在乡下。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈有经验，我们应该向他们学习。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听听老一辈的经验。", "target_word": "老一辈", "complexity_tier": "T3", "furigana": "wǒ xiǎng tīng tīng lǎo yí bèi de jīng yàn.", "sentence_source": "generated"}, {"text": "老一辈的人喜欢早睡早起。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜是老一辈教给我的。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听老一辈说，以前这里没有路。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈走过很长的路，知道很多事。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是老一辈，说话慢，心很好。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈的人常常把钱存起来。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，我们陪老一辈去公园走走。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "年纪大、有经验的一代人，爷爷奶奶那一辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老一辈", "is_correct": true, "explanation": "正确：老一辈是家里的长辈，住在乡下符合语境。"}, {"text": "同学", "is_correct": false, "explanation": "搭配：“我们家的”后面要接家庭成员，同学不属于家里。"}, {"text": "老板", "is_correct": false, "explanation": "搭配：老板是工作关系，不能说“我们家的老板”。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：外星人不住在乡下，句子与常识不符。"}], "explanations": {"老一辈": "正确：老一辈是家里的长辈，住在乡下符合语境。", "同学": "搭配：“我们家的”后面要接家庭成员，同学不属于家里。", "老板": "搭配：老板是工作关系，不能说“我们家的老板”。", "外星人": "语义：外星人不住在乡下，句子与常识不符。"}, "sentence_index": 0, "correct_answer": "老一辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家刚出生的小弟弟是老一辈。", "explanation": "这里应该用〈晚辈〉。老一辈指年长的一代，刚出生的弟弟是晚辈。"}, {"text": "我的老一辈都是95后。", "explanation": "这里应该用〈晚辈〉。老一辈指年长的一代，95后属于晚辈，不能算老一辈。"}, {"text": "我们家的老一辈今年才上小学。", "explanation": "这里应该用〈小孩子〉。老一辈指爷爷奶奶那一代年长的人，刚上小学的是小孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老一辈", "is_correct": true, "explanation": "正确：老一辈是年长的一代，“走过很长的路，知道很多事”符合其特点。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会走路，也没有经历，句意不通。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩没有走过很长的路，也不会知道很多事。"}, {"text": "婴儿", "is_correct": false, "explanation": "体貌：婴儿还不能走路，与“走过很长的路”矛盾。"}], "explanations": {"老一辈": "正确：老一辈是年长的一代，“走过很长的路，知道很多事”符合其特点。", "电脑": "语义：电脑不会走路，也没有经历，句意不通。", "小孩": "语义：小孩没有走过很长的路，也不会知道很多事。", "婴儿": "体貌：婴儿还不能走路，与“走过很长的路”矛盾。"}, "sentence_index": 6, "correct_answer": "老一辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末，我们陪幼儿园的老一辈去公园走走。", "explanation": "这里应该用〈小朋友〉。老一辈指年纪大的一代人，幼儿园里的是小朋友。"}, {"text": "周末，我们陪年轻的老一辈去公园走走。", "explanation": "这里应该用〈年轻人〉。老一辈指年纪大的一代，不能用“年轻”修饰。"}, {"text": "周末，我们陪老一辈的小狗去公园走走。", "explanation": "这里应该用〈老狗〉。老一辈指年长的人群，不能用来指小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是很老一辈的人，很有经验。", "corrected_sentence": "他是老一辈的人，很有经验。", "error_description": "“老一辈”是名词，不能被“很”修饰。应说“老一辈的人”，不能说“很老一辈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷是很老一辈，懂得很多事。", "corrected_sentence": "爷爷是老一辈，懂得很多事。", "error_description": "“老一辈”是名词，前面不能加“很”。错误：“很老一辈”。正确：“爷爷是老一辈，懂得很多事。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
