INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到问题后想办法解决它。", "primary_collocate": null, "pronunciation": "yìng duì", "ipa": "iŋ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "遇到突然的变化，我们要冷静应对。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对考试压力，他用运动来应对。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样应对紧张的面试。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会应对各种突发的问题。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对客人的投诉，服务员耐心地应对。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风快来了，居民提前买好食物应对。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道该怎么应对这么难的情况。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着应对了记者所有的问题。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中有压力，要学会自己应对。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没应对过这样的麻烦。", "target_word": "应对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应对了", "label": "体标"}, {"form": "应对过", "label": "体标"}, {"form": "应对措施", "label": "复合"}], "register": "中性", "sense_fingerprint": "遇到问题或变化时想办法处理、解决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应对", "is_correct": true, "explanation": "正确：“应对”表示想办法处理变化，与“我们要冷静___”相符。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：遇到变化不能靠“欢呼”来处理，句意不通。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是为喜事而做的活动，与“冷静”的态度相冲突。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“冷静”与“哭泣”相互矛盾，句意不通。"}], "explanations": {"应对": "正确：“应对”表示想办法处理变化，与“我们要冷静___”相符。", "欢呼": "语义：遇到变化不能靠“欢呼”来处理，句意不通。", "庆祝": "语义：“庆祝”是为喜事而做的活动，与“冷静”的态度相冲突。", "哭泣": "语义：“冷静”与“哭泣”相互矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "应对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会应对美丽的画。", "explanation": "这里应该用〈欣赏〉。“应对”指处理问题、应付情况，看画、赏画要说“欣赏”。"}, {"text": "她很会应对这首老歌。", "explanation": "这里应该用〈唱〉。“应对”指处理问题、应付情况，唱歌要说“唱”，不能说应对。"}, {"text": "他很会应对精致的蛋糕。", "explanation": "这里应该用〈制作〉。“应对”不用于做东西，做蛋糕要说“制作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应对", "is_correct": true, "explanation": "正确：“应对”表示处理困难的情况，与“这么难的情况”相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象多是人或活动，不说欢迎情况。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指欣赏美好的事物，用于困难的情况句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声表演，无法用来处理情况。"}], "explanations": {"应对": "正确：“应对”表示处理困难的情况，与“这么难的情况”相符。", "欢迎": "搭配：“欢迎”的对象多是人或活动，不说欢迎情况。", "欣赏": "语义：“欣赏”指欣赏美好的事物，用于困难的情况句意不通。", "唱": "语义：“唱”是发声表演，无法用来处理情况。"}, "sentence_index": 6, "correct_answer": "应对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里应对了一桌好菜。", "explanation": "这里应该用〈做〉。“应对”指处理问题、应付情况，做饭菜要说“做”。"}, {"text": "工人们在车间里应对了一块木板。", "explanation": "这里应该用〈加工〉。“应对”不用于加工物件，加工木板要说“加工”。"}, {"text": "奶奶在院子里应对了一件毛衣。", "explanation": "这里应该用〈织〉。“应对”不用于织毛衣，织毛衣要说“织”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都应对过突发的问题。", "corrected_sentence": "他每天都应对突发的问题。", "error_description": "体标误用：“过”表示曾经有过的经历，不能用于“每天”这类习惯性的时间状语；表示习惯应直接用动词，应为“每天都应对突发的问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，他曾经应对着很多次危机。", "corrected_sentence": "这些年，他曾经应对过很多次危机。", "error_description": "动态助词误用：“曾经”表示经历，应与“过”搭配，“着”表示持续，两者不能搭配。正确应为“应对过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "活", "is_correct": true, "explanation": "正确：“活”与“死”相对，指还有生命。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”是快速移动，与“死”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”是进食，与“死”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”是发出声音的动作，与“死”没有反义关系。"}], "correct_answer": "活", "explanations": {"活": "正确：“活”与“死”相对，指还有生命。", "跑": "“跑”是快速移动，与“死”没有反义关系。", "吃": "“吃”是进食，与“死”没有反义关系。", "唱": "“唱”是发出声音的动作，与“死”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "活", "is_correct": true, "explanation": "正确：“活”与“死”相对，指还有生命。"}, {"text": "走", "is_correct": false, "explanation": "“走”是移动，与“死”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”是入睡的动作，与“死”没有反义关系。"}, {"text": "哭", "is_correct": false, "explanation": "“哭”是流泪发声的动作，与“死”没有反义关系。"}], "correct_answer": "活", "explanations": {"活": "正确：“活”与“死”相对，指还有生命。", "走": "“走”是移动，与“死”没有反义关系。", "睡": "“睡”是入睡的动作，与“死”没有反义关系。", "哭": "“哭”是流泪发声的动作，与“死”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或动物没有生命了。", "primary_collocate": null, "pronunciation": "sǐ", "ipa": "sɹ̩˨˩˦", "syllable_count": 1, "sentences": [{"text": "那条鱼死了。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的小狗昨天死了。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟没有吃的，就会死。", "target_word": "死", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多动物因为冬天太冷而死。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爷爷死的时候，我才五岁。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只猫看起来死了，其实只是睡着了。", "target_word": "死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他不会死，只是受了伤。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "池塘里的鱼都死了，大家很难过。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗老了，可能很快就会死。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争中，很多人死了，也有很多人受伤。", "target_word": "死", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "死了", "label": "体标（了）"}, {"form": "死过", "label": "体标（过）"}, {"form": "死掉", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，指人或动物失去生命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死", "is_correct": true, "explanation": "正确：“死”读 sǐ（第三声），指人或动物没有了生命。"}, {"text": "四", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，意思是数字“四”。"}, {"text": "思", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）声调不同，意思是“思考”。"}, {"text": "使", "is_correct": false, "explanation": "shǐ 与 sǐ 声母不同（sh 与 s），意思是“让、叫”。"}], "explanations": {"死": "正确：“死”读 sǐ（第三声），指人或动物没有了生命。", "四": "sì（第四声）与 sǐ（第三声）声调不同，意思是数字“四”。", "思": "sī（第一声）与 sǐ（第三声）声调不同，意思是“思考”。", "使": "shǐ 与 sǐ 声母不同（sh 与 s），意思是“让、叫”。"}, "sentence_index": null, "correct_answer": "死"}, "level_3": {"options": [{"text": "死", "is_correct": true, "explanation": "正确：“死”表示鱼失去生命，与“那条鱼……了”相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字，鱼不能写，句子不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”要有能修理的对象，“鱼”不能被修，这里不搭。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”的对象是文字，鱼不能读，句子不通。"}], "explanations": {"死": "正确：“死”表示鱼失去生命，与“那条鱼……了”相符。", "写": "语义：“写”的对象是文字，鱼不能写，句子不通。", "修": "搭配：“修”要有能修理的对象，“鱼”不能被修，这里不搭。", "读": "语义：“读”的对象是文字，鱼不能读，句子不通。"}, "sentence_index": 0, "correct_answer": "死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那块石头昨天死了。", "explanation": "这里应该用〈碎〉。“死”只用于有生命的人、动物或植物，石头不能说死，应说“那块石头昨天碎了”。"}, {"text": "这块面包死了。", "explanation": "这里应该用〈馊〉。“死”只指生命结束，面包变质应说“这块面包馊了”。"}, {"text": "这张桌子昨天死了。", "explanation": "这里应该用〈坏〉。“死”只用于有生命的人或动物，桌子不能说死，应说“这张桌子坏了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "死", "is_correct": true, "explanation": "正确：“死”读 sǐ（第三声），指人或动物没有了生命。"}, {"text": "始", "is_correct": false, "explanation": "shǐ 与 sǐ 声母不同（sh 与 s），意思是“开始”。"}, {"text": "私", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）声调不同，意思是“私人的”。"}, {"text": "似", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，意思是“相像”。"}], "explanations": {"死": "正确：“死”读 sǐ（第三声），指人或动物没有了生命。", "始": "shǐ 与 sǐ 声母不同（sh 与 s），意思是“开始”。", "私": "sī（第一声）与 sǐ（第三声）声调不同，意思是“私人的”。", "似": "sì（第四声）与 sǐ（第三声）声调不同，意思是“相像”。"}, "sentence_index": null, "correct_answer": "死"}, "level_3": {"options": [{"text": "死", "is_correct": true, "explanation": "正确：“不会死”指不会失去生命，与“只是受了伤”相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”只用于水等液体，人不会结冰，句子不通。"}, {"text": "分类", "is_correct": false, "explanation": "搭配：“分类”需要有分类的对象，这里与“只是受了伤”不搭。"}, {"text": "放大", "is_correct": false, "explanation": "语义：“放大”指扩大，与“只是受了伤”的意思无关，句子不通。"}], "explanations": {"死": "正确：“不会死”指不会失去生命，与“只是受了伤”相符。", "结冰": "语义：“结冰”只用于水等液体，人不会结冰，句子不通。", "分类": "搭配：“分类”需要有分类的对象，这里与“只是受了伤”不搭。", "放大": "语义：“放大”指扩大，与“只是受了伤”的意思无关，句子不通。"}, "sentence_index": 6, "correct_answer": "死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试死了两门。", "explanation": "这里应该用〈挂〉。“死”指生命结束，不能用来说考试不及格，应说“他这次考试挂了两门”。"}, {"text": "我为了赶作业，整晚都死了。", "explanation": "这里应该用〈熬〉。“死”不能用来形容熬夜，应说“我为了赶作业，整晚都熬着”。"}, {"text": "炉子里的火死了。", "explanation": "这里应该用〈灭〉。“死”只用于有生命的东西，火不能说死，应说“炉子里的火灭了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只老猫昨天了死。", "corrected_sentence": "那只老猫昨天死了。", "error_description": "语序错误：“了”要放在动词“死”的后面，应说“死了”，写成“了死”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的狗死老了。", "corrected_sentence": "他的狗老死了。", "error_description": "语序错误：“老死”是“老”修饰“死”，表示年老而死，应说“老死了”；“死老了”把“死”和“老”的顺序颠倒了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
