INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25198, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住在那个地方的人。", "primary_collocate": null, "pronunciation": "dāng dì rén", "ipa": "tɑŋ˥˥ ti˥˩ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "他不是外国人，是当地人。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，您是当地人吗？", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人比我们更了解这座山。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人每天早上都去公园走路。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的当地人不多。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个当地人做朋友。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人告诉我们哪家饭馆好吃。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人的房子都很旧。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是当地人，所以说话有口音。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客走了以后，当地人又回到海边。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位当地人", "label": "量词"}], "register": "中性", "sense_fingerprint": "住在所说地方的人，相对外来者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当地人", "is_correct": true, "explanation": "正确：“当地人”指住在该地的人，与“外国人”相对，符合“不是外国人，是当地人”的语境。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”不是人，不能作“是”之后表示身份的成分，与前半句的人群对比不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的物体，不能用来表示人的身份。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“是……”表示身份的判断句要求人作为对象，“空气”不能表示人的身份。"}], "explanations": {"当地人": "正确：“当地人”指住在该地的人，与“外国人”相对，符合“不是外国人，是当地人”的语境。", "动物": "语义：“动物”不是人，不能作“是”之后表示身份的成分，与前半句的人群对比不符。", "石头": "语义：“石头”是无生命的物体，不能用来表示人的身份。", "空气": "配价：“是……”表示身份的判断句要求人作为对象，“空气”不能表示人的身份。"}, "sentence_index": 0, "correct_answer": "当地人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一本当地人，很会讲故事。", "explanation": "“本”用于书籍，指人要用“位”或“个”，应说“一位当地人”。"}, {"text": "这些当地人刚来这里，还不习惯。", "explanation": "这里应该用〈外地人〉。“当地人”指长期住在该地的人，刚来的人应说“外地人”。"}, {"text": "他会说一口流利的当地人。", "explanation": "这里应该用〈当地话〉。“当地人”指人，说语言要用“当地话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当地人", "is_correct": true, "explanation": "正确：“当地人”了解本地饭馆，能够告诉我们哪家好吃，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "配价：“告诉”需要有言语能力的施事，“猫”不能作施事。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不能告诉别人信息，与句意冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是无生命的物体，不能提供饭馆的推荐。"}], "explanations": {"当地人": "正确：“当地人”了解本地饭馆，能够告诉我们哪家好吃，符合句意。", "猫": "配价：“告诉”需要有言语能力的施事，“猫”不能作施事。", "桌子": "语义：“桌子”不能告诉别人信息，与句意冲突。", "窗户": "语义：“窗户”是无生命的物体，不能提供饭馆的推荐。"}, "sentence_index": 6, "correct_answer": "当地人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于来到了当地人。", "explanation": "这里应该用〈那座小镇〉。“当地人”指人，不能表示到达的地点；到达的地方应说“那座小镇”之类。"}, {"text": "这家当地人很好吃。", "explanation": "这里应该用〈饭馆〉。“当地人”指人，不能用来形容饭馆的味道；应说“这家饭馆很好吃”。"}, {"text": "我们一起去当地人旅游了。", "explanation": "这里应该用〈外地〉。“当地人”指人，不能充当去旅游的地点；应说“去外地旅游”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座村子地当地人很热情。", "corrected_sentence": "这座村子的当地人很热情。", "error_description": "错误形式：“村子地当地人”。正确形式：“村子的当地人”。修饰名词“当地人”要用“的”，“地”只用于修饰动词、形容词作状语，不能用于名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只当地人很热情，带我们去了老城。", "corrected_sentence": "那位当地人很热情，带我们去了老城。", "error_description": "错误形式：“那只当地人”。正确形式：“那位当地人”。“当地人”指人，量词应用“位”，“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
