INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25200, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "表示过了很久的一段时间。", "primary_collocate": null, "pronunciation": "cháng shí jiān", "ipa": "ʈʂʰɑŋ˧˥ ʂɨ˧˥ tɕjɛn˥˥", "syllable_count": 3, "sentences": [{"text": "他长时间站在门口，一动也不动。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子长时间没人住，到处都是灰。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间不联系，他们变得很陌生。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过长时间的讨论，大家同意了。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长时间哭着，妈妈很着急。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机长时间不用，电量会慢慢减少。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长时间学习汉语，说得很好。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河长时间没有水了。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我长时间没吃中国菜了，真想吃。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间下雨，路上有很多水。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长时间地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "表示动作或状态持续了很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长时间", "is_correct": true, "explanation": "正确：“长时间”表示过了很久，与“一动也不动”的持续状态相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用表示从未发生，不能直接修饰“站在门口”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指不经常发生，与“一动也不动”的持续站立状态相矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急促地行动，与“一动也不动”的静止状态相矛盾。"}], "explanations": {"长时间": "正确：“长时间”表示过了很久，与“一动也不动”的持续状态相符。", "从来": "搭配：“从来”通常与否定词连用表示从未发生，不能直接修饰“站在门口”。", "偶尔": "语义：“偶尔”指不经常发生，与“一动也不动”的持续站立状态相矛盾。", "赶紧": "语义：“赶紧”表示急促地行动，与“一动也不动”的静止状态相矛盾。"}, "sentence_index": 0, "correct_answer": "长时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长时间地眨了一下眼睛。", "explanation": "这里应该用〈短暂〉。“长时间”指持续很久，眨眼只是瞬间的动作，二者的时间跨度不相称。"}, {"text": "我长时间就解决了这个问题。", "explanation": "这里应该用〈很快〉。“就……解决了”表示迅速完成，“长时间”表示持续很久，二者不能搭配。"}, {"text": "他长时间打了个招呼就走了。", "explanation": "这里应该用〈匆匆〉。“匆匆”表示时间很短、动作急促，与“打个招呼”的短暂动作相合；“长时间”指持续很久，不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长时间", "is_correct": true, "explanation": "正确：“长时间”表示持续很久，与“学习汉语很久，说得很好”的过程相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上，学好汉语并说得很好需要长期积累，不能立刻完成。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指事情忽然发生，与持续学习的过程相矛盾。"}, {"text": "忽地", "is_correct": false, "explanation": "语域：“忽地”带有书面、文学色彩，与日常口语的叙述不协调。"}], "explanations": {"长时间": "正确：“长时间”表示持续很久，与“学习汉语很久，说得很好”的过程相符。", "立刻": "语义：“立刻”指马上，学好汉语并说得很好需要长期积累，不能立刻完成。", "突然": "语义：“突然”指事情忽然发生，与持续学习的过程相矛盾。", "忽地": "语域：“忽地”带有书面、文学色彩，与日常口语的叙述不协调。"}, "sentence_index": 6, "correct_answer": "长时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我长时间地吃了一口饭，就放下碗走了。", "explanation": "这里应该用〈只〉。吃一口饭只需很短的时间，应说“我只吃了一口饭”；“长时间”表示持续很久，不适用。"}, {"text": "他长时间地看了一眼窗外，又转过身去。", "explanation": "这里应该用〈匆匆〉。“看一眼”只需极短的时间，应说“匆匆看了一眼窗外”；“长时间”表示持续很久，与之冲突。"}, {"text": "我长时间地喝了一杯咖啡，就去上班了。", "explanation": "这里应该用〈匆匆〉。喝一杯咖啡只需很短的时间，“长时间”表示持续很久，二者冲突；应说“匆匆喝了一杯咖啡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在门口站了长时间，腿都麻了。", "corrected_sentence": "他在门口站了很长时间，腿都麻了。", "error_description": "错误形式：“站了长时间”。正确形式：“站了很长时间”。表示过了很久的“长时间”前应加“很”，否则不是自然的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井长时间的没有人用了。", "corrected_sentence": "这口井长时间没有人用了。", "error_description": "错误：“这口井长时间的没有人用了”，状语“长时间”后多出“的”。正确：“这口井长时间没有人用了”，状语“长时间”后不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "植物能经受干旱，缺少水分也能正常生长。", "primary_collocate": null, "pronunciation": "nài hàn", "ipa": "nai˥˩ xan˥˩", "syllable_count": 2, "sentences": [{"text": "这种草很耐旱，一个月不下雨也不会死。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙人掌特别耐旱，所以沙漠里也能长。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说多肉植物耐旱，不用常浇水。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方雨少，农民喜欢种耐旱的作物。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树很耐旱，今年夏天没下雨也活着。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一盆耐旱的花放在办公室。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小米比水稻更耐旱，缺水的地方也能种。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花不耐旱，三天不浇水就枯了。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上种了很多耐旱的果树。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这种草耐旱，我们的院子正好需要。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐旱性", "label": "复合"}], "register": "中性", "sense_fingerprint": "植物不怕缺水能存活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐旱", "is_correct": true, "explanation": "正确：耐旱指植物不怕缺水，与“一个月不下雨也不会死”的语境相符。"}, {"text": "水嫩", "is_correct": false, "explanation": "语义：“水嫩”说水分充足，与“一个月不下雨也不会死”的干旱语境相悖。"}, {"text": "娇气", "is_correct": false, "explanation": "语义：“娇气”说娇弱难养，与“一个月不下雨也不会死”的韧性相悖。"}, {"text": "孱弱", "is_correct": false, "explanation": "语义：“孱弱”指瘦弱、没有力气，与“一个月不下雨也不会死”的韧性相悖；且语体偏书面。"}], "explanations": {"耐旱": "正确：耐旱指植物不怕缺水，与“一个月不下雨也不会死”的语境相符。", "水嫩": "语义：“水嫩”说水分充足，与“一个月不下雨也不会死”的干旱语境相悖。", "娇气": "语义：“娇气”说娇弱难养，与“一个月不下雨也不会死”的韧性相悖。", "孱弱": "语义：“孱弱”指瘦弱、没有力气，与“一个月不下雨也不会死”的韧性相悖；且语体偏书面。"}, "sentence_index": 0, "correct_answer": "耐旱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "南极的企鹅很耐旱，冬天在冰上也不怕。", "explanation": "这里应该用〈耐寒〉。耐旱指植物忍受干旱少雨，企鹅抵御的是严寒，不能说“耐旱”。"}, {"text": "这种芦苇很耐旱，长在湖边水里也能活。", "explanation": "这里应该用〈耐涝〉。耐旱是忍受缺水，长在水里的芦苇要用“耐涝”。"}, {"text": "这双鞋很耐旱，踩了泥也不怕。", "explanation": "这里应该用〈耐脏〉。耐旱只用于植物，鞋子抗污要说“耐脏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐旱", "is_correct": true, "explanation": "正确：耐旱指植物忍受缺水，与“缺水的地方也能种”的语境相符。"}, {"text": "水灵", "is_correct": false, "explanation": "语义：“水灵”说水分充足、鲜嫩，与“缺水的地方也能种”相悖。"}, {"text": "娇嫩", "is_correct": false, "explanation": "语义：“娇嫩”说娇弱，与“缺水的地方也能种”所表达的强韧相悖。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”多形容环境或空气，不用来形容谷物，且与“缺水”相矛盾。"}], "explanations": {"耐旱": "正确：耐旱指植物忍受缺水，与“缺水的地方也能种”的语境相符。", "水灵": "语义：“水灵”说水分充足、鲜嫩，与“缺水的地方也能种”相悖。", "娇嫩": "语义：“娇嫩”说娇弱，与“缺水的地方也能种”所表达的强韧相悖。", "潮湿": "搭配：“潮湿”多形容环境或空气，不用来形容谷物，且与“缺水”相矛盾。"}, "sentence_index": 6, "correct_answer": "耐旱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工人在大太阳下干活，很耐旱，一整天不歇也行。", "explanation": "这里应该用〈耐热〉。耐旱只说植物忍受缺水，人忍受高温要用“耐热”。"}, {"text": "这种钢管很耐旱，能承受很大的水压。", "explanation": "这里应该用〈耐压〉。耐旱指忍受缺水，承受水压要用“耐压”。"}, {"text": "这种容器很耐旱，装什么液体都不怕。", "explanation": "这里应该用〈耐腐蚀〉。耐旱只用于植物，容器抵抗各种液体的侵蚀要用“耐腐蚀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种草跟玉米耐旱，一个月不浇水也能活。", "corrected_sentence": "这种草比玉米耐旱，一个月不浇水也能活。", "error_description": "比较标记错误：比较耐旱程度要用“比”，不能用“跟”。应说“比玉米耐旱”，不说“跟玉米耐旱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种草最很耐旱，三天不浇水也没事。", "corrected_sentence": "这种草很耐旱，三天不浇水也没事。", "error_description": "程度副词重复：“最”和“很”不能同时修饰“耐旱”。应说“很耐旱”，不说“最很耐旱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
