INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种粮食的地。", "primary_collocate": null, "pronunciation": "nóng tián", "ipa": "nʊŋ˧˥ tʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这片农田每年能收很多粮食。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷家有三亩农田。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不能在农田上盖房子。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农田里的麦子熟了。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村子周围都是农田。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小在农田里帮父母干活。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的农田可以多产粮食。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的农田一片绿色。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府要保护农田，不让人乱用。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农田太干了，需要浇水。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "農田", "label": "繁体"}, {"form": "片", "label": "量词"}, {"form": "农田水利", "label": "复合"}], "register": "中性", "sense_fingerprint": "种粮食的土地，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：工厂不产粮食，“收很多粮食”只能用于种粮食的土地。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校与收粮食无关，句子说的是土地的产出。"}, {"text": "市场", "is_correct": false, "explanation": "搭配：市场可以卖粮食，但不说“收”粮食，“收”要用于田地。"}, {"text": "农田", "is_correct": true, "explanation": "农田是种粮食的地，这片地每年能收很多粮食，符合句意。"}], "explanations": {"工厂": "语义：工厂不产粮食，“收很多粮食”只能用于种粮食的土地。", "学校": "语义：学校与收粮食无关，句子说的是土地的产出。", "市场": "搭配：市场可以卖粮食，但不说“收”粮食，“收”要用于田地。", "农田": "农田是种粮食的地，这片地每年能收很多粮食，符合句意。"}, "sentence_index": 0, "correct_answer": "农田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的研究方向是农田。", "explanation": "这里应该用〈农业〉。农田指种粮食的地，研究方向要用农业。"}, {"text": "周末我们去农田里买新衣服。", "explanation": "这里应该用〈商场〉。农田是种粮食的地，买衣服要去商场。"}, {"text": "他每天在农田里练习游泳。", "explanation": "这里应该用〈游泳池〉。农田是种粮食的地，不是游泳的地方，练游泳要去游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行不产粮食，句子说的是土地的产出。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆与粮食产量无关，句子讲的是田地的收成。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“多产”用于土地和作物，不能用于医院。"}, {"text": "农田", "is_correct": true, "explanation": "农田是种粮食的地，好的农田才能多产粮食，符合句意。"}], "explanations": {"银行": "语义：银行不产粮食，句子说的是土地的产出。", "图书馆": "语义：图书馆与粮食产量无关，句子讲的是田地的收成。", "医院": "搭配：“多产”用于土地和作物，不能用于医院。", "农田": "农田是种粮食的地，好的农田才能多产粮食，符合句意。"}, "sentence_index": 6, "correct_answer": "农田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们一家住在一间农田里。", "explanation": "这里应该用〈农舍〉。农田是耕地，不是住的地方，住房要说农舍。"}, {"text": "这片农田结满了苹果。", "explanation": "这里应该用〈果园〉。苹果长在树上，种果树的地方要说果园，农田种的是庄稼。"}, {"text": "他每天都在干农田。", "explanation": "这里应该用〈农活〉。农田是土地，不是劳动，干的是农活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶家有五间农田。", "corrected_sentence": "奶奶家有五亩农田。", "error_description": "量词错误：“农田”按面积计量，应说“亩”，“间”只用于房屋。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民农田里收割麦子。", "corrected_sentence": "村民在农田里收割麦子。", "error_description": "介词缺失：表示地点的“农田”前要加“在”，应说“在农田里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
