INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种能长很高的粮食，可以做酒。", "primary_collocate": null, "pronunciation": "gāo liang", "ipa": "kɑʊ˥ liɑŋ", "syllable_count": 2, "sentences": [{"text": "高粱是一种能长得很高的粮食。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的田里，高粱已经比人高了。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们那里的人用高粱酿酒。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去地里收高粱了。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片高粱长得又高又直。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种红色的粮食是高粱，不是玉米。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高粱不怕干，雨少的地方也能种。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年我们家种了两亩高粱。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，高粱做的酒味道很重。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没见过高粱，以为是玉米。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一棵高粱", "label": "量词"}, {"form": "高粱酒", "label": "复合"}], "register": "中性", "sense_fingerprint": "长得很高可酿酒的粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高粱", "is_correct": true, "explanation": "正确：高粱是一种能长得很高的粮食，与句中的描述相符。"}, {"text": "竹子", "is_correct": false, "explanation": "语义：竹子是植物，但不是粮食，与“粮食”的语义相悖。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不是粮食，不能作为“粮食”的例子。"}, {"text": "高楼", "is_correct": false, "explanation": "搭配：“长得很高”说植物，高楼不会“长”，也不是粮食。"}], "explanations": {"高粱": "正确：高粱是一种能长得很高的粮食，与句中的描述相符。", "竹子": "语义：竹子是植物，但不是粮食，与“粮食”的语义相悖。", "大树": "语义：大树不是粮食，不能作为“粮食”的例子。", "高楼": "搭配：“长得很高”说植物，高楼不会“长”，也不是粮食。"}, "sentence_index": 0, "correct_answer": "高粱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在山坡上采高粱，装进竹篮里。", "explanation": "这里应该用〈茶叶〉。“采”多用于茶叶、花草、蘑菇；高粱要割，不说采高粱。"}, {"text": "这个工厂用高粱生产了一台机器。", "explanation": "这里应该用〈钢铁〉。高粱是农作物，不能用来制造机器。"}, {"text": "农民去地里挖高粱，准备过冬。", "explanation": "这里应该用〈红薯〉。“挖”用于土豆、红薯等根茎作物；高粱靠穗子收获，不说挖高粱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高粱", "is_correct": true, "explanation": "正确：高粱耐旱，与“不怕干，雨少的地方也能种”的语境相符。"}, {"text": "水稻", "is_correct": false, "explanation": "语义：水稻需水多，与“雨少的地方也能种”相悖。"}, {"text": "荷花", "is_correct": false, "explanation": "语义：荷花生在水里，不耐干，与“不怕干”相悖。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“不怕干”说植物或物品，鱼离不开水，不能这样说。"}], "explanations": {"高粱": "正确：高粱耐旱，与“不怕干，雨少的地方也能种”的语境相符。", "水稻": "语义：水稻需水多，与“雨少的地方也能种”相悖。", "荷花": "语义：荷花生在水里，不耐干，与“不怕干”相悖。", "鱼": "搭配：“不怕干”说植物或物品，鱼离不开水，不能这样说。"}, "sentence_index": 6, "correct_answer": "高粱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶在炕头用纺车纺高粱，织成了一块布。", "explanation": "这里应该用〈羊毛〉。“纺”用于棉、麻、毛等纤维，高粱不是纤维，不能纺。"}, {"text": "妈妈用高粱给小女儿织了一条围巾。", "explanation": "这里应该用〈毛线〉。“织”要用线，高粱不是线材，不能用来织围巾。"}, {"text": "奶奶用高粱给孙子缝了一件棉袄。", "explanation": "这里应该用〈棉布〉。“缝”用于布料，高粱不是布料，不能缝衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年叔叔在山坡上种了三杯高粱。", "corrected_sentence": "今年叔叔在山坡上种了三亩高粱。", "error_description": "量词错误：「三杯高粱」应为「三亩高粱」。说种了多少高粱要用面积量词〈亩〉，〈杯〉用于饮料。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片高粱长得很高粱，比人还高。", "corrected_sentence": "这片高粱长得很高，比人还高。", "error_description": "词类错误：“高粱”是名词，不能用在“很”后面作形容词，应说“长得很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
