INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地里长出来的、人们种来吃或用的东西。", "primary_collocate": null, "pronunciation": "zuò wù", "ipa": "tswɔ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "农民在地里种了很多作物。", "target_word": "作物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种作物喜欢多晒太阳。", "target_word": "作物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下大雨以后，地里的作物都长得很好。", "target_word": "作物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玉米是北方常见的作物。", "target_word": "作物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年天气太热，不少作物都死了。", "target_word": "作物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在山上种过很多作物。", "target_word": "作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地太干，不适合种这种作物。", "target_word": "作物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些作物一年能收两次。", "target_word": "作物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农民每天给作物浇水，还要拔草。", "target_word": "作物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们跟着爷爷去田里看作物。", "target_word": "作物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "农作物", "label": "复合"}, {"form": "粮食作物", "label": "复合"}, {"form": "经济作物", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "作物：田地里种出来的庄稼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作物", "is_correct": true, "explanation": "正确：作物是地里种出来的庄稼，“农民在地里种了很多”说的正是它。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“种”的对象是植物，不能说“种桌子”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车不能种在地里，“种汽车”不成立。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是叙述的内容，不是可以种在地里的东西。"}], "explanations": {"作物": "正确：作物是地里种出来的庄稼，“农民在地里种了很多”说的正是它。", "桌子": "搭配：“种”的对象是植物，不能说“种桌子”。", "汽车": "搭配：汽车不能种在地里，“种汽车”不成立。", "故事": "语义：故事是叙述的内容，不是可以种在地里的东西。"}, "sentence_index": 0, "correct_answer": "作物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林里有很多作物，但没有人种过它们。", "explanation": "这里应该用〈植物〉。作物指人种来吃或用的庄稼，没人种过的野生植物要说“植物”。"}, {"text": "我们家的院子里开满了作物。", "explanation": "这里应该用〈花〉。院子里开的是观赏花草，作物是用来收获的农作物，不说“开满了作物”。"}, {"text": "这位画家今年完成了一批新作物。", "explanation": "这里应该用〈作品〉。“作物”指人种来吃或用的庄稼，画家创作的画要说“作品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作物", "is_correct": true, "explanation": "正确：“这块地太干，不适合种这种作物”说的是不适合种植的庄稼。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“种”的对象是植物，玩具不能种在地里。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：电脑不能种在地里，“种这种电脑”不成立。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是可以种植的东西，与“这块地太干”的语境无关。"}], "explanations": {"作物": "正确：“这块地太干，不适合种这种作物”说的是不适合种植的庄稼。", "玩具": "搭配：“种”的对象是植物，玩具不能种在地里。", "电脑": "搭配：电脑不能种在地里，“种这种电脑”不成立。", "音乐": "语义：音乐不是可以种植的东西，与“这块地太干”的语境无关。"}, "sentence_index": 6, "correct_answer": "作物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天开作物去上班。", "explanation": "这里应该用〈汽车〉。作物是地里种出来的庄稼，不能开着去上班。"}, {"text": "妈妈在厨房里做了一盘作物。", "explanation": "这里应该用〈菜〉。作物指长在地里的庄稼，做好端上桌的叫“菜”。"}, {"text": "动物园里的作物都很可爱，孩子们喜欢喂它们。", "explanation": "这里应该用〈动物〉。作物是人种的植物，不是动物园里养的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些作物长很好。", "corrected_sentence": "这些作物长得很好。", "error_description": "程度补语：“长”和“很好”之间要加“得”，应说“长得很好”，不说“长很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民今年种了一座作物。", "corrected_sentence": "农民今年种了一种作物。", "error_description": "量词用错：“作物”的量词应用“种”，“座”用于房屋、桥梁等，不能修饰作物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。"}, {"text": "种植", "is_correct": false, "explanation": "不是反义：种植指栽培植物，与“修建”不构成反义。"}, {"text": "挖掘", "is_correct": false, "explanation": "不是反义：挖掘指掘开土地或矿藏，与“修建”不构成反义。"}, {"text": "粉刷", "is_correct": false, "explanation": "不是反义：粉刷指给墙面涂上涂料，与“修建”不构成反义。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。", "种植": "不是反义：种植指栽培植物，与“修建”不构成反义。", "挖掘": "不是反义：挖掘指掘开土地或矿藏，与“修建”不构成反义。", "粉刷": "不是反义：粉刷指给墙面涂上涂料，与“修建”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。"}, {"text": "装饰", "is_correct": false, "explanation": "不是反义：装饰指美化外观，与“修建”不构成反义。"}, {"text": "改造", "is_correct": false, "explanation": "不是反义：改造指改变原有的样子，与“修建”不构成反义。"}, {"text": "美化", "is_correct": false, "explanation": "不是反义：美化指使事物更美观，与“修建”不构成反义。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。", "装饰": "不是反义：装饰指美化外观，与“修建”不构成反义。", "改造": "不是反义：改造指改变原有的样子，与“修建”不构成反义。", "美化": "不是反义：美化指使事物更美观，与“修建”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建造房屋、道路、堤坝等工程设施。", "primary_collocate": null, "pronunciation": "xiū jiàn", "ipa": "ɕjoʊ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "工人们在村口修建一条新路。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校想在操场旁边修建一个体育馆。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥修建了三年才完成。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在山上修建了一座小房子。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了防洪，人们在河边修建了高高的堤坝。", "target_word": "修建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市正在修建第三条地铁。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在山坡上修建梯田种茶。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院门前修建了停车场，方便病人。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老城墙是五百年前修建的。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们打算在花园里修建一个小池塘。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "修建了", "label": "体标（了）"}, {"form": "修建过", "label": "体标（过）"}, {"form": "修建着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "盖房子、修路等建造", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8ad67b-239f-4a6f-82cc-ce442b51a334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": true, "explanation": "正确：“修建”指建造新路，符合句中“在村口修建一条新路”的语境。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：修路是建造工程，不是装饰。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：句中的“新路”是要建造的，不能说摧毁。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于栽培植物，不能用来指修一条新路。"}], "explanations": {"修建": "正确：“修建”指建造新路，符合句中“在村口修建一条新路”的语境。", "装饰": "语义：修路是建造工程，不是装饰。", "摧毁": "语义：句中的“新路”是要建造的，不能说摧毁。", "种植": "搭配：“种植”用于栽培植物，不能用来指修一条新路。"}, "sentence_index": 0, "correct_answer": "修建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的自行车坏了，要去修建。", "explanation": "这里应该用〈修理〉。把坏了的自行车弄好用“修理”，“修建”指建造建筑或道路。"}, {"text": "花匠正在修建花草。", "explanation": "这里应该用〈修剪〉。剪掉花草多余的部分用“修剪”，“修建”不用于花草。"}, {"text": "她花时间修建文章的语言。", "explanation": "这里应该用〈修饰〉。“修饰”指润色、使更好，“修建”不用于文章的语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修建", "is_correct": true, "explanation": "正确：“修建”指建造梯田，符合句中为了种茶而做的工程语境。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能说收割梯田。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：句中讲的是修好梯田后种茶，不是烧毁。"}, {"text": "毁坏", "is_correct": false, "explanation": "语义：毁坏梯田就无法在山坡上种茶，与句意矛盾。"}], "explanations": {"修建": "正确：“修建”指建造梯田，符合句中为了种茶而做的工程语境。", "收割": "搭配：“收割”的对象是庄稼，不能说收割梯田。", "烧毁": "语义：句中讲的是修好梯田后种茶，不是烧毁。", "毁坏": "语义：毁坏梯田就无法在山坡上种茶，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "修建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件瓷器碎了，需要修建。", "explanation": "这里应该用〈修复〉。瓷器损坏后要修复，“修建”指建造建筑或道路，不用于瓷器。"}, {"text": "老师帮我修建了作文。", "explanation": "这里应该用〈修改〉。修改文章用“修改”，“修建”只用于建筑、道路等工程。"}, {"text": "袜子破了，要修建。", "explanation": "这里应该用〈修补〉。缝补破损的衣物用“修补”，“修建”指建造新的建筑或道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校打算在操场旁边修建了一个新的体育馆。", "corrected_sentence": "学校打算在操场旁边修建一个新的体育馆。", "error_description": "“打算”表示尚未发生的计划，不能与“了”同用。“修建”后面应去掉“了”，说“打算在操场旁边修建一个新的体育馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市计划把修建第四条地铁。", "corrected_sentence": "这座城市计划修建第四条地铁。", "error_description": "“把”字要放在处置对象前，“计划把修建第四条地铁”不通，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
