INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山坡是山斜斜的那一面，像一个大滑梯。", "primary_collocate": null, "pronunciation": "shān pō", "ipa": "ʂan˥ pʰo˥", "syllable_count": 2, "sentences": [{"text": "孩子们坐在草地上，从山坡上滑下来。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡的草很软，孩子们在上面打滚。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛慢慢地走上山坡。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山的东边是平地，西边是山坡。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过山坡，草都弯下了腰。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家就在山坡下面。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的山坡绿绿的。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在山坡旁边。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上有一条小路通向村子。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天，我们在山坡上玩雪橇。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个山坡", "label": "量词"}, {"form": "一片山坡", "label": "量词"}], "register": "中性", "sense_fingerprint": "山倾斜的一面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山坡", "is_correct": true, "explanation": "山坡是山斜斜的一面，孩子们可以从上面滑下来，符合句意。"}, {"text": "平地", "is_correct": false, "explanation": "搭配：“滑下来”需要从斜面上滑落，“平地”没有坡度，不能从上面滑下来。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是可以滑行的地方，孩子不能从它上面滑下来。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以滑下来的地方，与“坐在草地上”的情境冲突。"}], "explanations": {"山坡": "山坡是山斜斜的一面，孩子们可以从上面滑下来，符合句意。", "平地": "搭配：“滑下来”需要从斜面上滑落，“平地”没有坡度，不能从上面滑下来。", "书包": "语义：书包不是可以滑行的地方，孩子不能从它上面滑下来。", "天空": "语义：天空不是可以滑下来的地方，与“坐在草地上”的情境冲突。"}, "sentence_index": 0, "correct_answer": "山坡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这座山坡装进了行李箱，带回了家。", "explanation": "这里应该用〈石头〉。山坡是大片固定的地形，不能装进行李箱，能装进去的只有石头之类。"}, {"text": "妈妈在山坡里炒了两个菜。", "explanation": "这里应该用〈锅〉。炒菜要用锅，山坡是山上斜的那一面，不能在里面炒菜。"}, {"text": "这道山坡很深，掉下去就找不到了。", "explanation": "这里应该用〈山谷〉。山坡是斜面，没有深度；说“很深”、“掉下去找不到”的是山谷或沟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山坡", "is_correct": true, "explanation": "山坡上长着草木，春天会绿绿的，符合句意。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“绿绿的”多用于草木、田野，雪一般不说绿。"}, {"text": "墨汁", "is_correct": false, "explanation": "语义：墨汁是黑色的，不会呈现绿绿的颜色，与句意不符。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是暗的，不会是绿绿的，句中的描述与夜晚不符。"}], "explanations": {"山坡": "山坡上长着草木，春天会绿绿的，符合句意。", "雪": "搭配：“绿绿的”多用于草木、田野，雪一般不说绿。", "墨汁": "语义：墨汁是黑色的，不会呈现绿绿的颜色，与句意不符。", "夜晚": "语义：夜晚是暗的，不会是绿绿的，句中的描述与夜晚不符。"}, "sentence_index": 6, "correct_answer": "山坡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山坡从山顶一直流到村子里。", "explanation": "这里应该用〈河流〉。“流”指水的移动，山坡是陆地，不会流动。"}, {"text": "孩子们在山坡里游泳。", "explanation": "这里应该用〈池塘〉。游泳要在水中，山坡是陆地，不能说“游”。"}, {"text": "山坡上飘着几只小船。", "explanation": "这里应该用〈湖面〉。船能飘在水面上，山坡是陆地表面，不能“飘”着船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天，一棵山坡上开满了野花。", "corrected_sentence": "夏天，一片山坡上开满了野花。", "error_description": "量词错误：「一棵山坡」应为「一片山坡」。〈棵〉用于树木，山坡是地形，应用〈片〉来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在一条山坡上玩得很开心。", "corrected_sentence": "孩子们在一片山坡上玩得很开心。", "error_description": "量词错误：山坡是成片的地形，不用“条”，应说“一片山坡”。“条”多用于细长的物体，如路、河、绳子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
