INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25214, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很值钱，很珍贵，不能随便弄丢。", "primary_collocate": null, "pronunciation": "bǎo guì", "ipa": "pɑʊ̯˨˩ kweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这块玉很宝贵，别弄丢了。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶留下的戒指对我很宝贵。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本旧书很宝贵，请小心拿。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护照很宝贵，你要放好。", "target_word": "宝贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "博物馆里有很多宝贵的画。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是爷爷给我的宝贵礼物。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把最宝贵的东西藏在箱子里了。", "target_word": "宝贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图已经有两百年了，非常宝贵。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些宝贵的文物不能随便摸。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手机里有宝贵的照片，别删了。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宝贵", "label": "基本形式"}, {"form": "寶貴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容具体物品很值钱、很珍贵，要小心保管，不能弄丢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b7ca80-ae1c-4e7c-a5ec-daf599d2e99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宝贵", "is_correct": true, "explanation": "正确：“宝贵”说明这块玉很值钱，所以要小心，别弄丢。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音大，玉没有声音，句意不通。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场所或场面，不能用来形容一块玉。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”形容人的心情，不能用来形容物品。"}], "explanations": {"宝贵": "正确：“宝贵”说明这块玉很值钱，所以要小心，别弄丢。", "吵闹": "语义：“吵闹”形容声音大，玉没有声音，句意不通。", "热闹": "搭配：“热闹”形容场所或场面，不能用来形容一块玉。", "愉快": "语义：“愉快”形容人的心情，不能用来形容物品。"}, "sentence_index": 0, "correct_answer": "宝贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电视的价格很宝贵，我买不起。", "explanation": "这里应该用〈昂贵〉。宝贵说的是事物值得珍惜，不用来形容价格；价格高要说昂贵。"}, {"text": "这块玉的颜色很宝贵，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。宝贵说的是事物值得珍惜，不用来评价颜色；颜色亮丽要说鲜艳。"}, {"text": "他宝贵地跑完了一百米。", "explanation": "这里应该用〈快速〉。宝贵说的是东西值得珍惜，不能用来形容速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宝贵", "is_correct": true, "explanation": "正确：“最宝贵的东西”指最值钱、最需要保管的东西，与句意相符。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”形容想法或行为不成熟，不能用来形容要藏起来的东西。"}, {"text": "偏僻", "is_correct": false, "explanation": "搭配：“偏僻”形容地方位置冷清，不能用来形容东西。"}, {"text": "凄凉", "is_correct": false, "explanation": "语义：“凄凉”形容景象或心境冷清悲伤，与“东西”的意义不符。"}], "explanations": {"宝贵": "正确：“最宝贵的东西”指最值钱、最需要保管的东西，与句意相符。", "幼稚": "语义：“幼稚”形容想法或行为不成熟，不能用来形容要藏起来的东西。", "偏僻": "搭配：“偏僻”形容地方位置冷清，不能用来形容东西。", "凄凉": "语义：“凄凉”形容景象或心境冷清悲伤，与“东西”的意义不符。"}, "sentence_index": 6, "correct_answer": "宝贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个社团的人数很宝贵，大家都很高兴。", "explanation": "这里应该用〈多〉。人数的多少要说多或少；宝贵说的是事物值得珍惜，不用来形容数量。"}, {"text": "这个小孩的性格很宝贵，老师很喜欢他。", "explanation": "这里应该用〈好〉。宝贵说的是事物值得珍惜，不用来形容性格；性格好要说好。"}, {"text": "这个箱子的重量很宝贵，我搬不动。", "explanation": "这里应该用〈沉〉。说东西的轻重要用沉或轻；宝贵不用来形容重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一块很宝贵玉。", "corrected_sentence": "我找到了一块很宝贵的玉。", "error_description": "漏掉“的”：“很宝贵”修饰名词“玉”时要说“很宝贵的玉”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅古画已经有两百年了，被非常宝贵。", "corrected_sentence": "这幅古画已经有两百年了，非常宝贵。", "error_description": "被字句误用：「宝贵」是形容词，不能用「被」字句表达，应去掉「被」，说「非常宝贵」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
