INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山坡上像台阶一样的田。", "primary_collocate": null, "pronunciation": "tī tián", "ipa": "tʰi˥ tʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷家后面的山上有一片梯田。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯田的每一层都不太宽。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山坡上开出了梯田。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，水从上一层梯田流到下一层。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客站在高处看梯田，觉得很美。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯田里的稻子快要熟了。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了多种粮食，人们在山上造了梯田。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍的是广西的梯田。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片梯田在很高的山上，走到顶要一个小时。", "target_word": "梯田", "complexity_tier": "T3", "furigana": "zhè piàn tī tián zài hěn gāo de shān shàng, zǒu dào dǐng yào yí gè xiǎoshí.", "sentence_source": "generated"}, {"text": "我第一次看见梯田，就爱上了这个地方。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片梯田", "label": "量词"}, {"form": "一块梯田", "label": "量词"}], "register": "中性", "sense_fingerprint": "山坡上台阶状的田", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "梯田", "is_correct": true, "explanation": "正确：山上的一片农田，指梯田，与句意相符。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“片”可以用于田地或树林，不用于手机。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：高铁是交通工具，不会长在山上。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是山上的景物，与句意冲突。"}], "explanations": {"梯田": "正确：山上的一片农田，指梯田，与句意相符。", "手机": "搭配：量词“片”可以用于田地或树林，不用于手机。", "高铁": "语义：高铁是交通工具，不会长在山上。", "电脑": "语义：电脑不是山上的景物，与句意冲突。"}, "sentence_index": 0, "correct_answer": "梯田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在山坡上割梯田。", "explanation": "这里应该用〈庄稼〉。割的是庄稼，梯田是地块，不能割。"}, {"text": "梯田里住着很多人。", "explanation": "这里应该用〈高楼〉。高楼是住人的建筑，梯田是农田，不能住人。"}, {"text": "教室里放满了课桌，梯田里也放满了课桌。", "explanation": "这里应该用〈仓库〉。梯田是农田，课桌只能放在教室或仓库里，不能放在梯田里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梯田", "is_correct": true, "explanation": "正确：为了多种粮食，在山上修造梯田，符合句意。"}, {"text": "高楼", "is_correct": false, "explanation": "语义：造高楼是为了住人，与“为了多种粮食”的目的不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“造”的对象是建筑或设施，不说“造歌曲”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁建在地下，与“在山上”的地点冲突。"}], "explanations": {"梯田": "正确：为了多种粮食，在山上修造梯田，符合句意。", "高楼": "语义：造高楼是为了住人，与“为了多种粮食”的目的不合。", "歌曲": "搭配：“造”的对象是建筑或设施，不说“造歌曲”。", "地铁": "语义：地铁建在地下，与“在山上”的地点冲突。"}, "sentence_index": 6, "correct_answer": "梯田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在公园里玩梯田。", "explanation": "这里应该用〈滑梯〉。梯田是农田，不能用来玩耍。"}, {"text": "他把梯田搬进了屋里。", "explanation": "这里应该用〈桌子〉。梯田固定在山坡上，不能搬进屋里；能搬的应是桌子这类可移动的东西。"}, {"text": "梯田里停满了汽车。", "explanation": "这里应该用〈停车场〉。梯田是种庄稼的地方，不能用来停车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山腰上有一个梯田。", "corrected_sentence": "山腰上有一块梯田。", "error_description": "量词错误：梯田是成片的农田，不用“个”，应说“一块梯田”或“一片梯田”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个梯田被大雨冲坏了一部分。", "corrected_sentence": "一片梯田被大雨冲坏了一部分。", "error_description": "量词错误：梯田是成片的农田，不用“个”，应说“一片梯田”或“一块梯田”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
