INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小米是一种很小的、可以煮粥吃的黄色粮食。", "primary_collocate": null, "pronunciation": "xiǎo mǐ", "ipa": "ɕiɑʊ˨˩˦ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "小米很小，是黄色的。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用小米煮了一锅粥。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一袋小米，是爸爸买的。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小米和大米不一样，颗粒小得多。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小米倒进锅里，再加水。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢吃小米，更爱吃面条。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子身体不好，可以多喝点小米熬的粥。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人给鸽子撒小米。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶已经把小米煮好了。", "target_word": "小米", "complexity_tier": "T3", "furigana": "nǎinai yǐjīng bǎ xiǎomǐ zhǔ hǎo le.", "sentence_source": "generated"}, {"text": "小米要先洗一洗，再放进锅里煮。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一粒小米", "label": "量词"}, {"form": "小米粥", "label": "复合"}], "register": "中性", "sense_fingerprint": "很小可煮粥的黄色粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小米", "is_correct": true, "explanation": "正确：小米本身很小，是黄色的，与句意相符。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象体形很大，与“很小”的描述冲突。"}, {"text": "乌云", "is_correct": false, "explanation": "体貌：乌云是灰黑色，与“黄色的”冲突。"}, {"text": "高楼", "is_correct": false, "explanation": "语义：高楼体积大，不是很小的东西，与“很小”冲突。"}], "explanations": {"小米": "正确：小米本身很小，是黄色的，与句意相符。", "大象": "语义：大象体形很大，与“很小”的描述冲突。", "乌云": "体貌：乌云是灰黑色，与“黄色的”冲突。", "高楼": "语义：高楼体积大，不是很小的东西，与“很小”冲突。"}, "sentence_index": 0, "correct_answer": "小米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里把小米切成小块。", "explanation": "这里应该用〈土豆〉。切成小块是对块状食材的处理，小米是颗粒状粮食，不能切。"}, {"text": "我用小米做了一锅红烧肉。", "explanation": "这里应该用〈猪肉〉。红烧肉要用猪肉做，小米不能代替猪肉。"}, {"text": "他每天用小米开车去上班。", "explanation": "这里应该用〈汽油〉。小米是粮食，不能当燃料，“用小米开车”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小米", "is_correct": true, "explanation": "正确：小米可以熬粥，适合身体不好的小孩子喝。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能吃，也不能熬成粥。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料不能吃，与“熬的粥”冲突。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "搭配：熬粥要用能吃的食材，洗衣粉不能用来熬粥。"}], "explanations": {"小米": "正确：小米可以熬粥，适合身体不好的小孩子喝。", "汽油": "语义：汽油不能吃，也不能熬成粥。", "颜料": "语义：颜料不能吃，与“熬的粥”冲突。", "洗衣粉": "搭配：熬粥要用能吃的食材，洗衣粉不能用来熬粥。"}, "sentence_index": 6, "correct_answer": "小米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小米要泡一夜才能做豆腐。", "explanation": "这里应该用〈大豆〉。豆腐是用大豆等豆类做的，小米不能做豆腐。"}, {"text": "巧克力是用小米做的。", "explanation": "这里应该用〈可可豆〉。巧克力是用可可豆做的，不是用小米做的。"}, {"text": "薯片是用小米做的。", "explanation": "这里应该用〈土豆〉。薯片是用土豆等原料做的，小米不能用来做薯片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐给我称了两只小米。", "corrected_sentence": "姐姐给我称了两斤小米。", "error_description": "量词错误：小米按重量称，应用“斤”，不用“只”（“只”用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶昨天称了三斤小米们。", "corrected_sentence": "奶奶昨天称了三斤小米。", "error_description": "词形错误：小米是不可数的粮食，不能加“们”，应说“三斤小米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
