INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25221, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种地就是在田里种菜或粮食。", "primary_collocate": null, "pronunciation": "zhòng dì", "ipa": "ʈʂʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "我爸爸是农民，每天在田里种地。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喜欢种地，家后面有一块小田。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民伯伯春天种地，秋天收粮食。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山下种地，种的是玉米和小麦。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要种地，先要有田，也要有种子。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去乡下种地，自己种菜吃。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的年轻人都去城里了，很少有人种地。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，大家马上去田里种地。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王叔叔不种地了，他现在在城里开出租车。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种地需要水，所以农民很关心天气。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种了地", "label": "体标（了）"}, {"form": "种过地", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "在田里种菜或粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25221, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种地", "is_correct": true, "explanation": "正确：种地，指在田里种菜或粮食。"}, {"text": "中低", "is_correct": false, "explanation": "zhōngdī 与 zhòngdì 声母韵母相同，只是声调不同（第一声／第四声），意思是中等偏低。"}, {"text": "重力", "is_correct": false, "explanation": "lì 与 dì 声母不同（l／d），声调相同，意思是地球对物体的吸引力。"}, {"text": "重度", "is_correct": false, "explanation": "dù（第四声）与 dì（第四声）韵母不同，意思是程度深、严重。"}], "explanations": {"种地": "正确：种地，指在田里种菜或粮食。", "中低": "zhōngdī 与 zhòngdì 声母韵母相同，只是声调不同（第一声／第四声），意思是中等偏低。", "重力": "lì 与 dì 声母不同（l／d），声调相同，意思是地球对物体的吸引力。", "重度": "dù（第四声）与 dì（第四声）韵母不同，意思是程度深、严重。"}, "sentence_index": null, "correct_answer": "种地"}, "level_3": {"options": [{"text": "种地", "is_correct": true, "explanation": "正确：爸爸是农民，每天在田里种地，与句意一致。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：田里不能游泳，“每天在田里游泳”与农民的工作不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“在田里洗澡”不符合农民每天的工作语境。"}, {"text": "织布", "is_correct": false, "explanation": "搭配：“织布”需要织机和纱线，不在田里进行。"}], "explanations": {"种地": "正确：爸爸是农民，每天在田里种地，与句意一致。", "游泳": "语义：田里不能游泳，“每天在田里游泳”与农民的工作不符。", "洗澡": "语义：“在田里洗澡”不符合农民每天的工作语境。", "织布": "搭配：“织布”需要织机和纱线，不在田里进行。"}, "sentence_index": 0, "correct_answer": "种地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在公司种地，很晚才回家。", "explanation": "这里应该用〈上班〉。种地要在田里进行，在公司工作要说上班。"}, {"text": "爷爷每天在公园里种地，锻炼身体。", "explanation": "这里应该用〈散步〉。种地指耕种田地，在公园里锻炼要说散步。"}, {"text": "他每天在河边种地，希望能钓到大鱼。", "explanation": "这里应该用〈钓鱼〉。种地指耕种田地，希望钓到大鱼要说钓鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种地", "is_correct": true, "explanation": "正确：年轻人都去城里了，很少有人留在村里种地，与句意一致。"}, {"text": "长大", "is_correct": false, "explanation": "语义：“很少有人长大”说不通，“长大”与句子说的农事无关。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指刚来到世上，放在这句话里说不通。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”多用于老年人，与“年轻人”搭配不当。"}], "explanations": {"种地": "正确：年轻人都去城里了，很少有人留在村里种地，与句意一致。", "长大": "语义：“很少有人长大”说不通，“长大”与句子说的农事无关。", "出生": "语义：“出生”指刚来到世上，放在这句话里说不通。", "退休": "搭配：“退休”多用于老年人，与“年轻人”搭配不当。"}, "sentence_index": 6, "correct_answer": "种地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在修车店里种地，修好了很多汽车。", "explanation": "这里应该用〈修车〉。种地指耕种田地，修理汽车要说修车。"}, {"text": "她每天在舞台上种地，唱了很多歌。", "explanation": "这里应该用〈唱歌〉。种地指耕种田地，在舞台上唱歌要说唱歌。"}, {"text": "妈妈在屋里种地，绣了一朵花。", "explanation": "这里应该用〈绣花〉。种地指耕种田地，在屋里做针线活要说绣花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他爷爷一辈子都田里种地。", "corrected_sentence": "他爷爷一辈子都在田里种地。", "error_description": "表示处所的状语“在田里”前要加“在”，应说“在田里种地”，不能说“田里种地”。漏掉“在”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸把种地了，今年收成很好。", "corrected_sentence": "我爸爸把地种了，今年收成很好。", "error_description": "“种地”是离合词，用“把”字句时要说“把地种了”，不能说“把种地了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
