INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25224, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水走了。", "primary_collocate": null, "pronunciation": "liú zǒu", "ipa": "li̯oʊ̯˧˥ tsoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "水池的水都流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把塞子拔开，盆里的水就会流走。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水顺着路边流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的水流走了，一点儿也没留下。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，水都流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雪化了，雪水流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下水道通了，脏水很快流走。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流走以后，河底只剩下石头。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完澡，地上的水流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨停后，院子里的水慢慢流走。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流走了", "label": "体标（了）"}, {"form": "流不走", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "动词：水流到别处去了，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走：液体流开消失，与“水池的水都”没有了的句意一致。"}, {"text": "积攒", "is_correct": false, "explanation": "搭配：“积攒”多接钱物、经验，不说“水池的水积攒”。"}, {"text": "折叠", "is_correct": false, "explanation": "搭配：“折叠”用于纸、衣服等有形的东西，水不能折叠。"}, {"text": "溅起", "is_correct": false, "explanation": "搭配：“溅起”指水花向上飞起，不能说整池水都溅起。"}], "explanations": {"流走": "流走：液体流开消失，与“水池的水都”没有了的句意一致。", "积攒": "搭配：“积攒”多接钱物、经验，不说“水池的水积攒”。", "折叠": "搭配：“折叠”用于纸、衣服等有形的东西，水不能折叠。", "溅起": "搭配：“溅起”指水花向上飞起，不能说整池水都溅起。"}, "sentence_index": 0, "correct_answer": "流走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钥匙从口袋里流走了。", "explanation": "这里应该用〈掉出〉。流走只用于液体或时间等流动的东西，钥匙从口袋掉出要用掉出。"}, {"text": "犯人趁夜色流走了。", "explanation": "这里应该用〈逃跑〉。流走指液体流开不见，人逃跑要用逃跑。"}, {"text": "大风流走了屋顶的瓦片。", "explanation": "这里应该用〈吹走〉。流走是不及物动词，不能带“瓦片”作宾语，被风吹离要用吹走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走：脏水离开下水道、不再停留，与“下水道通了”的句意一致。"}, {"text": "聚集", "is_correct": false, "explanation": "语义：下水道通了，脏水应该顺畅离开，“聚集”与此矛盾。"}, {"text": "倒灌", "is_correct": false, "explanation": "语义：“倒灌”指水逆向涌入，与“下水道通了”的顺畅状态矛盾。"}, {"text": "堆积", "is_correct": false, "explanation": "搭配：“堆积”多接垃圾、货物，“脏水很快堆积”不自然。"}], "explanations": {"流走": "流走：脏水离开下水道、不再停留，与“下水道通了”的句意一致。", "聚集": "语义：下水道通了，脏水应该顺畅离开，“聚集”与此矛盾。", "倒灌": "语义：“倒灌”指水逆向涌入，与“下水道通了”的顺畅状态矛盾。", "堆积": "搭配：“堆积”多接垃圾、货物，“脏水很快堆积”不自然。"}, "sentence_index": 6, "correct_answer": "流走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门手艺在村子里流走了好几代。", "explanation": "这里应该用〈流传〉。流走表示消失，手艺代代传下去要用流传。"}, {"text": "她的钱包不见了，大概是在出租车上流走了。", "explanation": "这里应该用〈遗失〉。流走指液体流开消失，钱包丢失要用遗失。"}, {"text": "一群孩子听见铃声，立刻流走了。", "explanation": "这里应该用〈跑走〉。流走用于液体、时间等流动的东西，孩子跑开要用跑走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水池的水都流走来了，只剩下一层泥。", "corrected_sentence": "水池的水都流走了，只剩下一层泥。", "error_description": "“流走”表示液体流开离去，“走”已是趋向补语，不能再加“来”；正确说法是“流走了”，不说“流走来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶的雪水一会儿就把流走了。", "corrected_sentence": "屋顶的雪水一会儿就流走了。", "error_description": "“流走”是不及物的动补结构，没有可以被处置的宾语，不能放进“把”字句；正确说法是“雪水一会儿就流走了”，不说“把流走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
