INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25226, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水慢慢进到土里。", "primary_collocate": null, "pronunciation": "shèn rù", "ipa": "ʂən˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "下大雨后，雨水渗入田里。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从花盆上面渗入土里。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给花浇水，水很快渗入土中。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的沙地很松，水很容易渗入。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪化成水，一点一点渗入地里。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水渗入泥土以后，种子开始发芽了。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水渗入山上的土里，再慢慢流进小河。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的土很干，浇的水马上就渗入了。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水渗入农田的土里，庄稼才能长大。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天雨水少，水很难渗入冻硬的土地。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渗入了", "label": "体标"}, {"form": "渗入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "水慢慢进到土里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渗入", "is_correct": true, "explanation": "渗入 shèn rù：液体慢慢进到土里或物体内部。"}, {"text": "深入", "is_correct": false, "explanation": "深入 shēn rù：shēn（第一声）与 shèn（第四声）声调不同，指向深处进入。"}, {"text": "伸入", "is_correct": false, "explanation": "伸入 shēn rù：shēn（第一声）与 shèn（第四声）声调不同，指把东西伸进某处。"}, {"text": "盛入", "is_correct": false, "explanation": "盛入 shèng rù：韵母 eng 与 en 不同，指装进容器里。"}], "explanations": {"渗入": "渗入 shèn rù：液体慢慢进到土里或物体内部。", "深入": "深入 shēn rù：shēn（第一声）与 shèn（第四声）声调不同，指向深处进入。", "伸入": "伸入 shēn rù：shēn（第一声）与 shèn（第四声）声调不同，指把东西伸进某处。", "盛入": "盛入 shèng rù：韵母 eng 与 en 不同，指装进容器里。"}, "sentence_index": null, "correct_answer": "渗入"}, "level_3": {"options": [{"text": "渗入", "is_correct": true, "explanation": "渗入：雨水慢慢进到田里的土中，符合“下大雨后”的句意。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：下大雨后的雨水不会结冰，与句意矛盾。"}, {"text": "喷洒", "is_correct": false, "explanation": "搭配：“喷洒”多指人或机器把液体撒出，不说雨水喷洒田里。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：“漂浮”要说“在……上漂浮”，不能直接接“田里”。"}], "explanations": {"渗入": "渗入：雨水慢慢进到田里的土中，符合“下大雨后”的句意。", "结冰": "语义：下大雨后的雨水不会结冰，与句意矛盾。", "喷洒": "搭配：“喷洒”多指人或机器把液体撒出，不说雨水喷洒田里。", "漂浮": "搭配：“漂浮”要说“在……上漂浮”，不能直接接“田里”。"}, "sentence_index": 0, "correct_answer": "渗入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卡车渗入了山路。", "explanation": "这里应该用〈驶入〉。渗入只用于水、气等慢慢进入，卡车快速开进要用驶入。"}, {"text": "铁块慢慢渗入水底。", "explanation": "这里应该用〈沉入〉。渗入只用于液体或气体，铁块整块下沉要用沉入。"}, {"text": "小虫渗入了土里。", "explanation": "这里应该用〈钻入〉。渗入用于液体或气体，小虫钻进去要用钻入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渗入", "is_correct": true, "explanation": "渗入：雨水进到山上的土里，与后文“再慢慢流进小河”的先后顺序相接。"}, {"text": "射入", "is_correct": false, "explanation": "语义：“射入”指快速有力地进入，与“慢慢流进小河”的节奏矛盾。"}, {"text": "腐蚀", "is_correct": false, "explanation": "搭配：“腐蚀”多接岩石、金属，不说腐蚀“土里”。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：雨水在山上冻结，就无法再流进小河，与句意矛盾。"}], "explanations": {"渗入": "渗入：雨水进到山上的土里，与后文“再慢慢流进小河”的先后顺序相接。", "射入": "语义：“射入”指快速有力地进入，与“慢慢流进小河”的节奏矛盾。", "腐蚀": "搭配：“腐蚀”多接岩石、金属，不说腐蚀“土里”。", "冻结": "语义：雨水在山上冻结，就无法再流进小河，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "渗入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老鼠渗入了粮仓。", "explanation": "这里应该用〈溜入〉。渗入是水、气等慢慢进入，老鼠悄悄钻进粮仓要用溜入。"}, {"text": "箭渗入了靶心。", "explanation": "这里应该用〈射入〉。渗入是缓慢进入，箭快速刺入要用射入。"}, {"text": "铁钉渗入了木头。", "explanation": "这里应该用〈钉入〉。渗入是水、气等慢慢进入，铁钉被敲进木头要用钉入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河边的土很湿，雨水很快就把渗入了土里。", "corrected_sentence": "河边的土很湿，雨水很快就渗入了土里。", "error_description": "“把”字句中“把”后须接被处置的名词，“渗入”不能用于“把”字句；“把”应去掉，正确说法是“雨水很快就渗入了土里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天地上的雪水很快就被渗入了土里。", "corrected_sentence": "春天地上的雪水很快就渗入了土里。", "error_description": "“渗入”一般不用于“被”字句，表示被动的说法不自然；正确说法是“雪水渗入了土里”，不说“被渗入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
