INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "粮食产量指地里种出来的东西有多少。", "primary_collocate": null, "pronunciation": "liáng shi chǎn liàng", "ipa": "ljɑŋ˧˥ ʂɨ tʂʰan˨˩ ljɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这块地的粮食产量很高。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年水少，粮食产量不太好。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每年都会算一算粮食产量。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的粮食产量比去年多。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民希望粮食产量越来越高。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了很多雨，粮食产量可能会减少。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村的粮食产量在全县是最多的。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：你们家乡的粮食产量怎么样？", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用上新机器后，粮食产量多了不少。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱让粮食产量少了很多，大家都很担心。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粮食总产量", "label": "复合"}, {"form": "粮食年产量", "label": "复合"}], "register": "中性", "sense_fingerprint": "地里种出来的东西有多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粮食产量", "is_correct": true, "explanation": "正确。“很高”可以修饰粮食产量，指产量多。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的身体长度，不能用来描述土地。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，与土地无关。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积说“大”或“小”，不说“高”。"}], "explanations": {"粮食产量": "正确。“很高”可以修饰粮食产量，指产量多。", "身高": "语义：身高指人的身体长度，不能用来描述土地。", "工资": "语义：工资是劳动报酬，与土地无关。", "面积": "搭配：面积说“大”或“小”，不说“高”。"}, "sentence_index": 0, "correct_answer": "粮食产量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "粮食产量今年便宜了很多。", "explanation": "这里应该用〈粮食价格〉。“便宜”说的是价格，粮食产量是收获的数量，不能说便宜。"}, {"text": "我们去超市买了一些粮食产量。", "explanation": "这里应该用〈大米〉。粮食产量是收获的总数量，是统计数字，超市里卖的是大米这类实物，不能买粮食产量。"}, {"text": "农民在地里种粮食产量。", "explanation": "这里应该用〈粮食作物〉。粮食产量指收获的总数，不能用来种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粮食产量", "is_correct": true, "explanation": "正确。“在全县是最多的”修饰粮食产量，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是个人的属性，不能用来描述一个村子。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：寿命说“长”，不说“最多”。"}, {"text": "视力", "is_correct": false, "explanation": "语义：视力是人的能力，不能用来描述一个村子。"}], "explanations": {"粮食产量": "正确。“在全县是最多的”修饰粮食产量，与句意相符。", "体重": "语义：体重是个人的属性，不能用来描述一个村子。", "寿命": "搭配：寿命说“长”，不说“最多”。", "视力": "语义：视力是人的能力，不能用来描述一个村子。"}, "sentence_index": 6, "correct_answer": "粮食产量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库里还存放着很多粮食产量。", "explanation": "这里应该用〈粮食储备〉。粮食产量是某一时期收获的总数，不是仓库里存放的东西。"}, {"text": "去年的一颗粮食产量很低。", "explanation": "这里不该给“粮食产量”加量词“颗”。粮食产量是抽象的总数，不用个体量词计算，应直接说“粮食产量很低”。"}, {"text": "工厂每天把很多粮食产量磨成面粉。", "explanation": "这里应该用〈小麦〉。粮食产量是收获的总数量，不是可以磨成面粉的实物，磨面粉的是小麦等谷物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的粮食产量不没有去年高。", "corrected_sentence": "今年的粮食产量没有去年高。", "error_description": "“不”和“没有”不能同时用，“没有”前面不应再加否定词“不”，应说“没有去年高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年的粮食产量减少了了一大半。", "corrected_sentence": "去年的粮食产量减少了一大半。", "error_description": "“了”重复。“减少了”之后不应再加“了”，应说“减少了一大半”，表示变化已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：“相信”与“怀疑”意义相对，一个认为某事是真的，一个认为其真实性存疑。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：讨论表示交换意见，与相信不构成反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "无关：观察表示仔细看，与相信不构成反义关系。"}, {"text": "解释", "is_correct": false, "explanation": "无关：解释表示说明道理，与相信不构成反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：“相信”与“怀疑”意义相对，一个认为某事是真的，一个认为其真实性存疑。", "讨论": "无关：讨论表示交换意见，与相信不构成反义关系。", "观察": "无关：观察表示仔细看，与相信不构成反义关系。", "解释": "无关：解释表示说明道理，与相信不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：“相信”与“怀疑”意义相对，“相信它是真的”的反面正是“怀疑它是真的”。"}, {"text": "忘记", "is_correct": false, "explanation": "无关：忘记表示不再记得，与相信不构成反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "无关：提醒表示促使对方注意，与相信不构成反义关系。"}, {"text": "欣赏", "is_correct": false, "explanation": "无关：欣赏表示认为好而喜爱，与相信不构成反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：“相信”与“怀疑”意义相对，“相信它是真的”的反面正是“怀疑它是真的”。", "忘记": "无关：忘记表示不再记得，与相信不构成反义关系。", "提醒": "无关：提醒表示促使对方注意，与相信不构成反义关系。", "欣赏": "无关：欣赏表示认为好而喜爱，与相信不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得某件事是真的，在心里同意它。", "primary_collocate": null, "pronunciation": "xiāng xìn", "ipa": "ɕjɑŋ˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "听了你的解释，我相信你没有说谎。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我相信这个办法是对的。", "target_word": "相信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他相信朋友不会骗他。", "target_word": "相信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她还很小，还相信世界上有魔法。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我查了资料，相信这个说法是真的。", "target_word": "相信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太相信这种广告。", "target_word": "相信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明不相信这个数字，又算了一遍。", "target_word": "相信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信有外星人吗？", "target_word": "相信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈相信我会照顾好自己。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息很可靠，我相信它是真的。", "target_word": "相信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相信了", "label": "体标"}, {"form": "相信过", "label": "体标"}], "register": "中性", "sense_fingerprint": "心里觉得某事是真的并表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相信", "is_correct": true, "explanation": "正确：“听了你的解释，我相信你没有说谎”表示心里认同对方的话，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等，不能带“你没有说谎”这样的判断作宾语。"}, {"text": "摇头", "is_correct": false, "explanation": "配价：“摇头”是不及物动词，不能带“你没有说谎”作宾语。"}, {"text": "抄写", "is_correct": false, "explanation": "搭配：“抄写”的对象应是文字，不能与“你没有说谎”这一判断搭配。"}], "explanations": {"相信": "正确：“听了你的解释，我相信你没有说谎”表示心里认同对方的话，符合语境。", "打扫": "搭配：“打扫”的对象是房间、地面等，不能带“你没有说谎”这样的判断作宾语。", "摇头": "配价：“摇头”是不及物动词，不能带“你没有说谎”作宾语。", "抄写": "搭配：“抄写”的对象应是文字，不能与“你没有说谎”这一判断搭配。"}, "sentence_index": 0, "correct_answer": "相信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很相信这首歌。", "explanation": "这里应该用〈喜欢〉。相信接的是判断，不表示对歌曲的喜爱；表示喜爱要用〈喜欢〉。"}, {"text": "我们相信了一场大雨。", "explanation": "这里应该用〈淋〉。相信表示认为某件事是真的，不表示被雨淋湿；说被雨淋到要用〈淋〉。"}, {"text": "我相信了他的电话号码。", "explanation": "这里应该用〈忘记〉。相信表示认为某事是真的，不表示遗忘；忘了号码应说忘记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相信", "is_correct": true, "explanation": "正确：“小明不相信这个数字”表示不认同其真实性，于是又算一遍，符合语境。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬东西，与“这个数字”这类抽象事物不合，句子说不通。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的宾语应是可买卖的物品，“数字”不能购买。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，不能带“这个数字”作宾语。"}], "explanations": {"相信": "正确：“小明不相信这个数字”表示不认同其真实性，于是又算一遍，符合语境。", "咬": "语义：“咬”是用牙齿咬东西，与“这个数字”这类抽象事物不合，句子说不通。", "购买": "搭配：“购买”的宾语应是可买卖的物品，“数字”不能购买。", "出发": "配价：“出发”是不及物动词，不能带“这个数字”作宾语。"}, "sentence_index": 6, "correct_answer": "相信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生相信了电灯。", "explanation": "这里应该用〈发明〉。相信表示认为某事是真的，不表示创造出新事物；造出电灯要用〈发明〉。"}, {"text": "我们相信了博物馆。", "explanation": "这里应该用〈参观〉。相信的宾语是一件事的真实性，不能是地点；去看展览要用〈参观〉。"}, {"text": "工人相信了货物。", "explanation": "这里应该用〈搬运〉。“相信”表示认为某事为真，不表示移动物品；搬运货物要用〈搬运〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不相信得你会迟到。", "corrected_sentence": "我不相信你会迟到。", "error_description": "“相信”后面应直接接宾语，不能插入“得”；“得”只用于动词后的补语。错误形式：不相信得你；正确形式：不相信你。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不太相信了那个说法。", "corrected_sentence": "我不太相信那个说法。", "error_description": "否定句“不太相信”中不能加“了”，表示现在的态度时直接说“不太相信”；错误形式多出了“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
