INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25232, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水把土冲走了。", "primary_collocate": null, "pronunciation": "shuǐ tǔ liú shī", "ipa": "ʂweɪ̯˨˩˦ tʰu˨˩˦ li̯oʊ̯˧˥ ʂɨ˥", "syllable_count": 4, "sentences": [{"text": "山坡上没有草，大雨一来，水土流失了。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，河边的水土流失了很多。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树都砍光了，山上的水土流失得很快。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，田里的水土流失了。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天大雨，河边的水土流失了。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么这座山的水土流失得这么快？", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水冲过以后，山坡的水土流失了。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块地的水土流失了，不能再种菜了。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天，这里的水土流失了不少。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的水土流失了，河水都变黄了。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水土流失了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "动词：雨水把山坡或田里的土冲走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水土流失", "is_correct": true, "explanation": "水土流失是土被雨水冲走，句中大雨一来正是这个结果。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：大雨不会让山坡结冰，两者没有因果关系。"}, {"text": "干涸", "is_correct": false, "explanation": "搭配：“干涸”说的是缺水变干，不能跟“大雨一来”搭配。"}, {"text": "放晴", "is_correct": false, "explanation": "语义：大雨一来天气不会放晴，句中的意思是下大雨。"}], "explanations": {"水土流失": "水土流失是土被雨水冲走，句中大雨一来正是这个结果。", "结冰": "语义：大雨不会让山坡结冰，两者没有因果关系。", "干涸": "搭配：“干涸”说的是缺水变干，不能跟“大雨一来”搭配。", "放晴": "语义：大雨一来天气不会放晴，句中的意思是下大雨。"}, "sentence_index": 0, "correct_answer": "水土流失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机器用久了，水土流失得很快。", "explanation": "这里应该用〈损耗〉。损耗指机器等东西因使用而变少、变坏，水土流失只指土被水冲走，不能用来说机器。"}, {"text": "这块地的水土流失很漂亮。", "explanation": "这里应该用〈严重〉。水土流失是坏现象，只能用“严重”“明显”等形容，不能用“漂亮”。"}, {"text": "我们正在搬运这块地的水土流失。", "explanation": "这里应该用〈泥土〉。水土流失是土被水冲走的现象，不是一堆可以搬运的东西，不能说“搬运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水土流失", "is_correct": true, "explanation": "水土流失是土被冲走，雨水冲过以后山坡的正是这个情况。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“山坡的”后面不能接“下雨”，山坡不会下雨。"}, {"text": "长高", "is_correct": false, "explanation": "语义：山坡不会因为雨水冲过而长高。"}, {"text": "发霉", "is_correct": false, "explanation": "搭配：“发霉”说的是食物或潮湿的东西，不能用在山坡上。"}], "explanations": {"水土流失": "水土流失是土被冲走，雨水冲过以后山坡的正是这个情况。", "下雨": "语义：“山坡的”后面不能接“下雨”，山坡不会下雨。", "长高": "语义：山坡不会因为雨水冲过而长高。", "发霉": "搭配：“发霉”说的是食物或潮湿的东西，不能用在山坡上。"}, "sentence_index": 6, "correct_answer": "水土流失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋穿久了，水土流失了很多。", "explanation": "这里应该用〈磨损〉。磨损指物体因使用而变旧变薄，水土流失只指土被水冲走，不能用来说鞋。"}, {"text": "我们昨天吃了水土流失。", "explanation": "这里应该用〈饭菜〉。水土流失是土被水冲走的现象，不是食物，不能吃。"}, {"text": "他用水土流失做了一顿饭。", "explanation": "这里应该用〈面粉〉。面粉是做饭的材料，水土流失是土被水冲走的现象，不是材料，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨一冲，把山坡上的水土流失了。", "corrected_sentence": "大雨一冲，山坡上的水土流失了。", "error_description": "“水土流失”是主谓式的固定说法，指土被雨水冲走的现象，整体不能放进“把”字句作被处置的对象；应去掉“把”，说“山坡上的水土流失了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年冬天，那块地的水土流失了过很多。", "corrected_sentence": "去年冬天，那块地的水土流失了很多。", "error_description": "“了”与“过”不能这样连用，且“了过”语序不通；应去掉“过”，说“流失了很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻视", "is_correct": true, "explanation": "正确。“轻视”与“重视”是反义词，指认为不重要、不认真对待。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“重视”没有反义关系，二者不构成对立。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”与“重视”没有反义关系，不能互为对立。"}, {"text": "赞成", "is_correct": false, "explanation": "“赞成”与“重视”不是反义词，词典中没有这一对应关系。"}], "correct_answer": "轻视", "explanations": {"轻视": "正确。“轻视”与“重视”是反义词，指认为不重要、不认真对待。", "思考": "“思考”与“重视”没有反义关系，二者不构成对立。", "参加": "“参加”与“重视”没有反义关系，不能互为对立。", "赞成": "“赞成”与“重视”不是反义词，词典中没有这一对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "正确。“忽视”与“重视”是反义词，指不认真对待、不当回事。"}, {"text": "回答", "is_correct": false, "explanation": "“回答”与“重视”没有反义关系，二者不构成对立。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”与“重视”没有反义关系，不能互为对立。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”与“重视”不是反义词，词典中没有这一对应关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "正确。“忽视”与“重视”是反义词，指不认真对待、不当回事。", "回答": "“回答”与“重视”没有反义关系，二者不构成对立。", "观看": "“观看”与“重视”没有反义关系，不能互为对立。", "购买": "“购买”与“重视”不是反义词，词典中没有这一对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得某样东西很重要，会认真对待它。", "primary_collocate": null, "pronunciation": "zhòng shì", "ipa": "ʈʂʊŋ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "公司很重视学生的意见。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一直重视孩子的学习。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要重视身体健康。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师重视每一次考试。", "target_word": "重视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不重视睡觉，每天都很晚才睡。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人以前不重视环境问题。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理重视过他的建议。", "target_word": "重视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不重视这次机会？", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家越来越重视孩子的教育。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很重视朋友，常常打电话问好。", "target_word": "重视", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "重视了", "label": "体标"}, {"form": "重视过", "label": "体标"}, {"form": "重视着", "label": "体标"}], "register": "中性", "sense_fingerprint": "认为重要而认真对待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重视", "is_correct": true, "explanation": "正确。“重视”：认为重要，认真对待。"}, {"text": "中式", "is_correct": false, "explanation": "zhōngshì（第一声）与 zhòngshì（第四声）声调不同，意思是中国式的。"}, {"text": "忠实", "is_correct": false, "explanation": "zhōngshí 与 zhòngshì 两个音节的声调都不同，意思是诚实可靠。"}, {"text": "重试", "is_correct": false, "explanation": "chóngshì 与 zhòngshì 声母不同（ch/zh），声调也不同，意思是再试一次。"}], "explanations": {"重视": "正确。“重视”：认为重要，认真对待。", "中式": "zhōngshì（第一声）与 zhòngshì（第四声）声调不同，意思是中国式的。", "忠实": "zhōngshí 与 zhòngshì 两个音节的声调都不同，意思是诚实可靠。", "重试": "chóngshì 与 zhòngshì 声母不同（ch/zh），声调也不同，意思是再试一次。"}, "sentence_index": null, "correct_answer": "重视"}, "level_3": {"options": [{"text": "重视", "is_correct": true, "explanation": "正确。“重视”表示认为学生的意见重要，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语要能喝，意见不能喝，不说喝学生的意见。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，意见不能唱。"}, {"text": "穿", "is_correct": false, "explanation": "语义：穿的对象是衣物，意见不能穿。"}], "explanations": {"重视": "正确。“重视”表示认为学生的意见重要，符合句意。", "喝": "搭配：“喝”的宾语要能喝，意见不能喝，不说喝学生的意见。", "唱": "语义：唱的对象是歌曲，意见不能唱。", "穿": "语义：穿的对象是衣物，意见不能穿。"}, "sentence_index": 0, "correct_answer": "重视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱子很重视，我一个人抬不动。", "explanation": "这里应该用〈重〉。“重视”是认为重要的意思，不表示分量；形容箱子分量大要用〈重〉。"}, {"text": "他重视做了一遍作业。", "explanation": "这里应该用〈重新〉。“重视”是认为重要的意思，表示再做一次要用〈重新〉，二者不能替换。"}, {"text": "老师重视了一下窗外，转身离开了教室。", "explanation": "这里应该用〈看〉。“重视”表示认为重要，不能用来说看窗外，看一下要用〈看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重视", "is_correct": true, "explanation": "正确。“重视”表示认为建议重要，与“经理……过他的建议”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，建议不能吃。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不说洗建议。"}, {"text": "关", "is_correct": false, "explanation": "语义：关的对象是门窗等，建议不能被关。"}], "explanations": {"重视": "正确。“重视”表示认为建议重要，与“经理……过他的建议”搭配。", "吃": "语义：吃的对象是食物，建议不能吃。", "洗": "搭配：“洗”的对象是衣物等，不说洗建议。", "关": "语义：关的对象是门窗等，建议不能被关。"}, "sentence_index": 6, "correct_answer": "重视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在门口重视了一会儿，然后走了进去。", "explanation": "这里应该用〈看〉。“重视”表示认为某事物重要，不表示观看门口，看门口要用〈看〉。"}, {"text": "大家重视着舞台。", "explanation": "这里应该用〈注视〉。“重视”表示认为重要，看舞台要用“注视”。"}, {"text": "他重视了她一眼，然后低下了头。", "explanation": "这里应该用〈看〉。“重视”表示认为重要，不能用来说看人，看一眼要用〈看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师很重视到学生的想法。", "corrected_sentence": "老师很重视学生的想法。", "error_description": "补语错误：“重视”后面不能加“到”，应说“老师很重视学生的想法”。“重视到”是把“注意到”混在了一起，“重视”只表示认为重要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司把重视员工的意见。", "corrected_sentence": "公司很重视员工的意见。", "error_description": "错误：“把”后直接接动词“重视”，缺少被处置的名词，“重视”也不用“把”字句。应去掉“把”，说“公司很重视员工的意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确：“保护”指照顾使不受损害，与“伤害”意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨事物的规律，与“伤害”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“伤害”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做好某件事，与“伤害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确：“保护”指照顾使不受损害，与“伤害”意思相反。", "研究": "“研究”指探讨事物的规律，与“伤害”没有反义关系。", "参加": "“参加”指加入某项活动，与“伤害”没有反义关系。", "完成": "“完成”指做好某件事，与“伤害”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确：“保护”指照顾使不受损害，与“伤害”意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指大家一起交换意见，与“伤害”没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指开始动身去某地，与“伤害”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”指注意地看，与“伤害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确：“保护”指照顾使不受损害，与“伤害”意思相反。", "讨论": "“讨论”指大家一起交换意见，与“伤害”没有反义关系。", "出发": "“出发”指开始动身去某地，与“伤害”没有反义关系。", "观看": "“观看”指注意地看，与“伤害”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "伤害就是使别人的身体或感情受到损害。", "primary_collocate": null, "pronunciation": "shāng hài", "ipa": "ʂaŋ˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "你这样说话会伤害朋友的心。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是故意的，但还是伤害了她。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别玩火，小心伤害自己。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话伤害过很多人。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从不伤害小动物。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩手机太久会伤害眼睛。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说的那句话深深伤害了我。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想伤害你，所以没有说实话。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟不但伤害自己，也伤害身边的人。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伤害过我，我还没有忘记。", "target_word": "伤害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伤害了", "label": "体标"}, {"form": "伤害过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使人的身体或感情受到损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伤害", "is_correct": true, "explanation": "正确：伤害指使别人的身体或感情受到损害。"}, {"text": "商海", "is_correct": false, "explanation": "hǎi（第三声）与 hài（第四声）声调不同，意思是商业界。"}, {"text": "上海", "is_correct": false, "explanation": "shàng（第四声）与 shāng 声调不同，hǎi（第三声）与 hài 声调也不同，意思是中国城市上海。"}, {"text": "伤号", "is_correct": false, "explanation": "hào（第四声）与 hài 韵母不同（ao 与 ai），意思是伤员。"}], "explanations": {"伤害": "正确：伤害指使别人的身体或感情受到损害。", "商海": "hǎi（第三声）与 hài（第四声）声调不同，意思是商业界。", "上海": "shàng（第四声）与 shāng 声调不同，hǎi（第三声）与 hài 声调也不同，意思是中国城市上海。", "伤号": "hào（第四声）与 hài 韵母不同（ao 与 ai），意思是伤员。"}, "sentence_index": null, "correct_answer": "伤害"}, "level_3": {"options": [{"text": "伤害", "is_correct": true, "explanation": "正确：“伤害”带宾语，指使人的感情受到损害。"}, {"text": "伤心", "is_correct": false, "explanation": "配价：“伤心”是不及物动词，后面不能直接带宾语“朋友的心”。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”针对人的外表，不能用来对“心”进行这种动作，句子不通。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”的对象是人或事，不能迎接“心”，句子不通。"}], "explanations": {"伤害": "正确：“伤害”带宾语，指使人的感情受到损害。", "伤心": "配价：“伤心”是不及物动词，后面不能直接带宾语“朋友的心”。", "打扮": "语义：“打扮”针对人的外表，不能用来对“心”进行这种动作，句子不通。", "迎接": "语义：“迎接”的对象是人或事，不能迎接“心”，句子不通。"}, "sentence_index": 0, "correct_answer": "伤害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场台风伤害了很多房屋。", "explanation": "这里应该用〈损害〉。伤害多用于人的身体、感情，房屋等财物要用损害。"}, {"text": "他不小心伤害了手机。", "explanation": "这里应该用〈损坏〉。伤害针对人或有感情的对象，手机等物品要用损坏。"}, {"text": "这场大火伤害了城市的建筑。", "explanation": "这里应该用〈破坏〉。伤害用于人或生命，建筑等事物要用破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤害", "is_correct": true, "explanation": "正确：“伤害”带宾语，指使人的感情受到损害。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带宾语“我”，句子不通。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”的对象是人，“那句话”不能拜访人，句子不通。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”针对地面、房间等，不能用来对人做这个动作，句子不通。"}], "explanations": {"伤害": "正确：“伤害”带宾语，指使人的感情受到损害。", "散步": "配价：“散步”是不及物动词，不能带宾语“我”，句子不通。", "拜访": "语义：“拜访”的对象是人，“那句话”不能拜访人，句子不通。", "打扫": "语义：“打扫”针对地面、房间等，不能用来对人做这个动作，句子不通。"}, "sentence_index": 6, "correct_answer": "伤害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震伤害了山区的学校。", "explanation": "这里应该用〈摧毁〉。伤害多指对人或感情的损害，学校被彻底毁坏要用摧毁。"}, {"text": "这场大雨伤害了那条新修的马路。", "explanation": "这里应该用〈冲毁〉。伤害多指对人或感情的损害，道路被洪水冲坏要说冲毁。"}, {"text": "他随手一扔，伤害了那块旧手表。", "explanation": "这里应该用〈摔坏〉。伤害针对人或有感情的对象，手表被摔坏要用摔坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他伤害了过我。", "corrected_sentence": "他伤害过我。", "error_description": "错误：“了”和“过”不能同时用在同一个动词后，只保留“过”，应说“伤害过我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没伤害了他。", "corrected_sentence": "我从来没伤害过他。", "error_description": "错误：“从来没”否定过去的经历，动词后要用“过”，不能用“了”，应说“没伤害过他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
