INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一样东西变作另一样东西。", "primary_collocate": null, "pronunciation": "gǎi chéng", "ipa": "kai˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈把旧衣服改成了小包。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里把空地改成了小公园。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧沙发改成了书架。", "target_word": "改成", "complexity_tier": "T3", "furigana": "tā bǎ jiù shāfa gǎi chéng le shūjià", "sentence_source": "generated"}, {"text": "能不能把这个句子改成问句？", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把手机的声音改成静音。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算把车库改成工作室。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把足球场改成了篮球场。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把表格里的数字改成红色。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把原来的计划改成了新的。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐把长裤改成了短裤。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改成了", "label": "体标"}, {"form": "改成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把一样东西变作另一样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25238, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改成", "is_correct": true, "explanation": "改成（gǎi chéng）：把一样东西变作另一样东西，即本词。"}, {"text": "搞成", "is_correct": false, "explanation": "gǎo（第三声）与 gǎi（第三声）韵母不同（ao 与 ai），意思是“弄成、做成”。"}, {"text": "盖成", "is_correct": false, "explanation": "gài（第四声）与 gǎi（第三声）声调不同，意思是“盖好、建成”。"}, {"text": "改称", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是“改变名称”。"}], "explanations": {"改成": "改成（gǎi chéng）：把一样东西变作另一样东西，即本词。", "搞成": "gǎo（第三声）与 gǎi（第三声）韵母不同（ao 与 ai），意思是“弄成、做成”。", "盖成": "gài（第四声）与 gǎi（第三声）声调不同，意思是“盖好、建成”。", "改称": "chēng（第一声）与 chéng（第二声）声调不同，意思是“改变名称”。"}, "sentence_index": null, "correct_answer": "改成"}, "level_3": {"options": [{"text": "改成", "is_correct": true, "explanation": "改成：把旧衣服变作小包，符合句意。"}, {"text": "染成", "is_correct": false, "explanation": "搭配：“染成”后接颜色，不接物品，不能说“染成小包”。"}, {"text": "涂成", "is_correct": false, "explanation": "语义：涂是把颜料抹在表面，不能把衣服变成小包。"}, {"text": "画成", "is_correct": false, "explanation": "语义：画是描绘图像，不能把衣服变成实物小包。"}], "explanations": {"改成": "改成：把旧衣服变作小包，符合句意。", "染成": "搭配：“染成”后接颜色，不接物品，不能说“染成小包”。", "涂成": "语义：涂是把颜料抹在表面，不能把衣服变成小包。", "画成": "语义：画是描绘图像，不能把衣服变成实物小包。"}, "sentence_index": 0, "correct_answer": "改成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子长大后改成了医生。", "explanation": "这里应该用〈变成〉。“改成”指把一样东西变作另一样，人的成长不用“改成”。"}, {"text": "他的心情一下子改成了很高兴。", "explanation": "这里应该用〈变得〉。“改成”用于具体事物或形式的改变，心情的变化应说“变得”。"}, {"text": "我们一家从北京改成了上海。", "explanation": "这里应该用〈搬到〉。人搬迁到另一地不说“改成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改成", "is_correct": true, "explanation": "改成：把足球场改为篮球场，符合句意。"}, {"text": "煮成", "is_correct": false, "explanation": "语义：煮是用水加热食物，足球场不能被煮成篮球场。"}, {"text": "写成", "is_correct": false, "explanation": "语义：写是书写文字，足球场不会因为书写而变成篮球场。"}, {"text": "烤成", "is_correct": false, "explanation": "搭配：“烤”一般用于食物，不说“烤成篮球场”。"}], "explanations": {"改成": "改成：把足球场改为篮球场，符合句意。", "煮成": "语义：煮是用水加热食物，足球场不能被煮成篮球场。", "写成": "语义：写是书写文字，足球场不会因为书写而变成篮球场。", "烤成": "搭配：“烤”一般用于食物，不说“烤成篮球场”。"}, "sentence_index": 6, "correct_answer": "改成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她毕业后改成了医生。", "explanation": "这里应该用〈成为〉。“改成”用于物品或形式的改变，人的身份变化不说“改成”。"}, {"text": "天气一下子改成冷了。", "explanation": "这里应该用〈变〉。“改成”是人把一样东西变作另一样，天气自然变冷要说“变冷了”。"}, {"text": "他从学校改成了家里。", "explanation": "这里应该用〈回到〉。人从一个地方去另一个地方不说“改成”，应说“回到了家里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶把旧被子改成为了坐垫。", "corrected_sentence": "奶奶把旧被子改成了坐垫。", "error_description": "多了“为”：「改成为了坐垫」应为「改成了坐垫」。“改成”的“成”已表示变作，后面不必再加“为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把毛衣改成着背心。", "corrected_sentence": "他把毛衣改成了背心。", "error_description": "“了”误用为“着”：「改成着背心」应为「改成了背心」。“着”表示状态持续，这里指已完成的变化，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
