INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "抽水机是一种机器，能把水从低处抽到高处。", "primary_collocate": null, "pronunciation": "chōu shuǐ jī", "ipa": "tʂʰou˥ ʂwei˨˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "老师说，抽水机能把水抽到高处。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的菜地离河很远，我们用抽水机浇水。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在水井旁装了一台抽水机，用来取水。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水太少，他们用抽水机把水抽到田里。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽水机一直响，水从下面慢慢往上走。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开抽水机以前，要先检查一下管子。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地里太干了，农民开着抽水机浇地。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水井太深，用手提水很累，有了抽水机就方便多了。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽水机坏了，水上不来，大家只好去河边提水。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台抽水机很小，只能把水抽到二楼。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "电动抽水机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把水从低处抽到高处的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽水机", "is_correct": true, "explanation": "正确。抽水机是能把水抽到高处的机器，与句意相符。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯用来运送人或货物，不能把水抽到高处。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“把水抽到高处”需要机械作施事，“椅子”不能作这一动作的主语。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包用来装东西，不能把水抽到高处。"}], "explanations": {"抽水机": "正确。抽水机是能把水抽到高处的机器，与句意相符。", "电梯": "语义：电梯用来运送人或货物，不能把水抽到高处。", "椅子": "配价：“把水抽到高处”需要机械作施事，“椅子”不能作这一动作的主语。", "书包": "语义：书包用来装东西，不能把水抽到高处。"}, "sentence_index": 0, "correct_answer": "抽水机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用抽水机洗衣服。", "explanation": "这里应该用〈洗衣机〉。洗衣机用来洗衣服，抽水机只能把水抽到高处，不能洗衣服。"}, {"text": "农民挑着抽水机去河边挑水。", "explanation": "这里应该用〈水桶〉。挑水要用水桶等盛器，抽水机是抽水的机器，不能拿来挑。"}, {"text": "渔民撒下抽水机捕鱼。", "explanation": "这里应该用〈渔网〉。抽水机只用来抽水，不能用来捕鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽水机", "is_correct": true, "explanation": "正确。“开着抽水机”符合机器的用法，与浇地的语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来冷藏食物，不能用来浇地。"}, {"text": "水井", "is_correct": false, "explanation": "搭配：“开”后接的是机器或设备，不说“开水井”。"}, {"text": "手电筒", "is_correct": false, "explanation": "语义：手电筒用来照明，不能用来浇地。"}], "explanations": {"抽水机": "正确。“开着抽水机”符合机器的用法，与浇地的语境相符。", "冰箱": "语义：冰箱用来冷藏食物，不能用来浇地。", "水井": "搭配：“开”后接的是机器或设备，不说“开水井”。", "手电筒": "语义：手电筒用来照明，不能用来浇地。"}, "sentence_index": 6, "correct_answer": "抽水机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天家里开抽水机取暖。", "explanation": "这里应该用〈暖气〉。抽水机只能抽水，不能用来取暖。"}, {"text": "家里用抽水机冷藏食品。", "explanation": "这里应该用〈冷柜〉。抽水机不能冷藏食品，它的作用是把水抽到高处。"}, {"text": "工厂用抽水机供电。", "explanation": "这里应该用〈发电机〉。抽水机不能发电，只能抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽水机前天就了开，水一直往上走。", "corrected_sentence": "抽水机前天就开了，水一直往上走。", "error_description": "“了”应放在动词“开”之后，表示动作已经发生，应说“就开了”。“了开”把“了”放在动词前，不符合汉语语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用一只抽水机把水抽到了二楼。", "corrected_sentence": "他们用一台抽水机把水抽到了二楼。", "error_description": "量词错误：抽水机是机器，量词应用“台”，不能用“只”。应说“一台抽水机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
