INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水库是存很多水的大水池。", "primary_collocate": null, "pronunciation": "shuǐ kù", "ipa": "ʂweɪ˨˩˦ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "我家附近有一座很大的水库。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们去水库边钓鱼。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水库里有很多鱼，水也很干净。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天很热，水库边上有很多人。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座水库的水是从山上流下来的。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水库太深了，孩子不能下去游泳。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水库那边风景很美，我们拍了很多照片。", "target_word": "水库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带着我绕水库走了一圈。", "target_word": "水库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我常去水库玩水。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天水库的水很冷，没有人游泳。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "水库大坝", "label": "复合"}, {"form": "水庫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "存放大量水的大水池，常是人们钓鱼、游玩的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水库", "is_correct": true, "explanation": "正确：“一座很大的”修饰大型的水体或设施，符合“我家附近”的语境。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：沙发的量词是“张”，不能说“一座很大的沙发”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以用“座”计数的具体事物，“一座很大的天空”说不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是液体，不能用“座”来计量，“一座很大的牛奶”不合语境。"}], "explanations": {"水库": "正确：“一座很大的”修饰大型的水体或设施，符合“我家附近”的语境。", "沙发": "搭配：沙发的量词是“张”，不能说“一座很大的沙发”。", "天空": "语义：天空不是可以用“座”计数的具体事物，“一座很大的天空”说不通。", "牛奶": "语义：牛奶是液体，不能用“座”来计量，“一座很大的牛奶”不合语境。"}, "sentence_index": 0, "correct_answer": "水库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在厨房的水库里洗碗。", "explanation": "这里应该用〈水池〉。水库是存放大量水的大型水体，不在厨房里；厨房里洗碗用的是水池。"}, {"text": "我每天晚上在水库里泡澡，很放松。", "explanation": "这里应该用〈浴缸〉。泡澡要用浴缸，水库是大型蓄水工程，不能用来泡澡。"}, {"text": "客厅的水库里养着几条金鱼。", "explanation": "这里应该用〈鱼缸〉。养金鱼要用鱼缸，水库是大型水体，不会放在客厅里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水库", "is_correct": true, "explanation": "正确：“那边”指有景色的地方，水库边风景美，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是风景地，“厨房那边风景很美”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以说“那边风景很美”的地方。"}, {"text": "洗衣机", "is_correct": false, "explanation": "搭配：“风景很美”搭配的是自然景色或地点，洗衣机是家电，不能这样说。"}], "explanations": {"水库": "正确：“那边”指有景色的地方，水库边风景美，符合语境。", "厨房": "语义：厨房不是风景地，“厨房那边风景很美”说不通。", "冰箱": "语义：冰箱是家电，不是可以说“那边风景很美”的地方。", "洗衣机": "搭配：“风景很美”搭配的是自然景色或地点，洗衣机是家电，不能这样说。"}, "sentence_index": 6, "correct_answer": "水库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在水库里上课。", "explanation": "这里应该用〈教室〉。水库是蓄水的大水池，不能用来上课；上课要在教室里。"}, {"text": "这座水库很长，流过了好几个村庄。", "explanation": "这里应该用〈河流〉。河流会流动、流过村庄；水库是静止的蓄水体，不能说流过村庄。"}, {"text": "我把水库放进冰箱里冷藏。", "explanation": "这里应该用〈矿泉水〉。水库是大型水体，不能放进冰箱；能放进冰箱冷藏的是瓶装的矿泉水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家北边有一张很大的水库。", "corrected_sentence": "我家北边有一座很大的水库。", "error_description": "“水库”的量词应用“座”，不能用“张”（“张”多用于平面的东西）。错误形式：一张很大的水库；正确形式：一座很大的水库。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹带着狗绕水库们跑了两圈。", "corrected_sentence": "妹妹带着狗绕水库跑了两圈。", "error_description": "“水库”是非人名词，不能加“们”表示复数。错误形式：绕水库们跑；正确形式：绕水库跑。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
