INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水资源指自然界中可供人类使用的水。", "primary_collocate": null, "pronunciation": "shuǐ zī yuán", "ipa": "ʂweɪ˨˩˦ tsɨ˥ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "我们国家的水资源不太多。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的水资源比南方少。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都应该节约水资源。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市缺少水资源。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂不能污染水资源。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水资源对农业非常重要。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖泊是当地重要的水资源。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护水资源，不要浪费水。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水资源少的地方，人们用水都很节约。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了世界水资源的情况。", "target_word": "水资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水资源保护", "label": "复合词"}, {"form": "水資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自然界中可供人类使用的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水资源", "is_correct": true, "explanation": "水资源指自然界中可供人类使用的水，「我们国家的水资源不太多」意思通顺，正确。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的情绪，不能说「不太多」，与国家的情况不合。"}, {"text": "性格", "is_correct": false, "explanation": "语义：「性格」是人的性情，与国家的自然资源无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指人的身体高度，不能用来说国家的情况。"}], "explanations": {"水资源": "水资源指自然界中可供人类使用的水，「我们国家的水资源不太多」意思通顺，正确。", "心情": "语义：「心情」是人的情绪，不能说「不太多」，与国家的情况不合。", "性格": "语义：「性格」是人的性情，与国家的自然资源无关。", "身高": "体貌：「身高」指人的身体高度，不能用来说国家的情况。"}, "sentence_index": 0, "correct_answer": "水资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把水资源打碎了。", "explanation": "这里应该用〈玻璃杯〉。「水资源」指可利用的水，是抽象的总量，不是能打碎的实物，此处用错了词义。"}, {"text": "他在水资源里钓鱼。", "explanation": "这里应该用〈池塘〉。「水资源」是抽象的概念，不是可以钓鱼的地方，此处用错了词义。"}, {"text": "这个水资源很甜。", "explanation": "这里应该用〈苹果〉。「水资源」指水的总量，不能用来形容味道，此处用错了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水资源", "is_correct": true, "explanation": "水资源指可供人类使用的水，「湖泊是当地重要的水资源」意思通顺，正确。"}, {"text": "节日", "is_correct": false, "explanation": "语义：湖泊不是节日，「湖泊是当地重要的节日」说不通。"}, {"text": "科目", "is_correct": false, "explanation": "搭配：「科目」指学习内容，不能用来指湖泊，与「重要的」搭配也不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：湖泊是自然地理事物，不是手机，句意不通。"}], "explanations": {"水资源": "水资源指可供人类使用的水，「湖泊是当地重要的水资源」意思通顺，正确。", "节日": "语义：湖泊不是节日，「湖泊是当地重要的节日」说不通。", "科目": "搭配：「科目」指学习内容，不能用来指湖泊，与「重要的」搭配也不通。", "手机": "语义：湖泊是自然地理事物，不是手机，句意不通。"}, "sentence_index": 6, "correct_answer": "水资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃水资源。", "explanation": "这里应该用〈米饭〉。「水资源」指可利用的水，不是食物，不能用来指吃的东西，此处用错了词义。"}, {"text": "他的水资源坏了。", "explanation": "这里应该用〈汽车〉。「水资源」指可利用的水，不能用来指机器或东西坏了，此处用错了词义。"}, {"text": "他的水资源很高兴。", "explanation": "这里应该用〈朋友〉。「水资源」是水的总量，没有情绪，不能用来描述人高兴，此处用错了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区有一座宝贵的水资源。", "corrected_sentence": "这个地区有一种宝贵的水资源。", "error_description": "错误：「一座」。正确：「一种」。「座」用于山、房屋等大型固定物，「水资源」要用「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都要珍惜水资源们。", "corrected_sentence": "大家都要珍惜水资源。", "error_description": "错误：「水资源们」。「们」只加在指人或动物的名词后，「水资源」是抽象的总称，不能加「们」。正确：「大家都要珍惜水资源」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
