INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方的管理组织。", "primary_collocate": null, "pronunciation": "dāng dì zhèng fǔ", "ipa": "tɑŋ˥ ti˥˩ ʈʂɤŋ˥˩ fu˨˩˦", "syllable_count": 4, "sentences": [{"text": "当地政府的办公楼就在市中心。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在当地政府工作了十年。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府决定让公园门票免费。", "target_word": "当地政府", "complexity_tier": "T3", "furigana": "dāngdì zhèngfǔ juédìng ràng gōngyuán ménpiào miǎnfèi.", "sentence_source": "generated"}, {"text": "这位老师带学生去当地政府参观。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府正在帮农民卖水果。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想请当地政府帮忙找房子。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府发出通知，明天学校放假。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府为新来的居民办了登记。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有问题可以去找当地政府。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府每年都会办一次新年活动。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某个地方的管理组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会拥有办公楼，句子说不通。"}, {"text": "当地政府", "is_correct": true, "explanation": "正确：当地政府是机构，有办公楼；“市中心”的位置也符合句意。"}, {"text": "农民", "is_correct": false, "explanation": "搭配：“办公楼”属于机关、单位，个人不说“农民的办公楼”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有办公楼，句子不成立。"}], "explanations": {"小猫": "语义：小猫不会拥有办公楼，句子说不通。", "当地政府": "正确：当地政府是机构，有办公楼；“市中心”的位置也符合句意。", "农民": "搭配：“办公楼”属于机关、单位，个人不说“农民的办公楼”。", "石头": "语义：石头没有办公楼，句子不成立。"}, "sentence_index": 0, "correct_answer": "当地政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当地政府每天早上六点就起床了。", "explanation": "这里应该用〈当地居民〉。政府是机构，不会“起床”，说人的作息要用“当地居民”。"}, {"text": "当地政府每天骑自行车上学。", "explanation": "这里应该用〈当地学生〉。政府是机构，不会骑车上学，说学生上学要用“当地学生”。"}, {"text": "当地政府都喜欢吃辣的。", "explanation": "这里应该用〈当地人〉。当地政府是机构，不能说“喜欢吃”，说人的饮食习惯要用“当地人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不能发出通知，句子说不通。"}, {"text": "居民", "is_correct": false, "explanation": "搭配：“发出通知”多指机关、单位，个人居民不说“居民发出通知”。"}, {"text": "当地政府", "is_correct": true, "explanation": "正确：政府机构可以发出通知，“明天学校放假”的决定由它宣布，句意通顺。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不会发出通知，句子不成立。"}], "explanations": {"西瓜": "语义：西瓜不能发出通知，句子说不通。", "居民": "搭配：“发出通知”多指机关、单位，个人居民不说“居民发出通知”。", "当地政府": "正确：政府机构可以发出通知，“明天学校放假”的决定由它宣布，句意通顺。", "课本": "语义：课本不会发出通知，句子不成立。"}, "sentence_index": 6, "correct_answer": "当地政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈上周去当地政府看病。", "explanation": "这里应该用〈当地医院〉。政府是管理机构，不是看病的地方，看病要去“当地医院”。"}, {"text": "周末我常去当地政府买菜。", "explanation": "这里应该用〈当地超市〉。政府不是卖菜的地方，买菜要去“当地超市”。"}, {"text": "当地政府每周末在酒吧演出。", "explanation": "这里应该用〈当地乐队〉。政府不会在酒吧演出，乐队演出要用“当地乐队”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她当地政府工作了五年。", "corrected_sentence": "她在当地政府工作了五年。", "error_description": "错误：“她当地政府工作了五年”；正确：“她在当地政府工作了五年”。表示工作地点的“在”不能省略，“在……工作”是固定的处所结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条当地政府去年为居民办了很多活动。", "corrected_sentence": "当地政府去年为居民办了很多活动。", "error_description": "错误：“一条当地政府”；正确：“当地政府”。“条”用于细长的东西，不能修饰机构；这里直接说“当地政府”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
