INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "科技就是让人生活更方便的新东西，比如手机和电脑。", "primary_collocate": null, "pronunciation": "xiàn dài kē jì", "ipa": "ɕjɛn˥˩ taɪ˥˩ kʰɤ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "手机和电脑都是现代科技的产物。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代科技让买东西变得很方便。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我奶奶开始学用现代科技，比如视频电话。", "target_word": "现代科技", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代科技给我们带来了很多新东西。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为有现代科技，用手机就能付钱。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很喜欢现代科技，常常买新手机。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代科技使我们不出门也能买菜。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小孩对现代科技很感兴趣，总是玩平板电脑。", "target_word": "现代科技", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代科技走进了每个家庭。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得现代科技让生活更好了吗？", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代科技", "label": "繁体"}, {"form": "现代科技产品", "label": "复合"}], "register": "中性", "sense_fingerprint": "让生活更方便的新东西，如手机和电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代科技", "is_correct": true, "explanation": "正确。手机和电脑是现代科技的产物，句子的语义和搭配都合适。"}, {"text": "古代文物", "is_correct": false, "explanation": "语义：手机和电脑是现代的产品，不可能是古代文物的产物，句子不符合事实。"}, {"text": "体育运动", "is_correct": false, "explanation": "语义：手机和电脑不是体育运动的产物，两者之间没有这种关系。"}, {"text": "俚语", "is_correct": false, "explanation": "语义：俚语是一种说话方式，不能生产手机和电脑，句子不成立。"}], "explanations": {"现代科技": "正确。手机和电脑是现代科技的产物，句子的语义和搭配都合适。", "古代文物": "语义：手机和电脑是现代的产品，不可能是古代文物的产物，句子不符合事实。", "体育运动": "语义：手机和电脑不是体育运动的产物，两者之间没有这种关系。", "俚语": "语义：俚语是一种说话方式，不能生产手机和电脑，句子不成立。"}, "sentence_index": 0, "correct_answer": "现代科技"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家买了一朵现代科技。", "explanation": "这里应该用〈手机〉之类的具体产品。现代科技是抽象名词，不能用量词“朵”来计数，“朵”只用于花、云等。"}, {"text": "晚上电视里播放了现代科技。", "explanation": "这里应该用〈节目〉。电视播放的是节目，现代科技指技术和产品，不能被“播放”。"}, {"text": "他是一个很厉害的现代科技。", "explanation": "现代科技指技术或产品，不能指人，不能用“一个很厉害的……”来修饰人。指人应使用〈工程师〉这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代科技", "is_correct": true, "explanation": "正确。现代科技可以让人不出门就能买菜，句子的因果关系和搭配都合适。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不会让人不出门就能买菜，这个因果关系不成立，句子读起来不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是灾害，不会让人不出门也能买菜，与句子表达的便利正好相反。"}, {"text": "学术论文", "is_correct": false, "explanation": "语义：学术论文是文章，不能让人不出门就买到菜，因果关系不成立。"}], "explanations": {"现代科技": "正确。现代科技可以让人不出门就能买菜，句子的因果关系和搭配都合适。", "春天": "语义：春天不会让人不出门就能买菜，这个因果关系不成立，句子读起来不通。", "地震": "语义：地震是灾害，不会让人不出门也能买菜，与句子表达的便利正好相反。", "学术论文": "语义：学术论文是文章，不能让人不出门就买到菜，因果关系不成立。"}, "sentence_index": 6, "correct_answer": "现代科技"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议的现代科技很热烈。", "explanation": "这里应该用〈气氛〉。“热烈”形容气氛或场面，现代科技不能用“热烈”来形容。"}, {"text": "这位现代科技很有经验。", "explanation": "这里应该用〈专家〉。“有经验”说的是人，现代科技是技术领域，不能有经验。"}, {"text": "这家商场引进了一座现代科技。", "explanation": "这里应该用〈项〉。〈座〉用于山、桥、建筑等大型固定物，现代科技不能用“座”来计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学现代科技学的很快。", "corrected_sentence": "他学现代科技学得很快。", "error_description": "结构助词错误：动词与补语之间应用“得”，不能用“的”。正确的说法是“他学现代科技学得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一只现代科技来学习。", "corrected_sentence": "他用一种现代科技来学习。", "error_description": "量词错误：〈只〉用于动物或成对的东西，现代科技这类技术应该用〈种〉。正确的说法是“他用一种现代科技来学习。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
