INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看别人说的话或做的事来想自己该怎么做。", "primary_collocate": null, "pronunciation": "cān kǎo", "ipa": "tsʰan˥ kʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "做决定前，我想参考你的意见。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参考朋友的做法，也开始早起。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以参考一下他的经验。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子时，她参考了家人的建议。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的看法，我都会参考。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想参考一下别人是怎么做的。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参考同学的办法，解决了问题。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先参考一下同事的意见。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参考了哥哥的选择，决定学中文。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你参考过别人的做法吗？", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参考了", "label": "完成体"}, {"form": "参考过", "label": "经历体"}, {"form": "参考着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "借鉴别人的话或做法来决定自己怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正确：“参考”表示借鉴别人的意见来决定自己的做法，与“做决定前”的语境相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示喜庆，与“做决定前，我想……你的意见”的语境不符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能以“意见”为宾语。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”用于器物，不能与“意见”搭配。"}], "explanations": {"参考": "正确：“参考”表示借鉴别人的意见来决定自己的做法，与“做决定前”的语境相合。", "庆祝": "语义：“庆祝”表示喜庆，与“做决定前，我想……你的意见”的语境不符。", "吃": "配价：“吃”的宾语应是食物，不能以“意见”为宾语。", "擦亮": "搭配：“擦亮”用于器物，不能与“意见”搭配。"}, "sentence_index": 0, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向医生参考了病情。", "explanation": "这里应该用〈咨询〉。咨询指向医生请教，参考指查阅资料或借鉴经验，不能对医生使用。"}, {"text": "他昨天参考了一场婚礼。", "explanation": "这里应该用〈参加〉。参加指加入某个活动，参考指借鉴或查阅，不能用于参与婚礼。"}, {"text": "这部电影我想参考给你。", "explanation": "这里应该用〈推荐〉。推荐指把好的作品介绍给别人，参考不能用于介绍给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正确：“参考”表示借鉴别人的办法，与“解决了问题”的结果相合。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”指延迟，不能用来指借鉴别人的办法，与“解决了问题”矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，不能以“办法”为宾语。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能以“办法”为宾语，句子不成立。"}], "explanations": {"参考": "正确：“参考”表示借鉴别人的办法，与“解决了问题”的结果相合。", "拖延": "语义：“拖延”指延迟，不能用来指借鉴别人的办法，与“解决了问题”矛盾。", "喝": "配价：“喝”的宾语应是饮品，不能以“办法”为宾语。", "唱": "配价：“唱”不能以“办法”为宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参考过很多社会活动。", "explanation": "这里应该用〈参与〉。参与指加入某项活动，参考不能用来指参加社会活动。"}, {"text": "他参考过两次马拉松。", "explanation": "这里应该用〈参赛〉。参赛指以选手身份参加比赛，参考不能指参加比赛。"}, {"text": "我参考过他的电话。", "explanation": "这里应该用〈接〉。参考指借鉴或查阅，不能用来表示接听别人的电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做决定前，我想参考了你的意见。", "corrected_sentence": "做决定前，我想参考一下你的意见。", "error_description": "错误：“想”表示打算，“参考了”表示动作已完成，与句意矛盾。应改为“参考一下”，表示试着参考。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没参考了同学的做法。", "corrected_sentence": "我没参考过同学的做法。", "error_description": "助词错误：“没”后面表示未曾经历的动作要用“过”，不能用“了”。正确的说法是“我没参考过同学的做法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
