INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25252, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25252, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人在一起生活或做事情时，彼此对待的方式。", "primary_collocate": null, "pronunciation": "xiāng chǔ", "ipa": "ɕiɑŋ˥ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们是室友，相处得很愉快。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻相处，最重要的是互相尊重。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥小时候总是相处不好。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对朋友一起旅行，相处得很轻松。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新婚夫妻怎么相处，是个大问题。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和婆婆相处得像母女一样。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在一起以后，我们才知道怎么相处。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起工作两年，相处得不错。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你和室友相处得怎么样？", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脾气好，跟谁都相处得来。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相处了", "label": "完成体"}, {"form": "相处过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "共同生活或做事时彼此的对待方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相处", "is_correct": true, "explanation": "正确。两个室友共同生活，“相处得很愉快”符合语境，语义和搭配都合适。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：“争吵得很愉快”自相矛盾，与“愉快”的语境不符。"}, {"text": "失散", "is_correct": false, "explanation": "语义：“失散”指分开后失去联系，与“住在一起”“相处得很愉快”的语境都相矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹得很愉快”与“愉快”相冲突，也不符合室友共同生活的语境。"}], "explanations": {"相处": "正确。两个室友共同生活，“相处得很愉快”符合语境，语义和搭配都合适。", "争吵": "语义：“争吵得很愉快”自相矛盾，与“愉快”的语境不符。", "失散": "语义：“失散”指分开后失去联系，与“住在一起”“相处得很愉快”的语境都相矛盾。", "吵闹": "语义：“吵闹得很愉快”与“愉快”相冲突，也不符合室友共同生活的语境。"}, "sentence_index": 0, "correct_answer": "相处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师相处学生很认真。", "explanation": "这里应该用〈对待〉。“相处”指双方之间的相处关系，不能直接带“学生”作宾语，老师对学生的态度要用〈对待〉。"}, {"text": "妈妈相处生病的爸爸很耐心。", "explanation": "这里应该用〈照顾〉。“相处”不能带“生病的爸爸”作宾语，照顾病人要用〈照顾〉。"}, {"text": "两人相处了很多合同。", "explanation": "这里应该用〈签订〉。“相处”不能带“合同”作宾语，两人签订合同要用〈签订〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相处", "is_correct": true, "explanation": "正确。住在一起以后才学会与人共处的方式，“怎么相处”与句子的语义相合。"}, {"text": "分居", "is_correct": false, "explanation": "语义：“住在一起”之后说“怎么分居”，与句中的共同生活相矛盾。"}, {"text": "失散", "is_correct": false, "explanation": "语义：“失散”指分开后失去联系，与“住在一起以后”的语境相矛盾，句子读起来不通。"}, {"text": "发胖", "is_correct": false, "explanation": "语义：“发胖”说的是体形变化，与“住在一起以后才知道怎么……”的人际语境无关，句子不通。"}], "explanations": {"相处": "正确。住在一起以后才学会与人共处的方式，“怎么相处”与句子的语义相合。", "分居": "语义：“住在一起”之后说“怎么分居”，与句中的共同生活相矛盾。", "失散": "语义：“失散”指分开后失去联系，与“住在一起以后”的语境相矛盾，句子读起来不通。", "发胖": "语义：“发胖”说的是体形变化，与“住在一起以后才知道怎么……”的人际语境无关，句子不通。"}, "sentence_index": 6, "correct_answer": "相处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家相处了一个问题。", "explanation": "这里应该用〈讨论〉。“相处”不能带“问题”作宾语，谈论问题要用〈讨论〉。"}, {"text": "酒店相处了很多客人。", "explanation": "这里应该用〈接待〉。“相处”说的是双方共同生活或交往的关系，不表示招待客人，要用〈接待〉。"}, {"text": "他们很快相处了任务。", "explanation": "这里应该用〈完成〉。“相处”不能带“任务”作宾语，完成任务要用〈完成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和舍友没有相处了。", "corrected_sentence": "我和舍友没有相处过。", "error_description": "助词错误：“没有”后面表示未曾经历的动作要用“过”，不能用“了”。正确的说法是“我和舍友没有相处过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在一起相处的很愉快。", "corrected_sentence": "他们在一起相处得很愉快。", "error_description": "结构助词错误：动词后表示程度的补语要用“得”，不能用“的”。正确的说法是“他们在一起相处得很愉快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
