INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西里含有的水。", "primary_collocate": null, "pronunciation": "shuǐ fèn", "ipa": "ʂweɪ˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "西红柿里有很多水分。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把湿毛巾拧一拧，水分就少了。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干果的水分比新鲜水果少得多。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭里的水分太多，吃起来很软。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头水分太多，不能马上做桌子。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天出汗多，要多喝水来补充水分。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒了很久，肉里的水分都没有了。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄瓜的水分很足，吃起来很脆。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的土水分太少，花会枯死。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面条煮好后，先把水分沥干。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "水分：东西里含有的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a9e316-c77e-4d87-af76-e864fd5a52f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水分", "is_correct": true, "explanation": "正确答案，指东西里含有的水。"}, {"text": "水费", "is_correct": false, "explanation": "fèi（第四声）与 fèn（第四声）韵尾不同（i 与 n），意思是水费。"}, {"text": "水粉", "is_correct": false, "explanation": "fěn（第三声）与 fèn（第四声）声调不同，意思是水粉颜料。"}, {"text": "水嫩", "is_correct": false, "explanation": "nèn 与 fèn 声母不同（n 与 f），意思是水嫩。"}], "explanations": {"水分": "正确答案，指东西里含有的水。", "水费": "fèi（第四声）与 fèn（第四声）韵尾不同（i 与 n），意思是水费。", "水粉": "fěn（第三声）与 fèn（第四声）声调不同，意思是水粉颜料。", "水嫩": "nèn 与 fèn 声母不同（n 与 f），意思是水嫩。"}, "sentence_index": null, "correct_answer": "水分"}, "level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "正确：“水分”指东西里含有的水，“西红柿里有很多水分”符合语境。"}, {"text": "电池", "is_correct": false, "explanation": "语义：西红柿里不会含有电池，与西红柿的组成不符。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是金属零件，西红柿里不会有螺丝。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是电器，西红柿里不会有空调。"}], "explanations": {"水分": "正确：“水分”指东西里含有的水，“西红柿里有很多水分”符合语境。", "电池": "语义：西红柿里不会含有电池，与西红柿的组成不符。", "螺丝": "语义：螺丝是金属零件，西红柿里不会有螺丝。", "空调": "语义：空调是电器，西红柿里不会有空调。"}, "sentence_index": 0, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，想喝一杯水分。", "explanation": "这里应该用〈水〉。水分指东西里含有的水成分，不能直接拿来喝。"}, {"text": "这道菜的水分很鲜。", "explanation": "这里应该用〈味道〉。“鲜”形容味道，水分只指所含的水，不能用来描述鲜美。"}, {"text": "这块蛋糕的水分很软。", "explanation": "这里应该用〈口感〉。软硬是口感的特点，水分不能用来描述软硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "正确：炒肉时肉里所含的水分会减少，“水分都没有了”说得通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：肉里不含歌曲，“肉里的歌曲都没有了”语义不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是肉的组成部分，与“炒”的语境不合。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是肉的组成部分，“肉里的闹钟都没有了”语义不通。"}], "explanations": {"水分": "正确：炒肉时肉里所含的水分会减少，“水分都没有了”说得通。", "歌曲": "语义：肉里不含歌曲，“肉里的歌曲都没有了”语义不通。", "钥匙": "语义：钥匙不是肉的组成部分，与“炒”的语境不合。", "闹钟": "语义：闹钟不是肉的组成部分，“肉里的闹钟都没有了”语义不通。"}, "sentence_index": 6, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水分很甜，喝起来很爽口。", "explanation": "这里应该用〈果汁〉。“甜”形容果汁等的味道，水分只指所含的水成分，不能说“水分很甜”。"}, {"text": "水分很硬，敲上去会响。", "explanation": "这里应该用〈石头〉。“硬”形容固体的质地，水分是所含的水成分，不能说“水分很硬”。"}, {"text": "水分很冷，拿在手里很舒服。", "explanation": "这里应该用〈冰〉。“冷”形容温度，水分是所含的水成分，不能说“水分很冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "植物缺水时，要给土壤补充一个水分。", "corrected_sentence": "植物缺水时，要给土壤补充一点水分。", "error_description": "量词错误：“水分”前应用量词“点”，说“一点水分”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天出汗多，要多吃水分。", "corrected_sentence": "夏天出汗多，要多补充水分。", "error_description": "“吃”不能与“水分”搭配，应说“补充水分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
