INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西很少，不够用。", "primary_collocate": null, "pronunciation": "xī quē xìng", "ipa": "ɕi˥ tɕʰɥe˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "水很少，这就是水的稀缺性。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的稀缺性，让它特别贵。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了资源的稀缺性。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西的稀缺性越大，价格越高。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里水的稀缺性非常明显。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钻石的稀缺性是它值钱的原因。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要认识到纸张的稀缺性，不要浪费。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品的稀缺性让病人很着急。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为座位的稀缺性，好位子很快就卖完了。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电的稀缺性让工厂常常停工。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "东西很少、不够用的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺性", "is_correct": true, "explanation": "正确。前句说“水很少”，“稀缺性”正好说明东西少、不够用。"}, {"text": "充裕性", "is_correct": false, "explanation": "语义：“充裕性”指足够多，与前句“水很少”的语境矛盾。"}, {"text": "便利性", "is_correct": false, "explanation": "搭配：“便利性”多指使用起来方便，不说“水的便利性”。"}, {"text": "多样性", "is_correct": false, "explanation": "语义：“多样性”指种类多，与“水很少”的语境不符。"}], "explanations": {"稀缺性": "正确。前句说“水很少”，“稀缺性”正好说明东西少、不够用。", "充裕性": "语义：“充裕性”指足够多，与前句“水很少”的语境矛盾。", "便利性": "搭配：“便利性”多指使用起来方便，不说“水的便利性”。", "多样性": "语义：“多样性”指种类多，与“水很少”的语境不符。"}, "sentence_index": 0, "correct_answer": "稀缺性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村的水出现了稀缺性。", "explanation": "这里应该用〈短缺〉。“稀缺性”指东西本身少的属性，不说“出现稀缺性”；供应不够的状况要用“短缺”。"}, {"text": "这种稀缺性的味道很甜。", "explanation": "这里应该用〈水果〉。“稀缺性”指东西少的属性，没有味道，不能说很甜。"}, {"text": "我买了很多稀缺性。", "explanation": "“稀缺性”是东西少的属性，不是可以买的东西；应说“买了很多稀缺的东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺性", "is_correct": true, "explanation": "正确。后句“不要浪费”提示纸张少，需要珍惜，与“稀缺性”的含义吻合。"}, {"text": "透明性", "is_correct": false, "explanation": "语义：「透明性」指能透光，与「不要浪费」的劝告无关，句意不通。"}, {"text": "普遍性", "is_correct": false, "explanation": "语义：“普遍性”指到处都有，与“不要浪费”的语境不符。"}, {"text": "时效性", "is_correct": false, "explanation": "搭配：“时效性”多用于信息、政策，不说“纸张的时效性”。"}], "explanations": {"稀缺性": "正确。后句“不要浪费”提示纸张少，需要珍惜，与“稀缺性”的含义吻合。", "透明性": "语义：「透明性」指能透光，与「不要浪费」的劝告无关，句意不通。", "普遍性": "语义：“普遍性”指到处都有，与“不要浪费”的语境不符。", "时效性": "搭配：“时效性”多用于信息、政策，不说“纸张的时效性”。"}, "sentence_index": 6, "correct_answer": "稀缺性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种稀缺性很便宜。", "explanation": "这里应该用〈药〉。“稀缺性”指东西少的属性，不是可以买卖的东西，不能说很便宜。"}, {"text": "他的稀缺性让同学们很佩服。", "explanation": "“稀缺性”指东西少的属性，不用来形容人；说人的才能要用“难得”。"}, {"text": "这首歌的稀缺性很好听。", "explanation": "这里应该用〈声音〉。“稀缺性”指东西少的属性，不能用来形容声音好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子里，水稀缺性越来越明显。", "corrected_sentence": "这个村子里，水的稀缺性越来越明显。", "error_description": "“水”和“稀缺性”之间要用“的”连接，省略后“水稀缺性”不成词。正确形式：水的稀缺性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只稀缺性让工厂很为难。", "corrected_sentence": "这种稀缺性让工厂很为难。", "error_description": "“稀缺性”是抽象名词，量词应用“种”，不能用“只”（“只”用于动物等）。正确形式：这种稀缺性。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
