INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方很少下雨，土地很干，植物很难长。", "primary_collocate": null, "pronunciation": "gān hàn dì qū", "ipa": "kan˥ xan˥˩ ti˥˩ tɕʰy˥", "syllable_count": 4, "sentences": [{"text": "干旱地区的夏天又热又干。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在干旱地区工作了五年。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱地区的河很少，水很宝贵。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个干旱地区一年几乎不下雨。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在干旱地区，人们很节约用水。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片干旱地区的土地很硬，草也长不好。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想帮助干旱地区的孩子喝上干净水。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱地区常常刮大风，天空都是黄沙。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在干旱地区种了很多树。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上黄色的部分是干旱地区。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "干旱区", "label": "复合"}], "register": "中性", "sense_fingerprint": "很少下雨、土地干、植物难长的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "北极", "is_correct": false, "explanation": "语义：北极的夏天寒冷，与“又热又干”的描述矛盾。"}, {"text": "雨林", "is_correct": false, "explanation": "语义：雨林潮湿多雨，与“又干”的描述矛盾。"}, {"text": "干旱地区", "is_correct": true, "explanation": "正确。干旱地区的夏天又热又干，符合描述。"}, {"text": "湿地", "is_correct": false, "explanation": "搭配：“湿地”通常与潮湿搭配，与“又热又干”不搭。"}], "explanations": {"北极": "语义：北极的夏天寒冷，与“又热又干”的描述矛盾。", "雨林": "语义：雨林潮湿多雨，与“又干”的描述矛盾。", "干旱地区": "正确。干旱地区的夏天又热又干，符合描述。", "湿地": "搭配：“湿地”通常与潮湿搭配，与“又热又干”不搭。"}, "sentence_index": 0, "correct_answer": "干旱地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一片干旱地区里迷了路，四周都是绿树。", "explanation": "这里应该用〈森林〉。干旱地区指少雨、植物难长的地方，四周绿树成荫要说森林。"}, {"text": "我家门口的草场是一片干旱地区，草长得特别茂盛。", "explanation": "这里应该用〈绿洲〉。干旱地区指缺水、植物难长的地方，草长得特别茂盛的地方要说绿洲。"}, {"text": "这个地方是一个干旱地区，每天都下暴雨。", "explanation": "这里应该用〈多雨地区〉。干旱地区指很少下雨的地方，每天下暴雨要说多雨地区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月球", "is_correct": false, "explanation": "语义：月球上没有生活的孩子，与“喝上干净水”的现实语境不符。"}, {"text": "干旱地区", "is_correct": true, "explanation": "正确。帮助干旱地区的孩子喝上干净水，符合这句话的语境。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底没有生活的孩子，与“喝上干净水”的语境不符。"}, {"text": "童话里", "is_correct": false, "explanation": "语义：童话里的孩子是虚构的，不能真正帮助他们喝上干净水。"}], "explanations": {"月球": "语义：月球上没有生活的孩子，与“喝上干净水”的现实语境不符。", "干旱地区": "正确。帮助干旱地区的孩子喝上干净水，符合这句话的语境。", "海底": "语义：海底没有生活的孩子，与“喝上干净水”的语境不符。", "童话里": "语义：童话里的孩子是虚构的，不能真正帮助他们喝上干净水。"}, "sentence_index": 6, "correct_answer": "干旱地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一年的干旱地区很严重，庄稼几乎全都死了。", "explanation": "这里应该用〈旱情〉。“干旱地区”指地方，干旱的情况要说旱情。"}, {"text": "这个干旱地区的河道常年水深，船只可以通行。", "explanation": "这里应该用〈水乡〉。干旱地区少雨、土地干，河道水深、船只通行的地方要说水乡。"}, {"text": "我们在山上找到一片干旱地区，脚下全是泥浆。", "explanation": "这里应该用〈沼泽〉。干旱地区少雨、土地干，脚下满是泥浆的地方要说沼泽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座干旱地区的植被很稀少。", "corrected_sentence": "这片干旱地区的植被很稀少。", "error_description": "量词误用：“地区”应用“片”，“座”用于山、楼等，不能修饰地区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "向干旱地区的人来说，水非常重要。", "corrected_sentence": "对干旱地区的人来说，水非常重要。", "error_description": "介词误用：表示看法的对象要说“对……来说”，不能用“向”，应说“对干旱地区的人来说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
