INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人问你话，你回答他。", "primary_collocate": null, "pronunciation": "huí yìng", "ipa": "xweɪ˧˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "朋友叫我的名字，我马上回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在门外喊他，他没有回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师叫我的时候，我小声回应了一句。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我问他去不去，他只是笑，没有回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人敲门，里面有人回应：“请进！”", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你问他话，他应该有礼貌地回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我问了好几遍，弟弟才回应我。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着我，轻轻地回应了一声“好”。", "target_word": "回应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们问好，老师笑着回应。", "target_word": "回应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你回应一下，我在等你的答案。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回应了", "label": "体标（了）"}, {"form": "回应过", "label": "体标（过）"}, {"form": "回应着", "label": "体标（着）"}, {"form": "回應", "label": "繁体"}], "register": "口语", "sense_fingerprint": "别人叫你或问你时，你出声回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c14fd65d-7562-43e3-b9a1-66b88150ec98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回应", "is_correct": true, "explanation": "回应：对别人的叫唤出声答应，与“朋友叫我的名字”的语境相符。"}, {"text": "签字", "is_correct": false, "explanation": "语义：签字是在文件上写名字，与对别人叫名字的应答不相关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与对呼唤的应答不相符，句意不通。"}, {"text": "发言", "is_correct": false, "explanation": "语域：“发言”是正式场合的用语，不适合日常的呼唤应答。"}], "explanations": {"回应": "回应：对别人的叫唤出声答应，与“朋友叫我的名字”的语境相符。", "签字": "语义：签字是在文件上写名字，与对别人叫名字的应答不相关。", "睡觉": "语义：睡觉与对呼唤的应答不相符，句意不通。", "发言": "语域：“发言”是正式场合的用语，不适合日常的呼唤应答。"}, "sentence_index": 0, "correct_answer": "回应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常常回应那次旅行的快乐。", "explanation": "这里应该用〈回味〉。“回味”指回想过去的经历或滋味；“回应”不能表示回想。"}, {"text": "这些旧瓶子应该回应，不要乱扔。", "explanation": "这里应该用〈回收〉。“回收”指把用过的东西收集起来再利用；“回应”不能表示收集。"}, {"text": "放学以后，我马上回应家里去了。", "explanation": "这里应该用〈回〉。“回家”指返回家里；“回应”是对别人的叫唤或问话作出答复，不能表示返回某地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回应", "is_correct": true, "explanation": "回应：这里指弟弟最终对问话出声作出答复，与“问了好几遍”的语境相符。"}, {"text": "追", "is_correct": false, "explanation": "语义：“追”是追赶，与前文“问了好几遍”的语境不符。"}, {"text": "驳斥", "is_correct": false, "explanation": "语域：“驳斥”是书面语，意思是反驳，不适合这里的口语语境。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是动作攻击，与前文问话的语境相矛盾。"}], "explanations": {"回应": "回应：这里指弟弟最终对问话出声作出答复，与“问了好几遍”的语境相符。", "追": "语义：“追”是追赶，与前文“问了好几遍”的语境不符。", "驳斥": "语域：“驳斥”是书面语，意思是反驳，不适合这里的口语语境。", "打": "语义：“打”是动作攻击，与前文问话的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "回应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把教室里太冷的情况回应给了老师。", "explanation": "这里应该用〈反映〉。“反映”指向有关方面陈述情况；“回应”指对别人的话或要求作出反应，不能用于陈述情况。"}, {"text": "这本书我已经回应给图书馆了。", "explanation": "这里应该用〈归还〉。“归还”指把借来的东西还回去；“回应”不能用于还东西。"}, {"text": "同学们都回应他考上了大学，纷纷来道喜。", "explanation": "这里应该用〈祝贺〉。“祝贺”指对别人的喜事表示庆贺；“回应”不能表示庆贺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叫了他三次，他终于回应了了。", "corrected_sentence": "我叫了他三次，他终于回应了。", "error_description": "体标错误：同一个动词后只能用一个动态助词“了”，“回应了了”重复了。应去掉多余的“了”，写成“回应了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在操场上叫他，他轻轻地回应了着。", "corrected_sentence": "同学们在操场上叫他，他轻轻地回应着。", "error_description": "语法错误：“了”和“着”不能同时用在同一个动词后面，这里应只用“着”，写成“回应了着”不对，应为“回应着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
