INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沙漠里有一块有水和草的地方，叫绿洲。", "primary_collocate": null, "pronunciation": "lǜ zhōu", "ipa": "ly˥˩ ʈʂoʊ̯˥˥", "syllable_count": 2, "sentences": [{"text": "沙漠里有水和草的地方叫绿洲。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在沙漠里找到了一块绿洲。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿洲的天气比周围的沙漠凉快。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在绿洲吃饭，喝了很多水。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的绿洲是绿色的小点。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个绿洲有一口井。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的人看见绿洲，高兴极了。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿洲周围都是黄色的沙子。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把帐篷搭在绿洲边。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有绿洲，沙漠里的人很难活下去。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "綠洲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "沙漠里有水有草的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c14fd65d-7562-43e3-b9a1-66b88150ec98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿洲", "is_correct": true, "explanation": "正确。“有水和草的地方”就是绿洲的定义。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干旱缺水，与句中“有水和草”的定义正好相反。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不是以水草丰美为特征的地方，与定义不符。"}, {"text": "水井", "is_correct": false, "explanation": "搭配：水井只是取水的设施，没有草，“有水和草的地方叫水井”不搭配。"}], "explanations": {"绿洲": "正确。“有水和草的地方”就是绿洲的定义。", "沙漠": "语义：沙漠干旱缺水，与句中“有水和草”的定义正好相反。", "城市": "语义：城市不是以水草丰美为特征的地方，与定义不符。", "水井": "搭配：水井只是取水的设施，没有草，“有水和草的地方叫水井”不搭配。"}, "sentence_index": 0, "correct_answer": "绿洲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下大雪的时候，整个城市变成了一片白色的绿洲。", "explanation": "这里应该用〈世界〉。绿洲是沙漠里有水有草的地方，不能用来指下雪后的城市。"}, {"text": "绿洲会随着风慢慢移动。", "explanation": "这里应该用〈沙丘〉。沙丘会随风移动，绿洲是固定的水草地，不会移动。"}, {"text": "这块绿洲藏在很深的地下，要挖很深的井才能取到。", "explanation": "这里应该用〈地下水〉。地下水是埋在地下的水；绿洲是地面上有水草的地方，不能说藏在地下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿洲", "is_correct": true, "explanation": "正确。在沙漠中看见有水有草的绿洲，人会高兴。"}, {"text": "沙暴", "is_correct": false, "explanation": "语义：沙暴是危险的天气，看见它不会“高兴极了”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：看见垃圾不会让人高兴极了，与句子的情感语境不符。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“看见眼泪”与“高兴极了”搭配不当，情感前后矛盾。"}], "explanations": {"绿洲": "正确。在沙漠中看见有水有草的绿洲，人会高兴。", "沙暴": "语义：沙暴是危险的天气，看见它不会“高兴极了”。", "垃圾": "语义：看见垃圾不会让人高兴极了，与句子的情感语境不符。", "眼泪": "搭配：“看见眼泪”与“高兴极了”搭配不当，情感前后矛盾。"}, "sentence_index": 6, "correct_answer": "绿洲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在绿洲上堆了一个大雪人。", "explanation": "这里应该用〈雪地〉。堆雪人需要积雪；绿洲是沙漠中有水草的地方，一般没有雪。"}, {"text": "这片绿洲每天早上九点开门，晚上六点关门。", "explanation": "这里应该用〈商店〉。商店才会营业、开门关门；绿洲是自然形成的水草地，不会营业。"}, {"text": "我们把绿洲装进箱子，带回了家。", "explanation": "这里应该用〈水〉。绿洲是一片地区，不能装进箱子带走；装进箱子带走的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "沙漠里有一条绿洲，水很清。", "corrected_sentence": "沙漠里有一片绿洲，水很清。", "error_description": "量词错误：绿洲应用“片”，“条”用于河流、道路等细长的东西。正确说法是“一片绿洲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走了一整天，终于看到了一张绿洲。", "corrected_sentence": "我们走了一整天，终于看到了一片绿洲。", "error_description": "量词错误：绿洲是一块地方，应用量词“片”；“张”用于纸、桌子等平面的东西，不能用于绿洲。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
