INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人或一件事限制住另一个人或事，不让它随便动。", "primary_collocate": null, "pronunciation": "zhì yuē", "ipa": "ʈʂʐ̩˥˩ yɛ˥", "syllable_count": 2, "sentences": [{"text": "父母的规定制约着孩子的行为。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的规定制约了员工的自由。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的权力制约着每个员工。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队用防守制约了对方的主力。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个条约制约了两国的军队行动。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同制约着双方的做法。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练想用战术制约对手的速度。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "严格的校规制约着学生的行动。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身份制约了他说话的自由。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律制约着每个人的行为。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制约了", "label": "完成体标"}, {"form": "制约着", "label": "持续体标"}], "register": "书面", "sense_fingerprint": "人或事限制住对方，使其不能随意行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a9e316-c77e-4d87-af76-e864fd5a52f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制约", "is_correct": true, "explanation": "正确。“规定制约着孩子的行为”指规定限制孩子的行为。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞许的态度，规定本身不会欣赏孩子的行为。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”是注意地看，规定本身不能观察孩子的行为。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”的对象是人，不能带“行为”作宾语表示限制。"}], "explanations": {"制约": "正确。“规定制约着孩子的行为”指规定限制孩子的行为。", "欣赏": "语义：“欣赏”是赞许的态度，规定本身不会欣赏孩子的行为。", "观察": "语义：“观察”是注意地看，规定本身不能观察孩子的行为。", "祝福": "搭配：“祝福”的对象是人，不能带“行为”作宾语表示限制。"}, "sentence_index": 0, "correct_answer": "制约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈制约了孩子的手，让他自己走路。", "explanation": "这里应该用〈放开〉。制约表示限制住，与“放开”意思相反，前后语句也矛盾。"}, {"text": "温暖的阳光制约了小草快快生长。", "explanation": "这里应该用〈促进〉。制约表示限制，阳光让小草快快生长是促进，不是限制。"}, {"text": "他制约了那只狗，让它跑了。", "explanation": "这里应该用〈解开〉。制约是限制住，与解开的意思相反；狗跑了说明它没有被限制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制约", "is_correct": true, "explanation": "正确。“用战术制约对手的速度”指用战术限制对手的速度。"}, {"text": "提升", "is_correct": false, "explanation": "语义：“提升”是提高，与教练想压制对手速度的意图相反。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于庆祝人的成就，不能带“速度”作宾语。"}, {"text": "放大", "is_correct": false, "explanation": "语义：“放大”是扩大，与教练想压制对手速度的意图相反。"}], "explanations": {"制约": "正确。“用战术制约对手的速度”指用战术限制对手的速度。", "提升": "语义：“提升”是提高，与教练想压制对手速度的意图相反。", "祝贺": "搭配：“祝贺”用于庆祝人的成就，不能带“速度”作宾语。", "放大": "语义：“放大”是扩大，与教练想压制对手速度的意图相反。"}, "sentence_index": 6, "correct_answer": "制约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔奖金制约了员工的干劲。", "explanation": "这里应该用〈激励〉。制约表示限制，奖金应当激励员工。"}, {"text": "这根柱子制约了整座房子。", "explanation": "这里应该用〈支撑〉。制约表示限制，柱子对房子应是支撑。"}, {"text": "灯光制约了整个舞台。", "explanation": "这里应该用〈照亮〉。制约表示限制，灯光对舞台应是照亮，而不是限制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "铁链制约着了那只狗的活动。", "corrected_sentence": "铁链制约着那只狗的活动。", "error_description": "体标重复：“制约着”中的“着”已表示持续，其后不能再加“了”，应写作“铁链制约着那只狗的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "铁丝网制约了着他的脚步。", "corrected_sentence": "铁丝网制约着他的脚步。", "error_description": "错误在体标：“了”与“着”不能同时用在同一动词后，应去掉“了”，写作“铁丝网制约着他的脚步。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
