INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很高的山。", "primary_collocate": null, "pronunciation": "gāo shān", "ipa": "kɑʊ˥ ʂan˥", "syllable_count": 2, "sentences": [{"text": "远处的高山上还有白雪。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬高山需要很多体力。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢高山。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机从高山上方飞过。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高山上的冬天来得很早。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登山队正在向高山出发。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的风很大，只有高山才有这样的景色。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，很多人去高山避暑。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高山脚下有一个小湖。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的高山很雄伟。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "很高的山", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高山", "is_correct": true, "explanation": "正确：远处的高山上有白雪，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不在远处的山上，也不会有白雪，与句意冲突。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店与远处的白雪无关，句意不合理。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“远处的……上还有白雪”要求自然场所，教室不能与之搭配。"}], "explanations": {"高山": "正确：远处的高山上有白雪，符合句意。", "厨房": "语义：厨房不在远处的山上，也不会有白雪，与句意冲突。", "书店": "语义：书店与远处的白雪无关，句意不合理。", "教室": "搭配：“远处的……上还有白雪”要求自然场所，教室不能与之搭配。"}, "sentence_index": 0, "correct_answer": "高山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座高山只有几十米高，孩子们一会儿就爬到了山顶。", "explanation": "这里应该用〈小山丘〉。高山指很高的山，不能用来形容只有几十米高的小丘。"}, {"text": "他把高山搬回了家。", "explanation": "这里应该用〈石头〉。高山是很大的地形，无法搬动，能搬回家的应是石头这类小物。"}, {"text": "这座高山深得看不到底。", "explanation": "这里应该用〈深井〉。高山强调高度，不能用“深得看不到底”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高山", "is_correct": true, "explanation": "正确：山顶的风很大，只有高山才有这样的景色，句意通顺。"}, {"text": "平原", "is_correct": false, "explanation": "语义：平原没有山顶，与“山顶的风很大”的景色不符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海的景色与“山顶的风很大”的描述不符。"}, {"text": "沙滩", "is_correct": false, "explanation": "搭配：沙滩与“山顶的风很大”所描述的景色不搭配。"}], "explanations": {"高山": "正确：山顶的风很大，只有高山才有这样的景色，句意通顺。", "平原": "语义：平原没有山顶，与“山顶的风很大”的景色不符。", "大海": "语义：大海的景色与“山顶的风很大”的描述不符。", "沙滩": "搭配：沙滩与“山顶的风很大”所描述的景色不搭配。"}, "sentence_index": 6, "correct_answer": "高山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座高山矮得一跨就能过去。", "explanation": "这里应该用〈矮墙〉。高山指很高的山，不能用来形容矮得一跨就能过去的东西。"}, {"text": "高山的潮水每天涨落两次。", "explanation": "这里应该用〈大海〉。潮水涨落只出现在海洋，高山上没有潮水。"}, {"text": "他把高山装进了行李箱。", "explanation": "这里应该用〈小石子〉。高山是很大的地形，装不进行李箱，能装进去的应是小石子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条高山的山顶有雪。", "corrected_sentence": "这座高山的山顶有雪。", "error_description": "「山」的量词应为「座」，不能用「条」。正确的说法是「这座高山的山顶有雪。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照片里的这条高山很雄伟。", "corrected_sentence": "照片里的这座高山很雄伟。", "error_description": "「山」的量词应为「座」，不能用「条」。正确的说法是「照片里的这座高山很雄伟。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
