INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西带到某个地方。", "primary_collocate": null, "pronunciation": "yǐn zhì", "ipa": "in˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "工人把电缆引至二楼的机房。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把热水管引至浴室。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把煤气管引至厨房。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请人把网线引至书房。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把藤蔓引至墙边，让它向上爬。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把排水管引至屋后的池塘。", "target_word": "引至", "complexity_tier": "T3", "furigana": "gōng rén bǎ pái shuǐ guǎn yǐn zhì wū hòu de chí táng", "sentence_source": "generated"}, {"text": "他把灯线引至书桌旁。", "target_word": "引至", "complexity_tier": "T3", "furigana": "tā bǎ dēng xiàn yǐn zhì shū zhuō páng", "sentence_source": "generated"}, {"text": "保安把车辆引至停车场。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技师把输油管引至储油罐。", "target_word": "引至", "complexity_tier": "T3", "furigana": "jì shī bǎ shū yóu guǎn yǐn zhì chǔ yóu guàn", "sentence_source": "generated"}, {"text": "施工队把管道引至山下的水库。", "target_word": "引至", "complexity_tier": "T3", "furigana": "shī gōng duì bǎ guǎn dào yǐn zhì shān xià de shuǐ kù", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "把电线、管道、人或车辆等引导带到某个地点，「把……引至……」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把电线、管道等引导带到某地点，正是本句的词。"}, {"text": "银质", "is_correct": false, "explanation": "yín 与 yǐn 声调不同，“银质”意思是用银做的。"}, {"text": "印制", "is_correct": false, "explanation": "yìn 与 yǐn 声调不同，“印制”意思是印刷制作。"}, {"text": "引子", "is_correct": false, "explanation": "zi 与 zhì 的声母与韵母都不同，“引子”指开头或引语。"}], "explanations": {"引至": "引至：把电线、管道等引导带到某地点，正是本句的词。", "银质": "yín 与 yǐn 声调不同，“银质”意思是用银做的。", "印制": "yìn 与 yǐn 声调不同，“印制”意思是印刷制作。", "引子": "zi 与 zhì 的声母与韵母都不同，“引子”指开头或引语。"}, "sentence_index": null, "correct_answer": "引至"}, "level_3": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把电缆引导带到某地点，与“工人把电缆……二楼的机房”相合。"}, {"text": "染至", "is_correct": false, "explanation": "语义：染是着色，不能说把电缆染至二楼。"}, {"text": "踩至", "is_correct": false, "explanation": "搭配：“踩”是用脚践踏，电缆不能被踩至二楼。"}, {"text": "烧至", "is_correct": false, "explanation": "语义：烧是加热，电缆烧至二楼说不通。"}], "explanations": {"引至": "引至：把电缆引导带到某地点，与“工人把电缆……二楼的机房”相合。", "染至": "语义：染是着色，不能说把电缆染至二楼。", "踩至": "搭配：“踩”是用脚践踏，电缆不能被踩至二楼。", "烧至": "语义：烧是加热，电缆烧至二楼说不通。"}, "sentence_index": 0, "correct_answer": "引至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我请人把快递引至书房。", "explanation": "这里应该用〈送〉。引至用于电线、管道等，送快递应说“送”。"}, {"text": "工人把桌子引至二楼。", "explanation": "这里应该用〈搬〉。引至用于电线、管道等，搬桌子要用“搬”。"}, {"text": "卡车把砖头引至工地。", "explanation": "这里应该用〈运〉。引至是把管线、人或车辆引导到某处，用卡车搬运砖头要说“运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25270, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把电线、管道等引导带到某地点，正是本句的词。"}, {"text": "隐士", "is_correct": false, "explanation": "sh 与 zh 声母不同，“隐士”指隐居的人。"}, {"text": "银制", "is_correct": false, "explanation": "yín 与 yǐn 声调不同，“银制”指用银做的。"}, {"text": "印字", "is_correct": false, "explanation": "yìn 与 yǐn 声调不同，“印字”指把字印在纸上。"}], "explanations": {"引至": "引至：把电线、管道等引导带到某地点，正是本句的词。", "隐士": "sh 与 zh 声母不同，“隐士”指隐居的人。", "银制": "yín 与 yǐn 声调不同，“银制”指用银做的。", "印字": "yìn 与 yǐn 声调不同，“印字”指把字印在纸上。"}, "sentence_index": null, "correct_answer": "引至"}, "level_3": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把灯线引导带到书桌旁，符合句意。"}, {"text": "扛至", "is_correct": false, "explanation": "搭配：“扛”用于搬运重物，灯线不能扛至书桌旁。"}, {"text": "拆至", "is_correct": false, "explanation": "语义：拆是拆开，不能说把灯线拆至书桌旁。"}, {"text": "煮至", "is_correct": false, "explanation": "语义：煮是加热食物，灯线不能煮至书桌旁。"}], "explanations": {"引至": "引至：把灯线引导带到书桌旁，符合句意。", "扛至": "搭配：“扛”用于搬运重物，灯线不能扛至书桌旁。", "拆至": "语义：拆是拆开，不能说把灯线拆至书桌旁。", "煮至": "语义：煮是加热食物，灯线不能煮至书桌旁。"}, "sentence_index": 6, "correct_answer": "引至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司把厂房引至郊外。", "explanation": "这里应该用〈迁〉。引至用于管道、电线等，整体搬迁厂房要用“迁”。"}, {"text": "他把椅子引至门口。", "explanation": "这里应该用〈挪〉。引至不用于家具，挪动椅子要用“挪”。"}, {"text": "他把行李引至车站。", "explanation": "这里应该用〈拖〉。引至是把管线、人或车辆引导到某处，自己拉着行李走要说“拖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
