INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雪化后变成的水。", "primary_collocate": null, "pronunciation": "róng xuě shuǐ", "ipa": "ʐʊŋ˧˥ ɕɥe˨˩˦ ʂueɪ˨˩˦", "syllable_count": 3, "sentences": [{"text": "太阳出来后，融雪水开始往下流。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的融雪水很冷。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，山上的融雪水变成了小溪。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用融雪水洗了手。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋前的融雪水结成了冰。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "融雪水流过田地，麦子长得很好。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水主要是融雪水。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的融雪水很多，小心滑倒。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "融雪水滴到我的头上。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里的融雪水慢慢流进了湖里。", "target_word": "融雪水", "complexity_tier": "T3", "furigana": "shān gǔ lǐ de róng xuě shuǐ màn màn liú jìn le hú lǐ", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "雪化后变成的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融雪水", "is_correct": true, "explanation": "融雪水是雪化后变成的水，会往下流，符合“太阳出来后……开始往下流”。"}, {"text": "石块", "is_correct": false, "explanation": "语义：石块是固体，不会往下流。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“往下流”用于液体，不能说歌声往下流。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是固体，会飘落但不是流动的液体。"}], "explanations": {"融雪水": "融雪水是雪化后变成的水，会往下流，符合“太阳出来后……开始往下流”。", "石块": "语义：石块是固体，不会往下流。", "歌声": "搭配：“往下流”用于液体，不能说歌声往下流。", "树叶": "语义：树叶是固体，会飘落但不是流动的液体。"}, "sentence_index": 0, "correct_answer": "融雪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爬完山，满身大汗，身上全是融雪水。", "explanation": "这里应该用〈汗水〉。融雪水指雪化后的水，爬山流的汗要说汗水。"}, {"text": "他哭得很厉害，满脸都是融雪水。", "explanation": "这里应该用〈泪水〉。融雪水指雪化后的水，哭出的眼泪要说泪水。"}, {"text": "他的鼻子一直在流，手帕上全是融雪水。", "explanation": "这里应该用〈鼻涕〉。融雪水指雪化后的水，鼻子流出的要说鼻涕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融雪水", "is_correct": true, "explanation": "融雪水是这条河水的主要来源，与句意相合。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是飘在空中的水汽，不是河水的来源。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟是燃烧产生的气体，不能作河水的主要来源。"}, {"text": "泥巴", "is_correct": false, "explanation": "搭配：“泥巴”是土与水的混合物，不能说河水主要是泥巴。"}], "explanations": {"融雪水": "融雪水是这条河水的主要来源，与句意相合。", "云": "语义：云是飘在空中的水汽，不是河水的来源。", "烟": "语义：烟是燃烧产生的气体，不能作河水的主要来源。", "泥巴": "搭配：“泥巴”是土与水的混合物，不能说河水主要是泥巴。"}, "sentence_index": 6, "correct_answer": "融雪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的钢笔漏墨了，桌上全是融雪水。", "explanation": "这里应该用〈墨水〉。融雪水指雪化后的水，钢笔漏出来的要说墨水。"}, {"text": "早晨的大雾很浓，空气里弥漫着融雪水。", "explanation": "这里应该用〈雾气〉。融雪水是雪化后的水，弥漫在空中的雾气不是融雪水。"}, {"text": "他的手受伤了，流出的全是融雪水。", "explanation": "这里应该用〈血〉。融雪水指雪化后的水，流出的液体是血。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河边的一只融雪水很清。", "corrected_sentence": "河边的融雪水很清。", "error_description": "错误在于在“融雪水”前加了量词“只”。融雪水是液体，不能用“只”计量，应直接说“融雪水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山上的融雪水慢慢流了进小河。", "corrected_sentence": "山上的融雪水慢慢流进了小河。", "error_description": "错误在于“了”的位置：“流进”是动词加趋向补语，“了”要放在“流进”之后，应说“流进了小河”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
