INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坎儿井是一种在地下挖的水渠，用来把水引到田地里。", "primary_collocate": null, "pronunciation": "kǎnr jǐng", "ipa": "kʰɚ˨˩ tɕiŋ˨˩", "syllable_count": 2, "sentences": [{"text": "人们在地下挖了一条坎儿井。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井的水流进了田地。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井是新疆人想出来的好办法。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上读到过坎儿井。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井很长，水从山下流到村子。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了坎儿井，农民不用到远处挑水。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井里的水又凉又干净。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了坎儿井的照片。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修坎儿井要挖很多土。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子旁边的坎儿井，已经用了几百年。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "坎兒井", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地下挖的水渠，把水引到田地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c14fd65d-7562-43e3-b9a1-66b88150ec98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
